fn string_vec<const N: usize>(values: [&str; N]) -> Vec<String> {
    values.into_iter().map(str::to_string).collect()
}

fn scene_pack_room(room_id: &str) -> Option<NativeBevySceneRoom> {
    native_bevy_scene_pack_fixture()
        .rooms
        .into_iter()
        .find(|room| room.room_id == room_id)
}

fn scene_pack_actor(actor_id: &str) -> Option<NativeBevySceneActor> {
    native_bevy_scene_pack_fixture()
        .actors
        .into_iter()
        .find(|actor| actor.actor_id == actor_id)
}

fn scene_pack_task(task_id: &str) -> Option<NativeBevySceneTask> {
    native_bevy_scene_pack_fixture()
        .tasks
        .into_iter()
        .find(|task| task.task_id == task_id)
}

fn scene_pack_route_plan_for_task(start_room_id: &str, task_id: &str) -> NativeBevySceneRoutePlan {
    let scene_pack = native_bevy_scene_pack_fixture();
    let Some(task) = scene_pack_task(task_id) else {
        return NativeBevySceneRoutePlan {
            contract_version: TRILLIONNIUM_WORLD_BEVY_SCENE_PACK_ROUTE_DIRECTOR_CONTRACT
                .to_string(),
            task_id: task_id.to_string(),
            task_title: "unknown".to_string(),
            start_room_id: start_room_id.to_string(),
            target_room_id: "unknown".to_string(),
            target_room_name: "unknown".to_string(),
            unlock_rule: "missing_task".to_string(),
            path_room_ids: Vec::new(),
            steps: Vec::new(),
            generated_button_actions: Vec::new(),
            blocked_reason: Some(format!("task_missing:{task_id}")),
        };
    };
    let target_room_id = task
        .room_ids
        .last()
        .cloned()
        .unwrap_or_else(|| start_room_id.to_string());
    let target_room_name = scene_pack
        .rooms
        .iter()
        .find(|room| room.room_id == target_room_id)
        .map(|room| room.label.clone())
        .unwrap_or_else(|| target_room_id.clone());
    let route_waypoint_room_ids = task
        .room_ids
        .iter()
        .position(|room_id| room_id == start_room_id)
        .map(|start_index| task.room_ids[start_index..].to_vec())
        .unwrap_or_else(|| task.room_ids.clone());
    let route = ordered_scene_pack_task_path(&scene_pack, start_room_id, &route_waypoint_room_ids);
    let blocked_reason = if route.is_some() {
        None
    } else {
        Some(format!("route_missing:{start_room_id}->{target_room_id}"))
    };
    let path_room_ids = route.unwrap_or_default();
    let steps = path_room_ids
        .windows(2)
        .map(|pair| NativeBevySceneRouteStep {
            from_room_id: pair[0].clone(),
            to_room_id: pair[1].clone(),
            action_label: native_control_action_label(&NativeControlAction::EnterRoom {
                room_id: pair[1].clone(),
            }),
        })
        .collect::<Vec<_>>();
    let generated_button_actions = steps
        .iter()
        .map(|step| step.action_label.clone())
        .collect::<Vec<_>>();
    NativeBevySceneRoutePlan {
        contract_version: TRILLIONNIUM_WORLD_BEVY_SCENE_PACK_ROUTE_DIRECTOR_CONTRACT.to_string(),
        task_id: task.task_id,
        task_title: task.title,
        start_room_id: start_room_id.to_string(),
        target_room_id,
        target_room_name,
        unlock_rule: task.unlock_rule,
        path_room_ids,
        steps,
        generated_button_actions,
        blocked_reason,
    }
}

fn shortest_scene_pack_room_path(
    scene_pack: &NativeBevyScenePack,
    start_room_id: &str,
    target_room_id: &str,
) -> Option<Vec<String>> {
    if start_room_id == target_room_id {
        return Some(vec![start_room_id.to_string()]);
    }
    let rooms = scene_pack
        .rooms
        .iter()
        .map(|room| (room.room_id.as_str(), room))
        .collect::<HashMap<_, _>>();
    if !rooms.contains_key(start_room_id) || !rooms.contains_key(target_room_id) {
        return None;
    }
    let mut queue = VecDeque::from([start_room_id.to_string()]);
    let mut previous: HashMap<String, String> = HashMap::new();
    previous.insert(start_room_id.to_string(), String::new());
    while let Some(room_id) = queue.pop_front() {
        let Some(room) = rooms.get(room_id.as_str()) else {
            continue;
        };
        for next_room_id in &room.exits {
            if !rooms.contains_key(next_room_id.as_str()) || previous.contains_key(next_room_id) {
                continue;
            }
            previous.insert(next_room_id.clone(), room_id.clone());
            if next_room_id == target_room_id {
                let mut path = vec![target_room_id.to_string()];
                let mut cursor = target_room_id.to_string();
                while let Some(parent) = previous.get(&cursor) {
                    if parent.is_empty() {
                        break;
                    }
                    path.push(parent.clone());
                    cursor = parent.clone();
                }
                path.reverse();
                return Some(path);
            }
            queue.push_back(next_room_id.clone());
        }
    }
    None
}

fn ordered_scene_pack_task_path(
    scene_pack: &NativeBevyScenePack,
    start_room_id: &str,
    waypoint_room_ids: &[String],
) -> Option<Vec<String>> {
    let mut full_path = vec![start_room_id.to_string()];
    let mut cursor = start_room_id.to_string();
    for waypoint_room_id in waypoint_room_ids {
        if &cursor == waypoint_room_id {
            continue;
        }
        let segment = shortest_scene_pack_room_path(scene_pack, &cursor, waypoint_room_id)?;
        full_path.extend(segment.into_iter().skip(1));
        cursor = waypoint_room_id.clone();
    }
    Some(full_path)
}

fn scene_pack_route_actions(plan: &NativeBevySceneRoutePlan) -> Vec<NativeControlAction> {
    plan.steps
        .iter()
        .map(|step| NativeControlAction::EnterRoom {
            room_id: step.to_room_id.clone(),
        })
        .collect()
}

fn scene_pack_path_is_valid(plan: &NativeBevySceneRoutePlan) -> bool {
    if plan.blocked_reason.is_some() || plan.path_room_ids.is_empty() {
        return false;
    }
    plan.path_room_ids.windows(2).all(|pair| {
        scene_pack_room(&pair[0])
            .map(|room| room.exits.iter().any(|exit| exit == &pair[1]))
            .unwrap_or(false)
    })
}

fn native_contextual_action_deck(
    runtime: &NativeFirstPlayableRuntime,
) -> NativeBevyContextualActionDeck {
    let mut entries = Vec::new();
    push_contextual_action(
        runtime,
        &mut entries,
        NativeControlAction::NewGameFromTitle,
        "title",
        "title_new_game",
    );
    push_contextual_action(
        runtime,
        &mut entries,
        NativeControlAction::ContinueFromTitle,
        "title",
        "title_continue",
    );
    push_contextual_action(
        runtime,
        &mut entries,
        NativeControlAction::LoadFromTitle,
        "title",
        "title_load",
    );
    push_contextual_action(
        runtime,
        &mut entries,
        NativeControlAction::OpenTitleMenu,
        "title",
        "title_open",
    );
    push_contextual_action(
        runtime,
        &mut entries,
        NativeControlAction::StartCampaignFromTitle,
        "campaign",
        "title_campaign_start",
    );
    push_contextual_action(
        runtime,
        &mut entries,
        NativeControlAction::ContinueCampaignFromTitle,
        "campaign",
        "title_campaign_continue",
    );
    push_contextual_action(
        runtime,
        &mut entries,
        NativeControlAction::ReplayCampaignFromTitle,
        "campaign",
        "title_campaign_replay",
    );
    push_contextual_action(
        runtime,
        &mut entries,
        NativeControlAction::RegisterAccountFromTitle,
        "account",
        "title_account_register",
    );
    push_contextual_action(
        runtime,
        &mut entries,
        NativeControlAction::LoginAccountFromTitle,
        "account",
        "title_account_login",
    );
    push_contextual_action(
        runtime,
        &mut entries,
        NativeControlAction::ContinueAccountFromTitle,
        "account",
        "title_account_continue",
    );
    push_contextual_action(
        runtime,
        &mut entries,
        NativeControlAction::CycleCharacterName,
        "character_create",
        "cycle_name",
    );
    push_contextual_action(
        runtime,
        &mut entries,
        NativeControlAction::CycleCharacterArchetype,
        "character_create",
        "cycle_archetype",
    );
    push_contextual_action(
        runtime,
        &mut entries,
        NativeControlAction::ConfirmCharacterCreate,
        "character_create",
        "confirm_character",
    );
    push_contextual_action(
        runtime,
        &mut entries,
        NativeControlAction::BackToTitleFromCreate,
        "character_create",
        "back_to_title",
    );
    if runtime
        .active_room_npc_ids
        .iter()
        .any(|npc_id| npc_id == "npc-street-compass-sifu")
    {
        push_contextual_action(
            runtime,
            &mut entries,
            NativeControlAction::Talk,
            "npc",
            "mentor_dialogue_tile",
        );
        push_contextual_action(
            runtime,
            &mut entries,
            NativeControlAction::Train,
            "training",
            "mentor_dialogue_tile",
        );
    }
    for room_id in &runtime.available_room_exits {
        if scene_pack_room(room_id).is_some() {
            push_contextual_action(
                runtime,
                &mut entries,
                NativeControlAction::EnterRoom {
                    room_id: room_id.clone(),
                },
                "room_exit",
                "scene_pack_room_exit",
            );
        }
    }
    for npc_id in &runtime.active_room_npc_ids {
        push_contextual_action(
            runtime,
            &mut entries,
            NativeControlAction::InteractNpc {
                npc_id: npc_id.clone(),
            },
            "npc",
            "scene_pack_room_actor",
        );
    }
    let mut task_ids = runtime.available_task_ids.clone();
    task_ids.sort_by_key(|task_id| task_id != &runtime.route_director_task_id);
    for task_id in &task_ids {
        push_contextual_action(
            runtime,
            &mut entries,
            NativeControlAction::StartTask {
                task_id: task_id.clone(),
            },
            "task",
            "scene_pack_room_task",
        );
    }
    if runtime.current_room_id == "league-coliseum" {
        for action in [
            NativeControlAction::CombatAttack,
            NativeControlAction::CombatDefend,
            NativeControlAction::CombatUseItem,
            NativeControlAction::CombatEscape,
        ] {
            push_contextual_action(
                runtime,
                &mut entries,
                action,
                "combat",
                "arena_enemy_adjacent",
            );
        }
    }
    push_contextual_action(
        runtime,
        &mut entries,
        NativeControlAction::CompleteTask,
        "task",
        "combat_resolution",
    );
    push_contextual_action(
        runtime,
        &mut entries,
        NativeControlAction::Equip,
        "equipment",
        "reward_claim",
    );
    push_contextual_action(
        runtime,
        &mut entries,
        NativeControlAction::OpenBag,
        "inventory",
        "bag_state",
    );
    push_contextual_action(
        runtime,
        &mut entries,
        NativeControlAction::LootDrop,
        "loot",
        "victory_drop",
    );
    push_contextual_action(
        runtime,
        &mut entries,
        NativeControlAction::EquipItem {
            item_id: "bandit_sash".to_string(),
        },
        "equipment",
        "bag_item",
    );
    for title_id in build_branch_mastery_title_ids() {
        push_contextual_action(
            runtime,
            &mut entries,
            NativeControlAction::EquipBuildTitle {
                title_id: title_id.to_string(),
            },
            "title",
            "build_mastery_title",
        );
    }
    push_contextual_action(
        runtime,
        &mut entries,
        NativeControlAction::AcceptTitleRouteRecommendation,
        "title",
        "active_title_route",
    );
    for stat_id in native_growth_stat_button_ids() {
        push_contextual_action(
            runtime,
            &mut entries,
            NativeControlAction::AllocateStat {
                stat_id: stat_id.to_string(),
            },
            "growth",
            "unspent_stat_point",
        );
    }
    push_contextual_action(
        runtime,
        &mut entries,
        NativeControlAction::ConfirmStatAllocation,
        "growth",
        "stat_confirmation",
    );
    push_contextual_action(
        runtime,
        &mut entries,
        NativeControlAction::CancelStatAllocation,
        "growth",
        "stat_confirmation",
    );
    push_contextual_action(
        runtime,
        &mut entries,
        NativeControlAction::SaveSlot,
        "session",
        "save_slot",
    );
    push_contextual_action(
        runtime,
        &mut entries,
        NativeControlAction::LoadSlot,
        "session",
        "load_slot",
    );
    for slot_id in native_session_slot_ids() {
        push_contextual_action(
            runtime,
            &mut entries,
            NativeControlAction::SelectSlot {
                slot_id: slot_id.to_string(),
            },
            "session",
            "slot_select",
        );
        push_contextual_action(
            runtime,
            &mut entries,
            NativeControlAction::SaveSlotNamed {
                slot_id: slot_id.to_string(),
            },
            "session",
            "named_save_slot",
        );
        push_contextual_action(
            runtime,
            &mut entries,
            NativeControlAction::LoadSlotNamed {
                slot_id: slot_id.to_string(),
            },
            "session",
            "named_load_slot",
        );
    }
    push_contextual_action(
        runtime,
        &mut entries,
        NativeControlAction::SaveSelectedSlot,
        "session",
        "selected_save_slot",
    );
    push_contextual_action(
        runtime,
        &mut entries,
        NativeControlAction::LoadSelectedSlot,
        "session",
        "selected_load_slot",
    );
    push_contextual_action(
        runtime,
        &mut entries,
        NativeControlAction::ConfirmOverwriteSlot,
        "session",
        "overwrite_confirm",
    );
    push_contextual_action(
        runtime,
        &mut entries,
        NativeControlAction::CancelOverwriteSlot,
        "session",
        "overwrite_cancel",
    );
    push_contextual_action(
        runtime,
        &mut entries,
        NativeControlAction::ContinueAfterLoad,
        "session",
        "resume_continue",
    );
    push_contextual_action(
        runtime,
        &mut entries,
        NativeControlAction::PauseMenu,
        "session",
        "pause_menu",
    );
    push_contextual_action(
        runtime,
        &mut entries,
        NativeControlAction::ResumeFromPause,
        "session",
        "pause_resume",
    );
    push_contextual_action(
        runtime,
        &mut entries,
        NativeControlAction::OpenSettingsMenu,
        "settings",
        "settings_open",
    );
    push_contextual_action(
        runtime,
        &mut entries,
        NativeControlAction::CloseSettingsMenu,
        "settings",
        "settings_close",
    );
    push_contextual_action(
        runtime,
        &mut entries,
        NativeControlAction::ToggleLowMotion,
        "settings",
        "settings_low_motion",
    );
    push_contextual_action(
        runtime,
        &mut entries,
        NativeControlAction::VolumeDown,
        "settings",
        "settings_volume_down",
    );
    push_contextual_action(
        runtime,
        &mut entries,
        NativeControlAction::VolumeUp,
        "settings",
        "settings_volume_up",
    );
    push_contextual_action(
        runtime,
        &mut entries,
        NativeControlAction::CycleInputMode,
        "settings",
        "settings_input_mode",
    );
    let title_route_primary_action_label = build_branch_title_route_action_focus(runtime)
        .filter(|focus| focus.enabled && focus.action_label != "DONE")
        .map(|focus| focus.action_label);
    let primary_action_label = title_route_primary_action_label
        .filter(|label| {
            entries
                .iter()
                .any(|entry| entry.enabled && entry.label.as_str() == label.as_str())
        })
        .or_else(|| contextual_primary_action_label(&entries));
    for entry in &mut entries {
        entry.primary = Some(entry.label.as_str()) == primary_action_label.as_deref();
    }
    NativeBevyContextualActionDeck {
        contract_version: TRILLIONNIUM_WORLD_BEVY_CONTEXTUAL_ACTION_DECK_CONTRACT.to_string(),
        current_room_id: runtime.current_room_id.clone(),
        route_director_task_id: runtime.route_director_task_id.clone(),
        route_director_target_room_id: runtime.route_director_target_room_id.clone(),
        route_director_path: runtime.route_director_path.clone(),
        primary_action_label,
        actions: entries,
    }
}

fn push_contextual_action(
    runtime: &NativeFirstPlayableRuntime,
    entries: &mut Vec<NativeBevyContextualAction>,
    action: NativeControlAction,
    action_kind: &str,
    source: &str,
) {
    let label = native_control_action_label(&action);
    if entries.iter().any(|entry| entry.label == label) {
        return;
    }
    let (enabled, reason) = native_live_action_availability(runtime, &action);
    entries.push(NativeBevyContextualAction {
        label,
        action_kind: action_kind.to_string(),
        source: source.to_string(),
        enabled,
        reason,
        primary: false,
    });
}

fn contextual_primary_action_label(entries: &[NativeBevyContextualAction]) -> Option<String> {
    for label in ["TALK", "TRAIN"] {
        if entries
            .iter()
            .any(|entry| entry.enabled && entry.label == label)
        {
            return Some(label.to_string());
        }
    }
    for kind in ["combat", "task", "loot", "equipment", "npc", "room_exit"] {
        if let Some(entry) = entries
            .iter()
            .find(|entry| entry.enabled && entry.action_kind == kind)
        {
            return Some(entry.label.clone());
        }
    }
    entries
        .iter()
        .find(|entry| entry.enabled)
        .map(|entry| entry.label.clone())
}

fn refresh_contextual_action_runtime(runtime: &mut NativeFirstPlayableRuntime) {
    let deck = native_contextual_action_deck(runtime);
    runtime.contextual_action_labels = deck
        .actions
        .iter()
        .filter(|entry| entry.enabled)
        .map(|entry| entry.label.clone())
        .collect();
    runtime.contextual_primary_action_label = deck.primary_action_label.clone();
    push_history(
        &mut runtime.contextual_action_history,
        &format!(
            "contextual_deck:{}:{}",
            runtime.current_room_id,
            deck.primary_action_label
                .clone()
                .unwrap_or_else(|| "none".to_string())
        ),
    );
}

