fn runtime_has_active_build_title(runtime: &NativeFirstPlayableRuntime, stat_id: &str) -> bool {
    build_branch_mastery_title_id_for_stat(stat_id).is_some_and(|title_id| {
        runtime.active_build_title_id.as_deref() == Some(title_id)
            && runtime_has_build_title_id(runtime, title_id)
    })
}

fn active_build_title_parts(
    runtime: &NativeFirstPlayableRuntime,
) -> Option<(&str, &'static str, &str)> {
    let title_id = runtime.active_build_title_id.as_deref()?;
    let stat_id = build_branch_mastery_title_stat_for_id(title_id)?;
    let effect_id = runtime
        .active_build_title_effect
        .as_deref()
        .unwrap_or_else(|| {
            build_branch_mastery_title_effect_for_stat(stat_id).unwrap_or("custom_effect")
        });
    Some((title_id, stat_id, effect_id))
}

