pub struct TrillionniumWorldBevyPlugin {
    world: WorldState,
    actor_id: String,
}

impl TrillionniumWorldBevyPlugin {
    pub fn new(world: WorldState, actor_id: impl Into<String>) -> Self {
        Self {
            world,
            actor_id: actor_id.into(),
        }
    }
}

impl Plugin for TrillionniumWorldBevyPlugin {
    fn build(&self, app: &mut App) {
        let runtime_texture_probe = runtime_texture_manifest_probe_from_env();
        app.init_resource::<Assets<Image>>()
            .init_resource::<Assets<TextureAtlasLayout>>();
        let runtime_texture_asset_store = register_runtime_texture_asset_store_from_probe(
            app.world_mut(),
            &runtime_texture_probe,
        );
        app.insert_resource(AuthoritativeWorldResource {
            state: self.world.clone(),
        })
        .insert_resource(NativeWorldBootstrap {
            actor_id: self.actor_id.clone(),
        })
        .insert_resource(NativeAccountClientRuntime::for_actor(&self.actor_id))
        .insert_resource(NativeIntentQueue::default())
        .insert_resource(NativeGameplayLog {
            turn: 0,
            last_action: "boot".to_string(),
            last_result: "native_bevy_client_ready".to_string(),
            last_rejection: None,
        })
        .insert_resource(runtime_texture_probe)
        .insert_resource(runtime_texture_asset_store)
        .insert_resource(NativeTacticsCharacter {
            character: WorldTrillionniumCharacter::default_for(&self.actor_id),
        })
        .insert_resource(NativeFirstPlayableRuntime::default())
        .add_systems(Startup, spawn_native_world_shell)
        .add_systems(Update, apply_native_intent_queue);
    }
}

pub fn spawn_world_snapshot(
    bevy_world: &mut World,
    world: &WorldState,
    actor_id: &str,
) -> BevyWorldBridgeReport {
    for node in &world.nodes {
        bevy_world.spawn(BevyWorldNode {
            node_id: node.id.clone(),
            region: node.region.clone(),
            location_id: node.location_id.clone(),
            node_kind: node.node_kind.clone(),
        });
    }

    for position in &world.positions {
        bevy_world.spawn(BevyWorldActorPosition {
            actor_id: position.actor_id.clone(),
            node_id: position.node_id.clone(),
        });
    }

    bevy_world.spawn(BevyWorldHudAnchor {
        actor_id: actor_id.to_string(),
        projection_contract: TRILLIONNIUM_WORLD_FULL_SPLIT_PROJECTION_CONTRACT.to_string(),
    });

    refresh_projection_resource(bevy_world, world, actor_id);
    report_for_world(world)
}

fn spawn_native_world_shell(
    mut commands: Commands,
    bootstrap: Res<NativeWorldBootstrap>,
    world: Res<AuthoritativeWorldResource>,
) {
    for node in &world.state.nodes {
        commands.spawn(BevyWorldNode {
            node_id: node.id.clone(),
            region: node.region.clone(),
            location_id: node.location_id.clone(),
            node_kind: node.node_kind.clone(),
        });
    }

    for position in &world.state.positions {
        commands.spawn(BevyWorldActorPosition {
            actor_id: position.actor_id.clone(),
            node_id: position.node_id.clone(),
        });
    }

    commands.spawn(BevyWorldHudAnchor {
        actor_id: bootstrap.actor_id.clone(),
        projection_contract: TRILLIONNIUM_WORLD_FULL_SPLIT_PROJECTION_CONTRACT.to_string(),
    });
    commands.insert_resource(projection_resource(&world.state, &bootstrap.actor_id));
}

#[allow(clippy::too_many_arguments)]
fn apply_native_intent_queue(
    mut queue: ResMut<NativeIntentQueue>,
    mut world: ResMut<AuthoritativeWorldResource>,
    bootstrap: Res<NativeWorldBootstrap>,
    mut projection: ResMut<BevyWorldProjection>,
    mut tactics_character: ResMut<NativeTacticsCharacter>,
    mut gameplay_log: ResMut<NativeGameplayLog>,
    mut first_playable: ResMut<NativeFirstPlayableRuntime>,
    mut commands: Commands,
) {
    let Some(intent) = queue.pending.pop() else {
        return;
    };
    let action_label = native_command_label(&intent.command);
    let first_playable_action = match &intent.command {
        WorldCommand::Move { direction, .. } => Some(NativeControlAction::Move {
            direction: direction.clone(),
        }),
        _ => None,
    };
    let response = apply_native_intent(&mut world.state, intent.command);
    *projection = projection_resource(&world.state, &bootstrap.actor_id);
    gameplay_log.turn += 1;
    gameplay_log.last_action = action_label;
    gameplay_log.last_result = response.decision.reason.clone();
    gameplay_log.last_rejection = response
        .decision
        .transition
        .as_ref()
        .and_then(|transition| {
            transition
                .blocked_reason
                .clone()
                .or_else(|| (!transition.accepted).then(|| transition.result.clone()))
        });
    if let Some(action) = first_playable_action {
        update_first_playable_runtime(
            &mut first_playable,
            &action,
            Some(&response),
            &mut tactics_character.character,
            &world.state,
            &bootstrap.actor_id,
        );
    }
    commands.insert_resource(LastNativeCommandResponse {
        response_json: serde_json::to_string(&response)
            .expect("native command response serializes"),
    });
}

fn projection_resource(world: &WorldState, actor_id: &str) -> BevyWorldProjection {
    let mut projection = world_full_split_projection_json(world, actor_id);
    if let Some(object) = projection.as_object_mut() {
        object.insert(
            "account_client".to_string(),
            serde_json::to_value(NativeAccountClientRuntime::for_actor(actor_id))
                .expect("account client runtime serializes"),
        );
    }
    BevyWorldProjection {
        actor_id: actor_id.to_string(),
        projection_json: serde_json::to_string(&projection)
            .expect("full split projection serializes for Bevy client"),
    }
}

fn refresh_projection_resource(bevy_world: &mut World, world: &WorldState, actor_id: &str) {
    bevy_world.insert_resource(projection_resource(world, actor_id));
}

