pub fn native_account_client_boundary_evidence_value(actor_id: &str) -> serde_json::Value {
    let (app, report) = build_native_bevy_app(native_bevy_playable_fixture(), actor_id);
    let account = app.world().resource::<NativeAccountClientRuntime>().clone();
    let projection = app.world().resource::<BevyWorldProjection>();
    let projection_value: serde_json::Value =
        serde_json::from_str(&projection.projection_json).expect("projection JSON parses");
    let projection_account = projection_value
        .get("account_client")
        .cloned()
        .unwrap_or(serde_json::Value::Null);
    json!({
        "contract_version": TRILLIONNIUM_WORLD_BEVY_ACCOUNT_CLIENT_BOUNDARY_CONTRACT,
        "bevy_native_client_contract": TRILLIONNIUM_WORLD_BEVY_NATIVE_CLIENT_CONTRACT,
        "account_api_contract": WORLD_ACCOUNT_API_CONTRACT,
        "account_boundary_contract": WORLD_ACCOUNT_CLIENT_BOUNDARY_CONTRACT,
        "player_client_owner": account.player_client_owner,
        "account_api_owner": account.account_api_owner,
        "report_account_client_contract": report.account_client_contract,
        "report_account_api_contract": report.account_api_contract,
        "profile_actor_id": account.auth_decision.profile.actor_id,
        "profile_display_name": account.auth_decision.profile.display_name,
        "default_room_id": account.auth_decision.profile.default_room_id,
        "session_bound_to_bevy_actor": account.session_bound_to_bevy_actor,
        "visible_entry_points": account.visible_entry_points,
        "passwords_tokens_or_cookie_values_logged": account.passwords_tokens_or_cookie_values_logged,
        "cex_runtime_player_client_allowed": account.cex_runtime_player_client_allowed,
        "bevy_projection_contains_account_client": !projection_account.is_null(),
        "projection_account_client": projection_account,
        "source_of_truth": "trillionnium_owned_account_api_consumed_by_trnm_world_bevy",
        "green": account.auth_decision.accepted
            && account.session_bound_to_bevy_actor
            && !account.passwords_tokens_or_cookie_values_logged
            && !account.cex_runtime_player_client_allowed
            && !projection_account.is_null(),
    })
}

pub fn native_account_client_boundary_evidence_json(actor_id: &str) -> String {
    serde_json::to_string_pretty(&native_account_client_boundary_evidence_value(actor_id))
        .expect("native account client boundary evidence serializes")
}

pub fn native_account_title_flow_evidence_value(actor_id: &str) -> serde_json::Value {
    let mut app = build_keyboard_runtime_app(native_bevy_playable_fixture(), actor_id);
    let initial_sample = sample_live_app_state(&mut app, "initial_account_title_flow");
    let register_event =
        press_live_button_action(&mut app, NativeControlAction::RegisterAccountFromTitle);
    let after_register_sample = sample_live_app_state(&mut app, "after_account_register");
    let login_event =
        press_live_button_action(&mut app, NativeControlAction::LoginAccountFromTitle);
    let after_login_sample = sample_live_app_state(&mut app, "after_account_login");
    let continue_event =
        press_live_button_action(&mut app, NativeControlAction::ContinueAccountFromTitle);
    let final_sample = sample_live_app_state(&mut app, "after_account_continue");
    let snapshot = playable_snapshot_from_app(&app, actor_id);
    let (_restored_world, restored_character, _restored_log, restored_runtime) =
        native_restore_playable_save_snapshot(snapshot);
    let runtime = app.world().resource::<NativeFirstPlayableRuntime>().clone();
    let register_gate = register_event
        .get("accepted")
        .and_then(|value| value.as_bool())
        == Some(true)
        && after_register_sample
            .get("account_client_text")
            .and_then(|value| value.as_str())
            .is_some_and(|text| text.contains("ACCOUNT signed_in") && text.contains("register"));
    let login_gate = login_event
        .get("accepted")
        .and_then(|value| value.as_bool())
        == Some(true)
        && after_login_sample
            .get("account_client_text")
            .and_then(|value| value.as_str())
            .is_some_and(|text| text.contains("ACCOUNT signed_in") && text.contains("login"));
    let continue_gate = continue_event
        .get("accepted")
        .and_then(|value| value.as_bool())
        == Some(true)
        && final_sample
            .get("account_client_text")
            .and_then(|value| value.as_str())
            .is_some_and(|text| text.contains("ACCOUNT signed_in") && text.contains("session"));
    let no_cex_gate = runtime
        .session_account_history
        .iter()
        .all(|entry| !entry.contains("cex_runtime_player_client_allowed=true"));
    let character_identity_gate = final_sample
        .get("character_display_name")
        .and_then(|value| value.as_str())
        == Some("Local Trillionnium Player")
        && runtime
            .session_account_history
            .iter()
            .any(|entry| entry == "account_profile_bound_to_character_identity");
    let account_identity_persistence_gate = restored_character.display_name
        == "Local Trillionnium Player"
        && restored_runtime.session_account_auth_state == "signed_in"
        && restored_runtime.session_account_last_action == "session"
        && restored_runtime.session_account_session_bound
        && restored_runtime
            .session_account_history
            .iter()
            .any(|entry| entry == "account_profile_bound_to_character_identity");
    let green = register_gate
        && login_gate
        && continue_gate
        && character_identity_gate
        && account_identity_persistence_gate
        && runtime.session_account_session_bound
        && runtime.session_account_auth_state == "signed_in"
        && no_cex_gate;
    json!({
        "contract_version": TRILLIONNIUM_WORLD_BEVY_ACCOUNT_TITLE_FLOW_CONTRACT,
        "account_client_contract": TRILLIONNIUM_WORLD_BEVY_ACCOUNT_CLIENT_BOUNDARY_CONTRACT,
        "account_api_contract": WORLD_ACCOUNT_API_CONTRACT,
        "account_boundary_contract": WORLD_ACCOUNT_CLIENT_BOUNDARY_CONTRACT,
        "actor_id": actor_id,
        "player_client_owner": "trnm-world-bevy",
        "account_api_owner": "trillionnium_world_account_api",
        "title_actions": ["ACCOUNT:REGISTER", "ACCOUNT:LOGIN", "ACCOUNT:CONTINUE"],
        "session_account_auth_state": runtime.session_account_auth_state,
        "session_account_display_name": runtime.session_account_display_name,
        "session_account_last_action": runtime.session_account_last_action,
        "session_account_session_bound": runtime.session_account_session_bound,
        "session_account_history": runtime.session_account_history,
        "restored_account_character_display_name": restored_character.display_name,
        "restored_account_auth_state": restored_runtime.session_account_auth_state,
        "restored_account_last_action": restored_runtime.session_account_last_action,
        "restored_account_session_bound": restored_runtime.session_account_session_bound,
        "passwords_tokens_or_cookie_values_logged": false,
        "cex_runtime_player_client_allowed": false,
        "register_gate": register_gate,
        "login_gate": login_gate,
        "continue_gate": continue_gate,
        "character_identity_gate": character_identity_gate,
        "account_identity_persistence_gate": account_identity_persistence_gate,
        "no_cex_gate": no_cex_gate,
        "green": green,
        "source_of_truth": "Bevy title buttons drive Trillionnium-owned account API decisions without cex_runtime",
        "initial_sample": initial_sample,
        "register_event": register_event,
        "after_register_sample": after_register_sample,
        "login_event": login_event,
        "after_login_sample": after_login_sample,
        "continue_event": continue_event,
        "final_sample": final_sample,
    })
}

pub fn native_account_title_flow_evidence_json(actor_id: &str) -> String {
    serde_json::to_string_pretty(&native_account_title_flow_evidence_value(actor_id))
        .expect("native account title flow evidence serializes")
}

pub fn run_native_bevy_client(world: WorldState, actor_id: &str) {
    if native_bool_env_enabled("TRNM_WORLD_BEVY_CLASSIC_RENDERER") {
        #[cfg(not(target_os = "android"))]
        {
            run_native_classic_low_spec_client(world, actor_id);
            return;
        }
        #[cfg(target_os = "android")]
        eprintln!("TRNM_WORLD_BEVY_CLASSIC_RENDERER is host-only; using Bevy renderer on Android");
    }

    let (mut app, _report) = build_rendering_bevy_app(world, actor_id);
    if let Ok(stage) = env::var("TRNM_WORLD_BEVY_INITIAL_STAGE") {
        seed_rendering_app_for_stage(&mut app, actor_id, &stage);
    } else {
        seed_rendering_app_title_menu_state(&mut app);
    }
    app.run();
}

fn native_bool_env_enabled(key: &str) -> bool {
    env::var(key)
        .map(|value| {
            matches!(
                value.as_str(),
                "1" | "true" | "TRUE" | "yes" | "YES" | "on" | "ON"
            )
        })
        .unwrap_or(false)
}

fn native_bool_env_enabled_with_default(key: &str, default: bool) -> bool {
    env::var(key)
        .map(|value| {
            matches!(
                value.as_str(),
                "1" | "true" | "TRUE" | "yes" | "YES" | "on" | "ON"
            )
        })
        .unwrap_or(default)
}

#[cfg(not(target_os = "android"))]
fn classic_player_screen_mode_enabled() -> bool {
    native_bool_env_enabled("TRNM_WORLD_BEVY_CLASSIC_PLAYER_SCREEN")
}

fn native_usize_env_or(key: &str, default: usize) -> usize {
    env::var(key)
        .ok()
        .and_then(|value| value.parse::<usize>().ok())
        .filter(|value| *value >= 320)
        .unwrap_or(default)
}

