#[cfg(not(target_os = "android"))]
#[allow(clippy::too_many_arguments)]
fn classic_draw_rts_environment_life_scene_overlay(
    buffer: &mut [u32],
    width: usize,
    height: usize,
    origin_x: i32,
    origin_y: i32,
    tile_w: i32,
    tile_h: i32,
    scene_id: &str,
    stage: &str,
) {
    let tree_tiles: &[(i32, i32)] = match scene_id {
        "league_coliseum" => &[(2, 2), (9, 2), (10, 3)],
        "arena_outdoor" => &[(1, 2), (3, 1), (10, 2)],
        _ => &[(1, 1), (8, 1), (10, 2)],
    };
    let torch_tiles: &[(i32, i32)] = match scene_id {
        "mentor_training_room" => &[(3, 2), (8, 2), (10, 3)],
        "league_coliseum" => &[(3, 2), (6, 2), (9, 2)],
        _ => &[(4, 2), (6, 3), (9, 3)],
    };
    let water_tiles: &[(i32, i32)] = match scene_id {
        "league_coliseum" => &[(2, 6), (4, 6), (6, 6)],
        "arena_outdoor" => &[(5, 5), (6, 5), (7, 5), (8, 4)],
        _ => &[(6, 5), (7, 5), (8, 4)],
    };
    let banner_tiles: &[(i32, i32)] = match scene_id {
        "league_coliseum" => &[(3, 2), (5, 2), (9, 2), (10, 3)],
        "mentor_training_room" => &[(2, 2), (5, 1), (9, 2)],
        _ => &[(3, 2), (5, 2), (9, 2)],
    };
    let resource_tiles: &[(i32, i32)] = match scene_id {
        "mentor_training_room" => &[(2, 2), (8, 2), (9, 2)],
        "arena_outdoor" => &[(2, 3), (8, 2), (10, 2)],
        _ => &[(2, 2), (8, 2), (9, 2)],
    };
    let dust_tiles: &[(i32, i32)] = match scene_id {
        "league_coliseum" => &[(4, 4), (5, 4), (6, 4), (7, 4), (8, 4)],
        "arena_outdoor" => &[(4, 5), (5, 5), (6, 4), (7, 4), (8, 3)],
        _ => &[(4, 4), (5, 4), (6, 4), (7, 3), (8, 3)],
    };

    match stage {
        "tree_sway" => {
            for (index, tile) in tree_tiles.iter().enumerate() {
                let (center_x, screen_y) =
                    classic_iso_project(origin_x, origin_y, tile_w, tile_h, *tile);
                let base_y = screen_y + tile_h;
                for step in 0..6 {
                    classic_draw_rect(
                        buffer,
                        width,
                        height,
                        center_x - 28 + step * 10 + (index as i32 % 2) * 2,
                        base_y - 82 + (step % 3) * 5,
                        18,
                        5,
                        CLASSIC_RTS_ENVIRONMENT_TREE_SWAY_COLOR,
                    );
                }
                classic_draw_rect(
                    buffer,
                    width,
                    height,
                    center_x - 22 + index as i32,
                    base_y - 66,
                    44,
                    6,
                    CLASSIC_RTS_ENVIRONMENT_TREE_SWAY_COLOR,
                );
            }
        }
        "torch_flicker" => {
            for (index, tile) in torch_tiles.iter().enumerate() {
                let (center_x, screen_y) =
                    classic_iso_project(origin_x, origin_y, tile_w, tile_h, *tile);
                let base_y = screen_y + tile_h;
                for step in 0..5 {
                    classic_draw_rect(
                        buffer,
                        width,
                        height,
                        center_x - 10 + step * 5,
                        base_y - 58 - ((step + index as i32) % 3) * 4,
                        5,
                        12,
                        CLASSIC_RTS_ENVIRONMENT_TORCH_FLICKER_COLOR,
                    );
                }
                classic_draw_rect(
                    buffer,
                    width,
                    height,
                    center_x - 16,
                    base_y - 35,
                    32,
                    4,
                    CLASSIC_RTS_ENVIRONMENT_TORCH_FLICKER_COLOR,
                );
            }
        }
        "water_shimmer" => {
            for (index, tile) in water_tiles.iter().enumerate() {
                let (center_x, screen_y) =
                    classic_iso_project(origin_x, origin_y, tile_w, tile_h, *tile);
                let base_y = screen_y + tile_h;
                for step in 0..4 {
                    classic_draw_rect(
                        buffer,
                        width,
                        height,
                        center_x - 38 + step * 19 + (index as i32 % 2) * 4,
                        base_y - 10 + step * 3,
                        34,
                        4,
                        CLASSIC_RTS_ENVIRONMENT_WATER_SHIMMER_COLOR,
                    );
                }
            }
        }
        "banner_flutter" => {
            for (index, tile) in banner_tiles.iter().enumerate() {
                let (center_x, screen_y) =
                    classic_iso_project(origin_x, origin_y, tile_w, tile_h, *tile);
                let base_y = screen_y + tile_h;
                classic_draw_rect(
                    buffer,
                    width,
                    height,
                    center_x - 2,
                    base_y - 78,
                    4,
                    58,
                    CLASSIC_RTS_ENVIRONMENT_BANNER_FLUTTER_COLOR,
                );
                for step in 0..5 {
                    classic_draw_rect(
                        buffer,
                        width,
                        height,
                        center_x + 2 + step * 8,
                        base_y - 78 + step * 4 + (index as i32 % 2),
                        12,
                        8,
                        CLASSIC_RTS_ENVIRONMENT_BANNER_FLUTTER_COLOR,
                    );
                }
            }
        }
        "resource_glint" => {
            for (index, tile) in resource_tiles.iter().enumerate() {
                let (center_x, screen_y) =
                    classic_iso_project(origin_x, origin_y, tile_w, tile_h, *tile);
                let base_y = screen_y + tile_h;
                for step in 0..8 {
                    classic_draw_rect(
                        buffer,
                        width,
                        height,
                        center_x - 26 + step * 8,
                        base_y - 43 + ((step + index as i32) % 4) * 5,
                        5,
                        5,
                        CLASSIC_RTS_ENVIRONMENT_RESOURCE_GLINT_COLOR,
                    );
                }
                classic_draw_rect(
                    buffer,
                    width,
                    height,
                    center_x - 30,
                    base_y - 18,
                    60,
                    4,
                    CLASSIC_RTS_ENVIRONMENT_RESOURCE_GLINT_COLOR,
                );
            }
        }
        "ambient_dust" => {
            for (index, tile) in dust_tiles.iter().enumerate() {
                let (center_x, screen_y) =
                    classic_iso_project(origin_x, origin_y, tile_w, tile_h, *tile);
                let base_y = screen_y + tile_h;
                for step in 0..5 {
                    classic_draw_rect(
                        buffer,
                        width,
                        height,
                        center_x - 34 + step * 16,
                        base_y - 8 - ((step + index as i32) % 3) * 4,
                        12,
                        4,
                        CLASSIC_RTS_ENVIRONMENT_AMBIENT_DUST_COLOR,
                    );
                }
            }
        }
        _ => {}
    }
}

#[cfg(not(target_os = "android"))]
fn classic_rts_worker_harvest_animation_stage(
    runtime: Option<&NativeFirstPlayableRuntime>,
) -> Option<&'static str> {
    if let Some(runtime) = runtime {
        for event in runtime.rts_combat_event_log.iter().rev() {
            if event.contains("harvest_anim:return_path") {
                return Some("return_path");
            }
            if event.contains("harvest_anim:dropoff_burst") {
                return Some("dropoff_burst");
            }
            if event.contains("harvest_anim:carry_load") {
                return Some("carry_load");
            }
            if event.contains("harvest_anim:resource_pop") {
                return Some("resource_pop");
            }
            if event.contains("harvest_anim:tool_swing") {
                return Some("tool_swing");
            }
            if event.contains("harvest_anim:approach") {
                return Some("approach");
            }
        }
        if !runtime
            .rts_command_queue
            .iter()
            .any(|command| command.contains("harvest_anim:"))
        {
            return None;
        }
        return Some(match runtime.combat_turn % 6 {
            0 => "approach",
            1 => "tool_swing",
            2 => "resource_pop",
            3 => "carry_load",
            4 => "dropoff_burst",
            _ => "return_path",
        });
    }
    None
}

#[cfg(not(target_os = "android"))]
fn classic_draw_harvest_animation_route(
    buffer: &mut [u32],
    width: usize,
    height: usize,
    from: (i32, i32),
    to: (i32, i32),
    color: u32,
    y_offset: i32,
) {
    for step in 0..=9 {
        let x = from.0 + ((to.0 - from.0) * step) / 9;
        let y = from.1 + ((to.1 - from.1) * step) / 9 + y_offset;
        classic_draw_rect(buffer, width, height, x - 2, y - 2, 6, 4, color);
    }
}

#[cfg(not(target_os = "android"))]
#[allow(clippy::too_many_arguments)]
fn classic_draw_rts_worker_harvest_animation_scene_overlay(
    buffer: &mut [u32],
    width: usize,
    height: usize,
    origin_x: i32,
    origin_y: i32,
    tile_w: i32,
    tile_h: i32,
    scene_id: &str,
    stage: &str,
) {
    let worker_tile = match scene_id {
        "mentor_training_room" => (5, 4),
        "arena_outdoor" => (5, 5),
        _ => (5, 5),
    };
    let node_tile = match scene_id {
        "mentor_training_room" => (8, 2),
        "arena_outdoor" => (9, 2),
        _ => (8, 2),
    };
    let dropoff_tile = match scene_id {
        "mentor_training_room" => (3, 2),
        "arena_outdoor" => (4, 4),
        _ => (4, 4),
    };
    let (worker_x, worker_y) = classic_iso_project(origin_x, origin_y, tile_w, tile_h, worker_tile);
    let (node_x, node_y) = classic_iso_project(origin_x, origin_y, tile_w, tile_h, node_tile);
    let (dropoff_x, dropoff_y) =
        classic_iso_project(origin_x, origin_y, tile_w, tile_h, dropoff_tile);
    let worker_ground = (worker_x, worker_y + tile_h - 10);
    let node_ground = (node_x, node_y + tile_h - 8);
    let dropoff_ground = (dropoff_x, dropoff_y + tile_h - 12);

    match stage {
        "approach" => {
            classic_draw_harvest_animation_route(
                buffer,
                width,
                height,
                worker_ground,
                node_ground,
                CLASSIC_RTS_HARVEST_ANIMATION_APPROACH_COLOR,
                0,
            );
            for step in 0..4 {
                classic_draw_rect(
                    buffer,
                    width,
                    height,
                    worker_x - 14 + step * 9,
                    worker_y + tile_h - 38 + (step % 2) * 4,
                    7,
                    12,
                    CLASSIC_RTS_HARVEST_ANIMATION_APPROACH_COLOR,
                );
            }
        }
        "tool_swing" => {
            for step in 0..7 {
                classic_draw_rect(
                    buffer,
                    width,
                    height,
                    node_x - 36 + step * 10,
                    node_y + tile_h - 55 + step * 4,
                    12,
                    5,
                    CLASSIC_RTS_HARVEST_ANIMATION_TOOL_SWING_COLOR,
                );
            }
            classic_draw_rect(
                buffer,
                width,
                height,
                node_x - 14,
                node_y + tile_h - 47,
                28,
                6,
                CLASSIC_RTS_HARVEST_ANIMATION_TOOL_SWING_COLOR,
            );
        }
        "resource_pop" => {
            for step in 0..12 {
                classic_draw_rect(
                    buffer,
                    width,
                    height,
                    node_x - 32 + step * 6,
                    node_y + tile_h - 45 - (step % 4) * 7,
                    5,
                    5,
                    CLASSIC_RTS_HARVEST_ANIMATION_RESOURCE_POP_COLOR,
                );
            }
            classic_draw_rect(
                buffer,
                width,
                height,
                node_x - 24,
                node_y + tile_h - 18,
                48,
                5,
                CLASSIC_RTS_HARVEST_ANIMATION_RESOURCE_POP_COLOR,
            );
        }
        "carry_load" => {
            classic_draw_harvest_animation_route(
                buffer,
                width,
                height,
                node_ground,
                dropoff_ground,
                CLASSIC_RTS_HARVEST_ANIMATION_CARRY_LOAD_COLOR,
                -5,
            );
            for step in 0..5 {
                classic_draw_rect(
                    buffer,
                    width,
                    height,
                    worker_x - 16 + step * 8,
                    worker_y + tile_h - 58 - (step % 2) * 3,
                    7,
                    7,
                    CLASSIC_RTS_HARVEST_ANIMATION_CARRY_LOAD_COLOR,
                );
            }
        }
        "dropoff_burst" => {
            for step in 0..10 {
                classic_draw_rect(
                    buffer,
                    width,
                    height,
                    dropoff_x - 36 + step * 8,
                    dropoff_y + tile_h - 42 - (step % 5) * 5,
                    7,
                    7,
                    CLASSIC_RTS_HARVEST_ANIMATION_DROPOFF_BURST_COLOR,
                );
            }
            classic_draw_rect(
                buffer,
                width,
                height,
                dropoff_x - 28,
                dropoff_y + tile_h - 24,
                56,
                6,
                CLASSIC_RTS_HARVEST_ANIMATION_DROPOFF_BURST_COLOR,
            );
        }
        "return_path" => {
            classic_draw_harvest_animation_route(
                buffer,
                width,
                height,
                dropoff_ground,
                worker_ground,
                CLASSIC_RTS_HARVEST_ANIMATION_RETURN_PATH_COLOR,
                4,
            );
            classic_draw_harvest_animation_route(
                buffer,
                width,
                height,
                dropoff_ground,
                worker_ground,
                CLASSIC_RTS_HARVEST_ANIMATION_RETURN_PATH_COLOR,
                -4,
            );
            for step in 0..6 {
                classic_draw_rect(
                    buffer,
                    width,
                    height,
                    dropoff_x - 22 + step * 8,
                    dropoff_y + tile_h - 33 + (step % 3) * 4,
                    6,
                    5,
                    CLASSIC_RTS_HARVEST_ANIMATION_RETURN_PATH_COLOR,
                );
            }
            for step in 0..5 {
                classic_draw_rect(
                    buffer,
                    width,
                    height,
                    worker_x - 18 + step * 9,
                    worker_y + tile_h - 25 + (step % 2) * 5,
                    8,
                    8,
                    CLASSIC_RTS_HARVEST_ANIMATION_RETURN_PATH_COLOR,
                );
            }
        }
        _ => {}
    }
}

#[cfg(not(target_os = "android"))]
fn classic_rts_production_spawn_animation_stage(
    runtime: Option<&NativeFirstPlayableRuntime>,
) -> Option<&'static str> {
    if let Some(runtime) = runtime {
        for event in runtime.rts_combat_event_log.iter().rev() {
            if event.contains("production_spawn_anim:supply_flash") {
                return Some("supply_flash");
            }
            if event.contains("production_spawn_anim:formation_join") {
                return Some("formation_join");
            }
            if event.contains("production_spawn_anim:rally_flag") {
                return Some("rally_flag");
            }
            if event.contains("production_spawn_anim:spawn_door") {
                return Some("spawn_door");
            }
            if event.contains("production_spawn_anim:training_tick") {
                return Some("training_tick");
            }
            if event.contains("production_spawn_anim:queue_pulse") {
                return Some("queue_pulse");
            }
        }
        if !runtime
            .rts_command_queue
            .iter()
            .any(|command| command.contains("production_spawn_anim:"))
        {
            return None;
        }
        return Some(match runtime.combat_turn % 6 {
            0 => "queue_pulse",
            1 => "training_tick",
            2 => "spawn_door",
            3 => "rally_flag",
            4 => "formation_join",
            _ => "supply_flash",
        });
    }
    None
}

#[cfg(not(target_os = "android"))]
#[allow(clippy::too_many_arguments)]
fn classic_draw_rts_production_spawn_animation_scene_overlay(
    buffer: &mut [u32],
    width: usize,
    height: usize,
    origin_x: i32,
    origin_y: i32,
    tile_w: i32,
    tile_h: i32,
    scene_id: &str,
    stage: &str,
    runtime: &NativeFirstPlayableRuntime,
) {
    let training_tile = classic_rts_structure_tile_for_id(
        if runtime.rts_army_production_state.contains("signal_spire") {
            "signal_spire"
        } else {
            "training_hall"
        },
    );
    let supply_tile = classic_rts_structure_tile_for_id(
        if runtime.rts_army_production_state.contains("field_watch") {
            "field_watch"
        } else {
            "field_lodge"
        },
    );
    let fallback_rally_tile = match scene_id {
        "arena_outdoor" => (7, 4),
        "mentor_training_room" => (6, 4),
        _ => (7, 4),
    };
    let rally_tile = runtime
        .rts_army_rally_tile_ids
        .last()
        .and_then(|tile| classic_parse_rts_tile(tile))
        .unwrap_or(fallback_rally_tile);
    let (train_x, train_y) = classic_iso_project(origin_x, origin_y, tile_w, tile_h, training_tile);
    let (supply_x, supply_y) = classic_iso_project(origin_x, origin_y, tile_w, tile_h, supply_tile);
    let (rally_x, rally_y) = classic_iso_project(origin_x, origin_y, tile_w, tile_h, rally_tile);
    let train_ground = (train_x, train_y + tile_h - 12);
    let rally_ground = (rally_x, rally_y + tile_h - 8);

    match stage {
        "queue_pulse" => {
            for ring in 0..4 {
                classic_draw_iso_ellipse(
                    buffer,
                    width,
                    height,
                    train_x,
                    train_y + tile_h - 18 - ring * 6,
                    34 + ring * 6,
                    9 + ring * 2,
                    CLASSIC_RTS_PRODUCTION_SPAWN_QUEUE_PULSE_COLOR,
                );
            }
            for index in 0..5 {
                classic_draw_rect(
                    buffer,
                    width,
                    height,
                    train_x - 42 + index * 18,
                    train_y + tile_h - 70 - (index % 2) * 5,
                    12,
                    10,
                    CLASSIC_RTS_PRODUCTION_SPAWN_QUEUE_PULSE_COLOR,
                );
            }
        }
        "training_tick" => {
            let progress_width = (runtime.rts_training_progress_percent.max(58) as i32 * 82) / 100;
            classic_draw_rect(
                buffer,
                width,
                height,
                train_x - 44,
                train_y + tile_h - 64,
                88,
                8,
                CLASSIC_RTS_STRATEGY_PANEL_BORDER_COLOR,
            );
            classic_draw_rect(
                buffer,
                width,
                height,
                train_x - 41,
                train_y + tile_h - 62,
                progress_width,
                4,
                CLASSIC_RTS_PRODUCTION_SPAWN_TRAINING_TICK_COLOR,
            );
            for tick in 0..7 {
                classic_draw_rect(
                    buffer,
                    width,
                    height,
                    train_x - 34 + tick * 11,
                    train_y + tile_h - 51 + (tick % 3) * 3,
                    7,
                    16,
                    CLASSIC_RTS_PRODUCTION_SPAWN_TRAINING_TICK_COLOR,
                );
            }
        }
        "spawn_door" => {
            classic_draw_rect(
                buffer,
                width,
                height,
                train_x - 28,
                train_y + tile_h - 48,
                56,
                9,
                CLASSIC_RTS_PRODUCTION_SPAWN_DOOR_COLOR,
            );
            for panel in 0..5 {
                classic_draw_rect(
                    buffer,
                    width,
                    height,
                    train_x - 30 + panel * 15,
                    train_y + tile_h - 39 + (panel % 2) * 5,
                    11,
                    28,
                    CLASSIC_RTS_PRODUCTION_SPAWN_DOOR_COLOR,
                );
            }
            for step in 0..4 {
                classic_draw_iso_ellipse(
                    buffer,
                    width,
                    height,
                    train_x + 20 + step * 15,
                    train_y + tile_h - 8 + step * 2,
                    16,
                    5,
                    CLASSIC_RTS_PRODUCTION_SPAWN_DOOR_COLOR,
                );
            }
        }
        "rally_flag" => {
            for step in 0..=11 {
                let x = train_ground.0 + ((rally_ground.0 - train_ground.0) * step) / 11;
                let y = train_ground.1 + ((rally_ground.1 - train_ground.1) * step) / 11;
                classic_draw_rect(
                    buffer,
                    width,
                    height,
                    x - 3,
                    y - 2,
                    7,
                    4,
                    CLASSIC_RTS_PRODUCTION_SPAWN_RALLY_FLAG_COLOR,
                );
            }
            classic_draw_rect(
                buffer,
                width,
                height,
                rally_x - 3,
                rally_y + tile_h - 54,
                6,
                48,
                CLASSIC_RTS_PRODUCTION_SPAWN_RALLY_FLAG_COLOR,
            );
            for stripe in 0..4 {
                classic_draw_rect(
                    buffer,
                    width,
                    height,
                    rally_x + 2,
                    rally_y + tile_h - 53 + stripe * 9,
                    34 - stripe * 4,
                    7,
                    CLASSIC_RTS_PRODUCTION_SPAWN_RALLY_FLAG_COLOR,
                );
            }
        }
        "formation_join" => {
            let mut formation_tiles = runtime
                .rts_army_spawned_unit_ids
                .iter()
                .enumerate()
                .map(|(index, unit_id)| classic_rts_player_army_unit_tile_for_id(unit_id, index))
                .collect::<Vec<_>>();
            if formation_tiles.len() < 4 {
                formation_tiles.extend([(5, 5), (6, 5), (6, 4), (7, 4)]);
            }
            for (index, tile) in formation_tiles.iter().take(6).enumerate() {
                let (unit_x, unit_y) =
                    classic_iso_project(origin_x, origin_y, tile_w, tile_h, *tile);
                classic_draw_iso_ellipse(
                    buffer,
                    width,
                    height,
                    unit_x,
                    unit_y + tile_h - 8,
                    22,
                    7,
                    CLASSIC_RTS_PRODUCTION_SPAWN_FORMATION_JOIN_COLOR,
                );
                classic_draw_rect(
                    buffer,
                    width,
                    height,
                    unit_x - 10,
                    unit_y + tile_h - 42 - (index as i32 % 2) * 4,
                    20,
                    18,
                    CLASSIC_RTS_PRODUCTION_SPAWN_FORMATION_JOIN_COLOR,
                );
            }
            classic_draw_rect(
                buffer,
                width,
                height,
                rally_x - 46,
                rally_y + tile_h - 14,
                92,
                5,
                CLASSIC_RTS_PRODUCTION_SPAWN_FORMATION_JOIN_COLOR,
            );
        }
        "supply_flash" => {
            classic_draw_iso_ellipse(
                buffer,
                width,
                height,
                supply_x,
                supply_y + tile_h - 15,
                46,
                13,
                CLASSIC_RTS_PRODUCTION_SPAWN_SUPPLY_FLASH_COLOR,
            );
            for ray in 0..8 {
                classic_draw_rect(
                    buffer,
                    width,
                    height,
                    supply_x - 50 + ray * 14,
                    supply_y + tile_h - 66 + (ray % 4) * 9,
                    10,
                    20,
                    CLASSIC_RTS_PRODUCTION_SPAWN_SUPPLY_FLASH_COLOR,
                );
            }
            let supply_width = if runtime.rts_army_supply_cap == 0 {
                0
            } else {
                (runtime
                    .rts_army_supply_used
                    .min(runtime.rts_army_supply_cap) as i32
                    * 92)
                    / runtime.rts_army_supply_cap.max(1) as i32
            };
            classic_draw_rect(
                buffer,
                width,
                height,
                supply_x - 50,
                supply_y + tile_h - 88,
                100,
                9,
                CLASSIC_RTS_STRATEGY_PANEL_BORDER_COLOR,
            );
            classic_draw_rect(
                buffer,
                width,
                height,
                supply_x - 46,
                supply_y + tile_h - 86,
                supply_width.max(32),
                5,
                CLASSIC_RTS_PRODUCTION_SPAWN_SUPPLY_FLASH_COLOR,
            );
        }
        _ => {}
    }
}

#[cfg(not(target_os = "android"))]
fn classic_rts_unit_status_portrait_stage(
    runtime: Option<&NativeFirstPlayableRuntime>,
) -> Option<&'static str> {
    if let Some(runtime) = runtime {
        for event in runtime.rts_combat_event_log.iter().rev() {
            if event.contains("unit_status_portrait:multi_select") {
                return Some("multi_select");
            }
            if event.contains("unit_status_portrait:structure") {
                return Some("structure");
            }
            if event.contains("unit_status_portrait:creep_target") {
                return Some("creep_target");
            }
            if event.contains("unit_status_portrait:commander") {
                return Some("commander");
            }
            if event.contains("unit_status_portrait:guard") {
                return Some("guard");
            }
            if event.contains("unit_status_portrait:worker") {
                return Some("worker");
            }
        }
        if !runtime
            .rts_command_queue
            .iter()
            .any(|command| command.contains("unit_status_portrait:"))
        {
            return None;
        }
        return Some(match runtime.combat_turn % 6 {
            0 => "worker",
            1 => "guard",
            2 => "commander",
            3 => "creep_target",
            4 => "structure",
            _ => "multi_select",
        });
    }
    None
}

#[cfg(not(target_os = "android"))]
fn classic_unit_status_portrait_unit_id(
    runtime: &NativeFirstPlayableRuntime,
    stage: &str,
) -> String {
    match stage {
        "worker" => runtime
            .rts_selected_unit_ids
            .iter()
            .find(|id| id.contains("worker"))
            .cloned()
            .unwrap_or_else(|| "square_worker_carry".to_string()),
        "guard" => runtime
            .rts_selected_unit_ids
            .iter()
            .find(|id| id.contains("guard"))
            .cloned()
            .unwrap_or_else(|| "arena_guard_left".to_string()),
        "commander" => runtime
            .rts_commander_unit_id
            .clone()
            .unwrap_or_else(|| "mirror_captain".to_string()),
        "creep_target" => runtime
            .rts_attack_target_id
            .clone()
            .unwrap_or_else(|| "arena_creep_attack".to_string()),
        "structure" => runtime
            .rts_completed_structure_ids
            .first()
            .cloned()
            .unwrap_or_else(|| "training_hall".to_string()),
        _ => runtime
            .rts_selected_unit_ids
            .first()
            .cloned()
            .unwrap_or_else(|| "player".to_string()),
    }
}

#[cfg(not(target_os = "android"))]
#[allow(clippy::too_many_arguments)]
fn classic_draw_rts_unit_status_portrait_overlay(
    buffer: &mut [u32],
    width: usize,
    height: usize,
    runtime: &NativeFirstPlayableRuntime,
    stage: &str,
) {
    let panel_w = 304_i32;
    let panel_h = 142_i32;
    let x = (width as i32 - panel_w - 18).max(12);
    let y = (height as i32 - panel_h - 18).max(120);
    let unit_id = classic_unit_status_portrait_unit_id(runtime, stage);
    let health = runtime
        .rts_unit_health_percents
        .first()
        .copied()
        .unwrap_or_else(|| {
            if stage == "structure" {
                runtime
                    .rts_structure_health_percents
                    .first()
                    .copied()
                    .unwrap_or(86)
            } else if stage == "creep_target" {
                runtime.rts_target_health_percent.max(1)
            } else {
                88
            }
        });
    let mana = runtime
        .rts_ability_cooldown_percents
        .first()
        .copied()
        .map(|cooldown| 100_u8.saturating_sub(cooldown))
        .unwrap_or(68);
    let xp = (runtime.xp % 100) as u8;

    classic_draw_rect(
        buffer,
        width,
        height,
        x,
        y,
        panel_w,
        panel_h,
        CLASSIC_RTS_FIDELITY_PANEL_COLOR,
    );
    for (border_x, border_y, border_w, border_h) in [
        (x, y, panel_w, 3),
        (x, y + panel_h - 3, panel_w, 3),
        (x, y, 3, panel_h),
        (x + panel_w - 3, y, 3, panel_h),
    ] {
        classic_draw_rect(
            buffer,
            width,
            height,
            border_x,
            border_y,
            border_w,
            border_h,
            CLASSIC_RTS_STATUS_PORTRAIT_FRAME_COLOR,
        );
    }
    classic_draw_text(
        buffer,
        width,
        height,
        x + 96,
        y + 10,
        &classic_catalog_text_label(&format!("STATUS {}", stage.replace('_', " ")), 26),
        1,
        CLASSIC_RTS_STATUS_ROLE_BADGE_COLOR,
    );
    classic_draw_rts_fidelity_portrait(buffer, width, height, x + 16, y + 18, &unit_id, true);

    for (index, (label, value, color)) in [
        ("HP", health, CLASSIC_RTS_STATUS_HEALTH_BAR_COLOR),
        ("EN", mana, CLASSIC_RTS_STATUS_MANA_BAR_COLOR),
        ("XP", xp.max(28), CLASSIC_RTS_STATUS_XP_BAR_COLOR),
    ]
    .iter()
    .enumerate()
    {
        let row_y = y + 32 + index as i32 * 22;
        classic_draw_text(
            buffer,
            width,
            height,
            x + 96,
            row_y,
            label,
            1,
            CLASSIC_HUD_MUTED_TEXT_COLOR,
        );
        classic_draw_rect(
            buffer,
            width,
            height,
            x + 118,
            row_y + 2,
            128,
            8,
            CLASSIC_RTS_STRATEGY_PANEL_BORDER_COLOR,
        );
        classic_draw_rect(
            buffer,
            width,
            height,
            x + 121,
            row_y + 4,
            ((*value).min(100) as i32 * 122) / 100,
            4,
            *color,
        );
    }

    let role_badges = match stage {
        "worker" => ["HAR", "REP", "RET"],
        "guard" => ["ATK", "HLD", "DEF"],
        "commander" => ["AUR", "LVL", "CMD"],
        "creep_target" => ["THR", "ARM", "FOC"],
        "structure" => ["Q", "BLD", "UP"],
        _ => ["G1", "SEL", "ORD"],
    };
    for (index, badge) in role_badges.iter().enumerate() {
        classic_draw_rect(
            buffer,
            width,
            height,
            x + 96 + index as i32 * 48,
            y + 101,
            38,
            17,
            CLASSIC_RTS_STATUS_ROLE_BADGE_COLOR,
        );
        classic_draw_text(
            buffer,
            width,
            height,
            x + 105 + index as i32 * 48,
            y + 106,
            badge,
            1,
            CLASSIC_HUD_TEXT_COLOR,
        );
    }

    let status_entries = match stage {
        "structure" => runtime
            .rts_production_queue
            .iter()
            .take(3)
            .collect::<Vec<_>>(),
        "creep_target" => runtime
            .rts_combat_event_log
            .iter()
            .take(3)
            .collect::<Vec<_>>(),
        _ => runtime.rts_command_queue.iter().take(3).collect::<Vec<_>>(),
    };
    for (index, entry) in status_entries.iter().enumerate() {
        classic_draw_rect(
            buffer,
            width,
            height,
            x + 18 + index as i32 * 88,
            y + 124,
            78,
            11,
            CLASSIC_RTS_STATUS_QUEUE_BADGE_COLOR,
        );
        classic_draw_text(
            buffer,
            width,
            height,
            x + 22 + index as i32 * 88,
            y + 127,
            &classic_catalog_text_label(&entry.replace(':', " "), 11),
            1,
            CLASSIC_RTS_FIDELITY_PANEL_COLOR,
        );
    }

    if stage == "multi_select" {
        for (index, selected_id) in runtime.rts_selected_unit_ids.iter().take(4).enumerate() {
            let card_x = x + 14 + index as i32 * 35;
            let card_y = y + 86;
            classic_draw_rect(
                buffer,
                width,
                height,
                card_x,
                card_y,
                28,
                24,
                CLASSIC_RTS_STATUS_BUFF_BADGE_COLOR,
            );
            classic_draw_rts_fidelity_portrait(
                buffer,
                width,
                height,
                card_x + 3,
                card_y + 3,
                selected_id,
                index == 0,
            );
        }
    } else {
        classic_draw_rect(
            buffer,
            width,
            height,
            x + 18,
            y + 88,
            58,
            16,
            CLASSIC_RTS_STATUS_BUFF_BADGE_COLOR,
        );
        classic_draw_text(
            buffer,
            width,
            height,
            x + 24,
            y + 93,
            &classic_catalog_text_label(&unit_id.replace('_', " "), 12),
            1,
            CLASSIC_HUD_TEXT_COLOR,
        );
    }
}

#[cfg(not(target_os = "android"))]
fn classic_rts_selection_command_feedback_stage(
    runtime: Option<&NativeFirstPlayableRuntime>,
) -> Option<&'static str> {
    if let Some(runtime) = runtime {
        for event in runtime
            .rts_combat_event_log
            .iter()
            .rev()
            .chain(runtime.rts_command_queue.iter().rev())
        {
            if event.contains("selection_command_feedback:invalid_order") {
                return Some("invalid_order");
            }
            if event.contains("selection_command_feedback:attack_lock") {
                return Some("attack_lock");
            }
            if event.contains("selection_command_feedback:move_line") {
                return Some("move_line");
            }
            if event.contains("selection_command_feedback:rally_preview") {
                return Some("rally_preview");
            }
            if event.contains("selection_command_feedback:selection_confirm") {
                return Some("selection_confirm");
            }
            if event.contains("selection_command_feedback:marquee_start") {
                return Some("marquee_start");
            }
        }
        if !runtime
            .rts_command_queue
            .iter()
            .any(|command| command.contains("selection_command_feedback:"))
        {
            return None;
        }
        return Some(match runtime.combat_turn % 6 {
            0 => "marquee_start",
            1 => "selection_confirm",
            2 => "rally_preview",
            3 => "move_line",
            4 => "attack_lock",
            _ => "invalid_order",
        });
    }
    None
}

#[cfg(not(target_os = "android"))]
#[allow(clippy::too_many_arguments)]
fn classic_draw_rts_selection_command_feedback_overlay(
    buffer: &mut [u32],
    width: usize,
    height: usize,
    runtime: &NativeFirstPlayableRuntime,
    stage: &str,
) {
    let origin_x = (width as i32 / 2).clamp(250, (width as i32 - 280).max(340));
    let origin_y = 82_i32;
    let status_x = 116_i32;
    let status_y = (height as i32 - 152).max(172);

    classic_draw_rect(
        buffer,
        width,
        height,
        status_x - 8,
        status_y - 28,
        262,
        70,
        CLASSIC_RTS_STRATEGY_PANEL_COLOR,
    );
    classic_draw_rect(
        buffer,
        width,
        height,
        status_x - 8,
        status_y - 28,
        262,
        3,
        CLASSIC_RTS_SELECTION_FEEDBACK_ACK_COLOR,
    );
    classic_draw_text(
        buffer,
        width,
        height,
        status_x,
        status_y - 18,
        &classic_catalog_text_label(&format!("ORDER FEEDBACK {}", stage.replace('_', " ")), 34),
        1,
        CLASSIC_RTS_SELECTION_FEEDBACK_ACK_COLOR,
    );
    classic_draw_text(
        buffer,
        width,
        height,
        status_x,
        status_y - 4,
        &classic_catalog_text_label(
            &format!(
                "SEL {} CMD {}",
                runtime.rts_selected_unit_ids.len(),
                runtime.rts_command_queue.len()
            ),
            32,
        ),
        1,
        CLASSIC_HUD_TEXT_COLOR,
    );

    let selection_anchor = (origin_x - 88, origin_y + 132);
    let rally_anchor = (origin_x + 62, origin_y + 78);
    let target_anchor = (origin_x + 164, origin_y + 118);
    match stage {
        "marquee_start" => {
            let x = origin_x - 178;
            let y = origin_y + 92;
            let w = 176;
            let h = 94;
            for (rx, ry, rw, rh) in [
                (x, y, w, 3),
                (x, y + h, w, 3),
                (x, y, 3, h),
                (x + w, y, 3, h),
            ] {
                classic_draw_rect(
                    buffer,
                    width,
                    height,
                    rx,
                    ry,
                    rw,
                    rh,
                    CLASSIC_RTS_SELECTION_FEEDBACK_MARQUEE_COLOR,
                );
            }
            for (index, tile_id) in runtime
                .rts_selection_box_tile_ids
                .iter()
                .take(6)
                .enumerate()
            {
                let tile_x = x + 16 + (index as i32 % 3) * 48;
                let tile_y = y + 16 + (index as i32 / 3) * 32;
                classic_draw_rect(
                    buffer,
                    width,
                    height,
                    tile_x,
                    tile_y,
                    34,
                    20,
                    CLASSIC_RTS_SELECTION_FEEDBACK_MARQUEE_COLOR,
                );
                classic_draw_text(
                    buffer,
                    width,
                    height,
                    tile_x + 5,
                    tile_y + 6,
                    &classic_catalog_text_label(tile_id, 5),
                    1,
                    CLASSIC_RTS_STRATEGY_PANEL_COLOR,
                );
            }
        }
        "selection_confirm" => {
            for (index, unit_id) in runtime.rts_selected_unit_ids.iter().take(5).enumerate() {
                let x = selection_anchor.0 + index as i32 * 38;
                let y = selection_anchor.1 + (index as i32 % 2) * 18;
                classic_draw_rect(
                    buffer,
                    width,
                    height,
                    x - 14,
                    y + 18,
                    30,
                    5,
                    CLASSIC_RTS_SELECTION_FEEDBACK_CONFIRM_COLOR,
                );
                classic_draw_rect(
                    buffer,
                    width,
                    height,
                    x - 18,
                    y + 11,
                    5,
                    18,
                    CLASSIC_RTS_SELECTION_FEEDBACK_CONFIRM_COLOR,
                );
                classic_draw_rts_fidelity_portrait(
                    buffer,
                    width,
                    height,
                    x - 12,
                    y - 4,
                    unit_id,
                    index == 0,
                );
            }
        }
        "rally_preview" => {
            for step in 0..12 {
                let x = selection_anchor.0 + ((rally_anchor.0 - selection_anchor.0) * step) / 11;
                let y = selection_anchor.1 + ((rally_anchor.1 - selection_anchor.1) * step) / 11;
                classic_draw_rect(
                    buffer,
                    width,
                    height,
                    x - 3,
                    y - 3,
                    7,
                    7,
                    CLASSIC_RTS_SELECTION_FEEDBACK_RALLY_COLOR,
                );
            }
            classic_draw_rect(
                buffer,
                width,
                height,
                rally_anchor.0 - 4,
                rally_anchor.1 - 42,
                8,
                42,
                CLASSIC_RTS_SELECTION_FEEDBACK_RALLY_COLOR,
            );
            classic_draw_rect(
                buffer,
                width,
                height,
                rally_anchor.0 + 2,
                rally_anchor.1 - 42,
                46,
                22,
                CLASSIC_RTS_SELECTION_FEEDBACK_RALLY_COLOR,
            );
        }
        "move_line" => {
            for step in 0..14 {
                let x = selection_anchor.0 + ((target_anchor.0 - selection_anchor.0) * step) / 13;
                let y = selection_anchor.1 + ((target_anchor.1 - selection_anchor.1) * step) / 13;
                classic_draw_rect(
                    buffer,
                    width,
                    height,
                    x - 2,
                    y - 2,
                    5,
                    5,
                    CLASSIC_RTS_SELECTION_FEEDBACK_MOVE_COLOR,
                );
            }
            for radius in [10, 16, 23] {
                classic_draw_rect(
                    buffer,
                    width,
                    height,
                    target_anchor.0 - radius,
                    target_anchor.1 - radius,
                    radius * 2,
                    3,
                    CLASSIC_RTS_SELECTION_FEEDBACK_MOVE_COLOR,
                );
                classic_draw_rect(
                    buffer,
                    width,
                    height,
                    target_anchor.0 - radius,
                    target_anchor.1 + radius,
                    radius * 2,
                    3,
                    CLASSIC_RTS_SELECTION_FEEDBACK_MOVE_COLOR,
                );
                classic_draw_rect(
                    buffer,
                    width,
                    height,
                    target_anchor.0 - radius,
                    target_anchor.1 - radius,
                    3,
                    radius * 2,
                    CLASSIC_RTS_SELECTION_FEEDBACK_MOVE_COLOR,
                );
                classic_draw_rect(
                    buffer,
                    width,
                    height,
                    target_anchor.0 + radius,
                    target_anchor.1 - radius,
                    3,
                    radius * 2,
                    CLASSIC_RTS_SELECTION_FEEDBACK_MOVE_COLOR,
                );
            }
        }
        "attack_lock" => {
            for step in 0..16 {
                let x = selection_anchor.0 + ((target_anchor.0 - selection_anchor.0) * step) / 15;
                let y = selection_anchor.1 + ((target_anchor.1 - selection_anchor.1) * step) / 15;
                classic_draw_rect(
                    buffer,
                    width,
                    height,
                    x - 3,
                    y - 3,
                    7,
                    7,
                    CLASSIC_RTS_SELECTION_FEEDBACK_ATTACK_COLOR,
                );
            }
            classic_draw_rect(
                buffer,
                width,
                height,
                target_anchor.0 - 34,
                target_anchor.1 - 3,
                68,
                6,
                CLASSIC_RTS_SELECTION_FEEDBACK_ATTACK_COLOR,
            );
            classic_draw_rect(
                buffer,
                width,
                height,
                target_anchor.0 - 3,
                target_anchor.1 - 34,
                6,
                68,
                CLASSIC_RTS_SELECTION_FEEDBACK_ATTACK_COLOR,
            );
            classic_draw_rect(
                buffer,
                width,
                height,
                target_anchor.0 - 20,
                target_anchor.1 - 20,
                40,
                5,
                CLASSIC_RTS_SELECTION_FEEDBACK_ATTACK_COLOR,
            );
            classic_draw_rect(
                buffer,
                width,
                height,
                target_anchor.0 - 20,
                target_anchor.1 + 15,
                40,
                5,
                CLASSIC_RTS_SELECTION_FEEDBACK_ATTACK_COLOR,
            );
        }
        "invalid_order" => {
            let x = origin_x - 136;
            let y = origin_y + 82;
            classic_draw_rect(
                buffer,
                width,
                height,
                x,
                y,
                276,
                46,
                CLASSIC_RTS_SELECTION_FEEDBACK_ERROR_COLOR,
            );
            classic_draw_rect(buffer, width, height, x + 6, y + 6, 264, 34, 0x301812);
            classic_draw_text(
                buffer,
                width,
                height,
                x + 18,
                y + 16,
                "INVALID ORDER - NEED CLEAR PATH",
                1,
                CLASSIC_RTS_SELECTION_FEEDBACK_ERROR_COLOR,
            );
            for index in 0..5 {
                classic_draw_rect(
                    buffer,
                    width,
                    height,
                    x + 28 + index * 44,
                    y + 58,
                    30,
                    30,
                    CLASSIC_RTS_SELECTION_FEEDBACK_ERROR_COLOR,
                );
                classic_draw_rect(
                    buffer,
                    width,
                    height,
                    x + 34 + index * 44,
                    y + 64,
                    18,
                    18,
                    0x301812,
                );
            }
        }
        _ => {}
    }
}

#[cfg(not(target_os = "android"))]
fn classic_rts_ability_tooltip_telegraph_stage(
    runtime: Option<&NativeFirstPlayableRuntime>,
) -> Option<&'static str> {
    if let Some(runtime) = runtime {
        for event in runtime
            .rts_combat_event_log
            .iter()
            .rev()
            .chain(runtime.rts_command_queue.iter().rev())
        {
            if event.contains("ability_tooltip_telegraph:resource_warning") {
                return Some("resource_warning");
            }
            if event.contains("ability_tooltip_telegraph:queue_explain") {
                return Some("queue_explain");
            }
            if event.contains("ability_tooltip_telegraph:cooldown_sweep") {
                return Some("cooldown_sweep");
            }
            if event.contains("ability_tooltip_telegraph:cast_windup") {
                return Some("cast_windup");
            }
            if event.contains("ability_tooltip_telegraph:range_preview") {
                return Some("range_preview");
            }
            if event.contains("ability_tooltip_telegraph:hover_tooltip") {
                return Some("hover_tooltip");
            }
        }
        if !runtime
            .rts_command_queue
            .iter()
            .any(|command| command.contains("ability_tooltip_telegraph:"))
        {
            return None;
        }
        return Some(match runtime.combat_turn % 6 {
            0 => "hover_tooltip",
            1 => "range_preview",
            2 => "cast_windup",
            3 => "cooldown_sweep",
            4 => "queue_explain",
            _ => "resource_warning",
        });
    }
    None
}

#[cfg(not(target_os = "android"))]
#[allow(clippy::too_many_arguments)]
fn classic_draw_rts_ability_tooltip_telegraph_overlay(
    buffer: &mut [u32],
    width: usize,
    height: usize,
    runtime: &NativeFirstPlayableRuntime,
    stage: &str,
) {
    if width < 580 || height < 300 {
        return;
    }
    let center_x = width as i32 / 2;
    let origin_y = 64_i32;
    let caster = (center_x - 134, origin_y + 150);
    let target = (center_x + 126, origin_y + 118);
    let tooltip_x = (width as i32 - 318).max(250);
    let tooltip_y = (height as i32 - 172).max(126);
    let ability = runtime
        .rts_active_ability_id
        .as_deref()
        .unwrap_or("rally_aura");

    classic_draw_rect(
        buffer,
        width,
        height,
        tooltip_x,
        tooltip_y,
        304,
        78,
        CLASSIC_RTS_STRATEGY_PANEL_COLOR,
    );
    classic_draw_rect(
        buffer,
        width,
        height,
        tooltip_x,
        tooltip_y,
        304,
        3,
        CLASSIC_RTS_ABILITY_TELEGRAPH_TOOLTIP_COLOR,
    );
    classic_draw_text(
        buffer,
        width,
        height,
        tooltip_x + 10,
        tooltip_y + 10,
        &classic_catalog_text_label(&format!("ABILITY {}", ability.replace('_', " ")), 30),
        1,
        CLASSIC_RTS_ABILITY_TELEGRAPH_TOOLTIP_COLOR,
    );
    classic_draw_text(
        buffer,
        width,
        height,
        tooltip_x + 10,
        tooltip_y + 25,
        &classic_catalog_text_label(
            &format!(
                "SUPPLY {}/{} GOLD {}",
                runtime.rts_army_supply_used, runtime.rts_army_supply_cap, runtime.coins
            ),
            34,
        ),
        1,
        CLASSIC_HUD_TEXT_COLOR,
    );

    match stage {
        "hover_tooltip" => {
            classic_draw_rect(
                buffer,
                width,
                height,
                tooltip_x + 8,
                tooltip_y + 43,
                282,
                23,
                CLASSIC_RTS_ABILITY_TELEGRAPH_TOOLTIP_COLOR,
            );
            classic_draw_rect(
                buffer,
                width,
                height,
                tooltip_x + 12,
                tooltip_y + 47,
                274,
                15,
                CLASSIC_RTS_FIDELITY_PANEL_COLOR,
            );
            for (index, command) in runtime.rts_ability_command_ids.iter().take(6).enumerate() {
                let x = tooltip_x + 14 + index as i32 * 44;
                classic_draw_rect(
                    buffer,
                    width,
                    height,
                    x,
                    tooltip_y + 51,
                    33,
                    7,
                    CLASSIC_RTS_ABILITY_TELEGRAPH_TOOLTIP_COLOR,
                );
                classic_draw_text(
                    buffer,
                    width,
                    height,
                    x + 3,
                    tooltip_y + 47,
                    &classic_catalog_text_label(command, 4),
                    1,
                    CLASSIC_HUD_TEXT_COLOR,
                );
            }
        }
        "range_preview" => {
            for radius in [36, 58, 82] {
                classic_draw_rect(
                    buffer,
                    width,
                    height,
                    target.0 - radius,
                    target.1 - radius / 2,
                    radius * 2,
                    4,
                    CLASSIC_RTS_ABILITY_TELEGRAPH_RANGE_COLOR,
                );
                classic_draw_rect(
                    buffer,
                    width,
                    height,
                    target.0 - radius,
                    target.1 + radius / 2,
                    radius * 2,
                    4,
                    CLASSIC_RTS_ABILITY_TELEGRAPH_RANGE_COLOR,
                );
                classic_draw_rect(
                    buffer,
                    width,
                    height,
                    target.0 - radius,
                    target.1 - radius / 2,
                    4,
                    radius,
                    CLASSIC_RTS_ABILITY_TELEGRAPH_RANGE_COLOR,
                );
                classic_draw_rect(
                    buffer,
                    width,
                    height,
                    target.0 + radius,
                    target.1 - radius / 2,
                    4,
                    radius,
                    CLASSIC_RTS_ABILITY_TELEGRAPH_RANGE_COLOR,
                );
            }
            for step in 0..9 {
                let x = caster.0 + ((target.0 - caster.0) * step) / 8;
                let y = caster.1 + ((target.1 - caster.1) * step) / 8;
                classic_draw_rect(
                    buffer,
                    width,
                    height,
                    x - 5,
                    y - 5,
                    10,
                    10,
                    CLASSIC_RTS_ABILITY_TELEGRAPH_RANGE_COLOR,
                );
            }
        }
        "cast_windup" => {
            for step in 0..18 {
                let x = caster.0 + ((target.0 - caster.0) * step) / 17;
                let y = caster.1 + ((target.1 - caster.1) * step) / 17;
                classic_draw_rect(
                    buffer,
                    width,
                    height,
                    x - 3,
                    y - 3,
                    7,
                    7,
                    CLASSIC_RTS_ABILITY_TELEGRAPH_WINDUP_COLOR,
                );
            }
            for tick in 0..5 {
                classic_draw_rect(
                    buffer,
                    width,
                    height,
                    caster.0 - 34 + tick * 18,
                    caster.1 - 44,
                    12,
                    36 + tick * 4,
                    CLASSIC_RTS_ABILITY_TELEGRAPH_WINDUP_COLOR,
                );
            }
            classic_draw_rect(
                buffer,
                width,
                height,
                tooltip_x + 12,
                tooltip_y + 49,
                230,
                9,
                CLASSIC_RTS_ABILITY_TELEGRAPH_WINDUP_COLOR,
            );
        }
        "cooldown_sweep" => {
            let grid_x = width as i32 - 204;
            let grid_y = height as i32 - 78;
            for row in 0..3 {
                for col in 0..3 {
                    let index = (row * 3 + col) as usize;
                    let cooldown = runtime
                        .rts_ability_cooldown_percents
                        .get(index)
                        .copied()
                        .unwrap_or(0)
                        .max(if index == 8 { 72 } else { 0 });
                    let cell_x = grid_x + col * 32;
                    let cell_y = grid_y + row * 22;
                    let sweep_h = 4 + ((cooldown.min(100) as i32 * 14) / 100);
                    classic_draw_rect(
                        buffer,
                        width,
                        height,
                        cell_x + 2,
                        cell_y + 18 - sweep_h,
                        25,
                        sweep_h,
                        CLASSIC_RTS_ABILITY_TELEGRAPH_COOLDOWN_COLOR,
                    );
                }
            }
            classic_draw_text(
                buffer,
                width,
                height,
                tooltip_x + 12,
                tooltip_y + 50,
                "COOLDOWN SWEEP / DISABLED CELLS",
                1,
                CLASSIC_RTS_ABILITY_TELEGRAPH_COOLDOWN_COLOR,
            );
        }
        "queue_explain" => {
            classic_draw_rect(
                buffer,
                width,
                height,
                tooltip_x + 8,
                tooltip_y + 43,
                286,
                24,
                CLASSIC_RTS_ABILITY_TELEGRAPH_QUEUE_COLOR,
            );
            classic_draw_rect(
                buffer,
                width,
                height,
                tooltip_x + 13,
                tooltip_y + 48,
                (runtime.rts_training_progress_percent.max(54) as i32 * 244) / 100,
                7,
                CLASSIC_RTS_FIDELITY_PANEL_COLOR,
            );
            for (index, queued) in runtime.rts_production_queue.iter().take(4).enumerate() {
                let x = caster.0 - 96 + index as i32 * 58;
                classic_draw_rect(
                    buffer,
                    width,
                    height,
                    x,
                    caster.1 - 92,
                    48,
                    18,
                    CLASSIC_RTS_ABILITY_TELEGRAPH_QUEUE_COLOR,
                );
                classic_draw_text(
                    buffer,
                    width,
                    height,
                    x + 4,
                    caster.1 - 87,
                    &classic_catalog_text_label(&queued.replace(':', " "), 6),
                    1,
                    CLASSIC_RTS_STRATEGY_PANEL_COLOR,
                );
            }
        }
        "resource_warning" => {
            classic_draw_rect(
                buffer,
                width,
                height,
                tooltip_x + 8,
                tooltip_y + 43,
                286,
                24,
                CLASSIC_RTS_ABILITY_TELEGRAPH_WARNING_COLOR,
            );
            classic_draw_text(
                buffer,
                width,
                height,
                tooltip_x + 16,
                tooltip_y + 51,
                "NOT ENOUGH GOLD OR SUPPLY",
                1,
                CLASSIC_RTS_FIDELITY_PANEL_COLOR,
            );
            for index in 0..6 {
                classic_draw_rect(
                    buffer,
                    width,
                    height,
                    target.0 - 72 + index * 28,
                    target.1 + 52,
                    22,
                    18,
                    CLASSIC_RTS_ABILITY_TELEGRAPH_WARNING_COLOR,
                );
                classic_draw_rect(
                    buffer,
                    width,
                    height,
                    target.0 - 66 + index * 28,
                    target.1 + 58,
                    10,
                    6,
                    CLASSIC_RTS_STRATEGY_PANEL_COLOR,
                );
            }
        }
        _ => {}
    }
}

#[cfg(not(target_os = "android"))]
fn classic_rts_control_group_hotkey_feedback_stage(
    runtime: Option<&NativeFirstPlayableRuntime>,
) -> Option<&'static str> {
    if let Some(runtime) = runtime {
        for event in runtime
            .rts_combat_event_log
            .iter()
            .rev()
            .chain(runtime.rts_command_queue.iter().rev())
        {
            if event.contains("control_group_hotkey_feedback:ability_hotkey_ack") {
                return Some("ability_hotkey_ack");
            }
            if event.contains("control_group_hotkey_feedback:production_hotkey") {
                return Some("production_hotkey");
            }
            if event.contains("control_group_hotkey_feedback:idle_worker_ping") {
                return Some("idle_worker_ping");
            }
            if event.contains("control_group_hotkey_feedback:double_tap_camera") {
                return Some("double_tap_camera");
            }
            if event.contains("control_group_hotkey_feedback:recall_group") {
                return Some("recall_group");
            }
            if event.contains("control_group_hotkey_feedback:assign_group") {
                return Some("assign_group");
            }
        }
        if !runtime
            .rts_command_queue
            .iter()
            .any(|command| command.contains("control_group_hotkey_feedback:"))
        {
            return None;
        }
        return Some(match runtime.combat_turn % 6 {
            0 => "assign_group",
            1 => "recall_group",
            2 => "double_tap_camera",
            3 => "idle_worker_ping",
            4 => "production_hotkey",
            _ => "ability_hotkey_ack",
        });
    }
    None
}

#[cfg(not(target_os = "android"))]
#[allow(clippy::too_many_arguments)]
fn classic_draw_rts_control_group_slot_strip(
    buffer: &mut [u32],
    width: usize,
    height: usize,
    runtime: &NativeFirstPlayableRuntime,
    origin_x: i32,
    origin_y: i32,
    slot_w: i32,
    slot_h: i32,
) {
    let gap = 3_i32;
    for slot_index in 1..=10 {
        let slot = slot_index.to_string();
        let slot_x = origin_x + (slot_index as i32 - 1) * (slot_w + gap);
        let active = classic_rts_control_group_slot_is_active(runtime, &slot);
        let member_count = classic_rts_control_group_slot_member_count(runtime, &slot);
        let occupied = member_count > 0;
        let fill_color = if active {
            CLASSIC_RTS_CONTROL_GROUP_ASSIGN_COLOR
        } else if occupied {
            CLASSIC_RTS_CONTROL_GROUP_SLOT_OCCUPIED_COLOR
        } else {
            CLASSIC_RTS_FIDELITY_PANEL_COLOR
        };
        classic_draw_rect(
            buffer, width, height, slot_x, origin_y, slot_w, slot_h, fill_color,
        );
        classic_draw_rect(
            buffer,
            width,
            height,
            slot_x,
            origin_y,
            slot_w,
            2,
            if occupied {
                CLASSIC_RTS_CONTROL_GROUP_SLOT_COUNT_COLOR
            } else {
                CLASSIC_RTS_STRATEGY_PANEL_BORDER_COLOR
            },
        );
        if occupied {
            let count_bar_w = ((member_count.min(5) as i32) * (slot_w - 6) / 5).max(4);
            classic_draw_rect(
                buffer,
                width,
                height,
                slot_x + 3,
                origin_y + slot_h - 5,
                count_bar_w,
                3,
                CLASSIC_RTS_CONTROL_GROUP_SLOT_COUNT_COLOR,
            );
        }
        classic_draw_text(
            buffer,
            width,
            height,
            slot_x + 6,
            origin_y + 6,
            classic_rts_control_group_slot_label(&slot),
            1,
            if active {
                CLASSIC_RTS_STRATEGY_PANEL_COLOR
            } else {
                CLASSIC_HUD_TEXT_COLOR
            },
        );
        if occupied {
            classic_draw_text(
                buffer,
                width,
                height,
                slot_x + slot_w - 10,
                origin_y + slot_h - 11,
                &member_count.min(9).to_string(),
                1,
                if active {
                    CLASSIC_RTS_STRATEGY_PANEL_COLOR
                } else {
                    CLASSIC_RTS_CONTROL_GROUP_SLOT_COUNT_COLOR
                },
            );
        }
    }
}

#[cfg(not(target_os = "android"))]
fn classic_draw_rts_control_group_slot_strip_for_scene(
    buffer: &mut [u32],
    width: usize,
    height: usize,
    runtime: &NativeFirstPlayableRuntime,
) {
    if runtime.rts_control_group_assignments.is_empty() || width < 580 || height < 300 {
        return;
    }
    let width_i = width as i32;
    let height_i = height as i32;
    if width >= 900 && height >= 540 {
        classic_draw_rts_control_group_slot_strip(
            buffer,
            width,
            height,
            runtime,
            (width_i - 548).max(620),
            7,
            24,
            20,
        );
    } else {
        classic_draw_rts_control_group_slot_strip(
            buffer,
            width,
            height,
            runtime,
            18,
            (height_i - 124).max(54),
            26,
            22,
        );
    }
}

#[cfg(not(target_os = "android"))]
fn classic_draw_rts_control_group_hotkey_feedback_overlay(
    buffer: &mut [u32],
    width: usize,
    height: usize,
    runtime: &NativeFirstPlayableRuntime,
    stage: &str,
) {
    if width < 580 || height < 300 {
        return;
    }
    let panel_x = 18_i32;
    let panel_y = (height as i32 - 154).max(118);
    classic_draw_rect(
        buffer,
        width,
        height,
        panel_x,
        panel_y,
        308,
        100,
        CLASSIC_RTS_STRATEGY_PANEL_COLOR,
    );
    classic_draw_rect(
        buffer,
        width,
        height,
        panel_x,
        panel_y,
        308,
        3,
        CLASSIC_RTS_CONTROL_GROUP_ASSIGN_COLOR,
    );
    classic_draw_text(
        buffer,
        width,
        height,
        panel_x + 10,
        panel_y + 10,
        "CONTROL GROUP SLOTS / HOTKEY FEEDBACK",
        1,
        CLASSIC_HUD_TEXT_COLOR,
    );

    classic_draw_rts_control_group_slot_strip(
        buffer,
        width,
        height,
        runtime,
        panel_x + 12,
        panel_y + 28,
        24,
        24,
    );

    match stage {
        "assign_group" => {
            for (index, unit_id) in runtime.rts_selected_unit_ids.iter().take(5).enumerate() {
                let x = panel_x + 14 + index as i32 * 56;
                classic_draw_rect(
                    buffer,
                    width,
                    height,
                    x,
                    panel_y + 62,
                    46,
                    18,
                    CLASSIC_RTS_CONTROL_GROUP_ASSIGN_COLOR,
                );
                classic_draw_text(
                    buffer,
                    width,
                    height,
                    x + 4,
                    panel_y + 68,
                    &classic_catalog_text_label(unit_id, 5),
                    1,
                    CLASSIC_RTS_STRATEGY_PANEL_COLOR,
                );
            }
            classic_draw_rect(
                buffer,
                width,
                height,
                panel_x + 18,
                panel_y + 86,
                250,
                5,
                CLASSIC_RTS_CONTROL_GROUP_ASSIGN_COLOR,
            );
        }
        "recall_group" => {
            for (index, unit_id) in runtime.rts_selected_unit_ids.iter().take(4).enumerate() {
                let x = width as i32 / 2 - 126 + index as i32 * 72;
                let y = height as i32 / 2 - 58 + (index as i32 % 2) * 34;
                classic_draw_rect(
                    buffer,
                    width,
                    height,
                    x - 16,
                    y - 16,
                    56,
                    5,
                    CLASSIC_RTS_CONTROL_GROUP_RECALL_COLOR,
                );
                classic_draw_rect(
                    buffer,
                    width,
                    height,
                    x - 16,
                    y + 28,
                    56,
                    5,
                    CLASSIC_RTS_CONTROL_GROUP_RECALL_COLOR,
                );
                classic_draw_text(
                    buffer,
                    width,
                    height,
                    x - 10,
                    y + 1,
                    &classic_catalog_text_label(unit_id, 6),
                    1,
                    CLASSIC_RTS_CONTROL_GROUP_RECALL_COLOR,
                );
            }
            classic_draw_text(
                buffer,
                width,
                height,
                panel_x + 18,
                panel_y + 66,
                "GROUP RECALL ACK",
                1,
                CLASSIC_RTS_CONTROL_GROUP_RECALL_COLOR,
            );
        }
        "double_tap_camera" => {
            let camera_x = width as i32 / 2 - 124;
            let camera_y = height as i32 / 2 - 76;
            classic_draw_rect(
                buffer,
                width,
                height,
                camera_x,
                camera_y,
                248,
                6,
                CLASSIC_RTS_CONTROL_GROUP_CAMERA_COLOR,
            );
            classic_draw_rect(
                buffer,
                width,
                height,
                camera_x,
                camera_y + 138,
                248,
                6,
                CLASSIC_RTS_CONTROL_GROUP_CAMERA_COLOR,
            );
            classic_draw_rect(
                buffer,
                width,
                height,
                camera_x,
                camera_y,
                6,
                144,
                CLASSIC_RTS_CONTROL_GROUP_CAMERA_COLOR,
            );
            classic_draw_rect(
                buffer,
                width,
                height,
                camera_x + 242,
                camera_y,
                6,
                144,
                CLASSIC_RTS_CONTROL_GROUP_CAMERA_COLOR,
            );
            for tick in 0..5 {
                classic_draw_rect(
                    buffer,
                    width,
                    height,
                    panel_x + 38 + tick * 32,
                    panel_y + 64,
                    22,
                    22,
                    CLASSIC_RTS_CONTROL_GROUP_CAMERA_COLOR,
                );
            }
        }
        "idle_worker_ping" => {
            for index in 0..6 {
                classic_draw_rect(
                    buffer,
                    width,
                    height,
                    panel_x + 24 + index * 42,
                    panel_y + 60 + (index % 2) * 12,
                    24,
                    24,
                    CLASSIC_RTS_CONTROL_GROUP_IDLE_COLOR,
                );
                classic_draw_rect(
                    buffer,
                    width,
                    height,
                    panel_x + 30 + index * 42,
                    panel_y + 66 + (index % 2) * 12,
                    12,
                    12,
                    CLASSIC_RTS_STRATEGY_PANEL_COLOR,
                );
            }
            classic_draw_text(
                buffer,
                width,
                height,
                panel_x + 18,
                panel_y + 86,
                "IDLE WORKER HOTKEY",
                1,
                CLASSIC_RTS_CONTROL_GROUP_IDLE_COLOR,
            );
        }
        "production_hotkey" => {
            for (index, queued) in runtime.rts_production_queue.iter().take(5).enumerate() {
                let x = panel_x + 14 + index as i32 * 56;
                classic_draw_rect(
                    buffer,
                    width,
                    height,
                    x,
                    panel_y + 62,
                    46,
                    24,
                    CLASSIC_RTS_CONTROL_GROUP_PRODUCTION_COLOR,
                );
                classic_draw_text(
                    buffer,
                    width,
                    height,
                    x + 4,
                    panel_y + 69,
                    &classic_catalog_text_label(&queued.replace(':', " "), 5),
                    1,
                    CLASSIC_RTS_STRATEGY_PANEL_COLOR,
                );
            }
        }
        "ability_hotkey_ack" => {
            for (index, ability) in runtime.rts_ability_command_ids.iter().take(6).enumerate() {
                let x = panel_x + 12 + index as i32 * 45;
                let cooldown = runtime
                    .rts_ability_cooldown_percents
                    .get(index)
                    .copied()
                    .unwrap_or(0);
                classic_draw_rect(
                    buffer,
                    width,
                    height,
                    x,
                    panel_y + 60,
                    34,
                    26,
                    CLASSIC_RTS_CONTROL_GROUP_ABILITY_COLOR,
                );
                classic_draw_rect(
                    buffer,
                    width,
                    height,
                    x + 3,
                    panel_y + 82 - ((cooldown.min(100) as i32 * 18) / 100),
                    28,
                    4 + ((cooldown.min(100) as i32 * 18) / 100),
                    CLASSIC_RTS_FIDELITY_PANEL_COLOR,
                );
                classic_draw_text(
                    buffer,
                    width,
                    height,
                    x + 4,
                    panel_y + 67,
                    &classic_catalog_text_label(ability, 4),
                    1,
                    CLASSIC_RTS_STRATEGY_PANEL_COLOR,
                );
            }
        }
        _ => {}
    }
}

#[cfg(not(target_os = "android"))]
fn classic_draw_rts_scrollable_map_overlay(
    buffer: &mut [u32],
    width: usize,
    height: usize,
    step: &RtsScrollableMapCameraStep,
    stage: &str,
    focus_tile: (i32, i32),
) {
    if width < 580 || height < 300 {
        return;
    }
    let frame_x = (width as i32 / 2 - 238).max(156);
    let frame_y = 54_i32;
    let frame_w = 476_i32;
    let frame_h = 204_i32;
    for (x, y, w, h) in [
        (frame_x, frame_y, frame_w, 4),
        (frame_x, frame_y + frame_h, frame_w, 4),
        (frame_x, frame_y, 4, frame_h),
        (frame_x + frame_w, frame_y, 4, frame_h),
    ] {
        classic_draw_rect(
            buffer,
            width,
            height,
            x,
            y,
            w,
            h,
            CLASSIC_RTS_SCROLL_CAMERA_FRAME_COLOR,
        );
    }
    classic_draw_rect(
        buffer,
        width,
        height,
        frame_x + frame_w / 2 - 24,
        frame_y + frame_h / 2 - 3,
        48,
        6,
        CLASSIC_RTS_SCROLL_CAMERA_FRAME_COLOR,
    );
    classic_draw_rect(
        buffer,
        width,
        height,
        frame_x + frame_w / 2 - 3,
        frame_y + frame_h / 2 - 24,
        6,
        48,
        CLASSIC_RTS_SCROLL_CAMERA_FRAME_COLOR,
    );

    let panel_x = 18_i32;
    let panel_y = (height as i32 - 154).max(118);
    classic_draw_rect(
        buffer,
        width,
        height,
        panel_x,
        panel_y,
        312,
        104,
        CLASSIC_RTS_STRATEGY_PANEL_COLOR,
    );
    classic_draw_rect(
        buffer,
        width,
        height,
        panel_x,
        panel_y,
        312,
        3,
        CLASSIC_RTS_SCROLL_CAMERA_FRAME_COLOR,
    );
    classic_draw_text(
        buffer,
        width,
        height,
        panel_x + 10,
        panel_y + 10,
        "SCROLLABLE RTS MAP CAMERA",
        1,
        CLASSIC_HUD_TEXT_COLOR,
    );
    classic_draw_text(
        buffer,
        width,
        height,
        panel_x + 10,
        panel_y + 26,
        &classic_catalog_text_label(&stage.replace('_', " "), 34),
        1,
        CLASSIC_RTS_SCROLL_CAMERA_FRAME_COLOR,
    );
    classic_draw_text(
        buffer,
        width,
        height,
        panel_x + 10,
        panel_y + 42,
        &format!(
            "CENTER {:.0},{:.0} ZOOM {:.2}",
            step.after.center_x, step.after.center_y, step.after.zoom
        ),
        1,
        CLASSIC_HUD_TEXT_COLOR,
    );
    classic_draw_text(
        buffer,
        width,
        height,
        panel_x + 10,
        panel_y + 58,
        &format!("FOCUS TILE {},{}", focus_tile.0, focus_tile.1),
        1,
        CLASSIC_HUD_TEXT_COLOR,
    );

    if step.source.contains("edge_scroll") {
        classic_draw_rect(
            buffer,
            width,
            height,
            frame_x,
            frame_y,
            frame_w,
            14,
            CLASSIC_RTS_SCROLL_EDGE_COLOR,
        );
        classic_draw_rect(
            buffer,
            width,
            height,
            frame_x,
            frame_y + frame_h - 10,
            frame_w,
            14,
            CLASSIC_RTS_SCROLL_EDGE_COLOR,
        );
        classic_draw_rect(
            buffer,
            width,
            height,
            frame_x,
            frame_y,
            14,
            frame_h,
            CLASSIC_RTS_SCROLL_EDGE_COLOR,
        );
        classic_draw_rect(
            buffer,
            width,
            height,
            frame_x + frame_w - 10,
            frame_y,
            14,
            frame_h,
            CLASSIC_RTS_SCROLL_EDGE_COLOR,
        );
    }

    if step.source.contains("middle_mouse_drag") {
        let start_x = frame_x + 86;
        let start_y = frame_y + 146;
        for index in 0..15 {
            classic_draw_rect(
                buffer,
                width,
                height,
                start_x + index * 18,
                start_y - index * 6,
                22,
                7,
                CLASSIC_RTS_SCROLL_DRAG_COLOR,
            );
        }
        classic_draw_text(
            buffer,
            width,
            height,
            panel_x + 10,
            panel_y + 76,
            "MIDDLE DRAG PAN",
            1,
            CLASSIC_RTS_SCROLL_DRAG_COLOR,
        );
    }

    if step.zoom_delta.abs() > f32::EPSILON {
        let zoom_x = frame_x + frame_w - 52;
        let zoom_h = ((step.after.zoom * 42.0).round() as i32).clamp(18, 78);
        classic_draw_rect(
            buffer,
            width,
            height,
            zoom_x,
            frame_y + frame_h - zoom_h - 16,
            26,
            zoom_h,
            CLASSIC_RTS_SCROLL_ZOOM_COLOR,
        );
        classic_draw_rect(
            buffer,
            width,
            height,
            zoom_x - 7,
            frame_y + frame_h - 98,
            40,
            5,
            CLASSIC_RTS_SCROLL_ZOOM_COLOR,
        );
    }

    if let Some(tile_id) = &step.minimap_tile_id {
        let map_x = width as i32 - 174;
        let map_y = height as i32 - 130;
        classic_draw_rect(
            buffer,
            width,
            height,
            map_x,
            map_y,
            144,
            92,
            CLASSIC_RTS_STRATEGY_PANEL_COLOR,
        );
        classic_draw_rect(
            buffer,
            width,
            height,
            map_x + 12 + focus_tile.0 * 8,
            map_y + 10 + focus_tile.1 * 7,
            18,
            18,
            CLASSIC_RTS_SCROLL_MINIMAP_COLOR,
        );
        classic_draw_rect(
            buffer,
            width,
            height,
            map_x + 8,
            map_y + 8,
            128,
            3,
            CLASSIC_RTS_SCROLL_MINIMAP_COLOR,
        );
        classic_draw_rect(
            buffer,
            width,
            height,
            map_x + 8,
            map_y + 80,
            128,
            3,
            CLASSIC_RTS_SCROLL_MINIMAP_COLOR,
        );
        classic_draw_text(
            buffer,
            width,
            height,
            map_x + 10,
            map_y + 64,
            &classic_catalog_text_label(tile_id, 16),
            1,
            CLASSIC_RTS_SCROLL_MINIMAP_COLOR,
        );
    }

    if step.clamped {
        classic_draw_rect(
            buffer,
            width,
            height,
            frame_x + 22,
            frame_y + 20,
            frame_w - 44,
            16,
            CLASSIC_RTS_SCROLL_CLAMP_COLOR,
        );
        classic_draw_rect(
            buffer,
            width,
            height,
            frame_x + 22,
            frame_y + frame_h - 34,
            frame_w - 44,
            16,
            CLASSIC_RTS_SCROLL_CLAMP_COLOR,
        );
        classic_draw_text(
            buffer,
            width,
            height,
            panel_x + 10,
            panel_y + 76,
            "CAMERA BOUNDS CLAMPED",
            1,
            CLASSIC_RTS_SCROLL_CLAMP_COLOR,
        );
    }
}

#[cfg(not(target_os = "android"))]
#[allow(clippy::too_many_arguments)]
fn classic_draw_rts_camera_minimap_sync_overlay(
    buffer: &mut [u32],
    width: usize,
    height: usize,
    step: &RtsScrollableMapCameraStep,
    stage: &str,
    viewport_rect: RtsCameraMinimapViewportRect,
    focus_tile: (i32, i32),
    revealed_tile_ids: &[String],
    selected_unit_id: &str,
    control_group_id: &str,
) {
    if width < 580 || height < 300 {
        return;
    }
    let map_x = width as i32 - 214;
    let map_y = (height as i32 - 176).max(156);
    let map_w = 188_i32;
    let map_h = 166_i32;
    classic_draw_rect(
        buffer,
        width,
        height,
        map_x,
        map_y,
        map_w,
        map_h,
        CLASSIC_RTS_STRATEGY_PANEL_COLOR,
    );
    classic_draw_rect(
        buffer,
        width,
        height,
        map_x,
        map_y,
        map_w,
        3,
        CLASSIC_RTS_CAMERA_SYNC_VIEWPORT_COLOR,
    );
    classic_draw_text(
        buffer,
        width,
        height,
        map_x + 8,
        map_y + 8,
        "CAMERA / MINIMAP SYNC",
        1,
        CLASSIC_HUD_TEXT_COLOR,
    );
    classic_draw_text(
        buffer,
        width,
        height,
        map_x + 8,
        map_y + 23,
        &classic_catalog_text_label(&stage.replace('_', " "), 21),
        1,
        CLASSIC_RTS_CAMERA_SYNC_VIEWPORT_COLOR,
    );

    let grid_x = map_x + 14;
    let grid_y = map_y + 40;
    let cell_w = 4_i32;
    let cell_h = 4_i32;
    for tile_y in CLASSIC_RTS_LARGE_MAP_MIN_TILE..=CLASSIC_RTS_LARGE_MAP_MAX_Y {
        for tile_x in CLASSIC_RTS_LARGE_MAP_MIN_TILE..=CLASSIC_RTS_LARGE_MAP_MAX_X {
            let tile_id = format!("{tile_x},{tile_y}");
            let color = if revealed_tile_ids.contains(&tile_id) {
                CLASSIC_RTS_CAMERA_SYNC_REVEAL_COLOR
            } else {
                CLASSIC_RTS_CAMERA_SYNC_FOG_COLOR
            };
            let (tile_origin_x, tile_origin_y) =
                classic_rts_minimap_cell_origin(grid_x, grid_y, cell_w, cell_h, (tile_x, tile_y));
            classic_draw_rect(
                buffer,
                width,
                height,
                tile_origin_x,
                tile_origin_y,
                cell_w,
                cell_h,
                color,
            );
        }
    }

    let rect_x = grid_x + viewport_rect.x;
    let rect_y = grid_y + viewport_rect.y;
    for (x, y, w, h) in [
        (rect_x, rect_y, viewport_rect.width, 3),
        (
            rect_x,
            rect_y + viewport_rect.height,
            viewport_rect.width,
            3,
        ),
        (rect_x, rect_y, 3, viewport_rect.height),
        (
            rect_x + viewport_rect.width,
            rect_y,
            3,
            viewport_rect.height,
        ),
    ] {
        classic_draw_rect(
            buffer,
            width,
            height,
            x,
            y,
            w,
            h,
            CLASSIC_RTS_CAMERA_SYNC_VIEWPORT_COLOR,
        );
    }

    let (focus_x, focus_y) =
        classic_rts_minimap_cell_origin(grid_x, grid_y, cell_w, cell_h, focus_tile);
    classic_draw_rect(
        buffer,
        width,
        height,
        focus_x - 4,
        focus_y - 4,
        20,
        5,
        CLASSIC_RTS_CAMERA_SYNC_SELECTION_COLOR,
    );
    classic_draw_rect(
        buffer,
        width,
        height,
        focus_x + 3,
        focus_y - 10,
        5,
        20,
        CLASSIC_RTS_CAMERA_SYNC_SELECTION_COLOR,
    );
    for index in 0..15 {
        classic_draw_rect(
            buffer,
            width,
            height,
            grid_x + 8 + index * 7,
            grid_y + 118 - index * 4,
            10,
            3,
            CLASSIC_RTS_CAMERA_SYNC_ROUTE_COLOR,
        );
    }

    let detail_x = 22_i32;
    let detail_y = (height as i32 - 124).max(116);
    classic_draw_rect(
        buffer,
        width,
        height,
        detail_x,
        detail_y,
        324,
        82,
        CLASSIC_RTS_STRATEGY_PANEL_COLOR,
    );
    classic_draw_rect(
        buffer,
        width,
        height,
        detail_x,
        detail_y,
        324,
        3,
        CLASSIC_RTS_CAMERA_SYNC_SELECTION_COLOR,
    );
    classic_draw_text(
        buffer,
        width,
        height,
        detail_x + 10,
        detail_y + 12,
        &format!("GROUP {control_group_id} CAMERA LOCK"),
        1,
        CLASSIC_RTS_CAMERA_SYNC_SELECTION_COLOR,
    );
    classic_draw_text(
        buffer,
        width,
        height,
        detail_x + 10,
        detail_y + 29,
        &format!(
            "SELECT {}",
            classic_catalog_text_label(selected_unit_id, 22)
        ),
        1,
        CLASSIC_HUD_TEXT_COLOR,
    );
    classic_draw_text(
        buffer,
        width,
        height,
        detail_x + 10,
        detail_y + 46,
        &format!(
            "FOCUS {},{}  ZOOM {:.2}",
            focus_tile.0, focus_tile.1, step.after.zoom
        ),
        1,
        CLASSIC_HUD_TEXT_COLOR,
    );
    classic_draw_text(
        buffer,
        width,
        height,
        detail_x + 10,
        detail_y + 63,
        &format!("REVEALED {} TILES", revealed_tile_ids.len()),
        1,
        CLASSIC_RTS_CAMERA_SYNC_REVEAL_COLOR,
    );
}

