#[cfg(not(target_os = "android"))]
pub fn native_classic_rts_command_affordance_evidence_json(preview_path: &str) -> String {
    const PANEL_WIDTH: usize = 640;
    const PANEL_HEIGHT: usize = 360;
    const PREVIEW_COLUMNS: usize = 2;
    const PREVIEW_ROWS: usize = 2;
    let assets = load_classic_runtime_assets();
    let mut world = native_bevy_playable_fixture();
    let mut character = WorldTrillionniumCharacter::default_for("local-player");
    let mut gameplay_log = NativeGameplayLog::default();
    let mut runtime = NativeFirstPlayableRuntime {
        map_scene: "arena_outdoor".to_string(),
        coins: 188,
        xp: 96,
        facing_direction: "east".to_string(),
        walk_cycle_frame: 1,
        ..Default::default()
    };
    let actions = [
        (
            "drag_select_marquee",
            NativeControlAction::RtsSelectControlGroup {
                group_id: "box:frontline".to_string(),
            },
        ),
        (
            "right_click_move",
            NativeControlAction::RtsMoveCommand {
                command_id: "7,4:diamond".to_string(),
            },
        ),
        (
            "attack_cursor",
            NativeControlAction::RtsAttackCommand {
                target_id: "arena_creep_attack".to_string(),
            },
        ),
        (
            "ability_hotkey_ack",
            NativeControlAction::RtsAbilityCommand {
                ability_id: "guard_break".to_string(),
            },
        ),
    ];
    let preview_width = PANEL_WIDTH * PREVIEW_COLUMNS;
    let preview_height = PANEL_HEIGHT * PREVIEW_ROWS;
    let mut preview_pixels = vec![0x0b0d0c_u32; preview_width * preview_height];
    let mut frame_pixels = vec![0x0b0d0c_u32; PANEL_WIDTH * PANEL_HEIGHT];
    let mut accepted_input_count = 0_usize;
    let mut input_sources = HashSet::new();
    let mut action_labels = Vec::new();
    let mut stage_summaries = Vec::new();

    for (index, (stage, action)) in actions.iter().enumerate() {
        let action_label = native_control_action_label(action);
        action_labels.push(action_label.clone());
        apply_live_native_action_with_source(
            &mut world,
            &mut character,
            &mut gameplay_log,
            &mut runtime,
            "local-player",
            "classic_rts_command_affordance_input",
            action.clone(),
        );
        let latest_feedback = runtime.input_feedback_history.last();
        let accepted = latest_feedback.is_some_and(|event| event.accepted);
        if accepted {
            accepted_input_count += 1;
        }
        if let Some(event) = latest_feedback {
            input_sources.insert(event.input_source.clone());
        }
        frame_pixels.fill(0x0b0d0c_u32);
        classic_draw_scene(
            &mut frame_pixels,
            PANEL_WIDTH,
            PANEL_HEIGHT,
            (5, 5),
            &runtime,
            &assets,
        );
        let offset_x = ((index % PREVIEW_COLUMNS) * PANEL_WIDTH) as i32;
        let offset_y = ((index / PREVIEW_COLUMNS) * PANEL_HEIGHT) as i32;
        classic_copy_pixels(
            &mut preview_pixels,
            preview_width,
            preview_height,
            &frame_pixels,
            PANEL_WIDTH,
            PANEL_HEIGHT,
            offset_x,
            offset_y,
        );
        classic_draw_text(
            &mut preview_pixels,
            preview_width,
            preview_height,
            offset_x + 12,
            offset_y + PANEL_HEIGHT as i32 - 126,
            &format!("{:02} {}", index + 1, stage),
            1,
            CLASSIC_HUD_ACCENT_TEXT_COLOR,
        );
        stage_summaries.push(json!({
            "stage": stage,
            "action_label": action_label,
            "accepted": accepted,
            "last_action": gameplay_log.last_action,
            "last_feedback": runtime.last_feedback,
            "control_group_id": runtime.rts_control_group_id.clone(),
            "selected_unit_ids": runtime.rts_selected_unit_ids.clone(),
            "selection_box_tile_ids": runtime.rts_selection_box_tile_ids.clone(),
            "command_destination_tile": runtime.rts_command_destination_tile.clone(),
            "attack_target_id": runtime.rts_attack_target_id.clone(),
            "active_ability_id": runtime.rts_active_ability_id.clone(),
            "command_queue": runtime.rts_command_queue.clone(),
        }));
    }

    let write_gate =
        write_classic_rgb_buffer_ppm(preview_path, preview_width, preview_height, &preview_pixels)
            .is_ok();
    let count_color = |color: u32| -> usize {
        preview_pixels
            .iter()
            .filter(|pixel| **pixel == color)
            .count()
    };
    let non_background_pixels = preview_pixels
        .iter()
        .filter(|color| **color != 0x0b0d0c_u32)
        .count();
    let drag_marquee_pixel_count = count_color(CLASSIC_RTS_COMMAND_AFFORDANCE_DRAG_COLOR);
    let right_click_marker_pixel_count =
        count_color(CLASSIC_RTS_COMMAND_AFFORDANCE_RIGHT_CLICK_COLOR);
    let attack_cursor_pixel_count = count_color(CLASSIC_RTS_COMMAND_AFFORDANCE_ATTACK_CURSOR_COLOR);
    let cursor_arrow_pixel_count = count_color(CLASSIC_RTS_COMMAND_AFFORDANCE_CURSOR_ARROW_COLOR);
    let hotkey_pixel_count = count_color(CLASSIC_RTS_COMMAND_AFFORDANCE_HOTKEY_COLOR);
    let command_ack_pixel_count = count_color(CLASSIC_RTS_COMMAND_AFFORDANCE_ACK_COLOR);
    let live_command_affordance_input_gate = accepted_input_count == actions.len()
        && input_sources.len() == 1
        && input_sources.contains("classic_rts_command_affordance_input");
    let drag_select_gate = runtime
        .rts_command_queue
        .iter()
        .any(|entry| entry.starts_with("box_select:"))
        && runtime.rts_selected_unit_ids.len() >= 4
        && runtime.rts_selection_box_tile_ids.len() >= 4
        && drag_marquee_pixel_count > 80;
    let right_click_move_gate = runtime
        .rts_command_queue
        .iter()
        .any(|entry| entry == "move:7,4")
        && right_click_marker_pixel_count > 120
        && cursor_arrow_pixel_count > 60;
    let attack_cursor_gate = runtime.rts_attack_target_id.as_deref() == Some("arena_creep_attack")
        && attack_cursor_pixel_count > 120
        && runtime
            .rts_command_queue
            .iter()
            .any(|entry| entry == "attack:arena_creep_attack");
    let hotkey_ack_gate = runtime.rts_active_ability_id.as_deref() == Some("guard_break")
        && hotkey_pixel_count > 200
        && command_ack_pixel_count > 160
        && runtime
            .rts_command_queue
            .iter()
            .any(|entry| entry == "ability:guard_break");
    let original_art_policy_gate = assets.manifest.asset_boundary.contains("not_cex_runtime")
        && !assets.manifest.cex_runtime_player_client_allowed
        && !assets.manifest.wgpu_required;
    let green = write_gate
        && non_background_pixels > 220_000
        && live_command_affordance_input_gate
        && drag_select_gate
        && right_click_move_gate
        && attack_cursor_gate
        && hotkey_ack_gate
        && original_art_policy_gate;
    serde_json::to_string_pretty(&json!({
        "contract_version": TRILLIONNIUM_WORLD_BEVY_CLASSIC_RTS_COMMAND_AFFORDANCE_CONTRACT,
        "green": green,
        "preview_path": preview_path,
        "preview_format": "ppm_p3_rgb",
        "preview_width": preview_width,
        "preview_height": preview_height,
        "write_gate": write_gate,
        "input_path": "apply_live_native_action_with_source(classic_rts_command_affordance_input)",
        "input_action_count": actions.len(),
        "accepted_input_count": accepted_input_count,
        "input_sources": input_sources,
        "action_labels": action_labels,
        "stage_summaries": stage_summaries,
        "final_selected_unit_ids": runtime.rts_selected_unit_ids,
        "final_selection_box_tile_ids": runtime.rts_selection_box_tile_ids,
        "final_command_destination_tile": runtime.rts_command_destination_tile,
        "final_attack_target_id": runtime.rts_attack_target_id,
        "final_active_ability_id": runtime.rts_active_ability_id,
        "final_command_queue": runtime.rts_command_queue,
        "non_background_pixels": non_background_pixels,
        "drag_marquee_pixel_count": drag_marquee_pixel_count,
        "right_click_marker_pixel_count": right_click_marker_pixel_count,
        "attack_cursor_pixel_count": attack_cursor_pixel_count,
        "cursor_arrow_pixel_count": cursor_arrow_pixel_count,
        "hotkey_pixel_count": hotkey_pixel_count,
        "command_ack_pixel_count": command_ack_pixel_count,
        "live_command_affordance_input_gate": live_command_affordance_input_gate,
        "drag_select_gate": drag_select_gate,
        "right_click_move_gate": right_click_move_gate,
        "attack_cursor_gate": attack_cursor_gate,
        "hotkey_ack_gate": hotkey_ack_gate,
        "original_art_policy_gate": original_art_policy_gate,
        "warcraft_iii_asset_copied": false,
        "source_art_policy": "Original Trillionnium RTS command affordances; genre-control expectations are used as quality direction, not copied Warcraft III assets, cursor art, UI art, text, names, or models.",
        "cex_runtime_player_client_allowed": assets.manifest.cex_runtime_player_client_allowed,
        "wgpu_required": assets.manifest.wgpu_required,
        "source_of_truth": "Command affordance evidence drives drag-select, right-click move, attack cursor, and hotkey/ability acknowledgement through live native RTS input and the actual classic_draw_scene renderer."
    }))
    .expect("classic RTS command affordance evidence serializes")
}

#[cfg(not(target_os = "android"))]
pub fn native_classic_rts_command_surface_evidence_json(preview_path: &str) -> String {
    const PANEL_WIDTH: usize = 640;
    const PANEL_HEIGHT: usize = 360;
    const PREVIEW_COLUMNS: usize = 2;
    const PREVIEW_ROWS: usize = 2;
    let assets = load_classic_runtime_assets();
    let stages = [
        (
            "selection_state",
            "arena_outdoor",
            (5, 5),
            0_u8,
            "surface:selection_state",
        ),
        (
            "command_grid",
            "arena_outdoor",
            (5, 5),
            1_u8,
            "surface:command_grid",
        ),
        (
            "cooldown_disabled",
            "arena_outdoor",
            (5, 5),
            2_u8,
            "surface:cooldown_disabled",
        ),
        (
            "target_queue",
            "arena_outdoor",
            (6, 5),
            3_u8,
            "surface:target_queue",
        ),
    ];
    let preview_width = PANEL_WIDTH * PREVIEW_COLUMNS;
    let preview_height = PANEL_HEIGHT * PREVIEW_ROWS;
    let mut preview_pixels = vec![0x0b0d0c_u32; preview_width * preview_height];
    let mut frame_pixels = vec![0x0b0d0c_u32; PANEL_WIDTH * PANEL_HEIGHT];
    let mut stage_summaries = Vec::new();

    for (index, (stage, scene, player_tile, combat_turn, surface_event)) in
        stages.iter().enumerate()
    {
        let runtime = NativeFirstPlayableRuntime {
            map_scene: (*scene).to_string(),
            coins: 412 + index as u64,
            xp: 273 + (index as u64 * 13),
            facing_direction: "west".to_string(),
            walk_cycle_frame: (*combat_turn).max(1),
            combat_overlay_visible: true,
            combat_overlay_was_visible: true,
            combat_turn: *combat_turn,
            rts_control_group_id: Some("1".to_string()),
            rts_selected_unit_ids: string_vec([
                "player",
                "arena_guard_left",
                "arena_guard_right",
                "arena_creep_attack",
                "square_worker_carry",
            ]),
            rts_active_control_group_ids: string_vec(["1", "2", "3"]),
            rts_command_queue: string_vec([
                *surface_event,
                "select_group_1",
                "move:7,4",
                "attack:arena_creep_attack",
                "ability:guard_break",
                "queue:confirm",
            ]),
            rts_command_destination_tile: Some("7,4".to_string()),
            rts_attack_target_id: Some("arena_creep_attack".to_string()),
            rts_visible_tile_ids: string_vec(["4,4", "5,4", "6,4", "7,4", "8,4", "6,5", "7,5"]),
            rts_selection_box_tile_ids: string_vec(["4,4", "5,4", "6,5", "7,5"]),
            rts_fogged_tile_ids: string_vec(["0,0", "1,0", "10,0", "11,0"]),
            rts_production_queue: string_vec([
                "train:guard",
                "train:worker",
                "upgrade:signal_blade",
            ]),
            rts_unit_health_percents: vec![100, 83, 71, 38, 64],
            rts_ability_command_ids: string_vec([
                "move", "attack", "hold", "patrol", "focus", "build",
            ]),
            rts_ability_cooldown_percents: vec![0, 0, 45, 0, 72, 20],
            rts_active_ability_id: Some(match *stage {
                "command_grid" => "attack".to_string(),
                "target_queue" => "guard_break".to_string(),
                _ => "focus".to_string(),
            }),
            rts_target_health_percent: 36,
            rts_target_armor_percent: 22,
            rts_target_shield_percent: 8,
            rts_combat_event_log: string_vec([
                *surface_event,
                "guard_attack_windup",
                "worker_carry_supply",
                "surface_source:classic_draw_scene",
            ]),
            last_feedback: format!("RTS command surface stage: {stage}"),
            ..Default::default()
        };
        frame_pixels.fill(0x0b0d0c_u32);
        classic_draw_scene(
            &mut frame_pixels,
            PANEL_WIDTH,
            PANEL_HEIGHT,
            *player_tile,
            &runtime,
            &assets,
        );
        if let Some(surface_stage) = classic_rts_command_surface_stage(Some(&runtime)) {
            let scene_id = classic_scene_id(&runtime);
            let selected_units =
                classic_rts_control_group_entities(scene_id, *player_tile, &runtime);
            classic_draw_rts_command_surface_overlay(
                &mut frame_pixels,
                PANEL_WIDTH,
                PANEL_HEIGHT,
                &runtime,
                &selected_units,
                surface_stage,
            );
        }
        let offset_x = ((index % PREVIEW_COLUMNS) * PANEL_WIDTH) as i32;
        let offset_y = ((index / PREVIEW_COLUMNS) * PANEL_HEIGHT) as i32;
        classic_copy_pixels(
            &mut preview_pixels,
            preview_width,
            preview_height,
            &frame_pixels,
            PANEL_WIDTH,
            PANEL_HEIGHT,
            offset_x,
            offset_y,
        );
        classic_draw_text(
            &mut preview_pixels,
            preview_width,
            preview_height,
            offset_x + 12,
            offset_y + PANEL_HEIGHT as i32 - 140,
            &format!("COMMAND SURFACE {} {}", index + 1, stage),
            1,
            CLASSIC_HUD_ACCENT_TEXT_COLOR,
        );
        stage_summaries.push(json!({
            "stage": stage,
            "scene": scene,
            "surface_event": surface_event,
            "renderer_path": "classic_draw_scene",
            "selected_unit_count": runtime.rts_selected_unit_ids.len(),
            "ability_command_count": runtime.rts_ability_command_ids.len(),
            "cooldown_count": runtime.rts_ability_cooldown_percents.iter().filter(|cooldown| **cooldown > 0).count(),
            "command_queue_count": runtime.rts_command_queue.len(),
        }));
    }

    let write_gate =
        write_classic_rgb_buffer_ppm(preview_path, preview_width, preview_height, &preview_pixels)
            .is_ok();
    let count_color = |color: u32| -> usize {
        preview_pixels
            .iter()
            .filter(|pixel| **pixel == color)
            .count()
    };
    let selection_frame_pixel_count =
        count_color(CLASSIC_RTS_COMMAND_SURFACE_SELECTION_FRAME_COLOR);
    let ready_pixel_count = count_color(CLASSIC_RTS_COMMAND_SURFACE_READY_COLOR);
    let disabled_pixel_count = count_color(CLASSIC_RTS_COMMAND_SURFACE_DISABLED_COLOR);
    let cooldown_pixel_count = count_color(CLASSIC_RTS_COMMAND_SURFACE_COOLDOWN_COLOR);
    let target_panel_pixel_count = count_color(CLASSIC_RTS_COMMAND_SURFACE_TARGET_COLOR);
    let queue_confirm_pixel_count = count_color(CLASSIC_RTS_COMMAND_SURFACE_QUEUE_COLOR);
    let group_tab_pixel_count = count_color(CLASSIC_RTS_COMMAND_SURFACE_GROUP_TAB_COLOR);
    let selection_surface_gate = selection_frame_pixel_count > 800 && group_tab_pixel_count > 200;
    let command_grid_surface_gate = ready_pixel_count > 500;
    let cooldown_disabled_surface_gate = cooldown_pixel_count > 300 && disabled_pixel_count > 100;
    let target_queue_surface_gate =
        target_panel_pixel_count > 400 && queue_confirm_pixel_count > 250;
    let surface_stage_gate = [
        "surface:selection_state",
        "surface:command_grid",
        "surface:cooldown_disabled",
        "surface:target_queue",
    ]
    .iter()
    .all(|stage| {
        stage_summaries.iter().any(|summary| {
            summary
                .get("surface_event")
                .and_then(|value| value.as_str())
                == Some(*stage)
        })
    });
    let scene_renderer_gate = stage_summaries.len() == stages.len()
        && stage_summaries.iter().all(|summary| {
            summary
                .get("renderer_path")
                .and_then(|value| value.as_str())
                == Some("classic_draw_scene")
        });
    let original_art_policy_gate = assets.manifest.asset_boundary.contains("not_cex_runtime")
        && !assets.manifest.cex_runtime_player_client_allowed
        && !assets.manifest.wgpu_required;
    let green = write_gate
        && selection_surface_gate
        && command_grid_surface_gate
        && cooldown_disabled_surface_gate
        && target_queue_surface_gate
        && surface_stage_gate
        && scene_renderer_gate
        && original_art_policy_gate;
    serde_json::to_string_pretty(&json!({
        "contract_version": TRILLIONNIUM_WORLD_BEVY_CLASSIC_RTS_COMMAND_SURFACE_CONTRACT,
        "green": green,
        "preview_path": preview_path,
        "preview_format": "ppm_p3_rgb",
        "preview_width": preview_width,
        "preview_height": preview_height,
        "write_gate": write_gate,
        "renderer_path": "classic_draw_scene",
        "stage_summaries": stage_summaries,
        "selection_frame_pixel_count": selection_frame_pixel_count,
        "ready_pixel_count": ready_pixel_count,
        "disabled_pixel_count": disabled_pixel_count,
        "cooldown_pixel_count": cooldown_pixel_count,
        "target_panel_pixel_count": target_panel_pixel_count,
        "queue_confirm_pixel_count": queue_confirm_pixel_count,
        "group_tab_pixel_count": group_tab_pixel_count,
        "selection_surface_gate": selection_surface_gate,
        "command_grid_surface_gate": command_grid_surface_gate,
        "cooldown_disabled_surface_gate": cooldown_disabled_surface_gate,
        "target_queue_surface_gate": target_queue_surface_gate,
        "surface_stage_gate": surface_stage_gate,
        "scene_renderer_gate": scene_renderer_gate,
        "original_art_policy_gate": original_art_policy_gate,
        "warcraft_iii_asset_copied": false,
        "source_art_policy": "Original Trillionnium command-surface overlays; classic RTS selection cards, command grid states, cooldown/disabled marks, target panel, and queue confirmation are authored locally without copied Warcraft III assets, UI art, text, names, or models.",
        "cex_runtime_player_client_allowed": assets.manifest.cex_runtime_player_client_allowed,
        "wgpu_required": assets.manifest.wgpu_required,
        "source_of_truth": "Command surface evidence uses actual classic_draw_scene frames and surface-event driven HUD stages to prove selection cards, command-grid state, cooldown/disabled cells, target details, and command queue confirmation render in the playable RTS interface."
    }))
    .expect("classic RTS command surface evidence serializes")
}

