#[cfg(not(target_os = "android"))]
fn classic_poll_action(
    window: &MiniWindow,
    runtime: &NativeFirstPlayableRuntime,
    width: usize,
    height: usize,
    mouse_latch: &mut ClassicRuntimeMouseLatch,
) -> Option<ClassicPolledAction> {
    let shift_pressed =
        window.is_key_down(MiniKey::LeftShift) || window.is_key_down(MiniKey::RightShift);
    let ctrl_pressed =
        window.is_key_down(MiniKey::LeftCtrl) || window.is_key_down(MiniKey::RightCtrl);
    if let Some(action) =
        classic_poll_mouse_action(window, runtime, width, height, mouse_latch, shift_pressed)
    {
        Some(action)
    } else if let Some(action) =
        classic_poll_control_group_hotkey(window, mouse_latch, ctrl_pressed, shift_pressed)
    {
        Some(action)
    } else if window.is_key_pressed(MiniKey::M, MiniKeyRepeat::No) {
        Some(classic_polled_keyboard_action(
            NativeControlAction::RtsMoveCommand {
                command_id: classic_next_runtime_rts_move_command(runtime),
            },
        ))
    } else if window.is_key_pressed(MiniKey::Q, MiniKeyRepeat::No) {
        Some(classic_polled_keyboard_action(
            NativeControlAction::RtsMoveCommand {
                command_id: classic_next_runtime_rts_queued_waypoint_command(runtime),
            },
        ))
    } else if window.is_key_pressed(MiniKey::X, MiniKeyRepeat::No) {
        Some(classic_polled_keyboard_action(
            NativeControlAction::RtsMoveCommand {
                command_id: classic_next_runtime_rts_stop_command(runtime),
            },
        ))
    } else if window.is_key_pressed(MiniKey::H, MiniKeyRepeat::No) {
        Some(classic_polled_keyboard_action(
            NativeControlAction::RtsMoveCommand {
                command_id: classic_next_runtime_rts_hold_command(runtime),
            },
        ))
    } else if window.is_key_pressed(MiniKey::O, MiniKeyRepeat::No) {
        Some(classic_polled_keyboard_action(
            NativeControlAction::RtsMoveCommand {
                command_id: classic_next_runtime_rts_patrol_command(runtime),
            },
        ))
    } else if window.is_key_pressed(MiniKey::K, MiniKeyRepeat::No) {
        Some(classic_polled_keyboard_action(
            NativeControlAction::RtsMoveCommand {
                command_id: classic_next_runtime_rts_attack_move_command(runtime),
            },
        ))
    } else if !shift_pressed && window.is_key_pressed(MiniKey::A, MiniKeyRepeat::No) {
        Some(classic_polled_keyboard_action(
            NativeControlAction::RtsAttackCommand {
                target_id: classic_next_runtime_rts_attack_target(runtime),
            },
        ))
    } else if window.is_key_pressed(MiniKey::B, MiniKeyRepeat::No) {
        Some(classic_polled_keyboard_action(
            NativeControlAction::RtsQueueProduction {
                queue_id: classic_next_runtime_rts_build_queue(runtime),
            },
        ))
    } else if window.is_key_pressed(MiniKey::P, MiniKeyRepeat::No) {
        Some(classic_polled_keyboard_action(
            NativeControlAction::RtsQueueProduction {
                queue_id: classic_next_runtime_rts_train_queue(runtime),
            },
        ))
    } else if window.is_key_pressed(MiniKey::G, MiniKeyRepeat::No) {
        Some(classic_polled_keyboard_action(
            NativeControlAction::RtsQueueProduction {
                queue_id: classic_next_runtime_rts_economy_queue(runtime),
            },
        ))
    } else if window.is_key_pressed(MiniKey::V, MiniKeyRepeat::No)
        || window.is_key_pressed(MiniKey::Tab, MiniKeyRepeat::No)
    {
        Some(classic_polled_keyboard_action(
            NativeControlAction::RtsAbilityCommand {
                ability_id: classic_next_runtime_rts_ability(runtime),
            },
        ))
    } else if !shift_pressed
        && (window.is_key_pressed(MiniKey::Right, MiniKeyRepeat::Yes)
            || window.is_key_pressed(MiniKey::D, MiniKeyRepeat::Yes))
    {
        Some(classic_polled_keyboard_action(NativeControlAction::Move {
            direction: "east".to_string(),
        }))
    } else if !shift_pressed && window.is_key_pressed(MiniKey::Left, MiniKeyRepeat::Yes) {
        Some(classic_polled_keyboard_action(NativeControlAction::Move {
            direction: "west".to_string(),
        }))
    } else if !shift_pressed
        && (window.is_key_pressed(MiniKey::Up, MiniKeyRepeat::Yes)
            || window.is_key_pressed(MiniKey::W, MiniKeyRepeat::Yes))
    {
        Some(classic_polled_keyboard_action(NativeControlAction::Move {
            direction: "north".to_string(),
        }))
    } else if !shift_pressed
        && (window.is_key_pressed(MiniKey::Down, MiniKeyRepeat::Yes)
            || window.is_key_pressed(MiniKey::S, MiniKeyRepeat::Yes))
    {
        Some(classic_polled_keyboard_action(NativeControlAction::Move {
            direction: "south".to_string(),
        }))
    } else if window.is_key_pressed(MiniKey::R, MiniKeyRepeat::No) {
        Some(classic_polled_keyboard_action(NativeControlAction::Talk))
    } else if window.is_key_pressed(MiniKey::T, MiniKeyRepeat::No) {
        Some(classic_polled_keyboard_action(NativeControlAction::Train))
    } else if window.is_key_pressed(MiniKey::F, MiniKeyRepeat::No)
        || window.is_key_pressed(MiniKey::Space, MiniKeyRepeat::No)
    {
        Some(classic_polled_keyboard_action(NativeControlAction::Fight))
    } else if window.is_key_pressed(MiniKey::C, MiniKeyRepeat::No) {
        Some(classic_polled_keyboard_action(
            NativeControlAction::CompleteTask,
        ))
    } else if window.is_key_pressed(MiniKey::I, MiniKeyRepeat::No) {
        Some(classic_polled_keyboard_action(NativeControlAction::Equip))
    } else if window.is_key_pressed(MiniKey::Enter, MiniKeyRepeat::No) {
        player_action_coach_control_action(runtime).map(classic_polled_keyboard_action)
    } else {
        None
    }
}

#[cfg(not(target_os = "android"))]
fn classic_poll_control_group_hotkey(
    window: &MiniWindow,
    mouse_latch: &mut ClassicRuntimeMouseLatch,
    ctrl_pressed: bool,
    shift_pressed: bool,
) -> Option<ClassicPolledAction> {
    if mouse_latch.control_group_repeat_frames_remaining > 0 {
        mouse_latch.control_group_repeat_frames_remaining -= 1;
    } else {
        mouse_latch.control_group_repeat_slot = None;
    }

    let slot = [
        (MiniKey::Key1, "1"),
        (MiniKey::Key2, "2"),
        (MiniKey::Key3, "3"),
        (MiniKey::Key4, "4"),
        (MiniKey::Key5, "5"),
        (MiniKey::Key6, "6"),
        (MiniKey::Key7, "7"),
        (MiniKey::Key8, "8"),
        (MiniKey::Key9, "9"),
        (MiniKey::Key0, "10"),
    ]
    .iter()
    .find_map(|(key, slot)| {
        window
            .is_key_pressed(*key, MiniKeyRepeat::No)
            .then_some(*slot)
    })?;

    let group_id = if ctrl_pressed && shift_pressed {
        mouse_latch.control_group_repeat_slot = None;
        mouse_latch.control_group_repeat_frames_remaining = 0;
        format!("append:{slot}")
    } else if ctrl_pressed {
        mouse_latch.control_group_repeat_slot = None;
        mouse_latch.control_group_repeat_frames_remaining = 0;
        format!("assign:{slot}")
    } else if shift_pressed {
        mouse_latch.control_group_repeat_slot = Some(slot.to_string());
        mouse_latch.control_group_repeat_frames_remaining = 18;
        format!("recall_add:{slot}")
    } else if mouse_latch.control_group_repeat_slot.as_deref() == Some(slot)
        && mouse_latch.control_group_repeat_frames_remaining > 0
    {
        mouse_latch.control_group_repeat_slot = None;
        mouse_latch.control_group_repeat_frames_remaining = 0;
        format!("camera:{slot}")
    } else {
        mouse_latch.control_group_repeat_slot = Some(slot.to_string());
        mouse_latch.control_group_repeat_frames_remaining = 18;
        format!("recall:{slot}")
    };

    Some(classic_polled_keyboard_action(
        NativeControlAction::RtsSelectControlGroup { group_id },
    ))
}

#[cfg(not(target_os = "android"))]
fn classic_poll_mouse_action(
    window: &MiniWindow,
    runtime: &NativeFirstPlayableRuntime,
    width: usize,
    height: usize,
    mouse_latch: &mut ClassicRuntimeMouseLatch,
    shift_pressed: bool,
) -> Option<ClassicPolledAction> {
    if mouse_latch.unit_double_click_frames_remaining > 0 {
        mouse_latch.unit_double_click_frames_remaining -= 1;
    } else {
        mouse_latch.unit_double_click_unit_id = None;
    }

    let left_down = window.get_mouse_down(MiniMouseButton::Left);
    let right_down = window.get_mouse_down(MiniMouseButton::Right);
    let left_pressed = left_down && !mouse_latch.left_down;
    let left_released = !left_down && mouse_latch.left_down;
    let right_pressed = right_down && !mouse_latch.right_down;
    let mouse_pos = window
        .get_mouse_pos(MiniMouseMode::Discard)
        .map(|(x, y)| (x as i32, y as i32));
    if left_pressed {
        mouse_latch.left_anchor = mouse_pos;
        mouse_latch.left_current = mouse_pos;
    } else if left_down {
        if let Some(pos) = mouse_pos {
            mouse_latch.left_current = Some(pos);
        }
    }
    let action = if right_pressed {
        mouse_pos.and_then(|(x, y)| {
            classic_rts_mouse_action_with_source_from_point(
                runtime,
                width,
                height,
                x,
                y,
                MiniMouseButton::Right,
            )
        })
    } else if left_released {
        let anchor = mouse_latch.left_anchor;
        let release = mouse_pos.or(mouse_latch.left_current);
        mouse_latch.left_anchor = None;
        mouse_latch.left_current = None;
        match (anchor, release) {
            (Some(start), Some(end)) if classic_rts_drag_distance_sq(start, end) >= 36 => {
                classic_rts_drag_action_with_source_from_points(runtime, width, height, start, end)
            }
            (_, Some((x, y))) => {
                let mut polled = classic_rts_mouse_action_with_source_from_point_with_shift(
                    runtime,
                    width,
                    height,
                    x,
                    y,
                    MiniMouseButton::Left,
                    shift_pressed,
                );
                if !shift_pressed {
                    if let Some(ClassicPolledAction {
                        action: NativeControlAction::RtsSelectControlGroup { group_id },
                        input_source,
                    }) = &polled
                    {
                        if let Some(unit_id) = group_id.strip_prefix("unit:") {
                            let repeated_unit = mouse_latch.unit_double_click_unit_id.as_deref()
                                == Some(unit_id)
                                && mouse_latch.unit_double_click_frames_remaining > 0;
                            if repeated_unit {
                                polled = Some(ClassicPolledAction::new(
                                    *input_source,
                                    NativeControlAction::RtsSelectControlGroup {
                                        group_id: format!("double:unit:{unit_id}"),
                                    },
                                ));
                                mouse_latch.unit_double_click_unit_id = None;
                                mouse_latch.unit_double_click_frames_remaining = 0;
                            } else {
                                mouse_latch.unit_double_click_unit_id = Some(unit_id.to_string());
                                mouse_latch.unit_double_click_frames_remaining = 18;
                            }
                        }
                    }
                }
                polled
            }
            _ => None,
        }
    } else {
        None
    };
    if !left_down && !left_released {
        mouse_latch.left_anchor = None;
        mouse_latch.left_current = None;
    }
    mouse_latch.left_down = left_down;
    mouse_latch.right_down = right_down;
    action
}

#[cfg(not(target_os = "android"))]
#[derive(Debug, Clone, Copy)]
struct ClassicRtsShellLayout {
    sidebar_x: i32,
    viewport_x: i32,
    viewport_y: i32,
    viewport_w: i32,
    viewport_h: i32,
    bottom_y: i32,
    bottom_h: i32,
    radar_x: i32,
    radar_y: i32,
    radar_w: i32,
    radar_h: i32,
}

#[cfg(not(target_os = "android"))]
fn classic_rts_shell_layout(width: usize, height: usize) -> Option<ClassicRtsShellLayout> {
    if width < 900 || height < 540 {
        return None;
    }
    let width_i = width as i32;
    let height_i = height as i32;
    let sidebar_w = 264;
    let bottom_h = 148;
    let top_h = 34;
    let sidebar_x = width_i - sidebar_w - 8;
    let viewport_x = 8;
    let viewport_y = top_h + 8;
    let viewport_w = sidebar_x - viewport_x - 8;
    let viewport_h = height_i - bottom_h - viewport_y - 8;
    let bottom_y = height_i - bottom_h - 8;
    let radar_x = sidebar_x + 12;
    let radar_y = viewport_y + 28;
    let radar_w = sidebar_w - 24;
    let radar_h = 154;
    Some(ClassicRtsShellLayout {
        sidebar_x,
        viewport_x,
        viewport_y,
        viewport_w,
        viewport_h,
        bottom_y,
        bottom_h,
        radar_x,
        radar_y,
        radar_w,
        radar_h,
    })
}

#[cfg(not(target_os = "android"))]
fn classic_rts_viewport_tile_center(
    layout: &ClassicRtsShellLayout,
    tile: (i32, i32),
) -> (i32, i32) {
    let cell_w = ((layout.viewport_w - 44).max(120)) / 12;
    let cell_h = ((layout.viewport_h - 74).max(80)) / 8;
    let grid_x = layout.viewport_x + 22;
    let grid_y = layout.viewport_y + 48;
    (
        grid_x + tile.0.clamp(0, 11) * cell_w + cell_w / 2,
        grid_y + tile.1.clamp(0, 7) * cell_h + cell_h / 2,
    )
}

#[cfg(not(target_os = "android"))]
fn classic_rts_hover_target_preview_kind(affordance: &str) -> Option<&'static str> {
    if affordance.contains("attack") {
        Some("attack")
    } else if affordance.contains("harvest") {
        Some("harvest")
    } else if affordance.contains("follow") {
        Some("follow")
    } else if affordance.contains("move") {
        Some("move")
    } else {
        None
    }
}

#[cfg(not(target_os = "android"))]
fn classic_rts_hover_target_preview_color(kind: &str) -> u32 {
    match kind {
        "attack" => CLASSIC_RTS_TARGET_PREVIEW_ATTACK_COLOR,
        "harvest" => CLASSIC_RTS_TARGET_PREVIEW_HARVEST_COLOR,
        "follow" => CLASSIC_RTS_TARGET_PREVIEW_FOLLOW_COLOR,
        _ => CLASSIC_RTS_TARGET_PREVIEW_PATH_COLOR,
    }
}

#[cfg(not(target_os = "android"))]
fn classic_rts_primary_selected_tile(runtime: &NativeFirstPlayableRuntime) -> Option<(i32, i32)> {
    runtime
        .rts_selected_unit_ids
        .first()
        .and_then(|unit_id| classic_rts_selectable_unit_tile(unit_id))
        .or_else(|| {
            runtime
                .rts_selection_box_tile_ids
                .first()
                .and_then(|tile_id| classic_parse_rts_tile(tile_id))
        })
}

#[cfg(not(target_os = "android"))]
fn classic_rts_command_execution_feedback_kind(
    runtime: Option<&NativeFirstPlayableRuntime>,
) -> Option<&'static str> {
    let runtime = runtime?;
    if let Some(recent_feedback_chip) = runtime
        .rts_command_queue
        .iter()
        .rev()
        .find(|entry| entry.starts_with("feedback:"))
    {
        if recent_feedback_chip.starts_with("feedback:harvest_assigned:") {
            return Some("harvest");
        }
        if recent_feedback_chip.starts_with("feedback:follow@") {
            return Some("follow");
        }
        if recent_feedback_chip.starts_with("feedback:attack_move@") {
            return Some("attack");
        }
        if recent_feedback_chip.starts_with("feedback:line@")
            || recent_feedback_chip.starts_with("feedback:diamond@")
            || recent_feedback_chip.starts_with("feedback:waypoint_queued@")
            || recent_feedback_chip.starts_with("feedback:hold_position@")
            || recent_feedback_chip.starts_with("feedback:patrol_route@")
            || recent_feedback_chip.starts_with("feedback:rally_confirmed@")
            || recent_feedback_chip.starts_with("feedback:stop_hold@")
        {
            return Some("move");
        }
    }
    if runtime.rts_unit_response_state.starts_with("following:")
        || runtime.rts_group_command_state.starts_with("follow:")
        || runtime.rts_minimap_command_kind == "follow"
    {
        Some("follow")
    } else if runtime.rts_unit_response_state.starts_with("engaged:")
        || runtime
            .rts_unit_response_state
            .starts_with("attack_move_advancing:")
        || runtime.rts_group_command_state.starts_with("attack_move:")
    {
        Some("attack")
    } else if runtime.rts_command_destination_tile.is_some()
        && runtime.rts_minimap_command_kind != "harvest"
        && !runtime.rts_economy_state.starts_with("harvesting:")
        && (!runtime.rts_path_tile_ids.is_empty() || !runtime.rts_group_route_tile_ids.is_empty())
    {
        Some("move")
    } else if runtime.rts_minimap_command_kind == "harvest"
        || runtime.rts_economy_state.starts_with("harvesting:")
        || runtime
            .rts_command_queue
            .iter()
            .rev()
            .any(|entry| entry.starts_with("harvest:"))
    {
        Some("harvest")
    } else {
        None
    }
}

#[cfg(not(target_os = "android"))]
fn classic_rts_command_execution_feedback_visible(runtime: &NativeFirstPlayableRuntime) -> bool {
    matches!(
        runtime.rts_command_stamp_source.as_str(),
        "classic_rts_mouse_viewport" | "classic_rts_command_execution_test"
    )
}

#[cfg(not(target_os = "android"))]
fn classic_rts_command_execution_target_label(
    runtime: &NativeFirstPlayableRuntime,
    kind: &str,
) -> String {
    match kind {
        "attack" => runtime
            .rts_attack_target_id
            .clone()
            .unwrap_or_else(|| "target".to_string()),
        "follow" => runtime
            .rts_unit_response_state
            .strip_prefix("following:")
            .map(str::to_string)
            .or_else(|| {
                runtime
                    .rts_group_command_state
                    .strip_prefix("follow:")
                    .and_then(|target| target.split('@').next())
                    .map(str::to_string)
            })
            .unwrap_or_else(|| "unit".to_string()),
        "harvest" => runtime
            .rts_harvest_node_ids
            .first()
            .cloned()
            .or_else(|| {
                runtime.rts_command_queue.iter().rev().find_map(|entry| {
                    entry
                        .strip_prefix("harvest:")
                        .and_then(|value| value.split("->").next())
                        .filter(|value| !value.is_empty())
                        .map(str::to_string)
                })
            })
            .unwrap_or_else(|| "resource".to_string()),
        _ => runtime
            .rts_command_destination_tile
            .clone()
            .unwrap_or_else(|| "destination".to_string()),
    }
}

#[cfg(not(target_os = "android"))]
fn classic_rts_command_execution_player_label(
    runtime: &NativeFirstPlayableRuntime,
    kind: &str,
) -> String {
    let target_label = classic_rts_command_execution_target_label(runtime, kind)
        .replace('_', " ")
        .to_ascii_uppercase();
    match kind {
        "attack" => format!("ATTACK FOCUS {target_label}"),
        "follow" => format!("FOLLOWING {target_label}"),
        "harvest" => {
            let dropoff = runtime
                .rts_dropoff_structure_id
                .as_deref()
                .unwrap_or("dropoff")
                .replace('_', " ")
                .to_ascii_uppercase();
            format!("HARVEST {target_label} TO {dropoff}")
        }
        _ => format!("MOVE EXECUTING {target_label}"),
    }
}

#[cfg(not(target_os = "android"))]
fn classic_rts_command_execution_target_tile(
    runtime: &NativeFirstPlayableRuntime,
    kind: &str,
) -> Option<(i32, i32)> {
    let destination_tile = runtime
        .rts_command_destination_tile
        .as_deref()
        .and_then(classic_parse_rts_tile);
    match kind {
        "attack" => runtime
            .rts_attack_target_id
            .as_deref()
            .map(|target_id| classic_rts_target_tile_for_id(target_id, 0))
            .or(destination_tile),
        "follow" => {
            let target_label = classic_rts_command_execution_target_label(runtime, kind);
            classic_rts_selectable_unit_tile(&target_label).or(destination_tile)
        }
        "harvest" => runtime
            .rts_harvest_node_ids
            .first()
            .map(|node_id| classic_rts_harvest_tile_for_node(node_id))
            .or(destination_tile),
        _ => destination_tile,
    }
}

#[cfg(not(target_os = "android"))]
fn classic_draw_rts_command_execution_viewport_ping(
    buffer: &mut [u32],
    width: usize,
    height: usize,
    layout: &ClassicRtsShellLayout,
    tile: (i32, i32),
    active_color: u32,
) {
    let (x, y) = classic_rts_viewport_tile_center(layout, tile);
    classic_draw_rect(buffer, width, height, x - 5, y - 5, 10, 10, active_color);
    classic_draw_rect(
        buffer,
        width,
        height,
        x - 12,
        y - 12,
        24,
        4,
        CLASSIC_RTS_COMMAND_EXECUTION_VIEWPORT_MARKER_COLOR,
    );
    classic_draw_rect(
        buffer,
        width,
        height,
        x - 12,
        y + 8,
        24,
        4,
        CLASSIC_RTS_COMMAND_EXECUTION_VIEWPORT_MARKER_COLOR,
    );
    classic_draw_rect(
        buffer,
        width,
        height,
        x - 12,
        y - 12,
        4,
        24,
        CLASSIC_RTS_COMMAND_EXECUTION_VIEWPORT_MARKER_COLOR,
    );
    classic_draw_rect(
        buffer,
        width,
        height,
        x + 8,
        y - 12,
        4,
        24,
        CLASSIC_RTS_COMMAND_EXECUTION_VIEWPORT_MARKER_COLOR,
    );
}

#[cfg(not(target_os = "android"))]
fn classic_draw_rts_command_execution_viewport_markers(
    buffer: &mut [u32],
    width: usize,
    height: usize,
    layout: &ClassicRtsShellLayout,
    runtime: &NativeFirstPlayableRuntime,
    kind: &str,
    active_color: u32,
) {
    if let Some(source_tile) = classic_rts_primary_selected_tile(runtime) {
        classic_draw_rts_command_execution_viewport_ping(
            buffer,
            width,
            height,
            layout,
            source_tile,
            CLASSIC_RTS_COMMAND_EXECUTION_FRAME_COLOR,
        );
    }
    let route_tiles = if runtime.rts_path_tile_ids.is_empty() {
        &runtime.rts_group_route_tile_ids
    } else {
        &runtime.rts_path_tile_ids
    };
    for tile in route_tiles
        .iter()
        .take(8)
        .filter_map(|tile_id| classic_parse_rts_tile(tile_id))
    {
        classic_draw_rts_command_execution_viewport_ping(
            buffer,
            width,
            height,
            layout,
            tile,
            CLASSIC_RTS_COMMAND_EXECUTION_PATH_COLOR,
        );
    }
    if let Some(target_tile) = classic_rts_command_execution_target_tile(runtime, kind) {
        classic_draw_rts_command_execution_viewport_ping(
            buffer,
            width,
            height,
            layout,
            target_tile,
            active_color,
        );
    }
    if kind == "harvest" {
        if let Some(dropoff_tile) = runtime
            .rts_dropoff_structure_id
            .as_deref()
            .map(classic_rts_dropoff_tile_for_structure)
        {
            classic_draw_rts_command_execution_viewport_ping(
                buffer,
                width,
                height,
                layout,
                dropoff_tile,
                CLASSIC_RTS_COMMAND_EXECUTION_HARVEST_COLOR,
            );
        }
    }
}

#[cfg(not(target_os = "android"))]
fn classic_draw_rts_command_execution_feedback_overlay(
    buffer: &mut [u32],
    width: usize,
    height: usize,
    runtime: &NativeFirstPlayableRuntime,
    kind: &str,
) {
    if width < 580 || height < 300 {
        return;
    }
    let layout = classic_rts_shell_layout(width, height);
    let panel_w = layout
        .as_ref()
        .map(|layout| (layout.viewport_w - 38).clamp(320, 430))
        .unwrap_or_else(|| (width as i32 - 36).clamp(320, 430));
    let panel_h = 98_i32;
    let panel_x = layout
        .as_ref()
        .map(|layout| layout.viewport_x + 18)
        .unwrap_or(18);
    let panel_y = layout
        .as_ref()
        .map(|layout| layout.viewport_y + 106)
        .unwrap_or(108);
    let active_color = match kind {
        "attack" => CLASSIC_RTS_COMMAND_EXECUTION_TARGET_COLOR,
        "follow" => CLASSIC_RTS_COMMAND_EXECUTION_FOLLOW_COLOR,
        "harvest" => CLASSIC_RTS_COMMAND_EXECUTION_HARVEST_COLOR,
        _ => CLASSIC_RTS_COMMAND_EXECUTION_PATH_COLOR,
    };
    if let Some(layout) = layout.as_ref() {
        classic_draw_rts_command_execution_viewport_markers(
            buffer,
            width,
            height,
            layout,
            runtime,
            kind,
            active_color,
        );
    }
    classic_draw_rect(
        buffer,
        width,
        height,
        panel_x,
        panel_y,
        panel_w,
        panel_h,
        CLASSIC_RTS_STRATEGY_PANEL_COLOR,
    );
    classic_draw_rect(
        buffer,
        width,
        height,
        panel_x,
        panel_y,
        panel_w,
        4,
        CLASSIC_RTS_COMMAND_EXECUTION_FRAME_COLOR,
    );
    classic_draw_rect(
        buffer,
        width,
        height,
        panel_x,
        panel_y,
        5,
        panel_h,
        CLASSIC_RTS_COMMAND_EXECUTION_FRAME_COLOR,
    );
    classic_draw_rect(
        buffer,
        width,
        height,
        panel_x,
        panel_y + panel_h - 4,
        panel_w,
        4,
        CLASSIC_RTS_COMMAND_EXECUTION_FRAME_COLOR,
    );
    classic_draw_text(
        buffer,
        width,
        height,
        panel_x + 12,
        panel_y + 11,
        "COMMAND EXECUTION",
        1,
        CLASSIC_HUD_TEXT_COLOR,
    );
    classic_draw_rect(
        buffer,
        width,
        height,
        panel_x + 10,
        panel_y + 24,
        panel_w - 20,
        20,
        CLASSIC_RTS_COMMAND_EXECUTION_LABEL_COLOR,
    );
    classic_draw_rect(
        buffer,
        width,
        height,
        panel_x + 13,
        panel_y + 27,
        panel_w - 26,
        14,
        CLASSIC_RTS_STRATEGY_PANEL_COLOR,
    );
    classic_draw_text(
        buffer,
        width,
        height,
        panel_x + 16,
        panel_y + 30,
        &classic_catalog_text_label(
            &classic_rts_command_execution_player_label(runtime, kind),
            34,
        ),
        1,
        CLASSIC_RTS_COMMAND_EXECUTION_LABEL_COLOR,
    );

    let route_tiles = if runtime.rts_path_tile_ids.is_empty() {
        &runtime.rts_group_route_tile_ids
    } else {
        &runtime.rts_path_tile_ids
    };
    for (index, _) in route_tiles.iter().take(10).enumerate() {
        let x = panel_x + 14 + index as i32 * 26;
        let y = panel_y + 49 + (index as i32 % 2) * 4;
        classic_draw_rect(
            buffer,
            width,
            height,
            x,
            y,
            20,
            5,
            CLASSIC_RTS_COMMAND_EXECUTION_PATH_COLOR,
        );
    }
    if route_tiles.is_empty() {
        for index in 0..5 {
            classic_draw_rect(
                buffer,
                width,
                height,
                panel_x + 14 + index * 26,
                panel_y + 50 + (index % 2) * 4,
                20,
                5,
                CLASSIC_RTS_COMMAND_EXECUTION_PATH_COLOR,
            );
        }
    }

    let target_label = classic_rts_command_execution_target_label(runtime, kind);
    match kind {
        "attack" => {
            let cross_x = panel_x + panel_w - 78;
            let cross_y = panel_y + 48;
            classic_draw_rect(
                buffer,
                width,
                height,
                cross_x - 22,
                cross_y,
                52,
                5,
                CLASSIC_RTS_COMMAND_EXECUTION_TARGET_COLOR,
            );
            classic_draw_rect(
                buffer,
                width,
                height,
                cross_x,
                cross_y - 18,
                5,
                42,
                CLASSIC_RTS_COMMAND_EXECUTION_TARGET_COLOR,
            );
            classic_draw_rect(
                buffer,
                width,
                height,
                cross_x - 18,
                cross_y - 18,
                38,
                4,
                CLASSIC_RTS_COMMAND_EXECUTION_TARGET_COLOR,
            );
            classic_draw_text(
                buffer,
                width,
                height,
                panel_x + 12,
                panel_y + 69,
                &classic_catalog_text_label(&format!("FOCUS {target_label}"), 40),
                1,
                CLASSIC_RTS_COMMAND_EXECUTION_TARGET_COLOR,
            );
        }
        "follow" => {
            for index in 0..4 {
                classic_draw_rect(
                    buffer,
                    width,
                    height,
                    panel_x + panel_w - 104 + index * 18,
                    panel_y + 48 + index % 2 * 9,
                    15,
                    15,
                    CLASSIC_RTS_COMMAND_EXECUTION_FOLLOW_COLOR,
                );
            }
            classic_draw_text(
                buffer,
                width,
                height,
                panel_x + 12,
                panel_y + 69,
                &classic_catalog_text_label(&format!("FOLLOW {target_label}"), 40),
                1,
                CLASSIC_RTS_COMMAND_EXECUTION_FOLLOW_COLOR,
            );
        }
        "harvest" => {
            for (index, worker) in runtime.rts_worker_assignment_ids.iter().take(4).enumerate() {
                let chip_x = panel_x + panel_w - 140 + index as i32 * 31;
                classic_draw_rect(
                    buffer,
                    width,
                    height,
                    chip_x,
                    panel_y + 47,
                    24,
                    16,
                    CLASSIC_RTS_COMMAND_EXECUTION_HARVEST_COLOR,
                );
                classic_draw_rect(
                    buffer,
                    width,
                    height,
                    chip_x + 4,
                    panel_y + 51,
                    16,
                    8,
                    CLASSIC_RTS_STRATEGY_PANEL_COLOR,
                );
                classic_draw_text(
                    buffer,
                    width,
                    height,
                    chip_x + 2,
                    panel_y + 66,
                    &classic_catalog_text_label(worker, 3),
                    1,
                    CLASSIC_RTS_COMMAND_EXECUTION_HARVEST_COLOR,
                );
            }
            classic_draw_text(
                buffer,
                width,
                height,
                panel_x + 12,
                panel_y + 69,
                &classic_catalog_text_label(
                    &format!(
                        "HARVEST {target_label}->{dropoff}",
                        dropoff = runtime
                            .rts_dropoff_structure_id
                            .as_deref()
                            .unwrap_or("dropoff")
                    ),
                    40,
                ),
                1,
                CLASSIC_RTS_COMMAND_EXECUTION_HARVEST_COLOR,
            );
        }
        _ => {
            if let Some(tile_id) = &runtime.rts_command_destination_tile {
                classic_draw_rect(
                    buffer,
                    width,
                    height,
                    panel_x + panel_w - 92,
                    panel_y + 45,
                    58,
                    20,
                    CLASSIC_RTS_COMMAND_EXECUTION_PATH_COLOR,
                );
                classic_draw_text(
                    buffer,
                    width,
                    height,
                    panel_x + panel_w - 84,
                    panel_y + 52,
                    tile_id,
                    1,
                    CLASSIC_RTS_STRATEGY_PANEL_COLOR,
                );
            }
            classic_draw_text(
                buffer,
                width,
                height,
                panel_x + 12,
                panel_y + 69,
                &classic_catalog_text_label(&runtime.rts_group_command_state, 40),
                1,
                CLASSIC_RTS_COMMAND_EXECUTION_PATH_COLOR,
            );
        }
    }
}

#[cfg(not(target_os = "android"))]
fn classic_rts_drag_distance_sq(start: (i32, i32), end: (i32, i32)) -> i32 {
    let dx = end.0 - start.0;
    let dy = end.1 - start.1;
    dx * dx + dy * dy
}

#[cfg(not(target_os = "android"))]
fn classic_draw_live_mouse_drag_marquee(
    buffer: &mut [u32],
    width: usize,
    height: usize,
    mouse_latch: &ClassicRuntimeMouseLatch,
) {
    let (Some(start), Some(current)) = (mouse_latch.left_anchor, mouse_latch.left_current) else {
        return;
    };
    if !mouse_latch.left_down || classic_rts_drag_distance_sq(start, current) < 36 {
        return;
    }
    let x = start.0.min(current.0);
    let y = start.1.min(current.1);
    let w = (start.0 - current.0).abs().max(1);
    let h = (start.1 - current.1).abs().max(1);
    classic_draw_rect(
        buffer,
        width,
        height,
        x,
        y,
        w,
        2,
        CLASSIC_RTS_SELECTION_BOX_COLOR,
    );
    classic_draw_rect(
        buffer,
        width,
        height,
        x,
        y + h - 1,
        w,
        2,
        CLASSIC_RTS_SELECTION_BOX_COLOR,
    );
    classic_draw_rect(
        buffer,
        width,
        height,
        x,
        y,
        2,
        h,
        CLASSIC_RTS_SELECTION_BOX_COLOR,
    );
    classic_draw_rect(
        buffer,
        width,
        height,
        x + w - 1,
        y,
        2,
        h,
        CLASSIC_RTS_SELECTION_BOX_COLOR,
    );
    classic_draw_text(
        buffer,
        width,
        height,
        x + 6,
        y + 6,
        "DRAG SELECT",
        1,
        CLASSIC_HUD_TEXT_COLOR,
    );
}

#[cfg(not(target_os = "android"))]
fn classic_rts_drag_select_player_label(
    start_tile_id: &str,
    current_tile_id: &str,
    unit_count: usize,
) -> String {
    format!(
        "DRAG SELECT {} {} {}->{}",
        unit_count,
        if unit_count == 1 { "UNIT" } else { "UNITS" },
        start_tile_id,
        current_tile_id
    )
}

#[cfg(not(target_os = "android"))]
fn classic_rts_drag_select_preview_from_points(
    _runtime: &NativeFirstPlayableRuntime,
    width: usize,
    height: usize,
    start: (i32, i32),
    current: (i32, i32),
) -> Option<ClassicRtsDragSelectPreview> {
    if classic_rts_drag_distance_sq(start, current) < 36 {
        return None;
    }
    let layout = classic_rts_shell_layout(width, height)?;
    if !classic_point_in_rect(
        start.0,
        start.1,
        layout.viewport_x,
        layout.viewport_y,
        layout.viewport_w,
        layout.viewport_h,
    ) || !classic_point_in_rect(
        current.0,
        current.1,
        layout.viewport_x,
        layout.viewport_y,
        layout.viewport_w,
        layout.viewport_h,
    ) {
        return None;
    }
    let start_tile = classic_mouse_viewport_world_tile(
        _runtime,
        start.0,
        start.1,
        layout.viewport_x,
        layout.viewport_y,
        layout.viewport_w,
        layout.viewport_h,
    );
    let current_tile = classic_mouse_viewport_world_tile(
        _runtime,
        current.0,
        current.1,
        layout.viewport_x,
        layout.viewport_y,
        layout.viewport_w,
        layout.viewport_h,
    );
    let start_tile_id = classic_rts_tile_id(start_tile);
    let current_tile_id = classic_rts_tile_id(current_tile);
    let selection_tile_ids = classic_rts_selection_box_tiles_between(start_tile, current_tile);
    let candidate_unit_ids = classic_rts_drag_selected_units(start_tile, current_tile);
    let rejected_unit_ids = classic_rts_drag_rejected_unit_ids(start_tile, current_tile);
    let player_label = classic_rts_drag_select_player_label(
        &start_tile_id,
        &current_tile_id,
        candidate_unit_ids.len(),
    );
    Some(ClassicRtsDragSelectPreview {
        input_source: "classic_rts_mouse_drag".to_string(),
        start_tile_id,
        current_tile_id,
        selection_tile_ids,
        candidate_unit_ids,
        rejected_unit_ids,
        player_label,
    })
}

#[cfg(not(target_os = "android"))]
fn apply_classic_rts_drag_select_preview_from_points(
    runtime: &mut NativeFirstPlayableRuntime,
    width: usize,
    height: usize,
    start: (i32, i32),
    current: (i32, i32),
) -> Option<ClassicRtsDragSelectPreview> {
    let preview =
        classic_rts_drag_select_preview_from_points(runtime, width, height, start, current);
    if let Some(preview) = &preview {
        runtime.rts_drag_select_source = preview.input_source.clone();
        runtime.rts_drag_select_start_tile_id = Some(preview.start_tile_id.clone());
        runtime.rts_drag_select_current_tile_id = Some(preview.current_tile_id.clone());
        runtime.rts_drag_select_tile_ids = preview.selection_tile_ids.clone();
        runtime.rts_drag_select_unit_ids = preview.candidate_unit_ids.clone();
        runtime.rts_drag_select_player_label = preview.player_label.clone();
    } else {
        clear_classic_rts_drag_select_preview_runtime(runtime);
    }
    preview
}

#[cfg(not(target_os = "android"))]
fn apply_classic_rts_drag_select_preview_runtime(
    runtime: &mut NativeFirstPlayableRuntime,
    width: usize,
    height: usize,
    mouse_latch: &ClassicRuntimeMouseLatch,
) -> Option<ClassicRtsDragSelectPreview> {
    if !mouse_latch.left_down {
        clear_classic_rts_drag_select_preview_runtime(runtime);
        return None;
    }
    let Some(start) = mouse_latch.left_anchor else {
        clear_classic_rts_drag_select_preview_runtime(runtime);
        return None;
    };
    let Some(current) = mouse_latch.left_current else {
        clear_classic_rts_drag_select_preview_runtime(runtime);
        return None;
    };
    apply_classic_rts_drag_select_preview_from_points(runtime, width, height, start, current)
}

#[cfg(not(target_os = "android"))]
fn clear_classic_rts_drag_select_preview_runtime(runtime: &mut NativeFirstPlayableRuntime) {
    runtime.rts_drag_select_source.clear();
    runtime.rts_drag_select_start_tile_id = None;
    runtime.rts_drag_select_current_tile_id = None;
    runtime.rts_drag_select_tile_ids.clear();
    runtime.rts_drag_select_unit_ids.clear();
    runtime.rts_drag_select_player_label.clear();
}

