#[cfg(not(target_os = "android"))]
fn classic_rts_mouse_action_with_source_from_point_with_modifiers(
    runtime: &NativeFirstPlayableRuntime,
    width: usize,
    height: usize,
    mouse_x: i32,
    mouse_y: i32,
    button: MiniMouseButton,
    shift_pressed: bool,
    double_click: bool,
) -> Option<ClassicPolledAction> {
    let layout = classic_rts_shell_layout(width, height)?;

    if classic_point_in_rect(
        mouse_x,
        mouse_y,
        layout.radar_x,
        layout.radar_y,
        layout.radar_w,
        layout.radar_h,
    ) {
        let tile_id = classic_rts_tile_id(classic_mouse_grid_tile(
            mouse_x,
            mouse_y,
            layout.radar_x,
            layout.radar_y,
            layout.radar_w,
            layout.radar_h,
        ));
        return match button {
            MiniMouseButton::Left | MiniMouseButton::Right => Some(ClassicPolledAction::new(
                "classic_rts_mouse_minimap",
                NativeControlAction::RtsMoveCommand {
                    command_id: format!("minimap:{tile_id}:rally"),
                },
            )),
            MiniMouseButton::Middle => None,
        };
    }

    if let Some(action) =
        classic_rts_sidebar_action_from_point(runtime, &layout, mouse_x, mouse_y, button)
    {
        return Some(ClassicPolledAction::new(
            "classic_rts_mouse_sidebar",
            action,
        ));
    }

    if let Some(action) =
        classic_rts_bottom_action_from_point(runtime, &layout, mouse_x, mouse_y, button)
    {
        return Some(ClassicPolledAction::new(
            "classic_rts_mouse_command_bar",
            action,
        ));
    }

    if classic_point_in_rect(
        mouse_x,
        mouse_y,
        8,
        layout.bottom_y,
        layout.sidebar_x - 16,
        layout.bottom_h,
    ) {
        return match button {
            MiniMouseButton::Left => Some(ClassicPolledAction::new(
                "classic_rts_mouse_bottom_panel",
                NativeControlAction::RtsSelectControlGroup {
                    group_id: "box:frontline".to_string(),
                },
            )),
            MiniMouseButton::Right => Some(ClassicPolledAction::new(
                "classic_rts_mouse_bottom_panel",
                NativeControlAction::RtsAbilityCommand {
                    ability_id: classic_next_runtime_rts_ability(runtime),
                },
            )),
            MiniMouseButton::Middle => None,
        };
    }

    if classic_point_in_rect(
        mouse_x,
        mouse_y,
        layout.viewport_x,
        layout.viewport_y,
        layout.viewport_w,
        layout.viewport_h,
    ) {
        return match button {
            MiniMouseButton::Left => {
                let tile = classic_mouse_viewport_world_tile(
                    runtime,
                    mouse_x,
                    mouse_y,
                    layout.viewport_x,
                    layout.viewport_y,
                    layout.viewport_w,
                    layout.viewport_h,
                );
                let tile_id = classic_rts_tile_id(tile);
                let group_id = match classic_rts_selectable_unit_at_tile(tile) {
                    Some(unit_id) if classic_rts_unit_is_player_owned(unit_id) => {
                        if double_click {
                            format!("double:unit:{unit_id}")
                        } else if shift_pressed {
                            format!("shift:unit:{unit_id}")
                        } else {
                            format!("unit:{unit_id}")
                        }
                    }
                    Some(unit_id) if !shift_pressed => {
                        format!("clear:hostile:{unit_id}@{tile_id}")
                    }
                    None if !shift_pressed => format!("clear:empty@{tile_id}"),
                    _ => return None,
                };
                Some(ClassicPolledAction::new(
                    "classic_rts_mouse_viewport",
                    NativeControlAction::RtsSelectControlGroup { group_id },
                ))
            }
            MiniMouseButton::Right => {
                let tile = classic_mouse_viewport_world_tile(
                    runtime,
                    mouse_x,
                    mouse_y,
                    layout.viewport_x,
                    layout.viewport_y,
                    layout.viewport_w,
                    layout.viewport_h,
                );
                Some(ClassicPolledAction::new(
                    "classic_rts_mouse_viewport",
                    classic_rts_viewport_context_action_for_tile(runtime, tile),
                ))
            }
            MiniMouseButton::Middle => None,
        };
    }
    None
}

#[cfg(not(target_os = "android"))]
fn classic_rts_hover_preview_from_action(
    runtime: &NativeFirstPlayableRuntime,
    input_source: &'static str,
    tile_id: Option<String>,
    queue_id: Option<String>,
    affordance: &'static str,
    action: NativeControlAction,
) -> ClassicRtsHoverPreview {
    let action_label = native_control_action_label(&action);
    let (accepted, reason) = native_live_action_availability(runtime, &action);
    let player_label = classic_rts_hover_player_label(
        input_source,
        &action_label,
        tile_id.as_deref(),
        queue_id.as_deref(),
        affordance,
        accepted,
        &reason,
    );
    ClassicRtsHoverPreview {
        input_source: input_source.to_string(),
        tile_id,
        action_label,
        player_label,
        queue_id,
        affordance: affordance.to_string(),
        accepted,
        reason,
    }
}

#[cfg(not(target_os = "android"))]
fn classic_rts_hover_preview_from_point(
    runtime: &NativeFirstPlayableRuntime,
    width: usize,
    height: usize,
    mouse_x: i32,
    mouse_y: i32,
) -> Option<ClassicRtsHoverPreview> {
    let layout = classic_rts_shell_layout(width, height)?;

    if classic_point_in_rect(
        mouse_x,
        mouse_y,
        layout.radar_x,
        layout.radar_y,
        layout.radar_w,
        layout.radar_h,
    ) {
        let tile_id = classic_rts_tile_id(classic_mouse_grid_tile(
            mouse_x,
            mouse_y,
            layout.radar_x,
            layout.radar_y,
            layout.radar_w,
            layout.radar_h,
        ));
        return Some(classic_rts_hover_preview_from_action(
            runtime,
            "classic_rts_mouse_minimap",
            Some(tile_id.clone()),
            None,
            "minimap_rally",
            NativeControlAction::RtsMoveCommand {
                command_id: format!("minimap:{tile_id}:rally"),
            },
        ));
    }

    if let Some(preview) =
        classic_rts_sidebar_hover_preview_from_point(runtime, &layout, mouse_x, mouse_y)
    {
        return Some(preview);
    }

    if let Some(preview) =
        classic_rts_bottom_hover_preview_from_point(runtime, &layout, mouse_x, mouse_y)
    {
        return Some(preview);
    }

    if classic_point_in_rect(
        mouse_x,
        mouse_y,
        8,
        layout.bottom_y,
        layout.sidebar_x - 16,
        layout.bottom_h,
    ) {
        return Some(classic_rts_hover_preview_from_action(
            runtime,
            "classic_rts_mouse_bottom_panel",
            None,
            None,
            "selection_panel",
            NativeControlAction::RtsSelectControlGroup {
                group_id: "box:frontline".to_string(),
            },
        ));
    }

    if classic_point_in_rect(
        mouse_x,
        mouse_y,
        layout.viewport_x,
        layout.viewport_y,
        layout.viewport_w,
        layout.viewport_h,
    ) {
        let tile = classic_mouse_viewport_world_tile(
            runtime,
            mouse_x,
            mouse_y,
            layout.viewport_x,
            layout.viewport_y,
            layout.viewport_w,
            layout.viewport_h,
        );
        let tile_id = classic_rts_tile_id(tile);
        let action = classic_rts_viewport_context_action_for_tile(runtime, tile);
        let queue_id = match &action {
            NativeControlAction::RtsQueueProduction { queue_id } => Some(queue_id.clone()),
            _ => None,
        };
        let affordance = classic_rts_viewport_context_affordance(&action);
        return Some(classic_rts_hover_preview_from_action(
            runtime,
            "classic_rts_mouse_viewport",
            Some(tile_id.clone()),
            queue_id,
            affordance,
            action,
        ));
    }
    None
}

#[cfg(not(target_os = "android"))]
fn classic_rts_cursor_kind_for_hover_preview(preview: &ClassicRtsHoverPreview) -> &'static str {
    if !preview.accepted {
        return "blocked";
    }
    if preview.affordance.contains("attack") {
        "attack"
    } else if preview.affordance.contains("harvest") {
        "harvest"
    } else if preview.affordance.contains("follow") {
        "follow"
    } else if preview.affordance.contains("build") || preview.affordance.contains("queue") {
        "build"
    } else if preview.affordance.contains("command_button") {
        "ability"
    } else if preview.affordance.contains("rally") || preview.affordance.contains("minimap") {
        "rally"
    } else if preview.affordance.contains("selection")
        || preview.action_label.starts_with("RTS:SELECT:")
    {
        "select"
    } else {
        "move"
    }
}

#[cfg(not(target_os = "android"))]
fn classic_rts_cursor_label_for_hover_preview(
    preview: &ClassicRtsHoverPreview,
    cursor_kind: &str,
) -> String {
    let source =
        classic_rts_input_source_player_label(&preview.input_source, &preview.action_label);
    let state = if preview.accepted { "READY" } else { "LOCK" };
    format!(
        "{source} CURSOR {} {state}",
        cursor_kind.replace('-', " ").to_ascii_uppercase()
    )
}

#[cfg(not(target_os = "android"))]
fn apply_classic_rts_context_cursor_runtime(
    runtime: &mut NativeFirstPlayableRuntime,
    preview: &ClassicRtsHoverPreview,
    mouse_x: i32,
    mouse_y: i32,
) {
    let cursor_kind = classic_rts_cursor_kind_for_hover_preview(preview);
    runtime.rts_cursor_source = preview.input_source.clone();
    runtime.rts_cursor_screen_x = mouse_x;
    runtime.rts_cursor_screen_y = mouse_y;
    runtime.rts_cursor_tile_id = preview.tile_id.clone();
    runtime.rts_cursor_kind = cursor_kind.to_string();
    runtime.rts_cursor_player_label =
        classic_rts_cursor_label_for_hover_preview(preview, cursor_kind);
    runtime.rts_cursor_allowed = preview.accepted;
}

#[cfg(not(target_os = "android"))]
fn apply_classic_rts_hover_preview_runtime(
    runtime: &mut NativeFirstPlayableRuntime,
    width: usize,
    height: usize,
    mouse_x: i32,
    mouse_y: i32,
) -> Option<ClassicRtsHoverPreview> {
    let preview = classic_rts_hover_preview_from_point(runtime, width, height, mouse_x, mouse_y);
    if let Some(preview) = &preview {
        runtime.rts_hover_source = preview.input_source.clone();
        runtime.rts_hover_tile_id = preview.tile_id.clone();
        runtime.rts_hover_action_label = preview.action_label.clone();
        runtime.rts_hover_player_label = preview.player_label.clone();
        runtime.rts_hover_queue_id = preview.queue_id.clone();
        runtime.rts_hover_affordance = preview.affordance.clone();
        apply_classic_rts_context_cursor_runtime(runtime, preview, mouse_x, mouse_y);
    } else {
        clear_classic_rts_hover_preview_runtime(runtime);
    }
    preview
}

#[cfg(not(target_os = "android"))]
fn clear_classic_rts_hover_preview_runtime(runtime: &mut NativeFirstPlayableRuntime) {
    runtime.rts_hover_source.clear();
    runtime.rts_hover_tile_id = None;
    runtime.rts_hover_action_label.clear();
    runtime.rts_hover_player_label.clear();
    runtime.rts_hover_queue_id = None;
    runtime.rts_hover_affordance.clear();
    clear_classic_rts_context_cursor_runtime(runtime);
}

#[cfg(not(target_os = "android"))]
fn clear_classic_rts_context_cursor_runtime(runtime: &mut NativeFirstPlayableRuntime) {
    runtime.rts_cursor_source.clear();
    runtime.rts_cursor_screen_x = 0;
    runtime.rts_cursor_screen_y = 0;
    runtime.rts_cursor_tile_id = None;
    runtime.rts_cursor_kind.clear();
    runtime.rts_cursor_player_label.clear();
    runtime.rts_cursor_allowed = false;
}

#[cfg(not(target_os = "android"))]
fn classic_rts_command_stamp_for_action(
    runtime: &NativeFirstPlayableRuntime,
    input_source: &str,
    action: &NativeControlAction,
) -> Option<ClassicRtsCommandStamp> {
    let action_label = native_control_action_label(action);
    let source = classic_rts_input_source_player_label(input_source, &action_label);
    match action {
        NativeControlAction::RtsSelectControlGroup { group_id } => {
            if let Some((clear_kind, unit_id, tile_id)) =
                classic_rts_selection_clear_parts(group_id)
            {
                let select_label = if unit_id.is_some() {
                    format!("SELECTION CLEARED {}", clear_kind.to_ascii_uppercase())
                } else {
                    "SELECTION CLEARED".to_string()
                };
                return Some(ClassicRtsCommandStamp {
                    input_source: input_source.to_string(),
                    kind: "select-clear".to_string(),
                    tile_id: Some(tile_id),
                    target_id: unit_id,
                    player_label: format!("{source} {select_label}"),
                });
            }
            let selected_count = runtime.rts_selected_unit_ids.len().max(1);
            let unit_word = if selected_count == 1 { "UNIT" } else { "UNITS" };
            let (kind, select_label, target_id) =
                if let Some(slot) = group_id.strip_prefix("assign:") {
                    (
                        "control-group",
                        format!("GROUP {slot} ASSIGNED"),
                        Some(slot.to_string()),
                    )
                } else if let Some(slot) = group_id.strip_prefix("append:") {
                    (
                        "control-group",
                        format!("GROUP {slot} APPENDED"),
                        Some(slot.to_string()),
                    )
                } else if let Some(slot) = group_id.strip_prefix("recall:") {
                    (
                        "control-group",
                        format!("GROUP {slot} RECALLED"),
                        Some(slot.to_string()),
                    )
                } else if let Some(slot) = group_id.strip_prefix("recall_add:") {
                    (
                        "control-group",
                        format!("GROUP {slot} ADDED"),
                        Some(slot.to_string()),
                    )
                } else if let Some(slot) = group_id.strip_prefix("camera:") {
                    (
                        "control-group-camera",
                        format!("GROUP {slot} CAMERA SNAP"),
                        Some(slot.to_string()),
                    )
                } else if group_id.starts_with("shift:unit:") {
                    ("select", "SHIFT SELECT".to_string(), Some(group_id.clone()))
                } else if group_id.starts_with("double:unit:") {
                    (
                        "select",
                        "DOUBLE SELECT".to_string(),
                        Some(group_id.clone()),
                    )
                } else {
                    ("select", "SELECT".to_string(), Some(group_id.clone()))
                };
            let player_label = if group_id.starts_with("camera:") {
                format!("{source} {select_label}")
            } else if kind == "select" {
                format!("{source} {select_label} SENT {selected_count} {unit_word}")
            } else {
                format!("{source} {select_label} {selected_count} {unit_word}")
            };
            Some(ClassicRtsCommandStamp {
                input_source: input_source.to_string(),
                kind: kind.to_string(),
                tile_id: None,
                target_id,
                player_label,
            })
        }
        NativeControlAction::RtsQueueProduction { queue_id } => {
            let (kind, target_id, tile_id, item_label) = if queue_id.starts_with("build:") {
                let (structure_id, tile_id) = classic_rts_build_parts(queue_id);
                (
                    "build",
                    structure_id.clone(),
                    Some(tile_id),
                    classic_catalog_text_label(&structure_id.replace('_', " "), 20),
                )
            } else if let Some(unit_id) = queue_id.strip_prefix("train:") {
                (
                    "train",
                    unit_id.to_string(),
                    None,
                    classic_catalog_text_label(&unit_id.replace('_', " "), 20),
                )
            } else if let Some(node_id) = queue_id.strip_prefix("harvest:") {
                let tile_id = classic_rts_tile_id(classic_rts_harvest_tile_for_node(node_id));
                (
                    "harvest",
                    node_id.to_string(),
                    Some(tile_id),
                    classic_catalog_text_label(&node_id.replace('_', " "), 20),
                )
            } else if queue_id.starts_with("upgrade:") {
                let (upgrade_id, source_id) =
                    classic_rts_tech_parts(queue_id, "upgrade:", "training_hall");
                (
                    "upgrade",
                    upgrade_id.clone(),
                    Some(classic_rts_tile_id(classic_rts_structure_tile_for_id(
                        &source_id,
                    ))),
                    classic_catalog_text_label(&upgrade_id.replace('_', " "), 20),
                )
            } else {
                (
                    "queue",
                    queue_id.to_string(),
                    None,
                    classic_catalog_text_label(&queue_id.replace('_', " "), 20),
                )
            };
            let tile_suffix = tile_id
                .as_deref()
                .map(|tile| format!(" {tile}"))
                .unwrap_or_default();
            Some(ClassicRtsCommandStamp {
                input_source: input_source.to_string(),
                kind: kind.to_string(),
                tile_id,
                target_id: Some(target_id),
                player_label: format!(
                    "{source} {} SENT {item_label}{tile_suffix}",
                    kind.to_ascii_uppercase()
                ),
            })
        }
        NativeControlAction::RtsMoveCommand { command_id } => {
            let (tile_id, formation) = classic_rts_move_command_parts(command_id);
            classic_parse_rts_tile(tile_id)?;
            let follow_target_id = classic_rts_move_follow_target(formation);
            let formation_kind = classic_rts_move_formation_kind(formation);
            let kind = if command_id.starts_with("minimap:") || formation_kind == "rally" {
                "rally"
            } else if formation_kind == "shift_waypoint" {
                "waypoint"
            } else if formation_kind == "attack_move" {
                "attack-move"
            } else if formation_kind == "patrol" {
                "patrol"
            } else if formation_kind == "hold" {
                "hold"
            } else if formation_kind == "stop" {
                "stop"
            } else if formation_kind == "follow" {
                "follow"
            } else {
                "move"
            };
            let target_id = follow_target_id.map(ToOwned::to_owned);
            let player_label = if let Some(target_id) = follow_target_id {
                format!(
                    "{source} FOLLOW SENT {}",
                    classic_catalog_text_label(&target_id.replace('_', " "), 22)
                )
            } else {
                format!(
                    "{source} {} SENT {tile_id}",
                    kind.replace('-', " ").to_ascii_uppercase()
                )
            };
            Some(ClassicRtsCommandStamp {
                input_source: input_source.to_string(),
                kind: kind.to_string(),
                tile_id: Some(tile_id.to_string()),
                target_id,
                player_label,
            })
        }
        NativeControlAction::RtsAttackCommand { target_id } => {
            let tile_id = classic_rts_tile_id(classic_rts_target_tile_for_id(target_id, 0));
            Some(ClassicRtsCommandStamp {
                input_source: input_source.to_string(),
                kind: "attack".to_string(),
                tile_id: Some(tile_id),
                target_id: Some(target_id.clone()),
                player_label: format!(
                    "{source} ATTACK SENT {}",
                    classic_catalog_text_label(&target_id.replace('_', " "), 22)
                ),
            })
        }
        NativeControlAction::RtsAbilityCommand { ability_id } => {
            let target_id = runtime.rts_attack_target_id.clone();
            let tile_id = target_id
                .as_deref()
                .map(|target| classic_rts_tile_id(classic_rts_target_tile_for_id(target, 0)));
            Some(ClassicRtsCommandStamp {
                input_source: input_source.to_string(),
                kind: "ability".to_string(),
                tile_id,
                target_id,
                player_label: format!(
                    "{source} ABILITY SENT {}",
                    classic_catalog_text_label(&ability_id.replace('_', " "), 22)
                ),
            })
        }
        _ => None,
    }
}

#[cfg(not(target_os = "android"))]
fn apply_classic_rts_command_stamp_for_action(
    runtime: &mut NativeFirstPlayableRuntime,
    input_source: &str,
    action: &NativeControlAction,
) -> Option<ClassicRtsCommandStamp> {
    let stamp = classic_rts_command_stamp_for_action(runtime, input_source, action);
    if let Some(stamp) = &stamp {
        runtime.rts_command_stamp_source = stamp.input_source.clone();
        runtime.rts_command_stamp_kind = stamp.kind.clone();
        runtime.rts_command_stamp_tile_id = stamp.tile_id.clone();
        runtime.rts_command_stamp_target_id = stamp.target_id.clone();
        runtime.rts_command_stamp_player_label = stamp.player_label.clone();
    } else {
        clear_classic_rts_command_stamp_runtime(runtime);
    }
    stamp
}

#[cfg(not(target_os = "android"))]
fn clear_classic_rts_command_stamp_runtime(runtime: &mut NativeFirstPlayableRuntime) {
    runtime.rts_command_stamp_source.clear();
    runtime.rts_command_stamp_kind.clear();
    runtime.rts_command_stamp_tile_id = None;
    runtime.rts_command_stamp_target_id = None;
    runtime.rts_command_stamp_player_label.clear();
}

#[cfg(not(target_os = "android"))]
fn classic_rts_sidebar_action_from_point(
    runtime: &NativeFirstPlayableRuntime,
    layout: &ClassicRtsShellLayout,
    mouse_x: i32,
    mouse_y: i32,
    button: MiniMouseButton,
) -> Option<NativeControlAction> {
    if !matches!(button, MiniMouseButton::Left | MiniMouseButton::Right) {
        return None;
    }
    let prod_y = layout.radar_y + layout.radar_h + 16;
    let first_contact_chrome = classic_first_contact_player_screen_chrome_for_runtime(runtime);
    let production_slot_visible_count = first_contact_chrome
        .as_ref()
        .map(|chrome| chrome.production_slot_visible_count.max(1) as usize)
        .unwrap_or(4);
    let production_slot_column_count = first_contact_chrome
        .as_ref()
        .map(|chrome| chrome.production_slot_column_count.max(1) as usize)
        .unwrap_or(2);
    if let Some(index) = rts_bevy_runtime::rts_runtime_hit_test_grid(
        RtsRuntimeGridSpec {
            origin_x: layout.sidebar_x + 12,
            origin_y: prod_y + 18,
            columns: production_slot_column_count,
            count: production_slot_visible_count,
            stride_x: 116,
            stride_y: 34,
            slot_width: 56,
            slot_height: 18,
        },
        mouse_x,
        mouse_y,
    ) {
        if matches!(button, MiniMouseButton::Right) {
            return classic_rts_sidebar_cancel_action(runtime, index);
        }
        return Some(NativeControlAction::RtsQueueProduction {
            queue_id: classic_rts_production_slot_queue_id(runtime, index),
        });
    }
    let palette_y = prod_y + 98;
    let build_palette_visible_count = first_contact_chrome
        .as_ref()
        .map(|chrome| chrome.build_palette_visible_count.max(1) as usize)
        .unwrap_or(8);
    let build_palette_column_count = first_contact_chrome
        .as_ref()
        .map(|chrome| chrome.build_palette_column_count.max(1) as usize)
        .unwrap_or(4);
    if let Some(index) = rts_bevy_runtime::rts_runtime_hit_test_grid(
        RtsRuntimeGridSpec {
            origin_x: layout.sidebar_x + 12,
            origin_y: palette_y + 18,
            columns: build_palette_column_count,
            count: build_palette_visible_count,
            stride_x: 58,
            stride_y: 46,
            slot_width: 46,
            slot_height: 36,
        },
        mouse_x,
        mouse_y,
    ) {
        let queue_id =
            classic_rts_build_palette_queue_id_for_index(first_contact_chrome.as_ref(), index);
        if matches!(button, MiniMouseButton::Right) {
            return classic_rts_palette_cancel_action(runtime, &queue_id);
        }
        return Some(NativeControlAction::RtsQueueProduction { queue_id });
    }
    None
}

#[cfg(not(target_os = "android"))]
fn classic_rts_bottom_action_from_point(
    runtime: &NativeFirstPlayableRuntime,
    layout: &ClassicRtsShellLayout,
    mouse_x: i32,
    mouse_y: i32,
    button: MiniMouseButton,
) -> Option<NativeControlAction> {
    if !matches!(button, MiniMouseButton::Left | MiniMouseButton::Right) {
        return None;
    }
    let command_x = 360;
    let first_contact_chrome = classic_first_contact_player_screen_chrome_for_runtime(runtime);
    let command_grid_slot_count = first_contact_chrome
        .as_ref()
        .map(|chrome| chrome.command_grid_slot_count.max(1) as usize)
        .unwrap_or(12);
    let command_grid_column_count = first_contact_chrome
        .as_ref()
        .map(|chrome| chrome.command_grid_column_count.max(1) as usize)
        .unwrap_or(6);
    if let Some(index) = rts_bevy_runtime::rts_runtime_hit_test_grid(
        RtsRuntimeGridSpec {
            origin_x: command_x,
            origin_y: layout.bottom_y + 30,
            columns: command_grid_column_count,
            count: command_grid_slot_count,
            stride_x: 58,
            stride_y: 46,
            slot_width: 48,
            slot_height: 38,
        },
        mouse_x,
        mouse_y,
    ) {
        let ability =
            classic_rts_command_slot_id_for_index(runtime, first_contact_chrome.as_ref(), index);
        return Some(NativeControlAction::RtsAbilityCommand {
            ability_id: ability,
        });
    }
    let queue_x = command_x + 374;
    let order_queue_visible_count = first_contact_chrome
        .as_ref()
        .map(|chrome| chrome.order_queue_visible_count.max(1) as usize)
        .unwrap_or(5);
    for (index, order) in runtime
        .rts_command_queue
        .iter()
        .rev()
        .take(order_queue_visible_count)
        .enumerate()
    {
        let y = layout.bottom_y + 32 + index as i32 * 18;
        if classic_point_in_rect(mouse_x, mouse_y, queue_x, y, 220, 14) {
            return classic_rts_action_from_order_entry(runtime, order);
        }
    }
    None
}

