#[cfg(not(target_os = "android"))]
fn classic_first_contact_player_screen_chrome_for_runtime(
    runtime: &NativeFirstPlayableRuntime,
) -> Option<RtsFirstContactPlayerScreenChromeProfile> {
    if classic_player_screen_mode_enabled() && runtime.map_scene == "first_contact_basin" {
        Some(classic_first_contact_player_screen_profile().chrome)
    } else {
        None
    }
}

#[cfg(not(target_os = "android"))]
fn classic_rts_command_slot_id_for_index(
    runtime: &NativeFirstPlayableRuntime,
    first_contact_chrome: Option<&RtsFirstContactPlayerScreenChromeProfile>,
    index: usize,
) -> String {
    let fallback_id = first_contact_chrome
        .map(|chrome| chrome.command_slot_fallback_id.as_str())
        .unwrap_or("hold");
    first_contact_chrome
        .and_then(|chrome| {
            chrome
                .command_grid_slot_ids
                .get(index % chrome.command_grid_slot_ids.len().max(1))
        })
        .cloned()
        .or_else(|| {
            runtime
                .rts_ability_command_ids
                .get(index % runtime.rts_ability_command_ids.len().max(1))
                .cloned()
        })
        .unwrap_or_else(|| fallback_id.to_string())
}

#[cfg(not(target_os = "android"))]
fn classic_rts_build_palette_queue_id_for_index(
    first_contact_chrome: Option<&RtsFirstContactPlayerScreenChromeProfile>,
    index: usize,
) -> String {
    first_contact_chrome
        .and_then(|chrome| {
            classic_first_contact_build_palette_slot(&chrome.build_palette_slots, index)
                .map(|slot| slot.queue_id.clone())
        })
        .unwrap_or_else(|| classic_rts_build_palette_queue_id(index))
}

#[cfg(not(target_os = "android"))]
fn classic_rts_production_slot_queue_id(
    runtime: &NativeFirstPlayableRuntime,
    index: usize,
) -> String {
    runtime
        .rts_production_queue
        .get(index)
        .or_else(|| runtime.rts_build_queue.get(index.saturating_sub(2)))
        .cloned()
        .unwrap_or_else(|| {
            if index % 2 == 0 {
                classic_next_runtime_rts_train_queue(runtime)
            } else {
                classic_next_runtime_rts_build_queue(runtime)
            }
        })
}

#[cfg(not(target_os = "android"))]
fn classic_rts_build_palette_queue_id(index: usize) -> String {
    [
        "build:power_node@5,3",
        "build:training_hall@4,3",
        "build:refinery@6,4",
        "build:watch_tower@7,4",
        "build:command_post@5,2",
        "build:radar_spire@6,2",
        "build:wall@8,4",
        "upgrade:signal_blade",
    ]
    .get(index)
    .copied()
    .unwrap_or("build:watch_tower@7,4")
    .to_string()
}

#[cfg(not(target_os = "android"))]
fn classic_rts_sidebar_cancel_action(
    runtime: &NativeFirstPlayableRuntime,
    index: usize,
) -> Option<NativeControlAction> {
    if runtime.rts_production_queue.get(index).is_some() {
        Some(NativeControlAction::RtsQueueProduction {
            queue_id: format!("cancel:production:{index}"),
        })
    } else if index >= 2 && runtime.rts_build_queue.get(index - 2).is_some() {
        Some(NativeControlAction::RtsQueueProduction {
            queue_id: format!("cancel:build:{}", index - 2),
        })
    } else {
        None
    }
}

#[cfg(not(target_os = "android"))]
fn classic_rts_palette_cancel_action(
    runtime: &NativeFirstPlayableRuntime,
    queue_id: &str,
) -> Option<NativeControlAction> {
    if let Some(index) = runtime
        .rts_build_queue
        .iter()
        .position(|entry| entry == queue_id)
    {
        Some(NativeControlAction::RtsQueueProduction {
            queue_id: format!("cancel:build:{index}"),
        })
    } else if let Some(index) = runtime
        .rts_production_queue
        .iter()
        .position(|entry| entry == queue_id)
    {
        Some(NativeControlAction::RtsQueueProduction {
            queue_id: format!("cancel:production:{index}"),
        })
    } else if queue_id.starts_with("build:")
        && runtime
            .rts_building_blueprint_id
            .as_deref()
            .is_some_and(|id| queue_id.contains(id))
    {
        Some(NativeControlAction::RtsQueueProduction {
            queue_id: "cancel:active_build".to_string(),
        })
    } else {
        None
    }
}

#[cfg(not(target_os = "android"))]
fn classic_rts_sidebar_slot_status_label(
    runtime: &NativeFirstPlayableRuntime,
    index: usize,
    progress: u8,
    queue_id: &str,
) -> String {
    if runtime.rts_production_queue.get(index).is_some() {
        format!("Q{} {} R", index + 1, progress.min(100))
    } else if index >= 2 && runtime.rts_build_queue.get(index - 2).is_some() {
        format!("B{} {} R", index - 1, progress.min(100))
    } else if classic_rts_queue_is_affordable(runtime, queue_id) {
        "LMB ADD".to_string()
    } else {
        "LOCK".to_string()
    }
}

#[cfg(not(target_os = "android"))]
fn classic_rts_palette_state_label(runtime: &NativeFirstPlayableRuntime, queue_id: &str) -> String {
    if runtime
        .rts_building_blueprint_id
        .as_deref()
        .is_some_and(|id| queue_id.contains(id))
    {
        "ACT".to_string()
    } else if let Some(index) = runtime
        .rts_build_queue
        .iter()
        .position(|entry| entry == queue_id)
    {
        format!("B Q{}", index + 1)
    } else if let Some(index) = runtime
        .rts_production_queue
        .iter()
        .position(|entry| entry == queue_id)
    {
        format!("P Q{}", index + 1)
    } else if classic_rts_queue_is_affordable(runtime, queue_id) {
        "RDY".to_string()
    } else {
        "LOCK".to_string()
    }
}

#[cfg(not(target_os = "android"))]
fn classic_rts_sidebar_queue_summary(runtime: &NativeFirstPlayableRuntime) -> String {
    let production = runtime
        .rts_production_queue
        .first()
        .map(|queue| {
            format!(
                "{}@{}%",
                queue.replace("train:", "").replace("upgrade:", "up:"),
                runtime.rts_training_progress_percent.min(100)
            )
        })
        .unwrap_or_else(|| "ready".to_string());
    let build = runtime
        .rts_build_queue
        .first()
        .map(|queue| {
            format!(
                "{}@{}%",
                classic_rts_structure_id_from_queue(queue),
                runtime.rts_build_progress_percent.min(100)
            )
        })
        .unwrap_or_else(|| "ready".to_string());
    format!("P:{production} B:{build}")
}

#[cfg(not(target_os = "android"))]
fn classic_rts_action_from_order_entry(
    runtime: &NativeFirstPlayableRuntime,
    order: &str,
) -> Option<NativeControlAction> {
    let order = order.strip_prefix("queue:").unwrap_or(order);
    if let Some(target_id) = order.strip_prefix("attack:") {
        Some(NativeControlAction::RtsAttackCommand {
            target_id: target_id.to_string(),
        })
    } else if let Some(tile_id) = order.strip_prefix("move:") {
        Some(NativeControlAction::RtsMoveCommand {
            command_id: format!("{tile_id}:line"),
        })
    } else if order.starts_with("minimap:") {
        Some(NativeControlAction::RtsMoveCommand {
            command_id: order.to_string(),
        })
    } else if let Some(ability_id) = order.strip_prefix("ability:") {
        Some(NativeControlAction::RtsAbilityCommand {
            ability_id: ability_id.to_string(),
        })
    } else if order.starts_with("build:")
        || order.starts_with("train:")
        || order.starts_with("upgrade:")
        || order.starts_with("harvest:")
        || order.starts_with("complete:")
    {
        Some(NativeControlAction::RtsQueueProduction {
            queue_id: order.to_string(),
        })
    } else if order.starts_with("select_group_") {
        Some(NativeControlAction::RtsSelectControlGroup {
            group_id: order
                .strip_prefix("select_group_")
                .unwrap_or("1")
                .to_string(),
        })
    } else {
        Some(NativeControlAction::RtsAbilityCommand {
            ability_id: classic_next_runtime_rts_ability(runtime),
        })
    }
}

fn classic_rts_queue_gold_cost(queue_id: &str) -> u64 {
    let queue_id = queue_id.strip_prefix("queue:").unwrap_or(queue_id);
    let item_id = queue_id
        .split_once('@')
        .map(|(item_id, _)| item_id)
        .unwrap_or(queue_id);
    match item_id {
        "train:worker" => 80,
        "train:guard" => 140,
        "train:scout" => 110,
        "build:watch_tower" => 210,
        "build:training_hall" => 260,
        "build:signal_spire" => 320,
        "build:power_node" => 160,
        "build:refinery" => 240,
        "build:command_post" => 300,
        "build:radar_spire" => 220,
        "build:wall" => 60,
        "build:relay" | "build:scout_tower" => 180,
        "upgrade:signal_blade" | "upgrade:training_hall" => 210,
        "harvest:gold_vein" | "harvest:lumber_copse" => 0,
        _ if item_id.starts_with("complete:") => 0,
        _ if item_id.starts_with("cancel:") => 0,
        _ if item_id.starts_with("repair:") => 45,
        _ => 120,
    }
}

#[cfg(not(target_os = "android"))]
fn classic_rts_queue_cost_label(queue_id: &str) -> String {
    let cost = classic_rts_queue_gold_cost(queue_id);
    if cost == 0 {
        "-".to_string()
    } else {
        cost.to_string()
    }
}

#[cfg(not(target_os = "android"))]
fn classic_rts_log_gold_amount(entry: &str) -> u64 {
    entry
        .split(':')
        .filter_map(|part| part.trim().strip_suffix('g'))
        .filter_map(|amount| {
            amount
                .trim_start_matches(|value| value == '+' || value == '-')
                .parse::<u64>()
                .ok()
        })
        .sum()
}

#[cfg(not(target_os = "android"))]
fn classic_rts_resource_gold_commitment(runtime: &NativeFirstPlayableRuntime) -> u64 {
    runtime
        .rts_resource_spend_log
        .iter()
        .map(|entry| classic_rts_log_gold_amount(entry))
        .sum()
}

#[cfg(not(target_os = "android"))]
fn classic_rts_available_gold(runtime: &NativeFirstPlayableRuntime) -> u64 {
    let gross_gold = 620_u64.saturating_add(runtime.coins);
    let commitment = classic_rts_resource_gold_commitment(runtime);
    gross_gold.saturating_sub(commitment.min(gross_gold.saturating_sub(40)))
}

#[cfg(not(target_os = "android"))]
fn classic_rts_queue_is_affordable(runtime: &NativeFirstPlayableRuntime, queue_id: &str) -> bool {
    classic_rts_queue_gold_cost(queue_id) <= classic_rts_available_gold(runtime)
}

#[cfg(not(target_os = "android"))]
fn classic_rts_queue_requires_affordability_check(queue_id: &str) -> bool {
    let queue_id = queue_id.strip_prefix("queue:").unwrap_or(queue_id).trim();
    queue_id.starts_with("build:")
        || queue_id.starts_with("train:")
        || queue_id.starts_with("upgrade:")
        || queue_id.starts_with("research:")
        || queue_id.starts_with("repair:")
}

fn classic_rts_queue_unaffordable_reason(
    runtime: &NativeFirstPlayableRuntime,
    queue_id: &str,
) -> Option<String> {
    #[cfg(not(target_os = "android"))]
    {
        if classic_rts_queue_requires_affordability_check(queue_id)
            && !classic_rts_queue_is_affordable(runtime, queue_id)
        {
            return Some(format!("rts_queue_unaffordable:{queue_id}"));
        }
    }
    #[cfg(target_os = "android")]
    {
        let _ = runtime;
        let _ = queue_id;
    }
    None
}

#[cfg(not(target_os = "android"))]
fn classic_tick_openra_style_rts_runtime(
    runtime: &mut NativeFirstPlayableRuntime,
    frame_tick: u64,
) {
    if frame_tick % 15 != 0 {
        return;
    }
    if !runtime.rts_production_queue.is_empty() {
        runtime.rts_training_progress_percent = runtime
            .rts_training_progress_percent
            .saturating_add(6)
            .min(100);
        if runtime.rts_training_progress_percent >= 100 {
            let completed_queue = runtime.rts_production_queue.remove(0);
            if let Some(upgrade_id) = completed_queue.strip_prefix("upgrade:") {
                push_unique_string(&mut runtime.rts_completed_upgrade_ids, upgrade_id);
                push_history(
                    &mut runtime.rts_command_queue,
                    &format!("upgrade_complete:{upgrade_id}"),
                );
                runtime.rts_tech_state = format!("upgraded:{upgrade_id}");
                runtime.last_feedback = format!("RTS upgrade complete: {upgrade_id}");
            } else {
                let spawned_unit_id = classic_rts_spawned_unit_id_from_queue(
                    &completed_queue,
                    runtime.rts_army_spawned_unit_ids.len(),
                );
                push_unique_string(&mut runtime.rts_army_spawned_unit_ids, &spawned_unit_id);
                push_history(
                    &mut runtime.rts_command_queue,
                    &format!("production_complete:{completed_queue}->{spawned_unit_id}"),
                );
                push_history(
                    &mut runtime.rts_combat_event_log,
                    &format!("unit_ready:{spawned_unit_id}"),
                );
                runtime.last_feedback = format!("RTS production complete: {spawned_unit_id}");
            }
            runtime.rts_training_progress_percent = if runtime.rts_production_queue.is_empty() {
                100
            } else {
                8
            };
            push_feedback_event(runtime, &runtime.last_feedback.clone());
        }
    }
    if !runtime.rts_build_queue.is_empty() || runtime.rts_building_blueprint_id.is_some() {
        runtime.rts_build_progress_percent = runtime
            .rts_build_progress_percent
            .saturating_add(5)
            .min(100);
        runtime.rts_building_progress_percent = runtime
            .rts_building_progress_percent
            .saturating_add(5)
            .min(100);
        if runtime.rts_build_progress_percent >= 100 || runtime.rts_building_progress_percent >= 100
        {
            let completed_queue = runtime
                .rts_build_queue
                .first()
                .cloned()
                .or_else(|| {
                    runtime
                        .rts_building_blueprint_id
                        .as_deref()
                        .map(|id| format!("build:{id}@7,4"))
                })
                .unwrap_or_else(|| "build:watch_tower@7,4".to_string());
            if !runtime.rts_build_queue.is_empty() {
                runtime.rts_build_queue.remove(0);
            }
            let structure_id = classic_rts_structure_id_from_queue(&completed_queue);
            push_unique_string(&mut runtime.rts_completed_structure_ids, &structure_id);
            push_unique_string(&mut runtime.rts_base_structure_ids, &structure_id);
            runtime.rts_structure_health_percents.push(100);
            runtime.rts_structure_state = format!("completed:{structure_id}");
            push_history(
                &mut runtime.rts_command_queue,
                &format!("build_complete:{completed_queue}->{structure_id}"),
            );
            if let Some(next_queue) = runtime.rts_build_queue.first() {
                let (next_structure_id, next_tile_id) = classic_rts_build_parts(next_queue);
                runtime.rts_building_blueprint_id = Some(next_structure_id);
                runtime.rts_build_site_tile_ids = classic_rts_build_site_tiles(&next_tile_id);
            } else {
                runtime.rts_building_blueprint_id = None;
                runtime.rts_build_site_tile_ids.clear();
            }
            runtime.rts_build_progress_percent = if runtime.rts_build_queue.is_empty() {
                100
            } else {
                10
            };
            runtime.rts_building_progress_percent = runtime.rts_build_progress_percent;
            runtime.last_feedback = format!("RTS build complete: {structure_id}");
            push_feedback_event(runtime, &runtime.last_feedback.clone());
        }
    }
}

#[cfg(not(target_os = "android"))]
fn classic_rts_spawned_unit_id_from_queue(queue_id: &str, existing_count: usize) -> String {
    let unit_kind = queue_id
        .strip_prefix("train:")
        .unwrap_or(queue_id)
        .split_once('@')
        .map(|(unit_kind, _)| unit_kind)
        .unwrap_or_else(|| queue_id.strip_prefix("upgrade:").unwrap_or("unit"));
    format!("{}_{}", unit_kind.replace(':', "_"), existing_count + 1)
}

#[cfg(not(target_os = "android"))]
fn classic_rts_structure_id_from_queue(queue_id: &str) -> String {
    queue_id
        .strip_prefix("build:")
        .or_else(|| queue_id.strip_prefix("complete:"))
        .unwrap_or(queue_id)
        .split_once('@')
        .map(|(structure_id, _)| structure_id)
        .unwrap_or("watch_tower")
        .to_string()
}

#[cfg(not(target_os = "android"))]
#[allow(clippy::too_many_arguments)]
fn classic_draw_openra_style_build_placement_ghost(
    buffer: &mut [u32],
    width: usize,
    height: usize,
    runtime: &NativeFirstPlayableRuntime,
    viewport_x: i32,
    viewport_y: i32,
    viewport_w: i32,
    viewport_h: i32,
) {
    let Some(blueprint_id) = runtime.rts_building_blueprint_id.as_deref() else {
        return;
    };
    let Some(primary_tile_id) = runtime.rts_build_site_tile_ids.first() else {
        return;
    };
    let placement_queue_id = format!("build:{blueprint_id}@{primary_tile_id}");
    let affordable = classic_rts_queue_is_affordable(runtime, &placement_queue_id);
    let ghost_color = if affordable {
        CLASSIC_RTS_BUILD_BLUEPRINT_COLOR
    } else {
        CLASSIC_RTS_QUEUE_PREVIEW_CANCEL_COLOR
    };
    let cell_w = ((viewport_w - 44).max(120)) / 12;
    let cell_h = ((viewport_h - 74).max(80)) / 8;
    let grid_x = viewport_x + 22;
    let grid_y = viewport_y + 48;
    for (index, tile_id) in runtime.rts_build_site_tile_ids.iter().enumerate() {
        let Some(tile) = classic_parse_rts_tile(tile_id) else {
            continue;
        };
        let center_x = grid_x + tile.0.clamp(0, 11) * cell_w + cell_w / 2;
        let center_y = grid_y + tile.1.clamp(0, 7) * cell_h + cell_h / 2;
        classic_draw_iso_diamond(
            buffer,
            width,
            height,
            center_x,
            center_y - cell_h / 3,
            (cell_w / 2).clamp(28, 54),
            (cell_h / 2).clamp(16, 30),
            ghost_color,
        );
        classic_draw_rect(
            buffer,
            width,
            height,
            center_x - cell_w / 4,
            center_y + cell_h / 8,
            cell_w / 2,
            3,
            if index == 0 {
                CLASSIC_RTS_QUEUE_PREVIEW_WAYPOINT_COLOR
            } else {
                ghost_color
            },
        );
        classic_draw_rect(
            buffer,
            width,
            height,
            center_x - 2,
            center_y - cell_h / 6,
            4,
            cell_h / 3,
            ghost_color,
        );
    }
    let panel_x = viewport_x + 238;
    let panel_y = viewport_y + 8;
    classic_draw_rect(buffer, width, height, panel_x, panel_y, 286, 20, 0x101913);
    classic_draw_rect(buffer, width, height, panel_x, panel_y, 5, 20, ghost_color);
    classic_draw_text(
        buffer,
        width,
        height,
        panel_x + 10,
        panel_y + 7,
        &classic_catalog_text_label(
            &format!(
                "PLACEMENT {} {}C {}",
                blueprint_id.replace('_', " "),
                classic_rts_queue_gold_cost(&placement_queue_id),
                if affordable { "READY" } else { "LOW CRED" }
            ),
            42,
        ),
        1,
        CLASSIC_HUD_TEXT_COLOR,
    );
}

#[cfg(not(target_os = "android"))]
fn classic_draw_rts_drag_select_preview_overlay(
    buffer: &mut [u32],
    width: usize,
    height: usize,
    runtime: &NativeFirstPlayableRuntime,
) {
    if runtime.rts_drag_select_source.is_empty() || runtime.rts_drag_select_player_label.is_empty()
    {
        return;
    }
    let layout = classic_rts_shell_layout(width, height);
    let panel_x = layout
        .as_ref()
        .map(|layout| layout.viewport_x + 18)
        .unwrap_or(18);
    let panel_y = layout
        .as_ref()
        .map(|layout| layout.viewport_y + 44)
        .unwrap_or(48);
    let panel_w = (width as i32 - panel_x - 24).clamp(220, 382);
    classic_draw_rect(
        buffer,
        width,
        height,
        panel_x,
        panel_y,
        panel_w,
        26,
        CLASSIC_RTS_HOVER_PANEL_COLOR,
    );
    classic_draw_rect(
        buffer,
        width,
        height,
        panel_x,
        panel_y,
        5,
        26,
        CLASSIC_RTS_DRAG_PREVIEW_COLOR,
    );
    classic_draw_text(
        buffer,
        width,
        height,
        panel_x + 12,
        panel_y + 8,
        &classic_catalog_text_label(&runtime.rts_drag_select_player_label, 44),
        1,
        CLASSIC_RTS_DRAG_PREVIEW_COLOR,
    );

    if let Some(layout) = layout {
        let cell_w = ((layout.viewport_w - 44).max(120)) / 12;
        let cell_h = ((layout.viewport_h - 74).max(80)) / 8;
        let grid_x = layout.viewport_x + 22;
        let grid_y = layout.viewport_y + 48;
        let mut bounds: Option<(i32, i32, i32, i32)> = None;
        for tile_id in runtime.rts_drag_select_tile_ids.iter().take(48) {
            let Some(tile) = classic_parse_rts_tile(tile_id) else {
                continue;
            };
            let center_x = grid_x + tile.0.clamp(0, 11) * cell_w + cell_w / 2;
            let center_y = grid_y + tile.1.clamp(0, 7) * cell_h + cell_h / 2;
            bounds = Some(match bounds {
                Some((min_x, min_y, max_x, max_y)) => (
                    min_x.min(center_x),
                    min_y.min(center_y),
                    max_x.max(center_x),
                    max_y.max(center_y),
                ),
                None => (center_x, center_y, center_x, center_y),
            });
            classic_draw_iso_diamond(
                buffer,
                width,
                height,
                center_x,
                center_y - cell_h / 3,
                (cell_w / 3).clamp(18, 40),
                (cell_h / 3).clamp(10, 24),
                CLASSIC_RTS_DRAG_PREVIEW_COLOR,
            );
        }
        if let Some((min_x, min_y, max_x, max_y)) = bounds {
            let x = min_x - cell_w / 2;
            let y = min_y - cell_h / 2;
            let w = (max_x - min_x + cell_w).max(8);
            let h = (max_y - min_y + cell_h).max(8);
            classic_draw_rect(
                buffer,
                width,
                height,
                x,
                y,
                w,
                3,
                CLASSIC_RTS_DRAG_PREVIEW_COLOR,
            );
            classic_draw_rect(
                buffer,
                width,
                height,
                x,
                y + h - 2,
                w,
                3,
                CLASSIC_RTS_DRAG_PREVIEW_COLOR,
            );
            classic_draw_rect(
                buffer,
                width,
                height,
                x,
                y,
                3,
                h,
                CLASSIC_RTS_DRAG_PREVIEW_COLOR,
            );
            classic_draw_rect(
                buffer,
                width,
                height,
                x + w - 2,
                y,
                3,
                h,
                CLASSIC_RTS_DRAG_PREVIEW_COLOR,
            );
        }
    } else {
        let preview_x = panel_x + 8;
        let preview_y = panel_y + 34;
        let tile_count = runtime.rts_drag_select_tile_ids.len().clamp(1, 18);
        classic_draw_rect(
            buffer,
            width,
            height,
            preview_x - 4,
            preview_y - 4,
            190,
            38,
            CLASSIC_RTS_HOVER_PANEL_COLOR,
        );
        classic_draw_rect(
            buffer,
            width,
            height,
            preview_x - 4,
            preview_y - 4,
            190,
            3,
            CLASSIC_RTS_DRAG_PREVIEW_COLOR,
        );
        classic_draw_rect(
            buffer,
            width,
            height,
            preview_x - 4,
            preview_y + 31,
            190,
            3,
            CLASSIC_RTS_DRAG_PREVIEW_COLOR,
        );
        for index in 0..tile_count {
            let x = preview_x + (index % 9) as i32 * 20;
            let y = preview_y + (index / 9) as i32 * 15;
            classic_draw_rect(
                buffer,
                width,
                height,
                x,
                y,
                16,
                11,
                CLASSIC_RTS_DRAG_PREVIEW_COLOR,
            );
        }
    }
}

#[cfg(not(target_os = "android"))]
fn classic_draw_rts_hover_preview_overlay(
    buffer: &mut [u32],
    width: usize,
    height: usize,
    runtime: &NativeFirstPlayableRuntime,
) {
    if runtime.rts_hover_source.is_empty() || runtime.rts_hover_player_label.is_empty() {
        return;
    }
    let player_screen = classic_player_screen_mode_enabled();
    let layout = classic_rts_shell_layout(width, height);
    let panel_x = layout
        .as_ref()
        .map(|layout| layout.viewport_x + 18)
        .unwrap_or(18);
    let panel_y = layout
        .as_ref()
        .map(|layout| layout.viewport_y + 12)
        .unwrap_or(18);
    let panel_w = (width as i32 - panel_x - 24).clamp(220, 356);
    if !player_screen {
        classic_draw_rect(
            buffer,
            width,
            height,
            panel_x,
            panel_y,
            panel_w,
            24,
            CLASSIC_RTS_HOVER_PANEL_COLOR,
        );
        classic_draw_rect(
            buffer,
            width,
            height,
            panel_x,
            panel_y,
            5,
            24,
            CLASSIC_RTS_HOVER_PREVIEW_COLOR,
        );
        classic_draw_text(
            buffer,
            width,
            height,
            panel_x + 12,
            panel_y + 8,
            &classic_catalog_text_label(&runtime.rts_hover_player_label, 44),
            1,
            CLASSIC_RTS_HOVER_PREVIEW_COLOR,
        );
    }
    if let (Some(layout), Some(tile_id)) = (layout, runtime.rts_hover_tile_id.as_deref()) {
        if let Some(tile) = classic_parse_rts_tile(tile_id) {
            let cell_w = ((layout.viewport_w - 44).max(120)) / 12;
            let cell_h = ((layout.viewport_h - 74).max(80)) / 8;
            let (center_x, center_y) = classic_rts_viewport_tile_center(&layout, tile);
            let preview_color = if runtime.rts_hover_affordance.contains("attack") {
                CLASSIC_RTS_SELECTION_FEEDBACK_ATTACK_COLOR
            } else if runtime.rts_hover_affordance.contains("rally") {
                CLASSIC_RTS_SELECTION_FEEDBACK_RALLY_COLOR
            } else {
                CLASSIC_RTS_HOVER_PREVIEW_COLOR
            };
            classic_draw_iso_diamond(
                buffer,
                width,
                height,
                center_x,
                center_y - cell_h / 3,
                (cell_w / 2).clamp(24, 48),
                (cell_h / 2).clamp(14, 28),
                preview_color,
            );
            classic_draw_rect(
                buffer,
                width,
                height,
                center_x - 28,
                center_y + 13,
                56,
                4,
                CLASSIC_RTS_HOVER_PREVIEW_COLOR,
            );
            if runtime.rts_hover_source == "classic_rts_mouse_viewport" {
                if let Some(kind) =
                    classic_rts_hover_target_preview_kind(&runtime.rts_hover_affordance)
                {
                    let target_color = classic_rts_hover_target_preview_color(kind);
                    let source_tile = classic_rts_primary_selected_tile(runtime).unwrap_or((5, 5));
                    for route_tile_id in classic_rts_line_path_tiles(source_tile, tile)
                        .iter()
                        .take(8)
                    {
                        if let Some(route_tile) = classic_parse_rts_tile(route_tile_id) {
                            let (route_x, route_y) =
                                classic_rts_viewport_tile_center(&layout, route_tile);
                            classic_draw_rect(
                                buffer,
                                width,
                                height,
                                route_x - 11,
                                route_y + 20,
                                22,
                                4,
                                CLASSIC_RTS_TARGET_PREVIEW_PATH_COLOR,
                            );
                            classic_draw_rect(
                                buffer,
                                width,
                                height,
                                route_x - 2,
                                route_y + 12,
                                4,
                                20,
                                CLASSIC_RTS_TARGET_PREVIEW_PATH_COLOR,
                            );
                        }
                    }
                    classic_draw_rect(
                        buffer,
                        width,
                        height,
                        center_x - 42,
                        center_y - 31,
                        84,
                        4,
                        target_color,
                    );
                    classic_draw_rect(
                        buffer,
                        width,
                        height,
                        center_x - 42,
                        center_y + 31,
                        84,
                        4,
                        target_color,
                    );
                    classic_draw_rect(
                        buffer,
                        width,
                        height,
                        center_x - 42,
                        center_y - 31,
                        4,
                        66,
                        target_color,
                    );
                    classic_draw_rect(
                        buffer,
                        width,
                        height,
                        center_x + 38,
                        center_y - 31,
                        4,
                        66,
                        target_color,
                    );
                    if kind == "attack" {
                        classic_draw_rect(
                            buffer,
                            width,
                            height,
                            center_x - 48,
                            center_y,
                            96,
                            4,
                            target_color,
                        );
                        classic_draw_rect(
                            buffer,
                            width,
                            height,
                            center_x - 2,
                            center_y - 42,
                            4,
                            84,
                            target_color,
                        );
                    } else if kind == "harvest" {
                        for offset in [-20, 0, 20] {
                            classic_draw_rect(
                                buffer,
                                width,
                                height,
                                center_x + offset - 6,
                                center_y - 6,
                                12,
                                12,
                                target_color,
                            );
                        }
                    } else if kind == "follow" {
                        classic_draw_rect(
                            buffer,
                            width,
                            height,
                            center_x - 24,
                            center_y - 2,
                            48,
                            4,
                            target_color,
                        );
                        classic_draw_rect(
                            buffer,
                            width,
                            height,
                            center_x + 18,
                            center_y - 10,
                            4,
                            20,
                            target_color,
                        );
                    }
                    if !player_screen {
                        classic_draw_rect(
                            buffer,
                            width,
                            height,
                            panel_x,
                            panel_y + 29,
                            panel_w,
                            18,
                            CLASSIC_RTS_HOVER_PANEL_COLOR,
                        );
                        classic_draw_rect(
                            buffer,
                            width,
                            height,
                            panel_x,
                            panel_y + 29,
                            5,
                            18,
                            target_color,
                        );
                        classic_draw_text(
                            buffer,
                            width,
                            height,
                            panel_x + 12,
                            panel_y + 35,
                            &format!("RMB {} TARGET PREVIEW", kind.to_ascii_uppercase()),
                            1,
                            target_color,
                        );
                    }
                }
            }
        }
    }
}

#[cfg(not(target_os = "android"))]
fn classic_draw_rts_context_cursor_overlay(
    buffer: &mut [u32],
    width: usize,
    height: usize,
    runtime: &NativeFirstPlayableRuntime,
) {
    if runtime.rts_cursor_source.is_empty() || runtime.rts_cursor_player_label.is_empty() {
        return;
    }
    let marker_color = if runtime.rts_cursor_allowed {
        CLASSIC_RTS_CONTEXT_CURSOR_COLOR
    } else {
        CLASSIC_RTS_BLOCKED_FEEDBACK_CHIP_COLOR
    };
    let cursor_x = runtime
        .rts_cursor_screen_x
        .clamp(10, width.saturating_sub(11) as i32);
    let cursor_y = runtime
        .rts_cursor_screen_y
        .clamp(10, height.saturating_sub(11) as i32);

    classic_draw_rect(
        buffer,
        width,
        height,
        cursor_x - 10,
        cursor_y,
        21,
        2,
        marker_color,
    );
    classic_draw_rect(
        buffer,
        width,
        height,
        cursor_x,
        cursor_y - 10,
        2,
        21,
        marker_color,
    );
    classic_draw_rect(
        buffer,
        width,
        height,
        cursor_x - 5,
        cursor_y - 5,
        11,
        2,
        marker_color,
    );
    classic_draw_rect(
        buffer,
        width,
        height,
        cursor_x - 5,
        cursor_y + 5,
        11,
        2,
        marker_color,
    );
    classic_draw_rect(
        buffer,
        width,
        height,
        cursor_x - 5,
        cursor_y - 5,
        2,
        11,
        marker_color,
    );
    classic_draw_rect(
        buffer,
        width,
        height,
        cursor_x + 5,
        cursor_y - 5,
        2,
        11,
        marker_color,
    );

    if runtime.rts_cursor_kind == "attack" || runtime.rts_cursor_kind == "ability" {
        classic_draw_rect(
            buffer,
            width,
            height,
            cursor_x - 14,
            cursor_y - 1,
            28,
            2,
            marker_color,
        );
        classic_draw_rect(
            buffer,
            width,
            height,
            cursor_x - 1,
            cursor_y - 14,
            2,
            28,
            marker_color,
        );
    } else if runtime.rts_cursor_kind == "build" {
        classic_draw_rect(
            buffer,
            width,
            height,
            cursor_x - 12,
            cursor_y - 12,
            24,
            3,
            marker_color,
        );
        classic_draw_rect(
            buffer,
            width,
            height,
            cursor_x - 12,
            cursor_y + 9,
            24,
            3,
            marker_color,
        );
        classic_draw_rect(
            buffer,
            width,
            height,
            cursor_x - 12,
            cursor_y - 12,
            3,
            24,
            marker_color,
        );
        classic_draw_rect(
            buffer,
            width,
            height,
            cursor_x + 9,
            cursor_y - 12,
            3,
            24,
            marker_color,
        );
    } else if runtime.rts_cursor_kind == "rally" {
        classic_draw_rect(
            buffer,
            width,
            height,
            cursor_x - 12,
            cursor_y + 8,
            24,
            3,
            marker_color,
        );
        classic_draw_rect(
            buffer,
            width,
            height,
            cursor_x + 9,
            cursor_y - 8,
            3,
            19,
            marker_color,
        );
    } else if runtime.rts_cursor_kind == "select" {
        classic_draw_rect(
            buffer,
            width,
            height,
            cursor_x - 14,
            cursor_y - 10,
            28,
            2,
            marker_color,
        );
        classic_draw_rect(
            buffer,
            width,
            height,
            cursor_x - 14,
            cursor_y + 10,
            28,
            2,
            marker_color,
        );
    }

    if classic_player_screen_mode_enabled() {
        return;
    }

    let label_x = (cursor_x + 14)
        .min(width.saturating_sub(244) as i32)
        .max(12);
    let label_y = (cursor_y + 14)
        .min(height.saturating_sub(26) as i32)
        .max(12);
    classic_draw_rect(
        buffer,
        width,
        height,
        label_x,
        label_y,
        232,
        22,
        CLASSIC_RTS_HOVER_PANEL_COLOR,
    );
    classic_draw_rect(buffer, width, height, label_x, label_y, 4, 22, marker_color);
    classic_draw_text(
        buffer,
        width,
        height,
        label_x + 10,
        label_y + 7,
        &classic_catalog_text_label(&runtime.rts_cursor_player_label, 34),
        1,
        marker_color,
    );
}

#[cfg(not(target_os = "android"))]
fn classic_draw_rts_command_stamp_overlay(
    buffer: &mut [u32],
    width: usize,
    height: usize,
    runtime: &NativeFirstPlayableRuntime,
) {
    if runtime.rts_command_stamp_source.is_empty()
        || runtime.rts_command_stamp_player_label.is_empty()
    {
        return;
    }
    let layout = classic_rts_shell_layout(width, height);
    let panel_x = layout
        .as_ref()
        .map(|layout| layout.viewport_x + 18)
        .unwrap_or(18);
    let panel_y = layout
        .as_ref()
        .map(|layout| layout.viewport_y + 76)
        .unwrap_or(76);
    let panel_w = (width as i32 - panel_x - 24).clamp(244, 410);
    classic_draw_rect(
        buffer,
        width,
        height,
        panel_x,
        panel_y,
        panel_w,
        25,
        CLASSIC_RTS_HOVER_PANEL_COLOR,
    );
    classic_draw_rect(
        buffer,
        width,
        height,
        panel_x,
        panel_y,
        5,
        25,
        CLASSIC_RTS_COMMAND_STAMP_COLOR,
    );
    classic_draw_text(
        buffer,
        width,
        height,
        panel_x + 12,
        panel_y + 8,
        &classic_catalog_text_label(&runtime.rts_command_stamp_player_label, 48),
        1,
        CLASSIC_RTS_COMMAND_STAMP_COLOR,
    );

    if let (Some(layout), Some(tile_id)) = (layout, runtime.rts_command_stamp_tile_id.as_deref()) {
        if let Some(tile) = classic_parse_rts_tile(tile_id) {
            let cell_w = ((layout.viewport_w - 44).max(120)) / 12;
            let cell_h = ((layout.viewport_h - 74).max(80)) / 8;
            let grid_x = layout.viewport_x + 22;
            let grid_y = layout.viewport_y + 48;
            let center_x = grid_x + tile.0.clamp(0, 11) * cell_w + cell_w / 2;
            let center_y = grid_y + tile.1.clamp(0, 7) * cell_h + cell_h / 2;
            let marker_color = if runtime.rts_command_stamp_kind.contains("attack")
                || runtime.rts_command_stamp_kind == "ability"
            {
                CLASSIC_RTS_SELECTION_FEEDBACK_ATTACK_COLOR
            } else if runtime.rts_command_stamp_kind == "build" {
                CLASSIC_RTS_BUILD_BLUEPRINT_COLOR
            } else {
                CLASSIC_RTS_COMMAND_STAMP_COLOR
            };
            classic_draw_iso_diamond(
                buffer,
                width,
                height,
                center_x,
                center_y - cell_h / 3,
                (cell_w / 2).clamp(24, 48),
                (cell_h / 2).clamp(14, 28),
                marker_color,
            );
            classic_draw_rect(
                buffer,
                width,
                height,
                center_x - 34,
                center_y + 13,
                68,
                4,
                CLASSIC_RTS_COMMAND_STAMP_COLOR,
            );
            classic_draw_rect(
                buffer,
                width,
                height,
                center_x - 2,
                center_y - 28,
                4,
                56,
                CLASSIC_RTS_COMMAND_STAMP_COLOR,
            );
            classic_draw_rect(
                buffer,
                width,
                height,
                center_x - 18,
                center_y - 18,
                36,
                3,
                CLASSIC_RTS_COMMAND_STAMP_COLOR,
            );
            classic_draw_rect(
                buffer,
                width,
                height,
                center_x - 18,
                center_y + 18,
                36,
                3,
                CLASSIC_RTS_COMMAND_STAMP_COLOR,
            );
            classic_draw_rect(
                buffer,
                width,
                height,
                center_x - 18,
                center_y - 18,
                3,
                36,
                CLASSIC_RTS_COMMAND_STAMP_COLOR,
            );
            classic_draw_rect(
                buffer,
                width,
                height,
                center_x + 18,
                center_y - 18,
                3,
                36,
                CLASSIC_RTS_COMMAND_STAMP_COLOR,
            );
        }
    }
}

#[cfg(not(target_os = "android"))]
fn classic_point_in_rect(
    x: i32,
    y: i32,
    rect_x: i32,
    rect_y: i32,
    rect_w: i32,
    rect_h: i32,
) -> bool {
    x >= rect_x && y >= rect_y && x < rect_x + rect_w && y < rect_y + rect_h
}

#[cfg(not(target_os = "android"))]
fn classic_mouse_grid_tile(
    x: i32,
    y: i32,
    rect_x: i32,
    rect_y: i32,
    rect_w: i32,
    rect_h: i32,
) -> (i32, i32) {
    let col = (((x - rect_x).max(0) * 12) / rect_w.max(1)).clamp(0, 11);
    let row = (((y - rect_y).max(0) * 8) / rect_h.max(1)).clamp(0, 7);
    (col, row)
}

#[cfg(not(target_os = "android"))]
fn classic_rts_runtime_camera_focus_tile(runtime: &NativeFirstPlayableRuntime) -> (i32, i32) {
    runtime
        .rts_camera_focus_tile_id
        .as_deref()
        .and_then(classic_parse_rts_tile)
        .map(classic_rts_large_map_clamp_tile)
        .unwrap_or((5, 4))
}

#[cfg(not(target_os = "android"))]
fn classic_mouse_viewport_world_tile(
    runtime: &NativeFirstPlayableRuntime,
    x: i32,
    y: i32,
    rect_x: i32,
    rect_y: i32,
    rect_w: i32,
    rect_h: i32,
) -> (i32, i32) {
    let local = classic_mouse_grid_tile(x, y, rect_x, rect_y, rect_w, rect_h);
    let focus = classic_rts_runtime_camera_focus_tile(runtime);
    classic_rts_large_map_clamp_tile((focus.0 - 5 + local.0, focus.1 - 4 + local.1))
}

#[cfg(not(target_os = "android"))]
