#[cfg(not(target_os = "android"))]
fn classic_rts_command_slot_action(
    runtime: &NativeFirstPlayableRuntime,
    command_id: &str,
) -> NativeControlAction {
    match command_id {
        "move" => NativeControlAction::RtsMoveCommand {
            command_id: classic_next_runtime_rts_move_command(runtime),
        },
        "stop" => NativeControlAction::RtsMoveCommand {
            command_id: classic_next_runtime_rts_stop_command(runtime),
        },
        "hold" => NativeControlAction::RtsMoveCommand {
            command_id: classic_next_runtime_rts_hold_command(runtime),
        },
        "patrol" => NativeControlAction::RtsMoveCommand {
            command_id: classic_next_runtime_rts_patrol_command(runtime),
        },
        "attack" => NativeControlAction::RtsAttackCommand {
            target_id: classic_next_runtime_rts_attack_target(runtime),
        },
        ability_id => NativeControlAction::RtsAbilityCommand {
            ability_id: ability_id.to_string(),
        },
    }
}

#[cfg(not(target_os = "android"))]
fn classic_rts_command_slot_available(
    runtime: &NativeFirstPlayableRuntime,
    command_id: &str,
) -> bool {
    native_live_action_availability(
        runtime,
        &classic_rts_command_slot_action(runtime, command_id),
    )
    .0
}

#[cfg(not(target_os = "android"))]
fn classic_move_player(tile: &mut (i32, i32), direction: &str, max_cols: i32, max_rows: i32) {
    let (dx, dy) = classic_direction_delta(direction);
    tile.0 = (tile.0 + dx).clamp(0, max_cols - 1);
    tile.1 = (tile.1 + dy).clamp(0, max_rows - 1);
}

#[cfg(not(target_os = "android"))]
fn classic_direction_delta(direction: &str) -> (i32, i32) {
    match direction {
        "east" => (1, 0),
        "west" => (-1, 0),
        "north" => (0, -1),
        "south" => (0, 1),
        "north-east" => (1, -1),
        "north-west" => (-1, -1),
        "south-east" => (1, 1),
        "south-west" => (-1, 1),
        _ => (0, 0),
    }
}

#[cfg(not(target_os = "android"))]
fn classic_rts_camera_state_for_focus_tile(
    focus_tile: (i32, i32),
    zoom: f32,
) -> RtsScrollableMapCameraState {
    let config = rts_scrollable_map_camera_config();
    let camera_center = classic_rts_large_map_tile_to_camera_center(focus_tile);
    clamp_rts_scrollable_map_camera_state(
        RtsScrollableMapCameraState {
            center_x: camera_center.x,
            center_y: camera_center.y,
            zoom,
        },
        config,
    )
}

#[cfg(not(target_os = "android"))]
fn classic_sync_live_camera_runtime(
    runtime: &mut NativeFirstPlayableRuntime,
    camera_state: RtsScrollableMapCameraState,
    input_source: &str,
    record_history: bool,
) -> (i32, i32) {
    let focus_tile = rts_scrollable_map_camera_focus_tile(camera_state);
    let focus_tile_id = classic_rts_tile_id(focus_tile);
    runtime.rts_camera_focus_tile_id = Some(focus_tile_id.clone());
    runtime.rts_camera_input_source = input_source.to_string();
    runtime.rts_camera_zoom_percent =
        ((camera_state.zoom * 100.0).round() as i32).clamp(0, 255) as u8;
    runtime.rts_camera_viewport_rect =
        Some(rts_camera_minimap_viewport_rect(camera_state, 117, 56));
    runtime.rts_visible_tile_ids = rts_camera_minimap_revealed_tiles(focus_tile);
    if record_history {
        let camera_event = format!(
            "camera:{}:focus:{}:zoom:{}",
            input_source, focus_tile_id, runtime.rts_camera_zoom_percent
        );
        if runtime.rts_command_queue.last() != Some(&camera_event) {
            push_history(&mut runtime.rts_command_queue, &camera_event);
        }
        runtime.last_feedback = format!(
            "RTS camera {} focus {} zoom {}%",
            input_source, focus_tile_id, runtime.rts_camera_zoom_percent
        );
        push_feedback_event(runtime, &runtime.last_feedback.clone());
    }
    focus_tile
}

#[cfg(not(target_os = "android"))]
fn classic_poll_live_camera_step(
    window: &MiniWindow,
    camera_state: RtsScrollableMapCameraState,
    width: usize,
    height: usize,
    fps: usize,
) -> Option<RtsScrollableMapCameraStep> {
    let config = rts_scrollable_map_camera_config();
    let delta_seconds = (1.0 / fps.max(1) as f32).clamp(1.0 / 120.0, 1.0 / 12.0);
    let shift_pressed =
        window.is_key_down(MiniKey::LeftShift) || window.is_key_down(MiniKey::RightShift);
    let mut pan_delta = Vec2::ZERO;
    let mut source_parts = Vec::new();

    if shift_pressed {
        if window.is_key_down(MiniKey::Right) || window.is_key_down(MiniKey::D) {
            pan_delta.x += config.keyboard_speed * delta_seconds;
        }
        if window.is_key_down(MiniKey::Left) || window.is_key_down(MiniKey::A) {
            pan_delta.x -= config.keyboard_speed * delta_seconds;
        }
        if window.is_key_down(MiniKey::Up) || window.is_key_down(MiniKey::W) {
            pan_delta.y += config.keyboard_speed * delta_seconds;
        }
        if window.is_key_down(MiniKey::Down) || window.is_key_down(MiniKey::S) {
            pan_delta.y -= config.keyboard_speed * delta_seconds;
        }
        if pan_delta != Vec2::ZERO {
            source_parts.push("shift_keyboard_pan");
        }
    }

    if let Some((mouse_x, mouse_y)) = window.get_mouse_pos(MiniMouseMode::Discard) {
        if mouse_x <= config.edge_band_pixels {
            pan_delta.x -= config.edge_speed * delta_seconds;
            source_parts.push("edge_scroll");
        } else if mouse_x >= width as f32 - config.edge_band_pixels {
            pan_delta.x += config.edge_speed * delta_seconds;
            source_parts.push("edge_scroll");
        }
        if mouse_y <= config.edge_band_pixels {
            pan_delta.y -= config.edge_speed * delta_seconds;
            source_parts.push("edge_scroll");
        } else if mouse_y >= height as f32 - config.edge_band_pixels {
            pan_delta.y += config.edge_speed * delta_seconds;
            source_parts.push("edge_scroll");
        }
    }

    let zoom_delta = window
        .get_scroll_wheel()
        .map(|(_scroll_x, scroll_y)| scroll_y * config.wheel_zoom_step)
        .unwrap_or(0.0);
    if zoom_delta.abs() > f32::EPSILON {
        source_parts.push("wheel_zoom");
    }

    if pan_delta == Vec2::ZERO && zoom_delta.abs() <= f32::EPSILON {
        return None;
    }
    Some(apply_rts_scrollable_map_camera_input(
        &source_parts.join("+"),
        camera_state,
        config,
        pan_delta,
        zoom_delta,
        None,
    ))
}

#[cfg(not(target_os = "android"))]
fn classic_cardinal_actor_direction(direction: &str) -> &'static str {
    match direction {
        "north" => "north",
        "south" => "south",
        "east" | "north-east" | "south-east" => "east",
        "west" | "north-west" | "south-west" => "west",
        other if other.contains("east") => "east",
        other if other.contains("west") => "west",
        other if other.contains("north") => "north",
        _ => "south",
    }
}

#[cfg(not(target_os = "android"))]
fn classic_player_frame_id(
    assets: &ClassicRuntimeAssets,
    runtime: &NativeFirstPlayableRuntime,
) -> String {
    let Some(actor) = assets.actor_by_id.get("player") else {
        return "actor_player_idle_south".to_string();
    };
    let direction = classic_cardinal_actor_direction(&runtime.facing_direction);
    if let Some(facing) = actor
        .facing_frames
        .iter()
        .find(|facing| facing.direction == direction)
    {
        if runtime.walk_cycle_frame > 0 && !facing.walk_frame_ids.is_empty() {
            let frame_index = (runtime.walk_cycle_frame as usize - 1) % facing.walk_frame_ids.len();
            return facing.walk_frame_ids[frame_index].clone();
        }
        return facing.idle_frame_id.clone();
    }
    if runtime.walk_cycle_frame.is_multiple_of(2) {
        actor.default_frame_id.clone()
    } else {
        actor.walk_frame_id.clone()
    }
}

#[cfg(not(target_os = "android"))]
fn classic_draw_scene(
    buffer: &mut [u32],
    width: usize,
    height: usize,
    player_tile: (i32, i32),
    runtime: &NativeFirstPlayableRuntime,
    assets: &ClassicRuntimeAssets,
) {
    buffer.fill(0x101411);
    classic_draw_rect(buffer, width, height, 0, 0, width as i32, 40, 0x16211b);
    classic_draw_rect(
        buffer,
        width,
        height,
        width as i32 - 178,
        6,
        166,
        28,
        CLASSIC_HUD_PANEL_COLOR,
    );
    classic_draw_rect(
        buffer,
        width,
        height,
        0,
        height as i32 - 72,
        width as i32,
        72,
        0x171a1d,
    );

    let scene_id = classic_scene_id(runtime);
    let player_frame = classic_player_frame_id(assets, runtime);
    if scene_id == "first_contact_basin" {
        classic_draw_first_contact_basin_scene(buffer, width, height, runtime);
    } else {
        let scene = assets
            .scene_by_id
            .get(scene_id)
            .or_else(|| assets.scene_by_id.get("mirror_city_square"));
        classic_draw_isometric_scene(
            buffer,
            width,
            height,
            scene,
            assets,
            runtime,
            player_tile,
            &player_frame,
        );
    }

    let xp_width = (runtime.xp.min(100) as i32 * 180) / 100;
    classic_draw_rect(buffer, width, height, 96, 302, 184, 10, 0x29312b);
    classic_draw_rect(buffer, width, height, 98, 304, xp_width, 6, 0x7fcf6b);
    let danger =
        runtime.last_feedback.contains("blocked") || runtime.objective_status.contains("required");
    classic_draw_rect(
        buffer,
        width,
        height,
        300,
        302,
        244,
        10,
        if danger { 0x8a342e } else { 0x2f5d75 },
    );
    if scene_id == "first_contact_basin" {
        if !classic_player_screen_mode_enabled() {
            classic_draw_first_contact_top_overlay(
                buffer,
                width,
                height,
                runtime,
                assets,
                &player_frame,
            );
        }
    } else {
        classic_draw_model_overlay(
            buffer,
            width,
            height,
            runtime,
            assets,
            scene_id,
            &player_frame,
        );
    }
    let openra_shell_drawn = classic_draw_openra_style_rts_shell(
        buffer,
        width,
        height,
        runtime,
        assets,
        scene_id,
        player_tile,
    );
    if !openra_shell_drawn {
        if scene_id != "first_contact_basin" {
            classic_draw_rts_strategy_overlay(
                buffer,
                width,
                height,
                runtime,
                scene_id,
                player_tile,
            );
        }
        classic_draw_rts_product_alignment_hud(buffer, width, height, runtime);
    }
    classic_draw_rts_control_group_slot_strip_for_scene(buffer, width, height, runtime);
    if let Some(hotkey_stage) = classic_rts_control_group_hotkey_feedback_stage(Some(runtime)) {
        classic_draw_rts_control_group_hotkey_feedback_overlay(
            buffer,
            width,
            height,
            runtime,
            hotkey_stage,
        );
    }
    if let Some(command_strip_stage) =
        classic_rts_control_group_command_feedback_strip_stage(Some(runtime))
    {
        classic_draw_rts_control_group_command_feedback_strip_overlay(
            buffer,
            width,
            height,
            runtime,
            command_strip_stage,
        );
    }
    if let Some(command_lifecycle_stage) =
        classic_rts_control_group_command_feedback_lifecycle_stage(Some(runtime))
    {
        classic_draw_rts_control_group_command_feedback_lifecycle_overlay(
            buffer,
            width,
            height,
            runtime,
            command_lifecycle_stage,
        );
    }
    if classic_rts_control_group_command_history_visible(Some(runtime)) {
        classic_draw_rts_control_group_command_history_overlay(buffer, width, height, runtime);
    }
    if classic_rts_blocked_feedback_chip_visible(runtime) {
        classic_draw_rts_blocked_feedback_chip_overlay(buffer, width, height, runtime);
    }
    if let Some(telegraph_stage) = classic_rts_ability_tooltip_telegraph_stage(Some(runtime)) {
        classic_draw_rts_ability_tooltip_telegraph_overlay(
            buffer,
            width,
            height,
            runtime,
            telegraph_stage,
        );
    }
    if let Some(feedback_stage) = classic_rts_selection_command_feedback_stage(Some(runtime)) {
        classic_draw_rts_selection_command_feedback_overlay(
            buffer,
            width,
            height,
            runtime,
            feedback_stage,
        );
    }
    if let Some(queue_stage) = classic_rts_command_queue_path_preview_stage(Some(runtime)) {
        classic_draw_rts_command_queue_path_preview_overlay(
            buffer,
            width,
            height,
            runtime,
            queue_stage,
        );
    }
    if let Some(formation_stage) = classic_rts_formation_move_preview_stage(Some(runtime)) {
        classic_draw_rts_formation_move_preview_overlay(
            buffer,
            width,
            height,
            runtime,
            formation_stage,
        );
    }
    if let Some(execution_stage) = classic_rts_formation_move_execution_stage(Some(runtime)) {
        classic_draw_rts_formation_move_execution_overlay(
            buffer,
            width,
            height,
            runtime,
            execution_stage,
        );
    }
    if let Some(obstruction_stage) = classic_rts_local_obstruction_recovery_stage(Some(runtime)) {
        classic_draw_rts_local_obstruction_recovery_overlay(
            buffer,
            width,
            height,
            runtime,
            obstruction_stage,
        );
    }
    if classic_rts_command_execution_feedback_visible(runtime) {
        if let Some(command_execution_kind) =
            classic_rts_command_execution_feedback_kind(Some(runtime))
        {
            classic_draw_rts_command_execution_feedback_overlay(
                buffer,
                width,
                height,
                runtime,
                command_execution_kind,
            );
        }
    }
    classic_draw_rts_drag_select_preview_overlay(buffer, width, height, runtime);
    classic_draw_rts_hover_preview_overlay(buffer, width, height, runtime);
    classic_draw_rts_context_cursor_overlay(buffer, width, height, runtime);
    classic_draw_rts_command_stamp_overlay(buffer, width, height, runtime);
    if let Some(status_stage) = classic_rts_unit_status_portrait_stage(Some(runtime)) {
        classic_draw_rts_unit_status_portrait_overlay(buffer, width, height, runtime, status_stage);
    }
    if openra_shell_drawn
        && scene_id == "first_contact_basin"
        && !classic_player_screen_mode_enabled()
    {
        classic_draw_rts_product_alignment_hud(buffer, width, height, runtime);
    }
}

#[cfg(not(target_os = "android"))]
fn classic_scene_id(runtime: &NativeFirstPlayableRuntime) -> &'static str {
    if runtime.map_scene.contains("first_contact_basin") {
        "first_contact_basin"
    } else if runtime.indoor_tilemap_visible || runtime.map_scene.contains("training") {
        "mentor_training_room"
    } else if runtime.map_scene.contains("arena")
        || runtime
            .completed_steps
            .iter()
            .any(|step| step == "arrive_at_first_objective")
    {
        "league_coliseum"
    } else {
        "mirror_city_square"
    }
}

#[cfg(not(target_os = "android"))]
fn classic_scene_tile_frame_id(scene: &ClassicSceneMap, key: char) -> &str {
    scene
        .tile_palette
        .iter()
        .find(|entry| entry.key == key)
        .map(|entry| entry.frame_id.as_str())
        .unwrap_or("tile_grass_a")
}

#[cfg(not(target_os = "android"))]
fn classic_dynamic_landmark_frame_id<'a>(
    landmark: &'a ClassicSceneLandmark,
    runtime: &NativeFirstPlayableRuntime,
) -> &'a str {
    match landmark.id.as_str() {
        "mentor" if runtime.dialogue_overlay_visible => "actor_mentor_talk",
        "enemy" if runtime.combat_overlay_visible || runtime.combat_overlay_was_visible => {
            if runtime.enemy_hp <= 0 || runtime.enemy_damage_feedback.contains("yields") {
                "actor_enemy_hit"
            } else if runtime.combat_turn % 2 == 1
                || runtime.enemy_damage_feedback.contains("attack")
                || runtime.enemy_damage_feedback.contains("HP")
            {
                "actor_enemy_attack"
            } else {
                "actor_enemy_idle"
            }
        }
        "objective_gate" if runtime.walk_cycle_frame % 2 == 1 => "marker_interaction",
        _ => landmark.frame_id.as_str(),
    }
}

