#[cfg(not(target_os = "android"))]
fn classic_draw_rts_command_affordance_panel(
    buffer: &mut [u32],
    width: usize,
    height: usize,
    runtime: &NativeFirstPlayableRuntime,
) {
    if width < 640 || height < 320 {
        return;
    }
    let panel_w = 250_i32.min(width as i32 - 24);
    let x = ((width as i32 - panel_w) / 2).max(12);
    let y = height as i32 - 124;
    classic_draw_rect(
        buffer,
        width,
        height,
        x,
        y,
        panel_w,
        30,
        CLASSIC_RTS_COMMAND_AFFORDANCE_HOTKEY_COLOR,
    );
    classic_draw_rect(
        buffer,
        width,
        height,
        x + 4,
        y + 4,
        panel_w - 8,
        3,
        CLASSIC_RTS_COMMAND_AFFORDANCE_ACK_COLOR,
    );
    let hotkeys = ["1", "2", "A", "M", "H", "B", "F"];
    for (index, label) in hotkeys.iter().enumerate() {
        let key_x = x + 10 + index as i32 * 28;
        let active = match *label {
            "1" | "2" => {
                runtime
                    .rts_active_control_group_ids
                    .iter()
                    .any(|group_id| group_id == *label)
                    || runtime.rts_control_group_id.as_deref() == Some(*label)
            }
            "A" => runtime.rts_attack_target_id.is_some(),
            "M" => runtime.rts_command_destination_tile.is_some(),
            "F" => {
                runtime.rts_active_ability_id.as_deref() == Some("focus")
                    || runtime
                        .rts_active_ability_id
                        .as_deref()
                        .is_some_and(|ability| ability.contains("fire"))
            }
            _ => runtime
                .rts_ability_command_ids
                .iter()
                .any(|ability| ability.starts_with(&label.to_ascii_lowercase())),
        };
        classic_draw_rect(
            buffer,
            width,
            height,
            key_x,
            y + 10,
            21,
            16,
            if active {
                CLASSIC_RTS_COMMAND_AFFORDANCE_ACK_COLOR
            } else {
                CLASSIC_RTS_ABILITY_SLOT_COLOR
            },
        );
        classic_draw_text(
            buffer,
            width,
            height,
            key_x + 6,
            y + 14,
            label,
            1,
            if active {
                CLASSIC_RTS_FIDELITY_MODEL_EDGE_COLOR
            } else {
                CLASSIC_HUD_MUTED_TEXT_COLOR
            },
        );
    }
    let feedback = runtime
        .last_feedback
        .strip_prefix("RTS ")
        .unwrap_or(runtime.last_feedback.as_str());
    classic_draw_text(
        buffer,
        width,
        height,
        x + 10,
        y - 10,
        &classic_catalog_text_label(feedback, 26),
        1,
        CLASSIC_RTS_COMMAND_AFFORDANCE_ACK_COLOR,
    );
}

#[cfg(not(target_os = "android"))]
fn classic_rts_command_surface_stage(
    runtime: Option<&NativeFirstPlayableRuntime>,
) -> Option<&'static str> {
    if let Some(runtime) = runtime {
        for event in runtime.rts_combat_event_log.iter().rev() {
            if event.contains("surface:target_queue") {
                return Some("target_queue");
            }
            if event.contains("surface:cooldown_disabled") {
                return Some("cooldown_disabled");
            }
            if event.contains("surface:command_grid") {
                return Some("command_grid");
            }
            if event.contains("surface:selection_state") {
                return Some("selection_state");
            }
        }
        if !runtime
            .rts_command_queue
            .iter()
            .any(|command| command.contains("surface:"))
        {
            return None;
        }
        return Some(match runtime.combat_turn % 4 {
            0 => "selection_state",
            1 => "command_grid",
            2 => "cooldown_disabled",
            _ => "target_queue",
        });
    }
    None
}

#[cfg(not(target_os = "android"))]
fn classic_draw_rts_command_surface_overlay(
    buffer: &mut [u32],
    width: usize,
    height: usize,
    runtime: &NativeFirstPlayableRuntime,
    selected_units: &[ClassicIsoEntity],
    stage: &str,
) {
    if width < 640 || height < 320 {
        return;
    }
    let bar_h = 84_i32;
    let y = height as i32 - bar_h - 4;
    let cards_x = 228_i32;
    let grid_x = width as i32 - 210;
    let grid_y = y + 12;

    match stage {
        "selection_state" => {
            for (index, _entity) in selected_units.iter().take(5).enumerate() {
                let card_x = cards_x + index as i32 * 84;
                let card_y = y + 12;
                for (x, y, w, h) in [
                    (card_x - 2, card_y - 2, 80, 3),
                    (card_x - 2, card_y + 58, 80, 3),
                    (card_x - 2, card_y - 2, 3, 63),
                    (card_x + 75, card_y - 2, 3, 63),
                ] {
                    classic_draw_rect(
                        buffer,
                        width,
                        height,
                        x,
                        y,
                        w,
                        h,
                        CLASSIC_RTS_COMMAND_SURFACE_SELECTION_FRAME_COLOR,
                    );
                }
            }
            for group_index in 0..3 {
                let tab_x = 118 + group_index * 34;
                let group_label = (group_index + 1).to_string();
                let active = runtime
                    .rts_active_control_group_ids
                    .iter()
                    .any(|group| group == &group_label)
                    || runtime.rts_control_group_id.as_deref() == Some(group_label.as_str());
                classic_draw_rect(
                    buffer,
                    width,
                    height,
                    tab_x,
                    y + 48,
                    28,
                    11,
                    if active {
                        CLASSIC_RTS_COMMAND_SURFACE_GROUP_TAB_COLOR
                    } else {
                        CLASSIC_RTS_COMMAND_SURFACE_DISABLED_COLOR
                    },
                );
                classic_draw_text(
                    buffer,
                    width,
                    height,
                    tab_x + 10,
                    y + 51,
                    &group_label,
                    1,
                    CLASSIC_RTS_FIDELITY_MODEL_EDGE_COLOR,
                );
            }
        }
        "command_grid" => {
            for row in 0..3 {
                for col in 0..3 {
                    let cell_x = grid_x + col * 32;
                    let cell_y = grid_y + row * 22;
                    classic_draw_rect(
                        buffer,
                        width,
                        height,
                        cell_x - 2,
                        cell_y - 2,
                        31,
                        3,
                        CLASSIC_RTS_COMMAND_SURFACE_READY_COLOR,
                    );
                    classic_draw_rect(
                        buffer,
                        width,
                        height,
                        cell_x - 2,
                        cell_y + 17,
                        31,
                        3,
                        CLASSIC_RTS_COMMAND_SURFACE_READY_COLOR,
                    );
                    classic_draw_rect(
                        buffer,
                        width,
                        height,
                        cell_x + 3,
                        cell_y + 5,
                        5 + col * 3,
                        3,
                        CLASSIC_RTS_COMMAND_SURFACE_READY_COLOR,
                    );
                }
            }
        }
        "cooldown_disabled" => {
            for row in 0..3 {
                for col in 0..3 {
                    let index = (row * 3 + col) as usize;
                    let cell_x = grid_x + col * 32;
                    let cell_y = grid_y + row * 22;
                    let cooldown = runtime
                        .rts_ability_cooldown_percents
                        .get(index)
                        .copied()
                        .unwrap_or(0);
                    if cooldown > 0 {
                        classic_draw_rect(
                            buffer,
                            width,
                            height,
                            cell_x + 3,
                            cell_y + 3,
                            21,
                            4 + ((cooldown.min(100) as i32 * 11) / 100),
                            CLASSIC_RTS_COMMAND_SURFACE_COOLDOWN_COLOR,
                        );
                    } else if index >= runtime.rts_ability_command_ids.len() {
                        classic_draw_rect(
                            buffer,
                            width,
                            height,
                            cell_x + 4,
                            cell_y + 5,
                            20,
                            3,
                            CLASSIC_RTS_COMMAND_SURFACE_DISABLED_COLOR,
                        );
                        classic_draw_rect(
                            buffer,
                            width,
                            height,
                            cell_x + 4,
                            cell_y + 11,
                            20,
                            3,
                            CLASSIC_RTS_COMMAND_SURFACE_DISABLED_COLOR,
                        );
                    }
                }
            }
        }
        "target_queue" => {
            let panel_x = grid_x - 122;
            classic_draw_rect(
                buffer,
                width,
                height,
                panel_x,
                grid_y,
                104,
                48,
                CLASSIC_RTS_COMMAND_SURFACE_TARGET_COLOR,
            );
            classic_draw_rect(
                buffer,
                width,
                height,
                panel_x + 4,
                grid_y + 5,
                96,
                38,
                CLASSIC_RTS_FIDELITY_PANEL_COLOR,
            );
            classic_draw_text(
                buffer,
                width,
                height,
                panel_x + 8,
                grid_y + 8,
                &classic_catalog_text_label(
                    runtime
                        .rts_attack_target_id
                        .as_deref()
                        .unwrap_or("no_target"),
                    15,
                ),
                1,
                CLASSIC_RTS_COMMAND_SURFACE_TARGET_COLOR,
            );
            classic_draw_rect(
                buffer,
                width,
                height,
                panel_x + 8,
                grid_y + 24,
                (runtime.rts_target_health_percent.min(100) as i32 * 84) / 100,
                5,
                CLASSIC_RTS_COMMAND_SURFACE_TARGET_COLOR,
            );
            for (index, _command) in runtime.rts_command_queue.iter().rev().take(5).enumerate() {
                classic_draw_rect(
                    buffer,
                    width,
                    height,
                    panel_x + 7 + index as i32 * 17,
                    grid_y + 35,
                    12,
                    7,
                    CLASSIC_RTS_COMMAND_SURFACE_QUEUE_COLOR,
                );
            }
            classic_draw_rect(
                buffer,
                width,
                height,
                panel_x + 70,
                grid_y + 14,
                26,
                4,
                CLASSIC_RTS_COMMAND_SURFACE_QUEUE_COLOR,
            );
        }
        _ => {}
    }
}

#[cfg(not(target_os = "android"))]
fn classic_draw_rts_fidelity_overlay(
    buffer: &mut [u32],
    width: usize,
    height: usize,
    runtime: &NativeFirstPlayableRuntime,
    selected_units: &[ClassicIsoEntity],
) {
    if width < 640 || height < 320 {
        return;
    }

    let bar_h = 84_i32;
    let y = height as i32 - bar_h - 4;
    classic_draw_rect(
        buffer,
        width,
        height,
        0,
        y - 4,
        width as i32,
        bar_h + 8,
        CLASSIC_RTS_FIDELITY_MODEL_EDGE_COLOR,
    );
    classic_draw_rect(
        buffer,
        width,
        height,
        4,
        y,
        width as i32 - 8,
        bar_h,
        CLASSIC_RTS_FIDELITY_PANEL_COLOR,
    );
    classic_draw_rect(
        buffer,
        width,
        height,
        4,
        y,
        width as i32 - 8,
        3,
        CLASSIC_RTS_FIDELITY_PANEL_EDGE_COLOR,
    );

    let portrait_x = 16_i32;
    let portrait_y = y + 10;
    classic_draw_rts_fidelity_portrait(
        buffer,
        width,
        height,
        portrait_x,
        portrait_y,
        runtime
            .rts_selected_unit_ids
            .first()
            .map(String::as_str)
            .unwrap_or("player"),
        true,
    );
    classic_draw_text(
        buffer,
        width,
        height,
        portrait_x + 74,
        portrait_y + 4,
        "SELECTED",
        1,
        CLASSIC_HUD_MUTED_TEXT_COLOR,
    );
    classic_draw_text(
        buffer,
        width,
        height,
        portrait_x + 74,
        portrait_y + 15,
        &format!(
            "GROUP {} / {}",
            runtime.rts_control_group_id.as_deref().unwrap_or("-"),
            selected_units.len()
        ),
        1,
        CLASSIC_ISO_CONTROL_GROUP_COLOR,
    );
    classic_draw_text(
        buffer,
        width,
        height,
        portrait_x + 74,
        portrait_y + 28,
        &classic_catalog_text_label(
            runtime
                .rts_command_queue
                .last()
                .map(String::as_str)
                .unwrap_or("hold_position"),
            22,
        ),
        1,
        CLASSIC_RTS_FIDELITY_COMMAND_ACTIVE_COLOR,
    );

    let cards_x = 228_i32;
    for (index, entity) in selected_units.iter().take(5).enumerate() {
        let card_x = cards_x + index as i32 * 84;
        let card_y = y + 12;
        let health = runtime
            .rts_unit_health_percents
            .get(index)
            .copied()
            .unwrap_or(72);
        classic_draw_rts_fidelity_unit_card(
            buffer,
            width,
            height,
            card_x,
            card_y,
            entity.id.as_str(),
            entity.frame_id.as_str(),
            health,
            index == 0,
        );
    }

    let grid_x = width as i32 - 210;
    let grid_y = y + 12;
    classic_draw_text(
        buffer,
        width,
        height,
        grid_x,
        grid_y - 10,
        "COMMAND",
        1,
        CLASSIC_HUD_MUTED_TEXT_COLOR,
    );
    for row in 0..3 {
        for col in 0..3 {
            let index = row * 3 + col;
            let action = runtime
                .rts_ability_command_ids
                .get(index as usize)
                .map(String::as_str)
                .unwrap_or(match index {
                    0 => "move",
                    1 => "attack",
                    2 => "hold",
                    3 => "patrol",
                    4 => "focus",
                    5 => "build",
                    6 => "stop",
                    7 => "guard",
                    _ => "rally",
                });
            let cooldown = runtime
                .rts_ability_cooldown_percents
                .get(index as usize)
                .copied()
                .unwrap_or(0);
            let active = runtime.rts_active_ability_id.as_deref() == Some(action);
            classic_draw_rts_fidelity_command_cell(
                buffer,
                width,
                height,
                grid_x + col * 32,
                grid_y + row * 22,
                action,
                cooldown,
                active,
            );
        }
    }

    let strip_x = grid_x - 116;
    classic_draw_text(
        buffer,
        width,
        height,
        strip_x,
        grid_y - 10,
        "ACTIONS",
        1,
        CLASSIC_HUD_MUTED_TEXT_COLOR,
    );
    for (index, event) in runtime.rts_combat_event_log.iter().take(4).enumerate() {
        let row_y = grid_y + index as i32 * 15;
        classic_draw_rect(
            buffer,
            width,
            height,
            strip_x,
            row_y,
            96,
            12,
            CLASSIC_RTS_FIDELITY_COMMAND_GRID_COLOR,
        );
        classic_draw_rect(
            buffer,
            width,
            height,
            strip_x + 2,
            row_y + 3,
            8 + index as i32 * 5,
            3,
            CLASSIC_RTS_FIDELITY_ACTION_TRAIL_COLOR,
        );
        classic_draw_text(
            buffer,
            width,
            height,
            strip_x + 16,
            row_y + 2,
            &classic_catalog_text_label(&event.replace(':', " "), 11),
            1,
            CLASSIC_RTS_FIDELITY_NPC_ACTION_COLOR,
        );
    }
    if let Some(stage) = classic_rts_command_surface_stage(Some(runtime)) {
        classic_draw_rts_command_surface_overlay(
            buffer,
            width,
            height,
            runtime,
            selected_units,
            stage,
        );
    }
}

