#[cfg(not(target_os = "android"))]
fn classic_rts_visible_tiles(
    runtime: &NativeFirstPlayableRuntime,
    player_tile: (i32, i32),
    selected_units: &[ClassicIsoEntity],
) -> HashSet<(i32, i32)> {
    let mut visible = runtime
        .rts_visible_tile_ids
        .iter()
        .filter_map(|value| classic_parse_rts_tile(value))
        .collect::<HashSet<_>>();
    if visible.is_empty() {
        for center in selected_units
            .iter()
            .map(|entity| entity.tile)
            .chain(std::iter::once(player_tile))
        {
            for dy in -1..=1 {
                for dx in -1..=1 {
                    visible.insert(classic_rts_large_map_clamp_tile((
                        center.0 + dx,
                        center.1 + dy,
                    )));
                }
            }
        }
    }
    if let Some(destination_tile) = runtime
        .rts_command_destination_tile
        .as_deref()
        .and_then(classic_parse_rts_tile)
    {
        visible.insert(classic_rts_large_map_clamp_tile(destination_tile));
    }
    for tile in runtime
        .rts_fog_reveal_tile_ids
        .iter()
        .filter_map(|value| classic_parse_rts_tile(value))
    {
        visible.insert(classic_rts_large_map_clamp_tile(tile));
    }
    visible
}

#[cfg(not(target_os = "android"))]
fn classic_rts_fogged_tiles(runtime: &NativeFirstPlayableRuntime) -> Vec<(i32, i32)> {
    runtime
        .rts_fogged_tile_ids
        .iter()
        .filter_map(|value| classic_parse_rts_tile(value))
        .map(classic_rts_large_map_clamp_tile)
        .collect()
}

#[cfg(not(target_os = "android"))]
#[allow(clippy::too_many_arguments)]
fn classic_draw_rts_queue_slot(
    buffer: &mut [u32],
    width: usize,
    height: usize,
    x: i32,
    y: i32,
    label: &str,
    progress_percent: u8,
    progress_color: u32,
) {
    classic_draw_rect(
        buffer,
        width,
        height,
        x,
        y,
        56,
        18,
        CLASSIC_RTS_PRODUCTION_SLOT_COLOR,
    );
    classic_draw_rect(
        buffer,
        width,
        height,
        x,
        y,
        56,
        2,
        CLASSIC_RTS_STRATEGY_PANEL_BORDER_COLOR,
    );
    let progress_width = (progress_percent.min(100) as i32 * 52) / 100;
    classic_draw_rect(
        buffer,
        width,
        height,
        x + 2,
        y + 13,
        progress_width,
        3,
        progress_color,
    );
    let compact_label = label
        .replace("train:", "TR ")
        .replace("build:", "BD ")
        .replace("upgrade:", "UP ")
        .replace('_', " ");
    classic_draw_text(
        buffer,
        width,
        height,
        x + 4,
        y + 4,
        &classic_catalog_text_label(&compact_label, 8),
        1,
        CLASSIC_HUD_TEXT_COLOR,
    );
}

