#[cfg(not(target_os = "android"))]
#[allow(clippy::too_many_arguments)]
fn classic_draw_rts_ability_slot(
    buffer: &mut [u32],
    width: usize,
    height: usize,
    x: i32,
    y: i32,
    label: &str,
    cooldown_percent: u8,
    active: bool,
) {
    classic_draw_rect(
        buffer,
        width,
        height,
        x,
        y,
        16,
        16,
        CLASSIC_RTS_ABILITY_SLOT_COLOR,
    );
    if active {
        classic_draw_rect(
            buffer,
            width,
            height,
            x,
            y,
            16,
            2,
            CLASSIC_RTS_ACTIVE_ABILITY_COLOR,
        );
        classic_draw_rect(
            buffer,
            width,
            height,
            x,
            y,
            2,
            16,
            CLASSIC_RTS_ACTIVE_ABILITY_COLOR,
        );
    }
    let cooldown_height = (cooldown_percent.min(100) as i32 * 13) / 100;
    if cooldown_height > 0 {
        classic_draw_rect(
            buffer,
            width,
            height,
            x + 2,
            y + 14 - cooldown_height,
            12,
            cooldown_height,
            CLASSIC_RTS_ABILITY_COOLDOWN_COLOR,
        );
    }
    let hotkey = label.chars().next().unwrap_or('-').to_ascii_uppercase();
    classic_draw_text(
        buffer,
        width,
        height,
        x + 5,
        y + 5,
        &hotkey.to_string(),
        1,
        CLASSIC_HUD_TEXT_COLOR,
    );
}

