#[cfg(not(target_os = "android"))]
#[allow(clippy::too_many_arguments)]
fn classic_draw_frame_at_tile(
    buffer: &mut [u32],
    width: usize,
    height: usize,
    assets: &ClassicRuntimeAssets,
    frame_id: &str,
    origin_x: i32,
    origin_y: i32,
    tile_size: i32,
    grid: (i32, i32),
    scale: u32,
) {
    classic_blit_frame_scaled(
        buffer,
        width,
        height,
        assets,
        frame_id,
        origin_x + grid.0 * tile_size,
        origin_y + grid.1 * tile_size,
        scale,
    );
}

#[cfg(not(target_os = "android"))]
#[allow(clippy::too_many_arguments)]
fn classic_blit_frame_override_bottom_center(
    buffer: &mut [u32],
    width: usize,
    height: usize,
    assets: &ClassicRuntimeAssets,
    frame_id: &str,
    center_x: i32,
    bottom_y: i32,
) -> bool {
    let Some(frame_override) = assets.frame_override_pixels.get(frame_id) else {
        return false;
    };
    let x = center_x - frame_override.width as i32 / 2;
    let y = bottom_y - frame_override.height as i32;
    classic_blit_pixels_scaled(
        buffer,
        width,
        height,
        &frame_override.pixels,
        frame_override.width,
        frame_override.height,
        x,
        y,
        1,
    );
    true
}

#[cfg(not(target_os = "android"))]
#[allow(clippy::too_many_arguments)]
fn classic_blit_frame_scaled(
    buffer: &mut [u32],
    width: usize,
    height: usize,
    assets: &ClassicRuntimeAssets,
    frame_id: &str,
    x: i32,
    y: i32,
    scale: u32,
) -> bool {
    let Some(frame) = assets.frame_by_id.get(frame_id) else {
        return false;
    };
    let scale = scale.max(1) as i32;
    for sy in 0..frame.h as i32 {
        for sx in 0..frame.w as i32 {
            let color = classic_frame_source_pixel(assets, frame, sx as u32, sy as u32);
            if color == 0x000000 {
                continue;
            }
            for dy in 0..scale {
                for dx in 0..scale {
                    let px = x + sx * scale + dx;
                    let py = y + sy * scale + dy;
                    if px >= 0 && py >= 0 && px < width as i32 && py < height as i32 {
                        buffer[py as usize * width + px as usize] = color;
                    }
                }
            }
        }
    }
    true
}

#[cfg(not(target_os = "android"))]
#[allow(clippy::too_many_arguments)]
fn classic_blit_pixels_scaled(
    buffer: &mut [u32],
    width: usize,
    height: usize,
    pixels: &[u32],
    source_width: u32,
    source_height: u32,
    x: i32,
    y: i32,
    scale: u32,
) {
    let scale = scale.max(1) as i32;
    if scale == 1 {
        let left = x.max(0);
        let top = y.max(0);
        let right = (x + source_width as i32).clamp(0, width as i32);
        let bottom = (y + source_height as i32).clamp(0, height as i32);
        if left >= right || top >= bottom {
            return;
        }
        let source_width = source_width as usize;
        for py in top..bottom {
            let source_y = (py - y) as usize;
            let source_row = source_y * source_width;
            let target_row = py as usize * width;
            for px in left..right {
                let color = pixels[source_row + (px - x) as usize];
                if color != 0x000000 {
                    buffer[target_row + px as usize] = color;
                }
            }
        }
        return;
    }
    for sy in 0..source_height as i32 {
        for sx in 0..source_width as i32 {
            let color = pixels
                .get(sy as usize * source_width as usize + sx as usize)
                .copied()
                .unwrap_or_default();
            if color == 0x000000 {
                continue;
            }
            for dy in 0..scale {
                for dx in 0..scale {
                    let px = x + sx * scale + dx;
                    let py = y + sy * scale + dy;
                    if px >= 0 && py >= 0 && px < width as i32 && py < height as i32 {
                        buffer[py as usize * width + px as usize] = color;
                    }
                }
            }
        }
    }
}

#[cfg(not(target_os = "android"))]
#[allow(clippy::too_many_arguments)]
fn classic_draw_rect(
    buffer: &mut [u32],
    width: usize,
    height: usize,
    x: i32,
    y: i32,
    w: i32,
    h: i32,
    color: u32,
) {
    if w <= 0 || h <= 0 || width == 0 || height == 0 {
        return;
    }
    let left = x.max(0) as usize;
    let top = y.max(0) as usize;
    let right = (x + w).clamp(0, width as i32) as usize;
    let bottom = (y + h).clamp(0, height as i32) as usize;
    if left >= right || top >= bottom {
        return;
    }
    for py in top..bottom {
        let row_start = py * width;
        buffer[row_start + left..row_start + right].fill(color);
    }
}

