        && restored_first_playable
            .scene_history
            .iter()
            .any(|scene| scene == "arena_outdoor_tilemap")
        && restored_first_playable
            .scene_history
            .iter()
            .any(|scene| scene == "combat_encounter_overlay")
        && restored_first_playable
            .scene_history
            .iter()
            .any(|scene| scene == "combat_returned_to_map")
        && restored_first_playable.movement_lock_observed
        && !restored_first_playable.movement_input_locked
        && restored_first_playable.tile_step_progress_percent == 100
        && restored_first_playable.tile_interpolation_samples.len() >= 3
        && restored_first_playable
            .npc_behavior_history
            .iter()
            .any(|state| state == "dialogue_choice_opened")
        && restored_first_playable
