pub fn native_turn_combat_playability_evidence_json(actor_id: &str) -> String {
    let actions = vec![
        NativeControlAction::Talk,
        NativeControlAction::Train,
        NativeControlAction::Move {
            direction: "north".to_string(),
        },
        NativeControlAction::CombatAttack,
        NativeControlAction::CombatDefend,
        NativeControlAction::CombatUseItem,
        NativeControlAction::CombatAttack,
        NativeControlAction::CombatAttack,
    ];
    let (samples, input_samples, button_events, final_runtime) =
        run_bevy_button_sequence(actor_id, actions);
    let combat_events = button_events
        .iter()
        .filter(|event| {
            event
                .get("action")
                .and_then(|value| value.as_str())
                .is_some_and(|action| action.starts_with("COMBAT:"))
        })
        .collect::<Vec<_>>();
    let combat_events_accepted = combat_events
        .iter()
        .all(|event| event.get("accepted").and_then(|value| value.as_bool()) == Some(true));
    let green = combat_events.len() >= 5
        && combat_events_accepted
        && final_runtime.combat_turn >= 5
        && final_runtime.enemy_hp == 0
        && final_runtime.player_hp > 0
        && final_runtime.combat_result_state == "victory"
        && final_runtime
            .completed_steps
            .iter()
            .any(|step| step == "turn_combat_victory")
        && final_runtime
            .scene_history
            .iter()
            .any(|scene| scene == "turn_combat_scene_loaded")
        && final_runtime
            .scene_history
            .iter()
            .any(|scene| scene == "turn_combat_returned_to_map")
        && !final_runtime
            .inventory_items
            .iter()
            .any(|item| item == "small_healing_pill");
    let evidence = json!({
        "contract_version": TRILLIONNIUM_WORLD_BEVY_TURN_COMBAT_PLAYABILITY_CONTRACT,
        "actor_id": actor_id,
        "green": green,
        "running_state_sampling": true,
        "bevy_window_button_path": "NativeControlAction_button_Interaction_Pressed_to_handle_native_control_buttons",
        "combat_events_accepted": combat_events_accepted,
        "button_events": button_events,
        "samples": samples,
        "input_samples": input_samples,
        "final_runtime": final_runtime,
        "android_s5_real_device_claimed": false,
    });
    serde_json::to_string_pretty(&evidence).expect("turn combat evidence serializes")
}

pub fn native_four_lane_playability_evidence_json(actor_id: &str) -> String {
    let actions = vec![
        NativeControlAction::Talk,
        NativeControlAction::Train,
        NativeControlAction::EnterRoom {
            room_id: "starter-studio".to_string(),
        },
        NativeControlAction::InteractNpc {
            npc_id: "npc-starter-artisan".to_string(),
        },
        NativeControlAction::StartTask {
            task_id: "task-starter-forge-intro".to_string(),
        },
        NativeControlAction::EnterRoom {
            room_id: "forge-workbench".to_string(),
        },
        NativeControlAction::EnterRoom {
            room_id: "asset-yard".to_string(),
        },
        NativeControlAction::EnterRoom {
            room_id: "zbj-market-gate".to_string(),
        },
        NativeControlAction::InteractNpc {
            npc_id: "npc-market-clerk".to_string(),
        },
        NativeControlAction::EnterRoom {
            room_id: "client-board".to_string(),
        },
        NativeControlAction::StartTask {
            task_id: "task-market-client-intro".to_string(),
        },
        NativeControlAction::EnterRoom {
            room_id: "delivery-dock".to_string(),
        },
        NativeControlAction::EnterRoom {
            room_id: "league-coliseum".to_string(),
        },
        NativeControlAction::CombatAttack,
        NativeControlAction::CombatDefend,
        NativeControlAction::CombatUseItem,
        NativeControlAction::CombatAttack,
        NativeControlAction::CombatAttack,
        NativeControlAction::LootDrop,
        NativeControlAction::OpenBag,
        NativeControlAction::EquipItem {
            item_id: "bandit_sash".to_string(),
        },
    ];
    let (samples, input_samples, button_events, final_runtime) =
        run_bevy_button_sequence(actor_id, actions);
    let all_pressed_accepted = button_events
        .iter()
        .all(|event| event.get("accepted").and_then(|value| value.as_bool()) == Some(true));
    let initial_input = input_samples
        .iter()
        .find(|sample| sample.get("stage").and_then(|value| value.as_str()) == Some("initial"));
    let final_attack_input = input_samples.iter().rev().find(|sample| {
        sample.get("stage").and_then(|value| value.as_str()) == Some("after_COMBAT:attack")
    });
    let after_loot_input = input_samples.iter().find(|sample| {
        sample.get("stage").and_then(|value| value.as_str()) == Some("after_LOOT:drop")
    });
    let visible_surface_ids = samples
        .last()
        .and_then(|sample| sample.get("surface_ids"))
        .and_then(|value| value.as_array())
        .cloned()
        .unwrap_or_default();
    let required_actor_surfaces = [
        "npc_patrol_path_tiles",
        "enemy_patrol_path_tiles",
        "item_drop_sprite",
        "damage_number_sprite",
        "equipment_icon_sprite",
        "bag_slot_sprite",
    ];
    let visible_actor_surfaces_green = required_actor_surfaces.iter().all(|required| {
        visible_surface_ids
            .iter()
            .any(|surface| surface.as_str() == Some(required))
    });
    let live_interaction_gate = all_pressed_accepted
        && final_runtime.visited_rooms.len() >= 7
        && final_runtime.current_room_id == "league-coliseum"
        && final_runtime
            .active_task_ids
            .iter()
            .any(|task| task == "task-starter-forge-intro")
        && final_runtime
            .active_task_ids
            .iter()
            .any(|task| task == "task-market-client-intro")
        && final_runtime.combat_result_state == "victory"
        && final_runtime.bag_open
        && final_runtime
            .equipped_items
            .iter()
            .any(|item| item == "bandit_sash");
    let map_quality_gate = samples.iter().all(|sample| {
        sample
            .get("has_quality_surfaces")
            .and_then(|value| value.as_bool())
            == Some(true)
    }) && visible_actor_surfaces_green
        && final_runtime
            .visible_behavior_history
            .iter()
            .any(|event| event.starts_with("room_actor_patrol:"))
        && final_runtime
            .visible_behavior_history
            .iter()
            .any(|event| event == "item_drop_visible")
        && final_runtime
            .visible_behavior_history
            .iter()
            .any(|event| event == "equipment_icon_visible");
    let input_semantics_gate = availability_enabled(initial_input, "BAG:open")
        && !availability_enabled(initial_input, "LOOT:drop")
        && availability_enabled(final_attack_input, "LOOT:drop")
        && availability_enabled(after_loot_input, "EQUIP:bandit_sash")
        && final_runtime
            .inventory_items
            .iter()
            .all(|item| item != "bandit_sash");
    let acceptance_artifacts_gate =
        live_interaction_gate && map_quality_gate && input_semantics_gate;
    let green = acceptance_artifacts_gate;
    let evidence = json!({
        "contract_version": TRILLIONNIUM_WORLD_BEVY_FOUR_LANE_PLAYABILITY_CONTRACT,
        "visible_actor_behavior_contract": TRILLIONNIUM_WORLD_BEVY_VISIBLE_ACTOR_BEHAVIOR_CONTRACT,
        "expanded_input_semantics_contract": TRILLIONNIUM_WORLD_BEVY_EXPANDED_INPUT_SEMANTICS_CONTRACT,
        "actor_id": actor_id,
        "green": green,
        "running_state_sampling": true,
        "bevy_window_button_path": "NativeControlAction_button_Interaction_Pressed_to_handle_native_control_buttons",
        "four_lanes": {
            "live_interaction_gate": live_interaction_gate,
            "map_quality_gate": map_quality_gate,
            "input_semantics_gate": input_semantics_gate,
            "acceptance_artifacts_gate": acceptance_artifacts_gate
        },
        "visible_actor_surfaces_green": visible_actor_surfaces_green,
        "required_actor_surfaces": required_actor_surfaces,
        "button_events": button_events,
        "samples": samples,
        "input_samples": input_samples,
        "final_runtime": final_runtime,
        "acceptance_outputs": [
            "acceptance/S5_native_bevy_device/latest/bevy-four-lane-playability.json",
            "acceptance/S5_native_bevy_device/latest/manual_bevy/bevy-four-lane-playability-ui.png"
        ],
        "android_s5_real_device_claimed": false,
    });
    serde_json::to_string_pretty(&evidence).expect("four-lane evidence serializes")
}

