pub fn native_visible_actor_runtime_evidence_json(actor_id: &str) -> String {
    let (samples, input_samples, button_events, final_runtime) =
        run_bevy_button_sequence(actor_id, visible_actor_progression_actions(false));
    let required_actor_ids = [
        "npc-street-compass-sifu",
        "npc-starter-artisan",
        "npc-market-clerk",
        "npc-client-runner",
        "npc-dock-courier",
        "enemy-market-bandit",
        "drop-bandit-sash",
    ];
    let actor_visible = |target_actor_id: &str| {
        samples.iter().any(|sample| {
            sample
                .get("visible_actor_runtimes")
                .and_then(|value| value.as_array())
                .is_some_and(|actors| {
                    actors.iter().any(|entry| {
                        entry
                            .pointer("/actor/actor_id")
                            .and_then(|value| value.as_str())
                            == Some(target_actor_id)
                            && entry
                                .pointer("/actor/visible_state")
                                .and_then(|value| value.as_str())
                                == Some("visible")
                            && entry
                                .pointer("/transform/x")
                                .and_then(|value| value.as_f64())
                                .is_some_and(|x| x.abs() < 1000.0)
                    })
                })
        })
    };
    let all_required_actor_components_visible = required_actor_ids
        .iter()
        .all(|actor_id| actor_visible(actor_id));
    let drop_visible_before_loot = samples.iter().any(|sample| {
        sample
            .get("stage")
            .and_then(|value| value.as_str())
            .is_some_and(|stage| stage == "after_COMBAT:attack")
            && sample
                .get("visible_actor_runtimes")
                .and_then(|value| value.as_array())
                .is_some_and(|actors| {
                    actors.iter().any(|entry| {
                        entry
                            .pointer("/actor/actor_id")
                            .and_then(|value| value.as_str())
                            == Some("drop-bandit-sash")
                            && entry
                                .pointer("/actor/visible_state")
                                .and_then(|value| value.as_str())
                                == Some("visible")
                    })
                })
    });
    let drop_hidden_after_loot = samples.iter().any(|sample| {
        sample.get("stage").and_then(|value| value.as_str()) == Some("after_LOOT:drop")
            && sample
                .get("visible_actor_runtimes")
                .and_then(|value| value.as_array())
                .is_some_and(|actors| {
                    actors.iter().any(|entry| {
                        entry
                            .pointer("/actor/actor_id")
                            .and_then(|value| value.as_str())
                            == Some("drop-bandit-sash")
                            && entry
                                .pointer("/actor/visible_state")
                                .and_then(|value| value.as_str())
                                == Some("hidden")
                    })
                })
    });
    let enemy_hp_zero_after_victory = samples.iter().any(|sample| {
        sample
            .get("visible_actor_runtimes")
            .and_then(|value| value.as_array())
            .is_some_and(|actors| {
                actors.iter().any(|entry| {
                    entry
                        .pointer("/actor/actor_id")
                        .and_then(|value| value.as_str())
                        == Some("enemy-market-bandit")
                        && entry.pointer("/actor/hp").and_then(|value| value.as_i64()) == Some(0)
                        && entry
                            .pointer("/actor/animation_state")
                            .and_then(|value| value.as_str())
                            == Some("enemy_down_victory")
                })
            })
    });
    let patrol_frames_advanced = final_runtime.npc_patrol_frame > 0
        && final_runtime.enemy_patrol_frame > 0
        && final_runtime
            .visible_behavior_history
            .iter()
            .any(|event| event.starts_with("room_actor_patrol:"))
        && final_runtime
            .visible_behavior_history
            .iter()
            .any(|event| event.starts_with("enemy_combat_frame:"));
    let all_pressed_accepted = button_events
        .iter()
        .all(|event| event.get("accepted").and_then(|value| value.as_bool()) == Some(true));
    let green = all_pressed_accepted
        && all_required_actor_components_visible
        && drop_visible_before_loot
        && drop_hidden_after_loot
        && enemy_hp_zero_after_victory
        && patrol_frames_advanced;
    let evidence = json!({
        "contract_version": TRILLIONNIUM_WORLD_BEVY_VISIBLE_ACTOR_RUNTIME_CONTRACT,
        "actor_id": actor_id,
        "green": green,
        "bevy_component": "BevyWorldVisibleActorRuntime",
        "component_source_of_truth": "NativeFirstPlayableRuntime + Rust WorldState",
        "all_required_actor_components_visible": all_required_actor_components_visible,
        "drop_visible_before_loot": drop_visible_before_loot,
        "drop_hidden_after_loot": drop_hidden_after_loot,
        "enemy_hp_zero_after_victory": enemy_hp_zero_after_victory,
        "patrol_frames_advanced": patrol_frames_advanced,
        "required_actor_ids": required_actor_ids,
        "button_events": button_events,
        "samples": samples,
        "input_samples": input_samples,
        "final_runtime": final_runtime,
        "android_s5_real_device_claimed": false,
    });
    serde_json::to_string_pretty(&evidence).expect("visible actor runtime evidence serializes")
}

