pub fn native_scene_pack_evidence_json(actor_id: &str) -> String {
    let scene_pack = native_bevy_scene_pack_fixture();
    let (samples, input_samples, button_events, final_runtime) =
        run_bevy_button_sequence(actor_id, visible_actor_progression_actions(true));
    let helper_parity_gate = scene_pack.rooms.iter().all(|room| {
        runtime_room_exits(&room.room_id) == room.exits
            && runtime_room_interactions(&room.room_id) == room.interactions
            && runtime_room_npcs(&room.room_id) == room.npc_ids
            && runtime_room_tasks(&room.room_id) == room.task_ids
            && room_map_scene(&room.room_id) == room.map_scene
            && room_tilemap_variant(&room.room_id) == room.tilemap_variant
    });
    let room_actor_definitions_complete = scene_pack.rooms.iter().all(|room| {
        room.npc_ids.iter().all(|npc_id| {
            scene_pack
                .actors
                .iter()
                .any(|actor| actor.actor_id == *npc_id && actor.room_id == room.room_id)
        })
    });
    let task_room_definitions_complete = scene_pack.tasks.iter().all(|task| {
        task.room_ids.iter().all(|room_id| {
            scene_pack.rooms.iter().any(|room| {
                room.room_id == *room_id
                    && room.task_ids.iter().any(|task_id| task_id == &task.task_id)
            })
        })
    });
    let pack_actor_ids = scene_pack
        .actors
        .iter()
        .map(|actor| actor.actor_id.clone())
        .collect::<Vec<_>>();
    let component_actor_ids = samples
        .last()
        .and_then(|sample| sample.get("visible_actor_runtimes"))
        .and_then(|value| value.as_array())
        .map(|actors| {
            actors
                .iter()
                .filter_map(|entry| {
                    entry
                        .pointer("/actor/actor_id")
                        .and_then(|value| value.as_str())
                        .map(str::to_string)
                })
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();
    let component_pack_gate = pack_actor_ids
        .iter()
        .all(|actor_id| component_actor_ids.iter().any(|seen| seen == actor_id));
    let final_surface_ids = samples
        .last()
        .and_then(|sample| sample.get("surface_ids"))
        .and_then(|value| value.as_array())
        .map(|values| {
            values
                .iter()
                .filter_map(|value| value.as_str().map(str::to_string))
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();
    let surface_pack_gate = scene_pack
        .required_surface_ids
        .iter()
        .all(|surface_id| final_surface_ids.iter().any(|seen| seen == surface_id));
    let progression_pack_gate = scene_pack.tasks.iter().any(|task| {
        task.task_id == "task-arena-rematch-route"
            && task.unlock_rule == "equip:bandit_sash"
            && final_runtime
                .unlocked_task_ids
                .iter()
                .any(|task_id| task_id == "task-arena-rematch-route")
            && final_runtime
                .active_task_ids
                .iter()
                .any(|task_id| task_id == "task-arena-rematch-route")
    });
    let all_pressed_accepted = button_events
        .iter()
        .all(|event| event.get("accepted").and_then(|value| value.as_bool()) == Some(true));
    let green = all_pressed_accepted
        && helper_parity_gate
        && room_actor_definitions_complete
        && task_room_definitions_complete
        && component_pack_gate
        && surface_pack_gate
        && progression_pack_gate;
    let evidence = json!({
        "contract_version": TRILLIONNIUM_WORLD_BEVY_SCENE_PACK_CONTRACT,
        "actor_id": actor_id,
        "green": green,
        "scene_pack": scene_pack,
        "runtime_uses_scene_pack_helpers": helper_parity_gate,
        "room_actor_definitions_complete": room_actor_definitions_complete,
        "task_room_definitions_complete": task_room_definitions_complete,
        "component_pack_gate": component_pack_gate,
        "surface_pack_gate": surface_pack_gate,
        "progression_pack_gate": progression_pack_gate,
        "pack_actor_ids": pack_actor_ids,
        "component_actor_ids": component_actor_ids,
        "button_events": button_events,
        "samples": samples,
        "input_samples": input_samples,
        "final_runtime": final_runtime,
        "android_s5_real_device_claimed": false,
    });
    serde_json::to_string_pretty(&evidence).expect("scene pack evidence serializes")
}

pub fn native_scene_pack_route_director_evidence_json(actor_id: &str) -> String {
    let starter_plan =
        scene_pack_route_plan_for_task("mirror-city-square", "task-starter-forge-intro");
    let market_plan = scene_pack_route_plan_for_task("forge-workbench", "task-market-client-intro");
    let arena_plan = scene_pack_route_plan_for_task("delivery-dock", "task-arena-rematch-route");
    let plans = vec![
        starter_plan.clone(),
        market_plan.clone(),
        arena_plan.clone(),
    ];
    let expected_route_button_actions = plans
        .iter()
        .flat_map(|plan| plan.generated_button_actions.clone())
        .collect::<Vec<_>>();
    let actions = scene_pack_route_director_action_sequence();
    let generated_action_labels = actions
        .iter()
        .map(native_control_action_label)
        .collect::<Vec<_>>();
    let (samples, input_samples, button_events, final_runtime) =
        run_bevy_button_sequence(actor_id, actions);
    let actual_route_button_actions = button_events
        .iter()
        .filter_map(|event| event.get("action").and_then(|value| value.as_str()))
        .filter(|label| label.starts_with("ROOM:"))
        .map(str::to_string)
        .collect::<Vec<_>>();
    let all_plans_valid = plans.iter().all(scene_pack_path_is_valid);
    let generated_actions_match_scene_graph =
        expected_route_button_actions == actual_route_button_actions;
    let all_pressed_accepted = button_events
        .iter()
        .all(|event| event.get("accepted").and_then(|value| value.as_bool()) == Some(true));
    let runtime_route_director_green =
        final_runtime.route_director_task_id == "task-arena-rematch-route"
            && final_runtime.route_director_target_room_id == "league-coliseum"
            && final_runtime.route_director_next_room_id.is_none()
            && final_runtime
                .route_director_history
                .iter()
                .any(|entry| {
                    entry == "route_director:task-arena-rematch-route:league-coliseum:arrived:league-coliseum"
                });
    let rematch_combat_ready_green = final_runtime.combat_result_state == "in_progress"
        && final_runtime.combat_scene_state == "turn_combat_rematch_ready"
        && final_runtime.combat_overlay_visible
        && final_runtime.enemy_hp == 52
        && final_runtime.player_hp >= 100
        && final_runtime
            .progression_checkpoint_history
            .iter()
            .any(|entry| entry == "rematch_started");
    let final_state_green = final_runtime.current_room_id == "league-coliseum"
        && final_runtime
            .active_task_ids
            .iter()
            .any(|task_id| task_id == "task-starter-forge-intro")
        && final_runtime
            .active_task_ids
            .iter()
            .any(|task_id| task_id == "task-market-client-intro")
        && final_runtime
            .active_task_ids
            .iter()
            .any(|task_id| task_id == "task-arena-rematch-route")
        && final_runtime
            .equipped_items
            .iter()
            .any(|item_id| item_id == "bandit_sash")
        && rematch_combat_ready_green;
    let green = all_plans_valid
        && generated_actions_match_scene_graph
        && all_pressed_accepted
        && runtime_route_director_green
        && final_state_green;
    let evidence = json!({
        "contract_version": TRILLIONNIUM_WORLD_BEVY_SCENE_PACK_ROUTE_DIRECTOR_CONTRACT,
        "scene_pack_contract": TRILLIONNIUM_WORLD_BEVY_SCENE_PACK_CONTRACT,
        "actor_id": actor_id,
        "green": green,
        "source_of_truth": "NativeBevyScenePack room graph + task definitions",
        "all_plans_valid": all_plans_valid,
        "generated_actions_match_scene_graph": generated_actions_match_scene_graph,
        "all_pressed_accepted": all_pressed_accepted,
        "runtime_route_director_green": runtime_route_director_green,
        "rematch_combat_ready_green": rematch_combat_ready_green,
        "final_state_green": final_state_green,
        "route_plans": plans,
        "expected_route_button_actions": expected_route_button_actions,
        "actual_route_button_actions": actual_route_button_actions,
        "generated_action_labels": generated_action_labels,
        "button_events": button_events,
        "samples": samples,
        "input_samples": input_samples,
        "final_runtime": final_runtime,
        "android_s5_real_device_claimed": false,
    });
    serde_json::to_string_pretty(&evidence).expect("scene pack route director evidence serializes")
}

fn scene_pack_route_director_action_sequence() -> Vec<NativeControlAction> {
    let starter_plan =
        scene_pack_route_plan_for_task("mirror-city-square", "task-starter-forge-intro");
    let market_plan = scene_pack_route_plan_for_task("forge-workbench", "task-market-client-intro");
    let arena_plan = scene_pack_route_plan_for_task("delivery-dock", "task-arena-rematch-route");
    let mut actions = Vec::new();
    actions.extend(scene_pack_route_actions(&starter_plan));
    actions.push(NativeControlAction::StartTask {
        task_id: "task-starter-forge-intro".to_string(),
    });
    actions.extend(scene_pack_route_actions(&market_plan));
    actions.push(NativeControlAction::InteractNpc {
        npc_id: "npc-dock-courier".to_string(),
    });
    actions.push(NativeControlAction::StartTask {
        task_id: "task-market-client-intro".to_string(),
    });
    actions.extend(scene_pack_route_actions(&arena_plan));
    actions.extend([
        NativeControlAction::CombatAttack,
        NativeControlAction::CombatDefend,
        NativeControlAction::CombatUseItem,
        NativeControlAction::CombatAttack,
        NativeControlAction::CombatAttack,
        NativeControlAction::LootDrop,
        NativeControlAction::OpenBag,
        NativeControlAction::EquipItem {
            item_id: "bandit_sash".to_string(),
        },
        NativeControlAction::StartTask {
            task_id: "task-arena-rematch-route".to_string(),
        },
    ]);
    actions
}

pub fn native_contextual_action_deck_evidence_json(actor_id: &str) -> String {
    let (samples, input_samples, button_events, final_runtime) =
        run_bevy_button_sequence(actor_id, scene_pack_route_director_action_sequence());
    let initial_gate = contextual_action_enabled(&input_samples, "initial", "TALK")
        && contextual_action_enabled(&input_samples, "initial", "ROOM:starter-studio")
        && !contextual_action_enabled(&input_samples, "initial", "FIGHT")
        && contextual_primary_action(&input_samples, "initial").as_deref() == Some("TALK");
    let forge_gate = contextual_action_enabled(
        &input_samples,
        "after_ROOM:forge-workbench",
        "TASK:task-starter-forge-intro",
    ) && contextual_primary_action(&input_samples, "after_ROOM:forge-workbench")
        .as_deref()
        == Some("TASK:task-starter-forge-intro");
    let delivery_gate = contextual_action_enabled(
        &input_samples,
        "after_ROOM:delivery-dock",
        "NPC:npc-dock-courier",
    ) && contextual_action_enabled(
        &input_samples,
        "after_ROOM:delivery-dock",
        "TASK:task-market-client-intro",
    ) && contextual_action_enabled(
        &input_samples,
        "after_ROOM:delivery-dock",
        "ROOM:league-coliseum",
    );
    let arena_gate = contextual_action_enabled(
        &input_samples,
        "after_ROOM:league-coliseum",
        "COMBAT:attack",
    ) && !contextual_action_enabled(
        &input_samples,
        "after_ROOM:league-coliseum",
        "TASK:task-arena-rematch-route",
    ) && contextual_action_reason(
        &input_samples,
        "after_ROOM:league-coliseum",
        "TASK:task-arena-rematch-route",
    )
    .is_some_and(|reason| reason == "task_locked_by_progression:task-arena-rematch-route");
    let rematch_gate = contextual_action_enabled(
        &input_samples,
        "after_EQUIP:bandit_sash",
        "TASK:task-arena-rematch-route",
    ) && contextual_primary_action(&input_samples, "after_EQUIP:bandit_sash")
        .as_deref()
        == Some("TASK:task-arena-rematch-route");
    let runtime_history_gate = final_runtime.contextual_action_history.len() >= 8
        && final_runtime.blocked_action_history.is_empty()
        && final_runtime
            .contextual_action_history
            .iter()
            .any(|entry| entry == "contextual_deck:league-coliseum:TASK:task-arena-rematch-route")
        && final_runtime
            .contextual_action_labels
            .iter()
            .any(|label| label == "COMBAT:attack" || label == "TASK:task-fixture-first-route");
    let all_pressed_accepted = button_events
        .iter()
        .all(|event| event.get("accepted").and_then(|value| value.as_bool()) == Some(true));
    let green = initial_gate
        && forge_gate
        && delivery_gate
        && arena_gate
        && rematch_gate
        && runtime_history_gate
        && all_pressed_accepted;
    let evidence = json!({
        "contract_version": TRILLIONNIUM_WORLD_BEVY_CONTEXTUAL_ACTION_DECK_CONTRACT,
        "route_director_contract": TRILLIONNIUM_WORLD_BEVY_SCENE_PACK_ROUTE_DIRECTOR_CONTRACT,
        "actor_id": actor_id,
        "green": green,
        "source_of_truth": "NativeFirstPlayableRuntime + NativeBevyScenePack + native_live_action_availability",
        "initial_gate": initial_gate,
        "forge_gate": forge_gate,
        "delivery_gate": delivery_gate,
        "arena_gate": arena_gate,
        "rematch_gate": rematch_gate,
        "runtime_history_gate": runtime_history_gate,
        "all_pressed_accepted": all_pressed_accepted,
        "button_events": button_events,
        "samples": samples,
        "input_samples": input_samples,
        "final_runtime": final_runtime,
        "android_s5_real_device_claimed": false,
    });
    serde_json::to_string_pretty(&evidence).expect("contextual action deck evidence serializes")
}

fn contextual_action_enabled(
    samples: &[serde_json::Value],
    stage: &str,
    action_label: &str,
) -> bool {
    contextual_action_entry(samples, stage, action_label)
        .and_then(|entry| entry.get("enabled"))
        .and_then(|value| value.as_bool())
        == Some(true)
}

fn contextual_action_reason(
    samples: &[serde_json::Value],
    stage: &str,
    action_label: &str,
) -> Option<String> {
    contextual_action_entry(samples, stage, action_label)
        .and_then(|entry| entry.get("reason"))
        .and_then(|value| value.as_str())
        .map(str::to_string)
}

fn contextual_primary_action(samples: &[serde_json::Value], stage: &str) -> Option<String> {
    samples
        .iter()
        .find(|sample| sample.get("stage").and_then(|value| value.as_str()) == Some(stage))
        .and_then(|sample| sample.pointer("/contextual_action_deck/primary_action_label"))
        .and_then(|value| value.as_str())
        .map(str::to_string)
}

fn contextual_action_entry<'a>(
    samples: &'a [serde_json::Value],
    stage: &str,
    action_label: &str,
) -> Option<&'a serde_json::Value> {
    samples
        .iter()
        .find(|sample| sample.get("stage").and_then(|value| value.as_str()) == Some(stage))
        .and_then(|sample| sample.pointer("/contextual_action_deck/actions"))
        .and_then(|value| value.as_array())
        .and_then(|actions| {
            actions.iter().find(|entry| {
                entry.get("label").and_then(|value| value.as_str()) == Some(action_label)
            })
        })
}

pub fn native_contextual_button_state_evidence_json(actor_id: &str) -> String {
    let (samples, input_samples, button_events, final_runtime) =
        run_bevy_button_sequence(actor_id, scene_pack_route_director_action_sequence());
    let initial_visual_gate = button_visual_state(&samples, "initial", "TALK").as_deref()
        == Some("onboarding_next_button")
        && button_text(&samples, "initial", "TALK").as_deref() == Some(">> R TALK")
        && button_visual_state(&samples, "initial", "TRAIN").as_deref()
            == Some("disabled_contextual")
        && button_visual_state(&samples, "initial", "FIGHT").as_deref()
            == Some("hidden_or_not_current_context");
    let forge_visual_gate = button_visual_state(
        &samples,
        "after_ROOM:forge-workbench",
        "TASK:task-starter-forge-intro",
    )
    .as_deref()
        == Some("primary_enabled")
        && button_text(
            &samples,
            "after_ROOM:forge-workbench",
            "TASK:task-starter-forge-intro",
        )
        .as_deref()
            == Some("> FORGE JOB");
    let arena_visual_gate =
        button_visual_state(&samples, "after_ROOM:league-coliseum", "COMBAT:attack").as_deref()
            == Some("primary_enabled")
            && button_visual_state(
                &samples,
                "after_ROOM:league-coliseum",
                "TASK:task-arena-rematch-route",
            )
            .as_deref()
                == Some("disabled_contextual")
            && button_visual_reason(
                &samples,
                "after_ROOM:league-coliseum",
                "TASK:task-arena-rematch-route",
            )
            .as_deref()
                == Some("task_locked_by_progression:task-arena-rematch-route");
    let rematch_visual_gate = button_visual_state(
        &samples,
        "after_EQUIP:bandit_sash",
        "TASK:task-arena-rematch-route",
    )
    .as_deref()
        == Some("primary_enabled")
        && button_text(
            &samples,
            "after_EQUIP:bandit_sash",
            "TASK:task-arena-rematch-route",
        )
        .as_deref()
            == Some("> REMATCH");
    let final_visual_gate = button_visual_state(
        &samples,
        "after_TASK:task-arena-rematch-route",
        "TASK:task-arena-rematch-route",
    )
    .as_deref()
        == Some("disabled_contextual")
        && button_visual_reason(
            &samples,
            "after_TASK:task-arena-rematch-route",
            "TASK:task-arena-rematch-route",
        )
        .as_deref()
            == Some("task_already_active:task-arena-rematch-route");
    let all_pressed_accepted = button_events
        .iter()
        .all(|event| event.get("accepted").and_then(|value| value.as_bool()) == Some(true));
    let green = initial_visual_gate
        && forge_visual_gate
        && arena_visual_gate
        && rematch_visual_gate
        && final_visual_gate
        && all_pressed_accepted;
    let evidence = json!({
        "contract_version": TRILLIONNIUM_WORLD_BEVY_CONTEXTUAL_BUTTON_STATE_CONTRACT,
        "contextual_action_deck_contract": TRILLIONNIUM_WORLD_BEVY_CONTEXTUAL_ACTION_DECK_CONTRACT,
        "actor_id": actor_id,
        "green": green,
        "source_of_truth": "native_contextual_action_deck drives actual Bevy button colors and labels",
        "initial_visual_gate": initial_visual_gate,
        "forge_visual_gate": forge_visual_gate,
        "arena_visual_gate": arena_visual_gate,
        "rematch_visual_gate": rematch_visual_gate,
        "final_visual_gate": final_visual_gate,
        "all_pressed_accepted": all_pressed_accepted,
        "button_events": button_events,
        "samples": samples,
        "input_samples": input_samples,
        "final_runtime": final_runtime,
        "android_s5_real_device_claimed": false,
    });
    serde_json::to_string_pretty(&evidence).expect("contextual button state evidence serializes")
}

