pub fn native_contextual_button_guard_evidence_json(actor_id: &str) -> String {
    let actions = contextual_button_guard_action_sequence();
    let (samples, input_samples, button_events, final_runtime) =
        run_bevy_button_sequence(actor_id, actions);
    let disabled_events = button_events
        .iter()
        .filter(|event| event.get("accepted").and_then(|value| value.as_bool()) == Some(false))
        .collect::<Vec<_>>();
    let accepted_events = button_events
        .iter()
        .filter(|event| event.get("accepted").and_then(|value| value.as_bool()) == Some(true))
        .count();
    let first_disabled_rematch_sample = samples
        .iter()
        .find(|sample| {
            sample.get("stage").and_then(|value| value.as_str())
                == Some("after_TASK:task-arena-rematch-route")
        })
        .cloned()
        .unwrap_or_else(|| json!({}));
    let rematch_samples = samples
        .iter()
        .filter(|sample| {
            sample.get("stage").and_then(|value| value.as_str())
                == Some("after_TASK:task-arena-rematch-route")
        })
        .cloned()
        .collect::<Vec<_>>();
    let last_rematch_sample = rematch_samples.last().cloned().unwrap_or_else(|| json!({}));
    let initial_disabled_guard = disabled_events.len() >= 4
        && button_event_accepted(&button_events, 0) == Some(false)
        && button_event_action(&button_events, 0).as_deref() == Some("TRAIN")
        && button_event_accepted(&button_events, 1) == Some(false)
        && button_event_action(&button_events, 1).as_deref() == Some("FIGHT")
        && button_event_accepted(&button_events, 2) == Some(false)
        && button_event_action(&button_events, 2).as_deref()
            == Some("TASK:task-arena-rematch-route")
        && first_disabled_rematch_sample
            .pointer("/runtime/current_room_id")
            .and_then(|value| value.as_str())
            == Some("mirror-city-square")
        && first_disabled_rematch_sample
            .pointer("/runtime/active_task_ids")
            .and_then(|value| value.as_array())
            .is_some_and(Vec::is_empty)
        && first_disabled_rematch_sample
            .pointer("/runtime/equipped_items")
            .and_then(|value| value.as_array())
            .is_some_and(Vec::is_empty)
        && first_disabled_rematch_sample
            .pointer("/runtime/combat_result_state")
            .and_then(|value| value.as_str())
            == Some("not_started");
    let arena_locked_guard = rematch_samples.iter().any(|sample| {
        sample
            .pointer("/runtime/current_room_id")
            .and_then(|value| value.as_str())
            == Some("league-coliseum")
            && sample
                .pointer("/runtime/equipped_items")
                .and_then(|value| value.as_array())
                .is_some_and(Vec::is_empty)
            && sample
                .pointer("/runtime/active_task_ids")
                .and_then(|value| value.as_array())
                .is_some_and(|tasks| {
                    !tasks
                        .iter()
                        .any(|task| task.as_str() == Some("task-arena-rematch-route"))
                })
    });
    let unlocked_accepts_guard = button_events.last().is_some_and(|event| {
        event.get("action").and_then(|value| value.as_str())
            == Some("TASK:task-arena-rematch-route")
            && event.get("accepted").and_then(|value| value.as_bool()) == Some(true)
    }) && last_rematch_sample
        .pointer("/runtime/active_task_ids")
        .and_then(|value| value.as_array())
        .is_some_and(|tasks| {
            tasks
                .iter()
                .any(|task| task.as_str() == Some("task-arena-rematch-route"))
        })
        && last_rematch_sample
            .pointer("/runtime/equipped_items")
            .and_then(|value| value.as_array())
            .is_some_and(|items| {
                items
                    .iter()
                    .any(|item| item.as_str() == Some("bandit_sash"))
            });
    let blocked_history_gate = final_runtime.blocked_action_history.len() >= 3
        && final_runtime
            .blocked_action_history
            .iter()
            .any(|entry| entry == "TRAIN:talk_required_before_training")
        && final_runtime
            .blocked_action_history
            .iter()
            .any(|entry| entry == "FIGHT:arena_required_before_fight")
        && final_runtime.blocked_action_history.iter().any(|entry| {
            entry == "TASK:task-arena-rematch-route:task_locked_by_progression:task-arena-rematch-route"
        });
    let arena_locked_visual_guard = rematch_samples.iter().any(|sample| {
        sample
            .pointer("/runtime/current_room_id")
            .and_then(|value| value.as_str())
            == Some("league-coliseum")
            && sample
                .pointer("/runtime/equipped_items")
                .and_then(|value| value.as_array())
                .is_some_and(Vec::is_empty)
            && sample
                .pointer("/runtime/active_task_ids")
                .and_then(|value| value.as_array())
                .is_some_and(|tasks| {
                    !tasks
                        .iter()
                        .any(|task| task.as_str() == Some("task-arena-rematch-route"))
                })
            && contextual_button_visual_state_from_sample(sample, "TASK:task-arena-rematch-route")
                .as_deref()
                == Some("disabled_contextual")
            && contextual_button_text_from_sample(sample, "TASK:task-arena-rematch-route")
                .as_deref()
                == Some("x REMATCH")
    });
    let visual_guard = button_visual_state(&samples, "after_TRAIN", "TRAIN").as_deref()
        == Some("disabled_contextual")
        && arena_locked_visual_guard
        && button_text(&samples, "after_TRAIN", "TRAIN").as_deref() == Some("x T TRAIN");
    let green = initial_disabled_guard
        && arena_locked_guard
        && unlocked_accepts_guard
        && blocked_history_gate
        && visual_guard
        && accepted_events >= 10;
    let evidence = json!({
        "contract_version": TRILLIONNIUM_WORLD_BEVY_CONTEXTUAL_BUTTON_GUARD_CONTRACT,
        "contextual_button_state_contract": TRILLIONNIUM_WORLD_BEVY_CONTEXTUAL_BUTTON_STATE_CONTRACT,
        "actor_id": actor_id,
        "green": green,
        "source_of_truth": "disabled Bevy button presses route through native_live_action_availability before mutating runtime",
        "initial_disabled_guard": initial_disabled_guard,
        "arena_locked_guard": arena_locked_guard,
        "unlocked_accepts_guard": unlocked_accepts_guard,
        "blocked_history_gate": blocked_history_gate,
        "visual_guard": visual_guard,
        "disabled_event_count": disabled_events.len(),
        "accepted_event_count": accepted_events,
        "first_disabled_rematch_sample": first_disabled_rematch_sample,
        "last_rematch_sample": last_rematch_sample,
        "button_events": button_events,
        "samples": samples,
        "input_samples": input_samples,
        "final_runtime": final_runtime,
        "android_s5_real_device_claimed": false,
    });
    serde_json::to_string_pretty(&evidence).expect("contextual button guard evidence serializes")
}

#[derive(Clone)]
struct NativeKeyboardScriptInput {
    key: KeyCode,
    key_label: &'static str,
    action: NativeControlAction,
}

pub fn native_keyboard_input_guard_evidence_json(actor_id: &str) -> String {
    let steps = keyboard_input_guard_sequence();
    let (samples, input_samples, keyboard_events, final_runtime) =
        run_bevy_keyboard_sequence(actor_id, steps);
    let disabled_events = keyboard_events
        .iter()
        .filter(|event| event.get("accepted").and_then(|value| value.as_bool()) == Some(false))
        .collect::<Vec<_>>();
    let accepted_event_count = keyboard_events
        .iter()
        .filter(|event| event.get("accepted").and_then(|value| value.as_bool()) == Some(true))
        .count();
    let disabled_guard = disabled_events.len() >= 4
        && button_event_action(&keyboard_events, 0).as_deref() == Some("TRAIN")
        && button_event_accepted(&keyboard_events, 0) == Some(false)
        && button_event_action(&keyboard_events, 1).as_deref() == Some("FIGHT")
        && button_event_accepted(&keyboard_events, 1) == Some(false)
        && button_event_action(&keyboard_events, 2).as_deref() == Some("MOVE:north")
        && button_event_accepted(&keyboard_events, 2) == Some(true)
        && button_event_action(&keyboard_events, 3).as_deref() == Some("LOOT:drop")
        && button_event_accepted(&keyboard_events, 3) == Some(false)
        && button_event_action(&keyboard_events, 4).as_deref() == Some("EQUIP:bandit_sash")
        && button_event_accepted(&keyboard_events, 4) == Some(false)
        && disabled_events.iter().all(|event| {
            event
                .get("core_state_unchanged_when_disabled")
                .and_then(|value| value.as_bool())
                == Some(true)
        });
    let unlocked_accepts_guard = accepted_event_count >= 6
        && button_event_action(&keyboard_events, 5).as_deref() == Some("TALK")
        && button_event_accepted(&keyboard_events, 5) == Some(true)
        && button_event_action(&keyboard_events, 6).as_deref() == Some("TRAIN")
        && button_event_accepted(&keyboard_events, 6) == Some(true)
        && button_event_action(&keyboard_events, 7).as_deref() == Some("MOVE:north")
        && button_event_accepted(&keyboard_events, 7) == Some(true)
        && button_event_action(&keyboard_events, 8).as_deref() == Some("FIGHT")
        && button_event_accepted(&keyboard_events, 8) == Some(true)
        && button_event_action(&keyboard_events, 9).as_deref() == Some("COMPLETE")
        && button_event_accepted(&keyboard_events, 9) == Some(true)
        && button_event_action(&keyboard_events, 10).as_deref() == Some("EQUIP")
        && button_event_accepted(&keyboard_events, 10) == Some(true)
        && final_runtime.equipment_ready
        && final_runtime.objective_status == "first_playable_loop_complete";
    let keyboard_path_gate = keyboard_events.iter().all(|event| {
        event.get("input_path").and_then(|value| value.as_str())
            == Some(
                "ButtonInput<KeyCode> -> handle_native_keyboard_input -> apply_live_native_action",
            )
    });
    let movement_key_gate = keyboard_events.iter().any(|event| {
        event.get("key").and_then(|value| value.as_str()) == Some("KeyW")
            && event.get("action").and_then(|value| value.as_str()) == Some("MOVE:north")
            && event.get("accepted").and_then(|value| value.as_bool()) == Some(true)
            && event
                .get("current_room_after")
                .and_then(|value| value.as_str())
                == Some("league-coliseum")
    });
    let pre_training_movement_key_gate = keyboard_events.iter().any(|event| {
        event.get("key").and_then(|value| value.as_str()) == Some("KeyW")
            && event.get("action").and_then(|value| value.as_str()) == Some("MOVE:north")
            && event.get("accepted").and_then(|value| value.as_bool()) == Some(true)
            && event
                .get("availability_before")
                .and_then(|value| value.as_str())
                == Some("enabled_local_map_step_north")
            && event
                .get("current_room_after")
                .and_then(|value| value.as_str())
                == Some("mirror-city-square")
    });
    let blocked_history_gate = [
        "TRAIN:talk_required_before_training",
        "FIGHT:arena_required_before_fight",
        "LOOT:drop:victory_required_before_loot",
        "EQUIP:bandit_sash:item_not_in_bag:bandit_sash",
    ]
    .iter()
    .all(|expected| {
        final_runtime
            .blocked_action_history
            .iter()
            .any(|entry| entry == expected)
    });
    let visual_parity_gate = button_text(&samples, "initial", "TRAIN").as_deref()
        == Some("x T TRAIN")
        && button_text(&samples, "after_KeyR_TALK", "TRAIN").as_deref() == Some(">> T TRAIN")
        && button_text(&samples, "after_KeyI_EQUIP", "EQUIP").as_deref() == Some("x I BAG");
    let green = disabled_guard
        && unlocked_accepts_guard
        && keyboard_path_gate
        && movement_key_gate
        && pre_training_movement_key_gate
        && blocked_history_gate
        && visual_parity_gate;
    let evidence = json!({
        "contract_version": TRILLIONNIUM_WORLD_BEVY_KEYBOARD_INPUT_GUARD_CONTRACT,
        "live_input_sampling_contract": TRILLIONNIUM_WORLD_BEVY_LIVE_INPUT_SAMPLING_CONTRACT,
        "contextual_button_guard_contract": TRILLIONNIUM_WORLD_BEVY_CONTEXTUAL_BUTTON_GUARD_CONTRACT,
        "actor_id": actor_id,
        "green": green,
        "source_of_truth": "ButtonInput<KeyCode> feeds the same apply_live_native_action guard as Bevy buttons",
        "keyboard_path_gate": keyboard_path_gate,
        "disabled_guard": disabled_guard,
        "unlocked_accepts_guard": unlocked_accepts_guard,
        "movement_key_gate": movement_key_gate,
        "pre_training_movement_key_gate": pre_training_movement_key_gate,
        "blocked_history_gate": blocked_history_gate,
        "visual_parity_gate": visual_parity_gate,
        "disabled_event_count": disabled_events.len(),
        "accepted_event_count": accepted_event_count,
        "keyboard_events": keyboard_events,
        "samples": samples,
        "input_samples": input_samples,
        "final_runtime": final_runtime,
        "android_s5_real_device_claimed": false,
    });
    serde_json::to_string_pretty(&evidence).expect("keyboard input guard evidence serializes")
}

pub fn native_input_feedback_loop_evidence_json(actor_id: &str) -> String {
    let (button_samples, button_input_samples, button_events, button_runtime) =
        run_bevy_button_sequence(
            actor_id,
            vec![
                NativeControlAction::Train,
                NativeControlAction::Talk,
                NativeControlAction::Train,
            ],
        );
    let (keyboard_samples, keyboard_input_samples, keyboard_events, keyboard_runtime) =
        run_bevy_keyboard_sequence(actor_id, keyboard_input_guard_sequence());
    let button_feedback = &button_runtime.input_feedback_history;
    let keyboard_feedback = &keyboard_runtime.input_feedback_history;
    let button_blocked_feedback_gate = button_feedback.iter().any(|event| {
        event.input_source == "bevy_button"
            && event.action_label == "TRAIN"
            && !event.accepted
            && event.reason == "talk_required_before_training"
            && event
                .feedback_text
                .contains("Input blocked: TRAIN (talk_required_before_training)")
    });
    let button_accepted_feedback_gate = button_feedback.iter().any(|event| {
        event.input_source == "bevy_button"
            && event.action_label == "TALK"
            && event.accepted
            && event.reason == "enabled_at_mentor_tile"
            && event.feedback_text.contains("Mentor dialogue opened")
    }) && button_feedback.iter().any(|event| {
        event.input_source == "bevy_button"
            && event.action_label == "TRAIN"
            && event.accepted
            && event.reason == "enabled_after_dialogue_choice"
            && event.feedback_text.contains("Training room entered")
    });
    let keyboard_local_movement_feedback_gate = keyboard_feedback.iter().any(|event| {
        event.input_source == "keyboard"
            && event.action_label == "MOVE:north"
            && event.accepted
            && event.reason == "enabled_local_map_step_north"
            && event.feedback_text.contains("Map step: north")
    });
    let keyboard_accepted_feedback_gate = keyboard_feedback.iter().any(|event| {
        event.input_source == "keyboard"
            && event.action_label == "MOVE:north"
            && event.accepted
            && event.reason == "enabled_route_step_north"
            && event.feedback_text.contains("arena reached")
    }) && keyboard_feedback.iter().any(|event| {
        event.input_source == "keyboard"
            && event.action_label == "EQUIP"
            && event.accepted
            && event.reason == "enabled_after_reward_claim"
            && event.feedback_text.contains("Route Guard Staff ready")
    });
    let event_log_feedback_gate = button_samples.iter().any(|sample| {
        sample
            .get("event_log_text")
            .and_then(|value| value.as_str())
            .is_some_and(|text| {
                text.contains("INPUT") && text.contains("bevy_button TRAIN blocked")
            })
    }) && keyboard_samples.iter().any(|sample| {
        sample
            .get("event_log_text")
            .and_then(|value| value.as_str())
            .is_some_and(|text| {
                text.contains("INPUT") && text.contains("keyboard MOVE:north accepted")
            })
    });
    let feedback_history_cap_gate = button_feedback.len() <= 12
        && keyboard_feedback.len() <= 12
        && keyboard_feedback.len() >= 11;
    let green = button_blocked_feedback_gate
        && button_accepted_feedback_gate
        && keyboard_local_movement_feedback_gate
        && keyboard_accepted_feedback_gate
        && event_log_feedback_gate
        && feedback_history_cap_gate
        && keyboard_runtime.equipment_ready
        && keyboard_runtime.objective_status == "first_playable_loop_complete";
    let evidence = json!({
        "contract_version": TRILLIONNIUM_WORLD_BEVY_INPUT_FEEDBACK_LOOP_CONTRACT,
        "keyboard_input_guard_contract": TRILLIONNIUM_WORLD_BEVY_KEYBOARD_INPUT_GUARD_CONTRACT,
        "contextual_button_guard_contract": TRILLIONNIUM_WORLD_BEVY_CONTEXTUAL_BUTTON_GUARD_CONTRACT,
        "actor_id": actor_id,
        "green": green,
        "source_of_truth": "apply_live_native_action_with_source records structured input feedback after every accepted or blocked Bevy input",
        "button_blocked_feedback_gate": button_blocked_feedback_gate,
        "button_accepted_feedback_gate": button_accepted_feedback_gate,
        "keyboard_local_movement_feedback_gate": keyboard_local_movement_feedback_gate,
        "keyboard_accepted_feedback_gate": keyboard_accepted_feedback_gate,
        "event_log_feedback_gate": event_log_feedback_gate,
        "feedback_history_cap_gate": feedback_history_cap_gate,
        "button_feedback_history": button_feedback,
        "keyboard_feedback_history": keyboard_feedback,
        "button_events": button_events,
        "keyboard_events": keyboard_events,
        "button_samples": button_samples,
        "keyboard_samples": keyboard_samples,
        "button_input_samples": button_input_samples,
        "keyboard_input_samples": keyboard_input_samples,
        "button_final_runtime": button_runtime,
        "keyboard_final_runtime": keyboard_runtime,
        "android_s5_real_device_claimed": false,
    });
    serde_json::to_string_pretty(&evidence).expect("input feedback loop evidence serializes")
}

pub fn native_input_replay_telemetry_evidence_json(actor_id: &str) -> String {
    let (_button_samples, _button_input_samples, _button_events, button_runtime) =
        run_bevy_button_sequence(
            actor_id,
            vec![
                NativeControlAction::Train,
                NativeControlAction::Talk,
                NativeControlAction::Train,
            ],
        );
    let (_keyboard_samples, _keyboard_input_samples, keyboard_events, keyboard_runtime) =
        run_bevy_keyboard_sequence(actor_id, keyboard_input_guard_sequence());
    let (button_replay_runtime, button_replay_events) =
        replay_input_feedback_history(actor_id, &button_runtime.input_feedback_history);
    let (keyboard_replay_runtime, keyboard_replay_events) =
        replay_input_feedback_history(actor_id, &keyboard_runtime.input_feedback_history);
    let button_original_signature = input_replay_signature(&button_runtime);
    let button_replay_signature = input_replay_signature(&button_replay_runtime);
    let keyboard_original_signature = input_replay_signature(&keyboard_runtime);
    let keyboard_replay_signature = input_replay_signature(&keyboard_replay_runtime);
    let button_replay_signature_gate = button_original_signature == button_replay_signature;
    let keyboard_replay_signature_gate = keyboard_original_signature == keyboard_replay_signature;
    let parse_gate = replay_events_all_parsed(&button_replay_events)
        && replay_events_all_parsed(&keyboard_replay_events);
    let event_match_gate = replay_events_all_match(&button_replay_events)
        && replay_events_all_match(&keyboard_replay_events);
    let source_order_gate = feedback_source_action_pairs(&keyboard_runtime.input_feedback_history)
        == string_vec([
            "keyboard:TRAIN",
            "keyboard:FIGHT",
            "keyboard:MOVE:north",
            "keyboard:LOOT:drop",
            "keyboard:EQUIP:bandit_sash",
            "keyboard:TALK",
            "keyboard:TRAIN",
            "keyboard:MOVE:north",
            "keyboard:FIGHT",
            "keyboard:COMPLETE",
            "keyboard:EQUIP",
        ]);
    let blocked_replay_gate = keyboard_replay_events.iter().any(|event| {
        event.get("action_label").and_then(|value| value.as_str()) == Some("EQUIP:bandit_sash")
            && event
                .get("expected_accepted")
                .and_then(|value| value.as_bool())
                == Some(false)
            && event
                .get("replay_accepted")
                .and_then(|value| value.as_bool())
                == Some(false)
            && event.get("replay_reason").and_then(|value| value.as_str())
                == Some("item_not_in_bag:bandit_sash")
    });
    let local_movement_replay_gate = keyboard_replay_events.iter().any(|event| {
        event.get("action_label").and_then(|value| value.as_str()) == Some("MOVE:north")
            && event
                .get("expected_accepted")
                .and_then(|value| value.as_bool())
                == Some(true)
            && event
                .get("replay_accepted")
                .and_then(|value| value.as_bool())
                == Some(true)
            && event.get("replay_reason").and_then(|value| value.as_str())
                == Some("enabled_local_map_step_north")
    });
    let accepted_replay_gate = keyboard_replay_events.iter().any(|event| {
        event.get("action_label").and_then(|value| value.as_str()) == Some("EQUIP")
            && event
                .get("expected_accepted")
                .and_then(|value| value.as_bool())
                == Some(true)
            && event
                .get("replay_accepted")
                .and_then(|value| value.as_bool())
                == Some(true)
            && event.get("replay_reason").and_then(|value| value.as_str())
                == Some("enabled_after_reward_claim")
    }) && keyboard_replay_runtime.equipment_ready
        && keyboard_replay_runtime.objective_status == "first_playable_loop_complete";
    let green = parse_gate
        && event_match_gate
        && source_order_gate
        && blocked_replay_gate
        && local_movement_replay_gate
        && accepted_replay_gate
        && button_replay_signature_gate
        && keyboard_replay_signature_gate;
    let evidence = json!({
        "contract_version": TRILLIONNIUM_WORLD_BEVY_INPUT_REPLAY_TELEMETRY_CONTRACT,
        "input_feedback_loop_contract": TRILLIONNIUM_WORLD_BEVY_INPUT_FEEDBACK_LOOP_CONTRACT,
        "keyboard_input_guard_contract": TRILLIONNIUM_WORLD_BEVY_KEYBOARD_INPUT_GUARD_CONTRACT,
        "actor_id": actor_id,
        "green": green,
        "source_of_truth": "structured input feedback history can deterministically replay accepted and blocked Bevy inputs",
        "parse_gate": parse_gate,
        "event_match_gate": event_match_gate,
        "source_order_gate": source_order_gate,
        "blocked_replay_gate": blocked_replay_gate,
        "local_movement_replay_gate": local_movement_replay_gate,
        "accepted_replay_gate": accepted_replay_gate,
        "button_replay_signature_gate": button_replay_signature_gate,
        "keyboard_replay_signature_gate": keyboard_replay_signature_gate,
        "button_original_signature": button_original_signature,
        "button_replay_signature": button_replay_signature,
        "keyboard_original_signature": keyboard_original_signature,
        "keyboard_replay_signature": keyboard_replay_signature,
        "button_feedback_history": button_runtime.input_feedback_history,
        "keyboard_feedback_history": keyboard_runtime.input_feedback_history,
        "button_replay_events": button_replay_events,
        "keyboard_replay_events": keyboard_replay_events,
        "keyboard_events": keyboard_events,
        "button_replay_final_runtime": button_replay_runtime,
        "keyboard_replay_final_runtime": keyboard_replay_runtime,
        "android_s5_real_device_claimed": false,
    });
    serde_json::to_string_pretty(&evidence).expect("input replay telemetry evidence serializes")
}

pub fn native_input_telemetry_summary_evidence_json(actor_id: &str) -> String {
    let (button_samples, _button_input_samples, _button_events, button_runtime) =
        run_bevy_button_sequence(
            actor_id,
            vec![
                NativeControlAction::Train,
                NativeControlAction::Talk,
                NativeControlAction::Train,
            ],
        );
    let (keyboard_samples, _keyboard_input_samples, _keyboard_events, keyboard_runtime) =
        run_bevy_keyboard_sequence(actor_id, keyboard_input_guard_sequence());
    let button_summary = native_input_telemetry_summary(&button_runtime);
    let keyboard_summary = native_input_telemetry_summary(&keyboard_runtime);
    let button_sample_summary = button_samples
        .last()
        .and_then(|sample| sample.get("input_telemetry_summary"))
        .cloned()
        .unwrap_or_else(|| json!({}));
    let keyboard_sample_summary = keyboard_samples
        .last()
        .and_then(|sample| sample.get("input_telemetry_summary"))
        .cloned()
        .unwrap_or_else(|| json!({}));
    let button_summary_gate = button_summary.total_events == 3
        && button_summary.accepted_events == 2
        && button_summary.blocked_events == 1
        && button_summary.bevy_button_events == 3
        && button_summary.keyboard_events == 0
        && button_summary.last_action_label.as_deref() == Some("TRAIN")
        && button_summary.last_accepted == Some(true)
        && button_summary.last_reason.as_deref() == Some("enabled_after_dialogue_choice")
        && button_summary
            .blocked_reasons
            .iter()
            .any(|reason| reason == "talk_required_before_training");
    let keyboard_summary_gate = keyboard_summary.total_events == 11
        && keyboard_summary.accepted_events == 7
        && keyboard_summary.blocked_events == 4
        && keyboard_summary.keyboard_events == 11
        && keyboard_summary.bevy_button_events == 0
        && keyboard_summary.last_action_label.as_deref() == Some("EQUIP")
        && keyboard_summary.last_accepted == Some(true)
        && keyboard_summary.last_reason.as_deref() == Some("enabled_after_reward_claim")
        && keyboard_summary.final_objective_status == "first_playable_loop_complete"
        && keyboard_summary.equipment_ready;
    let blocked_reason_summary_gate = [
        "talk_required_before_training",
        "arena_required_before_fight",
        "victory_required_before_loot",
        "item_not_in_bag:bandit_sash",
    ]
    .iter()
    .all(|reason| {
        keyboard_summary
            .blocked_reasons
            .iter()
            .any(|blocked| blocked == reason)
    });
    let accepted_action_summary_gate =
        ["TALK", "TRAIN", "MOVE:north", "FIGHT", "COMPLETE", "EQUIP"]
            .iter()
            .all(|action| {
                keyboard_summary
                    .accepted_action_labels
                    .iter()
                    .any(|accepted| accepted == action)
            });
    let sample_summary_gate = serde_json::to_value(&button_summary)
        .expect("button summary serializes")
        == button_sample_summary
        && serde_json::to_value(&keyboard_summary).expect("keyboard summary serializes")
            == keyboard_sample_summary;
    let green = button_summary_gate
        && keyboard_summary_gate
        && blocked_reason_summary_gate
        && accepted_action_summary_gate
        && sample_summary_gate;
    let evidence = json!({
        "contract_version": TRILLIONNIUM_WORLD_BEVY_INPUT_TELEMETRY_SUMMARY_CONTRACT,
        "input_replay_telemetry_contract": TRILLIONNIUM_WORLD_BEVY_INPUT_REPLAY_TELEMETRY_CONTRACT,
        "input_feedback_loop_contract": TRILLIONNIUM_WORLD_BEVY_INPUT_FEEDBACK_LOOP_CONTRACT,
        "actor_id": actor_id,
        "green": green,
        "source_of_truth": "NativeFirstPlayableRuntime input_feedback_history summarized into stable input telemetry counters",
        "button_summary_gate": button_summary_gate,
        "keyboard_summary_gate": keyboard_summary_gate,
        "blocked_reason_summary_gate": blocked_reason_summary_gate,
        "accepted_action_summary_gate": accepted_action_summary_gate,
        "sample_summary_gate": sample_summary_gate,
        "button_summary": button_summary,
        "keyboard_summary": keyboard_summary,
        "button_sample_summary": button_sample_summary,
        "keyboard_sample_summary": keyboard_sample_summary,
        "android_s5_real_device_claimed": false,
    });
    serde_json::to_string_pretty(&evidence).expect("input telemetry summary evidence serializes")
}

pub fn native_input_telemetry_hud_evidence_json(actor_id: &str) -> String {
    let (samples, _input_samples, keyboard_events, final_runtime) =
        run_bevy_keyboard_sequence(actor_id, keyboard_input_guard_sequence());
    let final_sample = samples.last().cloned().unwrap_or_else(|| json!({}));
    let event_log_text = final_sample
        .get("event_log_text")
        .and_then(|value| value.as_str())
        .unwrap_or_default()
        .to_string();
    let final_sample_summary = final_sample
        .get("input_telemetry_summary")
        .cloned()
        .unwrap_or_else(|| json!({}));
    let input_summary = native_input_telemetry_summary(&final_runtime);
    let input_summary_json =
        serde_json::to_value(&input_summary).expect("input telemetry summary serializes");
    let hud_contract_gate = event_log_text
        .contains("INPUT SUMMARY total 11 accepted 7 blocked 4 keyboard 11 buttons 0")
        && event_log_text.contains("last keyboard EQUIP enabled_after_reward_claim");
    let hud_recent_input_gate = event_log_text
        .contains("keyboard EQUIP accepted (enabled_after_reward_claim)")
        && event_log_text.contains("keyboard COMPLETE accepted (enabled_after_combat)");
    let sample_summary_gate = input_summary_json == final_sample_summary
        && input_summary.contract_version
            == TRILLIONNIUM_WORLD_BEVY_INPUT_TELEMETRY_SUMMARY_CONTRACT
        && input_summary.total_events == 11
        && input_summary.accepted_events == 7
        && input_summary.blocked_events == 4
        && input_summary.keyboard_events == 11
        && input_summary.bevy_button_events == 0
        && input_summary.last_input_source.as_deref() == Some("keyboard")
        && input_summary.last_action_label.as_deref() == Some("EQUIP")
        && input_summary.last_accepted == Some(true)
        && input_summary.last_reason.as_deref() == Some("enabled_after_reward_claim");
    let final_runtime_gate = final_runtime.objective_status == "first_playable_loop_complete"
        && final_runtime.equipment_ready;
    let green =
        hud_contract_gate && hud_recent_input_gate && sample_summary_gate && final_runtime_gate;
    let evidence = json!({
        "contract_version": TRILLIONNIUM_WORLD_BEVY_INPUT_TELEMETRY_HUD_CONTRACT,
        "input_telemetry_summary_contract": TRILLIONNIUM_WORLD_BEVY_INPUT_TELEMETRY_SUMMARY_CONTRACT,
        "input_feedback_loop_contract": TRILLIONNIUM_WORLD_BEVY_INPUT_FEEDBACK_LOOP_CONTRACT,
        "keyboard_input_guard_contract": TRILLIONNIUM_WORLD_BEVY_KEYBOARD_INPUT_GUARD_CONTRACT,
        "actor_id": actor_id,
        "green": green,
        "source_of_truth": "Bevy event log panel renders NativeInputTelemetrySummary from NativeFirstPlayableRuntime input history",
        "hud_contract_gate": hud_contract_gate,
        "hud_recent_input_gate": hud_recent_input_gate,
        "sample_summary_gate": sample_summary_gate,
        "final_runtime_gate": final_runtime_gate,
        "event_log_text": event_log_text,
        "input_telemetry_summary": input_summary,
        "final_sample_input_telemetry_summary": final_sample_summary,
        "final_sample": final_sample,
        "keyboard_events": keyboard_events,
        "final_runtime": final_runtime,
        "android_s5_real_device_claimed": false,
    });
    serde_json::to_string_pretty(&evidence).expect("input telemetry hud evidence serializes")
}

pub fn native_player_hud_debug_layer_evidence_json(actor_id: &str) -> String {
    let (samples, _input_samples, _keyboard_events, final_runtime) =
        run_bevy_keyboard_sequence(actor_id, keyboard_input_guard_sequence());
    let final_sample = samples.last().cloned().unwrap_or_else(|| json!({}));
    let player_hud_text = final_sample
        .get("character_status_text")
        .and_then(|value| value.as_str())
        .unwrap_or_default()
        .to_string();
    let quest_panel_text = final_sample
        .get("quest_panel_text")
        .and_then(|value| value.as_str())
        .unwrap_or_default()
        .to_string();
    let debug_event_text = final_sample
        .get("event_log_text")
        .and_then(|value| value.as_str())
        .unwrap_or_default()
        .to_string();
    let debug_scene_text = final_sample
        .get("scene_state_text")
        .and_then(|value| value.as_str())
        .unwrap_or_default()
        .to_string();
    let input_hint_text = final_sample
        .get("input_hint_text")
        .and_then(|value| value.as_str())
        .unwrap_or_default()
        .to_string();
    let player_panel_ids = native_player_hud_panel_ids();
    let debug_panel_ids = native_debug_layer_panel_ids();
    let forbidden_player_debug_needles = ["INPUT SUMMARY", "DEBUG LAYER", "contract_version"];
    let player_hud_gate = player_hud_text.contains("PLAYER HUD")
        && player_hud_text.contains("Next")
        && player_hud_text.contains("Gear")
        && !forbidden_player_debug_needles
            .iter()
            .any(|needle| player_hud_text.contains(needle));
    let quest_layer_gate = quest_panel_text.contains("FIRST MINUTE HUD")
        && quest_panel_text.contains("QUEST JOURNAL")
        && quest_panel_text.contains("NEXT BUTTON");
    let debug_layer_gate = debug_event_text.contains("DEBUG LAYER")
        && debug_event_text.contains("INPUT SUMMARY")
        && debug_event_text.contains("keyboard EQUIP accepted");
    let scene_debug_gate = debug_scene_text.contains("DEBUG LAYER")
        && debug_scene_text.contains("Scene")
        && debug_scene_text.contains("Transition");
    let input_hint_gate = input_hint_text.contains("INPUT HUD | NEXT")
        && input_hint_text.contains("READY:")
        && input_hint_text.contains("LOCKED:");
    let panel_layer_gate = player_panel_ids.contains(&"top_character_status".to_string())
        && player_panel_ids.contains(&"quest_objective_panel".to_string())
        && debug_panel_ids.contains(&"event_log_panel".to_string())
        && debug_panel_ids.contains(&"scene_transition_panel".to_string());
    let runtime_gate = final_runtime.objective_status == "first_playable_loop_complete"
        && final_runtime.equipment_ready;
    let green = player_hud_gate
        && quest_layer_gate
        && debug_layer_gate
        && scene_debug_gate
        && input_hint_gate
        && panel_layer_gate
        && runtime_gate;
    let evidence = json!({
        "contract_version": TRILLIONNIUM_WORLD_BEVY_PLAYER_HUD_DEBUG_LAYER_CONTRACT,
        "actor_id": actor_id,
        "green": green,
        "source_of_truth": "Bevy runtime samples prove player-facing HUD text and engineering diagnostics render in separate named layers while Rust remains authoritative",
        "player_hud_gate": player_hud_gate,
        "quest_layer_gate": quest_layer_gate,
        "debug_layer_gate": debug_layer_gate,
        "scene_debug_gate": scene_debug_gate,
        "input_hint_gate": input_hint_gate,
        "panel_layer_gate": panel_layer_gate,
        "runtime_gate": runtime_gate,
        "player_layer": {
            "panel_ids": player_panel_ids,
            "forbidden_debug_needles": forbidden_player_debug_needles,
            "character_status_text": player_hud_text,
            "quest_panel_text": quest_panel_text
        },
        "debug_layer": {
            "panel_ids": debug_panel_ids,
            "event_log_text": debug_event_text,
            "scene_state_text": debug_scene_text,
            "input_hint_text": input_hint_text
        },
        "final_runtime": final_runtime,
        "android_s5_real_device_claimed": false,
    });
    serde_json::to_string_pretty(&evidence).expect("player HUD debug layer evidence serializes")
}

