pub fn native_authored_art_pack_evidence_json(actor_id: &str) -> String {
    let actor_id = actor_id.to_string();
    std::thread::Builder::new()
        .name("trnm-authored-art-pack-evidence".to_string())
        .stack_size(32 * 1024 * 1024)
        .spawn(move || native_authored_art_pack_evidence_json_inner(&actor_id))
        .expect("authored art pack evidence thread spawns")
        .join()
        .expect("authored art pack evidence thread completes")
}

fn native_authored_art_pack_evidence_json_inner(actor_id: &str) -> String {
    let player_ui_rescue: Value =
        serde_json::from_str(&native_player_ui_rescue_evidence_json(actor_id))
            .expect("player UI rescue evidence parses for authored art pack");
    let authored_art_pack_gate = player_ui_rescue
        .get("authored_art_pack_gate")
        .and_then(Value::as_bool)
        == Some(true);
    let tileset_polish_gate = player_ui_rescue
        .get("tileset_polish_gate")
        .and_then(Value::as_bool)
        == Some(true);
    let map_model_visual_gate = player_ui_rescue
        .get("map_model_visual_gate")
        .and_then(Value::as_bool)
        == Some(true);
    let policy = player_ui_rescue
        .get("authored_art_pack_policy")
        .cloned()
        .unwrap_or_else(|| json!({}));
    let green = authored_art_pack_gate && tileset_polish_gate && map_model_visual_gate;
    let evidence = json!({
        "contract_version": TRILLIONNIUM_WORLD_BEVY_AUTHORED_ART_PACK_CONTRACT,
        "actor_id": actor_id,
        "green": green,
        "authored_art_pack_gate": authored_art_pack_gate,
        "tileset_polish_gate": tileset_polish_gate,
        "map_model_visual_gate": map_model_visual_gate,
        "authored_art_pack_policy": policy,
        "source_of_truth": "Bevy authored art asset-pack evidence is derived from real runtime entity components sampled after the player UI rescue route, not from static markdown.",
        "asset_boundary": "project_owned_internal_placeholder_manifest_not_external_bitmap_ship_claim",
        "android_s5_real_device_claimed": false,
    });
    serde_json::to_string_pretty(&evidence).expect("authored art pack evidence serializes")
}

fn authored_art_asset_surfaces_from_runtime(actor_id: &str) -> Vec<Value> {
    let (samples, _input_samples, _keyboard_events, _final_runtime) =
        run_bevy_keyboard_sequence(actor_id, keyboard_input_guard_sequence());
    samples
        .last()
        .and_then(|sample| sample.get("authored_art_asset_surfaces"))
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default()
}

fn authored_surface_string(surface: &Value, key: &str) -> String {
    surface
        .get(key)
        .and_then(Value::as_str)
        .unwrap_or("unknown")
        .to_string()
}

fn push_first_authored_surface(
    selected: &mut Vec<Value>,
    seen_surface_ids: &mut HashSet<String>,
    surfaces: &[Value],
    key: &str,
    expected: &str,
) {
    if let Some(surface) = surfaces
        .iter()
        .find(|surface| surface.get(key).and_then(Value::as_str) == Some(expected))
    {
        let surface_id = authored_surface_string(surface, "surface_id");
        if seen_surface_ids.insert(surface_id) {
            selected.push(surface.clone());
        }
    }
}

fn authored_sprite_sheet_selected_surfaces(surfaces: &[Value]) -> Vec<Value> {
    let mut selected = Vec::new();
    let mut seen_surface_ids = HashSet::new();
    for asset_kind in [
        "terrain_tile",
        "road_tile",
        "building_tile",
        "foliage_sprite",
        "water_tile",
        "hud_icon",
        "hud_glyph",
        "actor_sprite",
        "feedback_glyph",
    ] {
        push_first_authored_surface(
            &mut selected,
            &mut seen_surface_ids,
            surfaces,
            "asset_kind",
            asset_kind,
        );
    }
    for gameplay_layer in [
        "terrain", "road", "building", "greenery", "water", "hud", "actor", "feedback",
    ] {
        push_first_authored_surface(
            &mut selected,
            &mut seen_surface_ids,
            surfaces,
            "gameplay_layer",
            gameplay_layer,
        );
    }
    for replacement_slot in [
        "tile_sprite_slot",
        "hud_icon_slot",
        "hud_glyph_slot",
        "actor_sprite_slot",
        "actor_shadow_slot",
        "actor_badge_slot",
        "feedback_glyph_slot",
    ] {
        push_first_authored_surface(
            &mut selected,
            &mut seen_surface_ids,
            surfaces,
            "replacement_slot",
            replacement_slot,
        );
    }
    for surface in surfaces {
        if selected.len() >= 32 {
            break;
        }
        let surface_id = authored_surface_string(surface, "surface_id");
        if seen_surface_ids.insert(surface_id) {
            selected.push(surface.clone());
        }
    }
    selected
}

fn authored_sprite_sheet_frame(index: usize, surface: &Value) -> Value {
    let cell_size = 32_u64;
    let columns = 8_u64;
    let x = (index as u64 % columns) * cell_size;
    let y = (index as u64 / columns) * cell_size;
    json!({
        "frame_index": index,
        "frame_id": format!("frame_{index:02}"),
        "surface_id": authored_surface_string(surface, "surface_id"),
        "asset_pack_id": authored_surface_string(surface, "asset_pack_id"),
        "asset_id": authored_surface_string(surface, "asset_id"),
        "asset_kind": authored_surface_string(surface, "asset_kind"),
        "gameplay_layer": authored_surface_string(surface, "gameplay_layer"),
        "replacement_slot": authored_surface_string(surface, "replacement_slot"),
        "source_origin": authored_surface_string(surface, "source_origin"),
        "license_scope": authored_surface_string(surface, "license_scope"),
        "x": x,
        "y": y,
        "w": cell_size,
        "h": cell_size,
    })
}

fn authored_sprite_sheet_rgb(asset_kind: &str, gameplay_layer: &str) -> (u8, u8, u8) {
    match (asset_kind, gameplay_layer) {
        ("terrain_tile", _) => (91, 132, 82),
        ("road_tile", _) => (164, 151, 118),
        ("building_tile", _) => (166, 103, 74),
        ("foliage_sprite", _) => (68, 157, 70),
        ("water_tile", _) => (62, 133, 171),
        ("hud_icon", _) => (214, 66, 52),
        ("hud_glyph", _) => (244, 209, 79),
        ("actor_sprite", _) => (92, 146, 232),
        ("feedback_glyph", _) => (236, 83, 72),
        _ => (112, 122, 132),
    }
}

fn write_authored_sprite_sheet_ppm(atlas_path: &str, frames: &[Value]) -> Result<u64, String> {
    let columns = 8_usize;
    let cell_size = 32_usize;
    let rows = frames.len().div_ceil(columns).max(1);
    let width = columns * cell_size;
    let height = rows * cell_size;
    let mut ppm = format!("P3\n{width} {height}\n255\n");
    for y in 0..height {
        for x in 0..width {
            let frame_index = (y / cell_size) * columns + (x / cell_size);
            let local_x = x % cell_size;
            let local_y = y % cell_size;
            let (r, g, b) = if let Some(frame) = frames.get(frame_index) {
                let asset_kind = frame
                    .get("asset_kind")
                    .and_then(Value::as_str)
                    .unwrap_or("unknown");
                let gameplay_layer = frame
                    .get("gameplay_layer")
                    .and_then(Value::as_str)
                    .unwrap_or("unknown");
                let (base_r, base_g, base_b) =
                    authored_sprite_sheet_rgb(asset_kind, gameplay_layer);
                if local_x == 0
                    || local_y == 0
                    || local_x == cell_size - 1
                    || local_y == cell_size - 1
                {
                    (236, 220, 124)
                } else if local_x == local_y || local_x + local_y == cell_size - 1 {
                    (
                        base_r.saturating_add(28),
                        base_g.saturating_add(28),
                        base_b.saturating_add(28),
                    )
                } else {
                    (base_r, base_g, base_b)
                }
            } else {
                (16, 22, 24)
            };
            ppm.push_str(&format!("{r} {g} {b} "));
        }
        ppm.push('\n');
    }
    if let Some(parent) = Path::new(atlas_path).parent() {
        fs::create_dir_all(parent).map_err(|err| err.to_string())?;
    }
    fs::write(atlas_path, ppm.as_bytes()).map_err(|err| err.to_string())?;
    fs::metadata(atlas_path)
        .map(|metadata| metadata.len())
        .map_err(|err| err.to_string())
}

fn authored_frame_set(frames: &[Value], key: &str) -> HashSet<String> {
    frames
        .iter()
        .filter_map(|frame| frame.get(key).and_then(Value::as_str).map(str::to_string))
        .collect()
}

pub fn native_authored_sprite_sheet_artifact_evidence_json(
    actor_id: &str,
    atlas_path: &str,
    manifest_path: &str,
) -> String {
    let surfaces = authored_art_asset_surfaces_from_runtime(actor_id);
    let selected_surfaces = authored_sprite_sheet_selected_surfaces(&surfaces);
    let frames = selected_surfaces
        .iter()
        .enumerate()
        .map(|(index, surface)| authored_sprite_sheet_frame(index, surface))
        .collect::<Vec<_>>();
    let frame_asset_kinds = authored_frame_set(&frames, "asset_kind");
    let frame_gameplay_layers = authored_frame_set(&frames, "gameplay_layer");
    let frame_replacement_slots = authored_frame_set(&frames, "replacement_slot");
    let frame_source_origins = authored_frame_set(&frames, "source_origin");
    let frame_license_scopes = authored_frame_set(&frames, "license_scope");
    let atlas_bytes = write_authored_sprite_sheet_ppm(atlas_path, &frames).unwrap_or_default();
    let atlas_exists = Path::new(atlas_path).exists();
    let manifest = json!({
        "contract_version": TRILLIONNIUM_WORLD_BEVY_AUTHORED_SPRITE_SHEET_ARTIFACT_CONTRACT,
        "actor_id": actor_id,
        "atlas_path": atlas_path,
        "atlas_format": "ppm_p3_rgb",
        "atlas_columns": 8,
        "cell_size_px": 32,
        "frame_count": frames.len(),
        "frames": frames,
        "source_surface_count": surfaces.len(),
        "asset_boundary": "generated_project_owned_local_ppm_atlas_not_final_external_bitmap_art",
        "android_s5_real_device_claimed": false,
    });
    if let Some(parent) = Path::new(manifest_path).parent() {
        fs::create_dir_all(parent).expect("authored sprite sheet manifest parent is writable");
    }
    fs::write(
        manifest_path,
        serde_json::to_string_pretty(&manifest).expect("sprite sheet manifest serializes"),
    )
    .expect("authored sprite sheet manifest writes to disk");
    let manifest_bytes = fs::metadata(manifest_path)
        .map(|metadata| metadata.len())
        .unwrap_or_default();
    let manifest_parse_gate = fs::read_to_string(manifest_path)
        .ok()
        .and_then(|text| serde_json::from_str::<Value>(&text).ok())
        .and_then(|value| {
            value
                .get("contract_version")
                .and_then(Value::as_str)
                .map(|contract| {
                    contract == TRILLIONNIUM_WORLD_BEVY_AUTHORED_SPRITE_SHEET_ARTIFACT_CONTRACT
                })
        })
        == Some(true);
    let frame_count_gate = frames.len() >= 32;
    let frame_asset_kind_gate = [
        "terrain_tile",
        "road_tile",
        "building_tile",
        "foliage_sprite",
        "water_tile",
        "hud_icon",
        "hud_glyph",
        "actor_sprite",
        "feedback_glyph",
    ]
    .iter()
    .all(|kind| frame_asset_kinds.contains(*kind));
    let frame_layer_gate = [
        "terrain", "road", "building", "greenery", "water", "hud", "actor", "feedback",
    ]
    .iter()
    .all(|layer| frame_gameplay_layers.contains(*layer));
    let frame_slot_gate = [
        "tile_sprite_slot",
        "hud_icon_slot",
        "hud_glyph_slot",
        "actor_sprite_slot",
        "actor_shadow_slot",
        "actor_badge_slot",
        "feedback_glyph_slot",
    ]
    .iter()
    .all(|slot| frame_replacement_slots.contains(*slot));
    let source_boundary_gate = frame_source_origins
        .contains("local_authored_primitive_manifest_v1")
        && frame_license_scopes.contains("project_owned_internal_placeholder");
    let atlas_write_gate = atlas_exists && atlas_bytes > 50_000;
    let manifest_write_gate = manifest_bytes > 2_048 && manifest_parse_gate;
    let green = surfaces.len() >= 120
        && frame_count_gate
        && frame_asset_kind_gate
        && frame_layer_gate
        && frame_slot_gate
        && source_boundary_gate
        && atlas_write_gate
        && manifest_write_gate;
    let evidence = json!({
        "contract_version": TRILLIONNIUM_WORLD_BEVY_AUTHORED_SPRITE_SHEET_ARTIFACT_CONTRACT,
        "actor_id": actor_id,
        "green": green,
        "authored_art_pack_contract": TRILLIONNIUM_WORLD_BEVY_AUTHORED_ART_PACK_CONTRACT,
        "atlas_path": atlas_path,
        "manifest_path": manifest_path,
        "atlas_format": "ppm_p3_rgb",
        "atlas_bytes": atlas_bytes,
        "manifest_bytes": manifest_bytes,
        "source_surface_count": surfaces.len(),
        "frame_count": frames.len(),
        "frame_asset_kinds": frame_asset_kinds.iter().cloned().collect::<Vec<_>>(),
        "frame_gameplay_layers": frame_gameplay_layers.iter().cloned().collect::<Vec<_>>(),
        "frame_replacement_slots": frame_replacement_slots.iter().cloned().collect::<Vec<_>>(),
        "frame_source_origins": frame_source_origins.iter().cloned().collect::<Vec<_>>(),
        "frame_license_scopes": frame_license_scopes.iter().cloned().collect::<Vec<_>>(),
        "frame_count_gate": frame_count_gate,
        "frame_asset_kind_gate": frame_asset_kind_gate,
        "frame_layer_gate": frame_layer_gate,
        "frame_slot_gate": frame_slot_gate,
        "source_boundary_gate": source_boundary_gate,
        "atlas_write_gate": atlas_write_gate,
        "manifest_write_gate": manifest_write_gate,
        "manifest_parse_gate": manifest_parse_gate,
        "asset_boundary": "generated_project_owned_local_ppm_atlas_not_final_external_bitmap_art",
        "source_of_truth": "The Bevy runtime writes a local PPM sprite-sheet atlas and a JSON frame manifest from authored art asset surfaces sampled from real runtime entities.",
        "android_s5_real_device_claimed": false,
    });
    serde_json::to_string_pretty(&evidence)
        .expect("authored sprite sheet artifact evidence serializes")
}

fn authored_binding_runtime_target(replacement_slot: &str) -> &'static str {
    match replacement_slot {
        "tile_sprite_slot" => "map_tile_renderer",
        "hud_icon_slot" | "hud_glyph_slot" => "hud_renderer",
        "actor_sprite_slot" | "actor_shadow_slot" | "actor_badge_slot" => "actor_renderer",
        "feedback_glyph_slot" => "feedback_renderer",
        _ => "generic_sprite_renderer",
    }
}

fn authored_binding_material_slot(replacement_slot: &str) -> &'static str {
    match replacement_slot {
        "tile_sprite_slot" => "world_tile_material",
        "hud_icon_slot" | "hud_glyph_slot" => "hud_icon_material",
        "actor_sprite_slot" | "actor_shadow_slot" | "actor_badge_slot" => "actor_sprite_material",
        "feedback_glyph_slot" => "feedback_glyph_material",
        _ => "generic_sprite_material",
    }
}

fn authored_texture_binding_frame(
    frame: &Value,
    atlas_path: &str,
    atlas_width: f64,
    atlas_height: f64,
) -> Value {
    let x = frame.get("x").and_then(Value::as_f64).unwrap_or_default();
    let y = frame.get("y").and_then(Value::as_f64).unwrap_or_default();
    let w = frame.get("w").and_then(Value::as_f64).unwrap_or(32.0);
    let h = frame.get("h").and_then(Value::as_f64).unwrap_or(32.0);
    let replacement_slot = frame
        .get("replacement_slot")
        .and_then(Value::as_str)
        .unwrap_or("unknown");
    let runtime_target = authored_binding_runtime_target(replacement_slot);
    let material_slot = authored_binding_material_slot(replacement_slot);
    let frame_index = frame
        .get("frame_index")
        .and_then(Value::as_u64)
        .unwrap_or_default();
    json!({
        "binding_id": format!("binding_{frame_index:02}"),
        "texture_handle_id": "runtime_texture_handle::trnm_world_authored_sprite_sheet_v1",
        "texture_source_path": atlas_path,
        "frame_id": sample_pointer_value(frame, "/frame_id"),
        "frame_index": frame_index,
        "surface_id": sample_pointer_value(frame, "/surface_id"),
        "asset_id": sample_pointer_value(frame, "/asset_id"),
        "asset_kind": sample_pointer_value(frame, "/asset_kind"),
        "gameplay_layer": sample_pointer_value(frame, "/gameplay_layer"),
        "replacement_slot": replacement_slot,
        "runtime_target": runtime_target,
        "material_slot": material_slot,
        "sampler": "nearest_pixel_art",
        "alpha_mode": "premultiplied_ui_safe",
        "source_origin": sample_pointer_value(frame, "/source_origin"),
        "license_scope": sample_pointer_value(frame, "/license_scope"),
        "uv_rect": {
            "u0": x / atlas_width,
            "v0": y / atlas_height,
            "u1": (x + w) / atlas_width,
            "v1": (y + h) / atlas_height,
        }
    })
}

fn authored_binding_set(bindings: &[Value], key: &str) -> HashSet<String> {
    bindings
        .iter()
        .filter_map(|binding| binding.get(key).and_then(Value::as_str).map(str::to_string))
        .collect()
}

pub fn native_authored_texture_atlas_binding_evidence_json(
    actor_id: &str,
    atlas_path: &str,
    manifest_path: &str,
    binding_path: &str,
) -> String {
    let sprite_sheet_evidence: Value = serde_json::from_str(
        &native_authored_sprite_sheet_artifact_evidence_json(actor_id, atlas_path, manifest_path),
    )
    .expect("sprite sheet artifact evidence parses for texture atlas binding");
    let manifest_text = fs::read_to_string(manifest_path).unwrap_or_default();
    let manifest: Value = serde_json::from_str(&manifest_text).unwrap_or_else(|_| json!({}));
    let frames = manifest
        .get("frames")
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default();
    let atlas_columns = manifest
        .get("atlas_columns")
        .and_then(Value::as_u64)
        .unwrap_or(8);
    let cell_size = manifest
        .get("cell_size_px")
        .and_then(Value::as_u64)
        .unwrap_or(32);
    let atlas_width = (atlas_columns * cell_size) as f64;
    let atlas_rows = (frames.len() as u64).div_ceil(atlas_columns).max(1);
    let atlas_height = (atlas_rows * cell_size) as f64;
    let bindings = frames
        .iter()
        .map(|frame| authored_texture_binding_frame(frame, atlas_path, atlas_width, atlas_height))
        .collect::<Vec<_>>();
    let runtime_targets = authored_binding_set(&bindings, "runtime_target");
    let material_slots = authored_binding_set(&bindings, "material_slot");
    let replacement_slots = authored_binding_set(&bindings, "replacement_slot");
    let source_origins = authored_binding_set(&bindings, "source_origin");
    let license_scopes = authored_binding_set(&bindings, "license_scope");
    let sampler_modes = authored_binding_set(&bindings, "sampler");
    let uv_rect_gate = bindings.iter().all(|binding| {
        let Some(rect) = binding.get("uv_rect") else {
            return false;
        };
        let u0 = rect.get("u0").and_then(Value::as_f64).unwrap_or(-1.0);
        let v0 = rect.get("v0").and_then(Value::as_f64).unwrap_or(-1.0);
        let u1 = rect.get("u1").and_then(Value::as_f64).unwrap_or(2.0);
        let v1 = rect.get("v1").and_then(Value::as_f64).unwrap_or(2.0);
        u0 >= 0.0 && v0 >= 0.0 && u1 <= 1.0 && v1 <= 1.0 && u0 < u1 && v0 < v1
    });
    let atlas_source_gate = Path::new(atlas_path).exists()
        && fs::metadata(atlas_path)
            .map(|metadata| metadata.len() > 50_000)
            .unwrap_or(false);
    let binding_manifest = json!({
        "contract_version": TRILLIONNIUM_WORLD_BEVY_AUTHORED_TEXTURE_ATLAS_BINDING_CONTRACT,
        "actor_id": actor_id,
        "atlas_path": atlas_path,
        "source_manifest_path": manifest_path,
        "atlas_format": "ppm_p3_rgb",
        "texture_handle_id": "runtime_texture_handle::trnm_world_authored_sprite_sheet_v1",
        "binding_count": bindings.len(),
        "bindings": bindings,
        "asset_boundary": "runtime_texture_atlas_binding_for_generated_local_ppm_not_final_external_art",
        "android_s5_real_device_claimed": false,
    });
    if let Some(parent) = Path::new(binding_path).parent() {
        fs::create_dir_all(parent).expect("texture atlas binding parent is writable");
    }
    fs::write(
        binding_path,
        serde_json::to_string_pretty(&binding_manifest)
            .expect("texture atlas binding manifest serializes"),
    )
    .expect("texture atlas binding manifest writes to disk");
    let binding_bytes = fs::metadata(binding_path)
        .map(|metadata| metadata.len())
        .unwrap_or_default();
    let binding_parse_gate = fs::read_to_string(binding_path)
        .ok()
        .and_then(|text| serde_json::from_str::<Value>(&text).ok())
        .and_then(|value| {
            value
                .get("contract_version")
                .and_then(Value::as_str)
                .map(|contract| {
                    contract == TRILLIONNIUM_WORLD_BEVY_AUTHORED_TEXTURE_ATLAS_BINDING_CONTRACT
                })
        })
        == Some(true);
    let binding_count_gate = bindings.len() >= 32 && bindings.len() == frames.len();
    let runtime_target_gate = [
        "map_tile_renderer",
        "hud_renderer",
        "actor_renderer",
        "feedback_renderer",
    ]
    .iter()
    .all(|target| runtime_targets.contains(*target));
    let material_slot_gate = [
        "world_tile_material",
        "hud_icon_material",
        "actor_sprite_material",
        "feedback_glyph_material",
    ]
    .iter()
    .all(|slot| material_slots.contains(*slot));
    let replacement_slot_gate = [
        "tile_sprite_slot",
        "hud_icon_slot",
        "hud_glyph_slot",
        "actor_sprite_slot",
        "actor_shadow_slot",
        "actor_badge_slot",
        "feedback_glyph_slot",
    ]
    .iter()
    .all(|slot| replacement_slots.contains(*slot));
    let source_boundary_gate = source_origins.contains("local_authored_primitive_manifest_v1")
        && license_scopes.contains("project_owned_internal_placeholder")
        && sampler_modes.contains("nearest_pixel_art");
    let binding_write_gate = binding_bytes > 8_192 && binding_parse_gate;
    let green = sprite_sheet_evidence.get("green").and_then(Value::as_bool) == Some(true)
        && atlas_source_gate
        && binding_count_gate
        && uv_rect_gate
        && runtime_target_gate
        && material_slot_gate
        && replacement_slot_gate
        && source_boundary_gate
        && binding_write_gate;
    let evidence = json!({
        "contract_version": TRILLIONNIUM_WORLD_BEVY_AUTHORED_TEXTURE_ATLAS_BINDING_CONTRACT,
        "actor_id": actor_id,
        "green": green,
        "authored_sprite_sheet_contract": TRILLIONNIUM_WORLD_BEVY_AUTHORED_SPRITE_SHEET_ARTIFACT_CONTRACT,
        "atlas_path": atlas_path,
        "manifest_path": manifest_path,
        "binding_path": binding_path,
        "atlas_format": "ppm_p3_rgb",
        "texture_handle_id": "runtime_texture_handle::trnm_world_authored_sprite_sheet_v1",
        "atlas_bytes": sample_pointer_value(&sprite_sheet_evidence, "/atlas_bytes"),
        "manifest_bytes": sample_pointer_value(&sprite_sheet_evidence, "/manifest_bytes"),
        "binding_bytes": binding_bytes,
        "binding_count": bindings.len(),
        "runtime_targets": runtime_targets.iter().cloned().collect::<Vec<_>>(),
        "material_slots": material_slots.iter().cloned().collect::<Vec<_>>(),
        "replacement_slots": replacement_slots.iter().cloned().collect::<Vec<_>>(),
        "source_origins": source_origins.iter().cloned().collect::<Vec<_>>(),
        "license_scopes": license_scopes.iter().cloned().collect::<Vec<_>>(),
        "sampler_modes": sampler_modes.iter().cloned().collect::<Vec<_>>(),
        "atlas_source_gate": atlas_source_gate,
        "binding_count_gate": binding_count_gate,
        "uv_rect_gate": uv_rect_gate,
        "runtime_target_gate": runtime_target_gate,
        "material_slot_gate": material_slot_gate,
        "replacement_slot_gate": replacement_slot_gate,
        "source_boundary_gate": source_boundary_gate,
        "binding_write_gate": binding_write_gate,
        "binding_parse_gate": binding_parse_gate,
        "sprite_sheet_summary": {
            "green": sample_pointer_value(&sprite_sheet_evidence, "/green"),
            "atlas_bytes": sample_pointer_value(&sprite_sheet_evidence, "/atlas_bytes"),
            "manifest_bytes": sample_pointer_value(&sprite_sheet_evidence, "/manifest_bytes"),
            "frame_count": sample_pointer_value(&sprite_sheet_evidence, "/frame_count"),
        },
        "asset_boundary": "runtime_texture_atlas_binding_for_generated_local_ppm_not_final_external_art",
        "source_of_truth": "The runtime binding evidence reads the generated local atlas manifest, computes frame UV rects, and writes a texture/material binding manifest for map, HUD, actor, and feedback render targets.",
        "android_s5_real_device_claimed": false,
    });
    serde_json::to_string_pretty(&evidence)
        .expect("authored texture atlas binding evidence serializes")
}

fn authored_consumption_scene_layer(runtime_target: &str) -> &'static str {
    match runtime_target {
        "map_tile_renderer" => "map",
        "hud_renderer" => "hud",
        "actor_renderer" => "actor",
        "feedback_renderer" => "feedback",
        _ => "generic",
    }
}

fn authored_consumption_component(runtime_target: &str) -> &'static str {
    match runtime_target {
        "map_tile_renderer" => "Sprite+BevyWorldTileRpgSurface+BevyWorldAuthoredArtAssetSurface",
        "hud_renderer" => "Text2d/Sprite+BevyWorldAuthoredArtAssetSurface",
        "actor_renderer" => "Sprite+BevyWorldVisibleActorRuntime+BevyWorldAuthoredArtAssetSurface",
        "feedback_renderer" => "Sprite/Text2d+BevyWorldAuthoredArtAssetSurface",
        _ => "Sprite+BevyWorldAuthoredArtAssetSurface",
    }
}

fn authored_material_consumption_record(
    binding: &Value,
    scene_surface_lookup: &HashMap<String, Value>,
) -> Value {
    let binding_id = authored_surface_string(binding, "binding_id");
    let surface_id = authored_surface_string(binding, "surface_id");
    let runtime_target = authored_surface_string(binding, "runtime_target");
    let material_slot = authored_surface_string(binding, "material_slot");
    let replacement_slot = authored_surface_string(binding, "replacement_slot");
    let scene_surface = scene_surface_lookup.get(surface_id.as_str());
    let scene_layer = authored_consumption_scene_layer(&runtime_target);
    json!({
        "consumption_id": format!("consumes::{binding_id}"),
        "binding_id": binding_id,
        "frame_id": sample_pointer_value(binding, "/frame_id"),
        "frame_index": sample_pointer_value(binding, "/frame_index"),
        "texture_handle_id": sample_pointer_value(binding, "/texture_handle_id"),
        "texture_source_path": sample_pointer_value(binding, "/texture_source_path"),
        "visible_runtime_surface_id": surface_id,
        "scene_surface_match": scene_surface.is_some(),
        "scene_asset_id": scene_surface
            .map(|surface| authored_surface_string(surface, "asset_id"))
            .unwrap_or_else(|| "missing_scene_surface".to_string()),
        "scene_asset_kind": scene_surface
            .map(|surface| authored_surface_string(surface, "asset_kind"))
            .unwrap_or_else(|| authored_surface_string(binding, "asset_kind")),
        "scene_gameplay_layer": scene_surface
            .map(|surface| authored_surface_string(surface, "gameplay_layer"))
            .unwrap_or_else(|| authored_surface_string(binding, "gameplay_layer")),
        "scene_layer": scene_layer,
        "runtime_target": runtime_target,
        "material_slot": material_slot,
        "replacement_slot": replacement_slot,
        "bevy_consumer_component": authored_consumption_component(&runtime_target),
        "material_consumption_mode": "runtime_texture_handle_material_slot_uv_rect",
        "sampler": sample_pointer_value(binding, "/sampler"),
        "alpha_mode": sample_pointer_value(binding, "/alpha_mode"),
        "uv_rect": sample_pointer_value(binding, "/uv_rect"),
        "source_origin": sample_pointer_value(binding, "/source_origin"),
        "license_scope": sample_pointer_value(binding, "/license_scope"),
        "generated_atlas_consumed": true,
        "asset_boundary": "scene_material_consumes_generated_local_atlas_binding_not_final_external_art",
    })
}

pub fn native_authored_material_consumption_evidence_json(
    actor_id: &str,
    atlas_path: &str,
    manifest_path: &str,
    binding_path: &str,
    consumption_path: &str,
) -> String {
    let texture_binding_evidence: Value =
        serde_json::from_str(&native_authored_texture_atlas_binding_evidence_json(
            actor_id,
            atlas_path,
            manifest_path,
            binding_path,
        ))
        .expect("texture atlas binding evidence parses for material consumption");
    let binding_text = fs::read_to_string(binding_path).unwrap_or_default();
    let binding_manifest: Value = serde_json::from_str(&binding_text).unwrap_or_else(|_| json!({}));
    let bindings = binding_manifest
        .get("bindings")
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default();
    let scene_surfaces = authored_art_asset_surfaces_from_runtime(actor_id);
    let scene_surface_lookup = scene_surfaces
        .iter()
        .filter_map(|surface| {
            surface
                .get("surface_id")
                .and_then(Value::as_str)
                .map(|surface_id| (surface_id.to_string(), surface.clone()))
        })
        .collect::<HashMap<_, _>>();
    let consumptions = bindings
        .iter()
        .map(|binding| authored_material_consumption_record(binding, &scene_surface_lookup))
        .collect::<Vec<_>>();
    let runtime_targets = authored_binding_set(&consumptions, "runtime_target");
    let material_slots = authored_binding_set(&consumptions, "material_slot");
    let replacement_slots = authored_binding_set(&consumptions, "replacement_slot");
    let scene_layers = authored_binding_set(&consumptions, "scene_layer");
    let consumer_components = authored_binding_set(&consumptions, "bevy_consumer_component");
    let consumption_modes = authored_binding_set(&consumptions, "material_consumption_mode");
    let source_origins = authored_binding_set(&consumptions, "source_origin");
    let license_scopes = authored_binding_set(&consumptions, "license_scope");
    let uv_rect_consumption_gate = consumptions.iter().all(|consumption| {
        let Some(rect) = consumption.get("uv_rect") else {
            return false;
        };
        let u0 = rect.get("u0").and_then(Value::as_f64).unwrap_or(-1.0);
        let v0 = rect.get("v0").and_then(Value::as_f64).unwrap_or(-1.0);
        let u1 = rect.get("u1").and_then(Value::as_f64).unwrap_or(2.0);
        let v1 = rect.get("v1").and_then(Value::as_f64).unwrap_or(2.0);
        u0 >= 0.0 && v0 >= 0.0 && u1 <= 1.0 && v1 <= 1.0 && u0 < u1 && v0 < v1
    });
    let material_consumption_count_gate = consumptions.len() >= 32
        && consumptions.len() == bindings.len()
        && consumptions.len() <= scene_surfaces.len();
    let scene_surface_match_gate = consumptions.iter().all(|consumption| {
        consumption
            .get("scene_surface_match")
            .and_then(Value::as_bool)
            == Some(true)
    });
    let runtime_target_consumption_gate = [
        "map_tile_renderer",
        "hud_renderer",
        "actor_renderer",
        "feedback_renderer",
    ]
    .iter()
    .all(|target| runtime_targets.contains(*target));
    let material_slot_consumption_gate = [
        "world_tile_material",
        "hud_icon_material",
        "actor_sprite_material",
        "feedback_glyph_material",
    ]
    .iter()
    .all(|slot| material_slots.contains(*slot));
    let scene_layer_consumption_gate = ["map", "hud", "actor", "feedback"]
        .iter()
        .all(|layer| scene_layers.contains(*layer));
    let consumer_component_gate = [
        "Sprite+BevyWorldTileRpgSurface+BevyWorldAuthoredArtAssetSurface",
        "Text2d/Sprite+BevyWorldAuthoredArtAssetSurface",
        "Sprite+BevyWorldVisibleActorRuntime+BevyWorldAuthoredArtAssetSurface",
        "Sprite/Text2d+BevyWorldAuthoredArtAssetSurface",
    ]
    .iter()
    .all(|component| consumer_components.contains(*component));
    let replacement_slot_consumption_gate = [
        "tile_sprite_slot",
        "hud_icon_slot",
        "hud_glyph_slot",
        "actor_sprite_slot",
        "actor_shadow_slot",
        "actor_badge_slot",
        "feedback_glyph_slot",
    ]
    .iter()
    .all(|slot| replacement_slots.contains(*slot));
    let source_boundary_gate = source_origins.contains("local_authored_primitive_manifest_v1")
        && license_scopes.contains("project_owned_internal_placeholder")
        && consumption_modes.contains("runtime_texture_handle_material_slot_uv_rect");
    let consumption_manifest = json!({
        "contract_version": TRILLIONNIUM_WORLD_BEVY_AUTHORED_MATERIAL_CONSUMPTION_CONTRACT,
        "actor_id": actor_id,
        "authored_texture_atlas_binding_contract": TRILLIONNIUM_WORLD_BEVY_AUTHORED_TEXTURE_ATLAS_BINDING_CONTRACT,
        "atlas_path": atlas_path,
        "binding_path": binding_path,
        "texture_handle_id": "runtime_texture_handle::trnm_world_authored_sprite_sheet_v1",
        "consumption_count": consumptions.len(),
        "consumptions": consumptions,
        "asset_boundary": "scene_material_consumes_generated_local_atlas_binding_not_final_external_art",
        "android_s5_real_device_claimed": false,
    });
    if let Some(parent) = Path::new(consumption_path).parent() {
        fs::create_dir_all(parent).expect("authored material consumption parent is writable");
    }
    fs::write(
        consumption_path,
        serde_json::to_string_pretty(&consumption_manifest)
            .expect("authored material consumption manifest serializes"),
    )
    .expect("authored material consumption manifest writes to disk");
    let consumption_bytes = fs::metadata(consumption_path)
        .map(|metadata| metadata.len())
        .unwrap_or_default();
    let consumption_parse_gate = fs::read_to_string(consumption_path)
        .ok()
        .and_then(|text| serde_json::from_str::<Value>(&text).ok())
        .and_then(|value| {
            value
                .get("contract_version")
                .and_then(Value::as_str)
                .map(|contract| {
                    contract == TRILLIONNIUM_WORLD_BEVY_AUTHORED_MATERIAL_CONSUMPTION_CONTRACT
                })
        })
        == Some(true);
    let consumption_write_gate = consumption_bytes > 8_192 && consumption_parse_gate;
    let green = texture_binding_evidence
        .get("green")
        .and_then(Value::as_bool)
        == Some(true)
        && material_consumption_count_gate
        && scene_surface_match_gate
        && runtime_target_consumption_gate
        && material_slot_consumption_gate
        && replacement_slot_consumption_gate
        && scene_layer_consumption_gate
        && consumer_component_gate
        && uv_rect_consumption_gate
        && source_boundary_gate
        && consumption_write_gate;
    let evidence = json!({
        "contract_version": TRILLIONNIUM_WORLD_BEVY_AUTHORED_MATERIAL_CONSUMPTION_CONTRACT,
        "actor_id": actor_id,
        "green": green,
        "authored_texture_atlas_binding_contract": TRILLIONNIUM_WORLD_BEVY_AUTHORED_TEXTURE_ATLAS_BINDING_CONTRACT,
        "atlas_path": atlas_path,
        "manifest_path": manifest_path,
        "binding_path": binding_path,
        "consumption_path": consumption_path,
        "texture_handle_id": "runtime_texture_handle::trnm_world_authored_sprite_sheet_v1",
        "atlas_bytes": sample_pointer_value(&texture_binding_evidence, "/atlas_bytes"),
        "binding_bytes": sample_pointer_value(&texture_binding_evidence, "/binding_bytes"),
        "consumption_bytes": consumption_bytes,
        "scene_surface_count": scene_surfaces.len(),
        "consumption_count": consumptions.len(),
        "runtime_targets": runtime_targets.iter().cloned().collect::<Vec<_>>(),
        "material_slots": material_slots.iter().cloned().collect::<Vec<_>>(),
        "replacement_slots": replacement_slots.iter().cloned().collect::<Vec<_>>(),
        "scene_layers": scene_layers.iter().cloned().collect::<Vec<_>>(),
        "consumer_components": consumer_components.iter().cloned().collect::<Vec<_>>(),
        "consumption_modes": consumption_modes.iter().cloned().collect::<Vec<_>>(),
        "source_origins": source_origins.iter().cloned().collect::<Vec<_>>(),
        "license_scopes": license_scopes.iter().cloned().collect::<Vec<_>>(),
        "material_consumption_count_gate": material_consumption_count_gate,
        "scene_surface_match_gate": scene_surface_match_gate,
        "runtime_target_consumption_gate": runtime_target_consumption_gate,
        "material_slot_consumption_gate": material_slot_consumption_gate,
        "replacement_slot_consumption_gate": replacement_slot_consumption_gate,
        "scene_layer_consumption_gate": scene_layer_consumption_gate,
        "consumer_component_gate": consumer_component_gate,
        "uv_rect_consumption_gate": uv_rect_consumption_gate,
        "source_boundary_gate": source_boundary_gate,
        "consumption_write_gate": consumption_write_gate,
        "consumption_parse_gate": consumption_parse_gate,
        "texture_binding_summary": {
            "green": sample_pointer_value(&texture_binding_evidence, "/green"),
            "binding_count": sample_pointer_value(&texture_binding_evidence, "/binding_count"),
            "runtime_target_gate": sample_pointer_value(&texture_binding_evidence, "/runtime_target_gate"),
            "material_slot_gate": sample_pointer_value(&texture_binding_evidence, "/material_slot_gate"),
        },
        "asset_boundary": "scene_material_consumes_generated_local_atlas_binding_not_final_external_art",
        "source_of_truth": "The native Bevy scene samples runtime authored-art surfaces, reads the generated atlas binding manifest, and writes a material-consumption manifest that maps visible map, HUD, actor, and feedback surfaces to texture handle, material slot, and UV rect.",
        "android_s5_real_device_claimed": false,
    });
    serde_json::to_string_pretty(&evidence)
        .expect("authored material consumption evidence serializes")
}

fn authored_application_render_pipeline(scene_layer: &str) -> &'static str {
    match scene_layer {
        "hud" => "bevy_text2d_sprite_icon_material_pipeline",
        "map" | "actor" | "feedback" => "bevy_sprite_2d_material_pipeline",
        _ => "bevy_sprite_2d_fallback_material_pipeline",
    }
}

fn authored_application_render_order(scene_layer: &str) -> i32 {
    match scene_layer {
        "map" => 40,
        "actor" => 50,
        "feedback" => 60,
        "hud" => 70,
        _ => 10,
    }
}

fn authored_material_application_record(consumption: &Value) -> Value {
    let consumption_id = authored_surface_string(consumption, "consumption_id");
    let scene_layer = authored_surface_string(consumption, "scene_layer");
    let material_slot = authored_surface_string(consumption, "material_slot");
    json!({
        "application_id": format!("applies::{consumption_id}"),
        "consumption_id": consumption_id,
        "binding_id": sample_pointer_value(consumption, "/binding_id"),
        "frame_id": sample_pointer_value(consumption, "/frame_id"),
        "frame_index": sample_pointer_value(consumption, "/frame_index"),
        "texture_handle_id": sample_pointer_value(consumption, "/texture_handle_id"),
        "visible_runtime_surface_id": sample_pointer_value(consumption, "/visible_runtime_surface_id"),
        "scene_layer": scene_layer,
        "runtime_target": sample_pointer_value(consumption, "/runtime_target"),
        "material_slot": material_slot,
        "uv_rect": sample_pointer_value(consumption, "/uv_rect"),
        "sampler": sample_pointer_value(consumption, "/sampler"),
        "alpha_mode": sample_pointer_value(consumption, "/alpha_mode"),
        "bevy_consumer_component": sample_pointer_value(consumption, "/bevy_consumer_component"),
        "render_pipeline": authored_application_render_pipeline(&scene_layer),
        "render_layer_order": authored_application_render_order(&scene_layer),
        "material_instance_id": format!("material_instance::{scene_layer}::{material_slot}"),
        "material_application_mode": "apply_texture_handle_material_slot_uv_rect_to_visible_scene_surface",
        "replacement_policy": "replace_placeholder_sprite_color_with_authored_texture_region",
        "fallback_policy": "generated_palette_fallback_if_texture_missing",
        "host_side_runtime_application_claimed": true,
        "gpu_upload_claimed": false,
        "android_s5_real_device_claimed": false,
        "source_origin": sample_pointer_value(consumption, "/source_origin"),
        "license_scope": sample_pointer_value(consumption, "/license_scope"),
        "asset_boundary": "host_side_material_application_plan_for_generated_local_atlas_not_gpu_or_device_claim",
    })
}

