    let retained_history_group_ids = string_vec(["26", "27", "28"]);
    let pruned_history_group_ids = string_vec(["25", "24"]);
    let group_26_member_ids =
        string_vec(["multi0.recall.order.runner", "multi0.recall.order.wing"]);
