pub fn native_input_affordance_feedback_evidence_json(actor_id: &str) -> String {
    for slot_id in native_session_slot_ids() {
        let _ = fs::remove_file(native_action_session_slot_path(slot_id));
    }
    let mut app = build_keyboard_runtime_app(native_bevy_playable_fixture(), actor_id);
    seed_rendering_app_title_menu(&mut app);
    let initial_sample = sample_live_app_state(&mut app, "initial_title_affordance");
    let blocked_fight_event = press_live_button_action(&mut app, NativeControlAction::Fight);
    let after_blocked_fight_sample = sample_live_app_state(&mut app, "after_blocked_title_fight");
    let title_new_event = press_live_button_action(&mut app, NativeControlAction::NewGameFromTitle);
    let after_title_new_sample = sample_live_app_state(&mut app, "after_title_new_affordance");
    let blocked_talk_event = press_live_button_action(&mut app, NativeControlAction::Talk);
    let after_blocked_talk_sample = sample_live_app_state(&mut app, "after_blocked_create_talk");

    let initial_feedback_text = initial_sample
        .get("feedback_banner_text")
        .and_then(|value| value.as_str())
        .unwrap_or_default();
    let initial_input_hint_text = initial_sample
        .get("input_hint_text")
        .and_then(|value| value.as_str())
        .unwrap_or_default();
    let blocked_fight_feedback_text = after_blocked_fight_sample
        .get("feedback_banner_text")
        .and_then(|value| value.as_str())
        .unwrap_or_default();
    let title_new_feedback_text = after_title_new_sample
        .get("feedback_banner_text")
        .and_then(|value| value.as_str())
        .unwrap_or_default();
    let blocked_talk_feedback_text = after_blocked_talk_sample
        .get("feedback_banner_text")
        .and_then(|value| value.as_str())
        .unwrap_or_default();
    let title_new_state = contextual_button_state_value_from_sample(&initial_sample, "TITLE:NEW");
    let fight_state = contextual_button_state_value_from_sample(&initial_sample, "FIGHT");
    let create_confirm_state =
        contextual_button_state_value_from_sample(&after_title_new_sample, "CREATE:CONFIRM");
    let initial_ready_toast_gate = initial_feedback_text.contains("TOAST READY")
        && initial_feedback_text.contains("NEXT TITLE:NEW");
    let input_hud_gate = initial_input_hint_text.contains("INPUT HUD | NEXT TITLE:NEW")
        && initial_input_hint_text.contains("READY:")
        && initial_input_hint_text.contains("LOCKED:")
        && initial_input_hint_text.contains("GATES:");
    let next_button_affordance_gate = title_new_state
        .get("visual_state")
        .and_then(|value| value.as_str())
        == Some("onboarding_next_button")
        && title_new_state
            .get("enabled")
            .and_then(|value| value.as_bool())
            == Some(true)
        && contextual_button_text_from_sample(&initial_sample, "TITLE:NEW")
            .is_some_and(|text| text.starts_with(">> ") && text.contains("NEW"));
    let locked_button_affordance_gate =
        fight_state.get("enabled").and_then(|value| value.as_bool()) == Some(false)
            && contextual_button_text_from_sample(&initial_sample, "FIGHT").as_deref()
                == Some("x F FIGHT");
    let blocked_fight_toast_gate = blocked_fight_event
        .get("accepted")
        .and_then(|value| value.as_bool())
        == Some(false)
        && blocked_fight_feedback_text.contains("TOAST BLOCKED | FIGHT")
        && blocked_fight_feedback_text.contains("title_menu_choice_required")
        && blocked_fight_feedback_text.contains("NEXT TITLE:NEW")
        && after_blocked_fight_sample
            .get("input_hint_text")
            .and_then(|value| value.as_str())
            .is_some_and(|text| text.contains("INPUT HUD | NEXT TITLE:NEW"));
    let accepted_title_toast_gate = title_new_event
        .get("accepted")
        .and_then(|value| value.as_bool())
        == Some(true)
        && title_new_feedback_text.contains("TOAST OK | TITLE:NEW")
        && title_new_feedback_text.contains("enabled_title_new_game")
        && title_new_feedback_text.contains("NEXT CREATE:CONFIRM")
        && create_confirm_state
            .get("visual_state")
            .and_then(|value| value.as_str())
            == Some("onboarding_next_button");
    let blocked_create_toast_gate = blocked_talk_event
        .get("accepted")
        .and_then(|value| value.as_bool())
        == Some(false)
        && blocked_talk_feedback_text.contains("TOAST BLOCKED | TALK")
        && blocked_talk_feedback_text.contains("character_create_confirm_required")
        && blocked_talk_feedback_text.contains("NEXT CREATE:CONFIRM")
        && after_blocked_talk_sample
            .get("input_hint_text")
            .and_then(|value| value.as_str())
            .is_some_and(|text| text.contains("INPUT HUD | NEXT CREATE:CONFIRM"));
    let green = initial_ready_toast_gate
        && input_hud_gate
        && next_button_affordance_gate
        && locked_button_affordance_gate
        && blocked_fight_toast_gate
        && accepted_title_toast_gate
        && blocked_create_toast_gate;
    let evidence = json!({
        "contract_version": TRILLIONNIUM_WORLD_BEVY_INPUT_AFFORDANCE_FEEDBACK_CONTRACT,
        "runtime_probe_contract": TRILLIONNIUM_WORLD_BEVY_RUNTIME_PROBE_CONTRACT,
        "green": green,
        "source_of_truth": "visible Bevy input HUD, button labels, and feedback banner expose NEXT / READY / LOCKED / TOAST states from NativeFirstPlayableRuntime input feedback",
        "actor_id": actor_id,
        "initial_ready_toast_gate": initial_ready_toast_gate,
        "input_hud_gate": input_hud_gate,
        "next_button_affordance_gate": next_button_affordance_gate,
        "locked_button_affordance_gate": locked_button_affordance_gate,
        "blocked_fight_toast_gate": blocked_fight_toast_gate,
        "accepted_title_toast_gate": accepted_title_toast_gate,
        "blocked_create_toast_gate": blocked_create_toast_gate,
        "button_events": [
            blocked_fight_event,
            title_new_event,
            blocked_talk_event,
        ],
        "samples": [
            initial_sample,
            after_blocked_fight_sample,
            after_title_new_sample,
            after_blocked_talk_sample,
        ],
        "android_s5_real_device_claimed": false,
    });
    serde_json::to_string_pretty(&evidence).expect("input affordance feedback evidence serializes")
}

pub fn native_quest_journal_evidence_json(actor_id: &str) -> String {
    for slot_id in native_session_slot_ids() {
        let _ = fs::remove_file(native_action_session_slot_path(slot_id));
    }
    let mut app = build_keyboard_runtime_app(native_bevy_playable_fixture(), actor_id);
    seed_rendering_app_title_menu(&mut app);
    let mut button_events = Vec::new();
    let mut samples = vec![sample_live_app_state(&mut app, "initial_title_journal")];
    for action in [
        NativeControlAction::NewGameFromTitle,
        NativeControlAction::ConfirmCharacterCreate,
        NativeControlAction::Talk,
        NativeControlAction::Train,
        NativeControlAction::Move {
            direction: "north".to_string(),
        },
        NativeControlAction::Fight,
        NativeControlAction::CompleteTask,
        NativeControlAction::Equip,
    ] {
        let label = native_control_action_label(&action);
        button_events.push(press_live_button_action(&mut app, action));
        samples.push(sample_live_app_state(&mut app, &format!("after_{label}")));
    }
    let quest_texts = samples
        .iter()
        .map(|sample| {
            sample
                .get("quest_panel_text")
                .and_then(|value| value.as_str())
                .unwrap_or_default()
                .to_string()
        })
        .collect::<Vec<_>>();
    let event_acceptance_gate = button_events
        .iter()
        .all(|event| event.get("accepted").and_then(|value| value.as_bool()) == Some(true));
    let journal_presence_gate = quest_texts.iter().all(|text| {
        text.contains("QUEST JOURNAL | TRACKED:")
            && text.contains("MILESTONES:")
            && text.contains("TASKS active:")
            && text.contains("REWARDS:")
    });
    let initial_journal_gate = quest_texts.first().is_some_and(|text| {
        text.contains("NEXT: TITLE:NEW")
            && text.contains("[ ]CREATE")
            && text.contains("locked: task-arena-rematch-route")
    });
    let create_progress_gate = quest_texts.get(2).is_some_and(|text| {
        text.contains("NEXT: TALK") && text.contains("[x]CREATE") && text.contains("[ ]TALK")
    });
    let train_progress_gate = quest_texts.get(4).is_some_and(|text| {
        text.contains("NEXT: MOVE:north") && text.contains("[x]TALK") && text.contains("[x]TRAIN")
    });
    let fight_progress_gate = quest_texts.get(6).is_some_and(|text| {
        text.contains("NEXT: SAVE:SELECTED")
            && text.contains("[x]ARENA")
            && text.contains("[x]FIGHT")
    });
    let completion_progress_gate = quest_texts.get(7).is_some_and(|text| {
        text.contains("[x]COMPLETE")
            && text.contains("completed: task-fixture-first-route")
            && text.contains("claim claimed")
            && text.contains("coins 10")
    });
    let equip_progress_gate = quest_texts.get(8).is_some_and(|text| {
        text.contains("[x]EQUIP") && text.contains("equipment ready") && text.contains("xp 40")
    });
    let final_runtime = app.world().resource::<NativeFirstPlayableRuntime>().clone();
    let final_runtime_gate = final_runtime.objective_status == "first_playable_loop_complete"
        && final_runtime.reward_claimed
        && final_runtime.equipment_ready;
    let green = event_acceptance_gate
        && journal_presence_gate
        && initial_journal_gate
        && create_progress_gate
        && train_progress_gate
        && fight_progress_gate
        && completion_progress_gate
        && equip_progress_gate
        && final_runtime_gate;
    let evidence = json!({
        "contract_version": TRILLIONNIUM_WORLD_BEVY_QUEST_JOURNAL_CONTRACT,
        "input_affordance_contract": TRILLIONNIUM_WORLD_BEVY_INPUT_AFFORDANCE_FEEDBACK_CONTRACT,
        "green": green,
        "source_of_truth": "Bevy quest panel renders NativeFirstPlayableRuntime milestone, task, route, and reward state while actions mutate through real Bevy buttons",
        "actor_id": actor_id,
        "event_acceptance_gate": event_acceptance_gate,
        "journal_presence_gate": journal_presence_gate,
        "initial_journal_gate": initial_journal_gate,
        "create_progress_gate": create_progress_gate,
        "train_progress_gate": train_progress_gate,
        "fight_progress_gate": fight_progress_gate,
        "completion_progress_gate": completion_progress_gate,
        "equip_progress_gate": equip_progress_gate,
        "final_runtime_gate": final_runtime_gate,
        "button_events": button_events,
        "quest_texts": quest_texts,
        "samples": samples,
        "final_runtime": final_runtime,
        "android_s5_real_device_claimed": false,
    });
    for slot_id in native_session_slot_ids() {
        let _ = fs::remove_file(native_action_session_slot_path(slot_id));
    }
    serde_json::to_string_pretty(&evidence).expect("quest journal evidence serializes")
}

pub fn native_inventory_equipment_evidence_json(actor_id: &str) -> String {
    let actions = vec![
        NativeControlAction::Talk,
        NativeControlAction::Train,
        NativeControlAction::Move {
            direction: "north".to_string(),
        },
        NativeControlAction::CombatAttack,
        NativeControlAction::CombatDefend,
        NativeControlAction::CombatUseItem,
        NativeControlAction::CombatAttack,
        NativeControlAction::CombatAttack,
        NativeControlAction::OpenBag,
        NativeControlAction::LootDrop,
        NativeControlAction::EquipItem {
            item_id: "bandit_sash".to_string(),
        },
    ];
    let (samples, input_samples, button_events, final_runtime) =
        run_bevy_button_sequence(actor_id, actions);
    let sample_by_stage = |stage: &str| -> serde_json::Value {
        samples
            .iter()
            .rev()
            .find(|sample| sample.get("stage").and_then(|value| value.as_str()) == Some(stage))
            .cloned()
            .unwrap_or_else(|| json!({}))
    };
    let inventory_text = |sample: &serde_json::Value| -> String {
        sample
            .get("inventory_panel_text")
            .and_then(|value| value.as_str())
            .unwrap_or_default()
            .to_string()
    };
    let initial_sample = sample_by_stage("initial");
    let victory_sample = sample_by_stage("after_COMBAT:attack");
    let open_bag_sample = sample_by_stage("after_BAG:open");
    let loot_sample = sample_by_stage("after_LOOT:drop");
    let equip_sample = sample_by_stage("after_EQUIP:bandit_sash");
    let initial_inventory_text = inventory_text(&initial_sample);
    let victory_inventory_text = inventory_text(&victory_sample);
    let open_bag_inventory_text = inventory_text(&open_bag_sample);
    let loot_inventory_text = inventory_text(&loot_sample);
    let equip_inventory_text = inventory_text(&equip_sample);
    let event_acceptance_gate = button_events
        .iter()
        .all(|event| event.get("accepted").and_then(|value| value.as_bool()) == Some(true));
    let inventory_panel_presence_gate = [
        &initial_inventory_text,
        &victory_inventory_text,
        &open_bag_inventory_text,
        &loot_inventory_text,
        &equip_inventory_text,
    ]
    .iter()
    .all(|text| {
        text.contains("BAG HUD | STATUS")
            && text.contains("BAG ITEMS:")
            && text.contains("EQUIPPED:")
            && text.contains("ITEM DETAIL:")
            && text.contains("PROGRESSION:")
    });
    let initial_bag_gate = initial_inventory_text.contains("STATUS CLOSED")
        && initial_inventory_text.contains("small_healing_pill")
        && initial_inventory_text.contains("bandit_sash:locked");
    let victory_drop_gate = victory_inventory_text.contains("DROPS: bandit_sash")
        && victory_inventory_text.contains("loot visible")
        && final_runtime
            .loot_history
            .iter()
            .any(|event| event == "loot:bandit_sash");
    let bag_open_gate = open_bag_inventory_text.contains("STATUS OPEN")
        && open_bag_inventory_text.contains("bag_overlay_visible");
    let loot_collection_gate = loot_inventory_text.contains("BAG ITEMS: bandit_sash")
        && loot_inventory_text.contains("accessory bandit_sash:in_bag")
        && loot_inventory_text.contains("loot collected");
    let equip_gate = equip_inventory_text.contains("accessory bandit_sash:equipped")
        && equip_inventory_text.contains("equipment ready")
        && equip_inventory_text.contains("level 2 +1 stat")
        && equip_inventory_text.contains("AFFIX: AFFIX dormant")
        && final_runtime
            .equipped_items
            .iter()
            .any(|item| item == "bandit_sash")
        && final_runtime
            .inventory_items
            .iter()
            .all(|item| item != "bandit_sash");
    let rematch_unlock_gate = final_runtime
        .unlocked_task_ids
        .iter()
        .any(|task| task == "task-arena-rematch-route")
        && input_samples.iter().any(|sample| {
            sample.get("stage").and_then(|value| value.as_str()) == Some("after_EQUIP:bandit_sash")
                && sample
                    .pointer("/contextual_action_deck/primary_action_label")
                    .and_then(|value| value.as_str())
                    == Some("TASK:task-arena-rematch-route")
        });
    let green = event_acceptance_gate
        && inventory_panel_presence_gate
        && initial_bag_gate
        && victory_drop_gate
        && bag_open_gate
        && loot_collection_gate
        && equip_gate
        && rematch_unlock_gate;
    let evidence = json!({
        "contract_version": TRILLIONNIUM_WORLD_BEVY_INVENTORY_EQUIPMENT_CONTRACT,
        "quest_journal_contract": TRILLIONNIUM_WORLD_BEVY_QUEST_JOURNAL_CONTRACT,
        "green": green,
        "source_of_truth": "Bevy inventory panel renders NativeFirstPlayableRuntime bag, drop, equipment, item-detail, and unlock state while real Bevy buttons mutate the runtime",
        "actor_id": actor_id,
        "event_acceptance_gate": event_acceptance_gate,
        "inventory_panel_presence_gate": inventory_panel_presence_gate,
        "initial_bag_gate": initial_bag_gate,
        "victory_drop_gate": victory_drop_gate,
        "bag_open_gate": bag_open_gate,
        "loot_collection_gate": loot_collection_gate,
        "equip_gate": equip_gate,
        "rematch_unlock_gate": rematch_unlock_gate,
        "button_events": button_events,
        "inventory_texts": {
            "initial": initial_inventory_text,
            "after_victory": victory_inventory_text,
            "after_bag_open": open_bag_inventory_text,
            "after_loot": loot_inventory_text,
            "after_equip": equip_inventory_text
        },
        "samples": samples,
        "input_samples": input_samples,
        "final_runtime": final_runtime,
        "android_s5_real_device_claimed": false,
    });
    serde_json::to_string_pretty(&evidence).expect("inventory equipment evidence serializes")
}

pub fn native_stat_allocation_evidence_json(actor_id: &str) -> String {
    let actions = vec![
        NativeControlAction::Talk,
        NativeControlAction::Train,
        NativeControlAction::Move {
            direction: "north".to_string(),
        },
        NativeControlAction::CombatAttack,
        NativeControlAction::CombatDefend,
        NativeControlAction::CombatUseItem,
        NativeControlAction::CombatAttack,
        NativeControlAction::CombatAttack,
        NativeControlAction::OpenBag,
        NativeControlAction::LootDrop,
        NativeControlAction::EquipItem {
            item_id: "bandit_sash".to_string(),
        },
        NativeControlAction::AllocateStat {
            stat_id: "force".to_string(),
        },
        NativeControlAction::ConfirmStatAllocation,
    ];
    let (samples, input_samples, button_events, final_runtime) =
        run_bevy_button_sequence(actor_id, actions);
    let sample_by_stage = |stage: &str| -> serde_json::Value {
        samples
            .iter()
            .rev()
            .find(|sample| sample.get("stage").and_then(|value| value.as_str()) == Some(stage))
            .cloned()
            .unwrap_or_else(|| json!({}))
    };
    let input_sample_by_stage = |stage: &str| -> serde_json::Value {
        input_samples
            .iter()
            .rev()
            .find(|sample| sample.get("stage").and_then(|value| value.as_str()) == Some(stage))
            .cloned()
            .unwrap_or_else(|| json!({}))
    };
    let character_text = |sample: &serde_json::Value| -> String {
        sample
            .get("character_detail_text")
            .and_then(|value| value.as_str())
            .unwrap_or_default()
            .to_string()
    };
    let attr_u64 = |sample: &serde_json::Value, key: &str| -> Option<u64> {
        sample
            .get("character_attributes")
            .and_then(|value| value.get(key))
            .and_then(|value| value.as_u64())
    };
    let combat_hint = |sample: &serde_json::Value| -> Option<u64> {
        sample
            .pointer("/character_attributes/derived_stats/combat_power_hint")
            .and_then(|value| value.as_u64())
    };
    let before_sample = sample_by_stage("after_EQUIP:bandit_sash");
    let pending_sample = sample_by_stage("after_STAT:force");
    let after_sample = sample_by_stage("after_STAT:confirm");
    let before_input = input_sample_by_stage("after_EQUIP:bandit_sash");
    let pending_input = input_sample_by_stage("after_STAT:force");
    let after_input = input_sample_by_stage("after_STAT:confirm");
    let before_character_text = character_text(&before_sample);
    let pending_character_text = character_text(&pending_sample);
    let after_character_text = character_text(&after_sample);
    let before_force = attr_u64(&before_sample, "force");
    let pending_force = attr_u64(&pending_sample, "force");
    let after_force = attr_u64(&after_sample, "force");
    let before_combat_hint = combat_hint(&before_sample);
    let pending_combat_hint = combat_hint(&pending_sample);
    let after_combat_hint = combat_hint(&after_sample);
    let after_stat_button_state =
        contextual_button_state_value_from_sample(&after_sample, "STAT:force");
    let pending_stat_button_state =
        contextual_button_state_value_from_sample(&pending_sample, "STAT:force");
    let pending_confirm_button_state =
        contextual_button_state_value_from_sample(&pending_sample, "STAT:confirm");
    let pending_cancel_button_state =
        contextual_button_state_value_from_sample(&pending_sample, "STAT:cancel");
    let before_stat_button_state =
        contextual_button_state_value_from_sample(&before_sample, "STAT:force");
    let event_acceptance_gate = button_events
        .iter()
        .all(|event| event.get("accepted").and_then(|value| value.as_bool()) == Some(true));
    let character_sheet_presence_gate =
        [&before_character_text, &after_character_text]
            .iter()
            .all(|text| {
                text.contains("CHARACTER SHEET | LV")
                    && text.contains("UNSPENT")
                    && text.contains("ATTR P")
                    && text.contains("DERIVED HP")
                    && text.contains("GROWTH:")
            });
    let point_award_gate = before_character_text.contains("CHARACTER SHEET | LV 2 | UNSPENT 1")
        && before_character_text.contains("accessory bandit_sash")
        && before_force == Some(11)
        && before_combat_hint == Some(46);
    let stat_button_enabled_gate = availability_enabled(Some(&before_input), "STAT:force")
        && before_stat_button_state
            .get("enabled")
            .and_then(|value| value.as_bool())
            == Some(true)
        && before_stat_button_state
            .get("visual_state")
            .and_then(|value| value.as_str())
            .is_some_and(|state| state == "enabled_contextual" || state == "primary_enabled");
    let stat_confirmation_pending_gate = pending_character_text
        .contains("STAT CONFIRM | pending force")
        && pending_character_text.contains("Cost: 1 stat point")
        && pending_character_text.contains("FORCE pending -> rematch attack +4 DMG")
        && pending_force == before_force
        && pending_combat_hint == before_combat_hint
        && availability_enabled(Some(&pending_input), "STAT:confirm")
        && availability_enabled(Some(&pending_input), "STAT:cancel")
        && pending_stat_button_state
            .get("reason")
            .and_then(|value| value.as_str())
            .is_some_and(|reason| reason == "stat_confirmation_pending:force")
        && pending_confirm_button_state
            .get("visual_state")
            .and_then(|value| value.as_str())
            == Some("stat_confirmation_pending")
        && pending_cancel_button_state
            .get("visual_state")
            .and_then(|value| value.as_str())
            == Some("stat_confirmation_pending");
    let stat_spend_gate = after_character_text.contains("CHARACTER SHEET | LV 2 | UNSPENT 0")
        && after_character_text.contains("F12")
        && after_character_text.contains("allocated force")
        && final_runtime.growth_stat_points == 0
        && final_runtime
            .allocated_stat_points
            .iter()
            .any(|stat| stat == "force")
        && final_runtime
            .growth_history
            .iter()
            .any(|event| event == "stat:force:+1")
        && final_runtime
            .progression_checkpoint_history
            .iter()
            .any(|checkpoint| checkpoint == "stat_allocated:force");
    let character_attribute_mutation_gate = before_force == Some(11)
        && after_force == Some(12)
        && before_combat_hint == Some(46)
        && after_combat_hint == Some(48);
    let stat_button_lock_after_gate = !availability_enabled(Some(&after_input), "STAT:force")
        && after_stat_button_state
            .get("reason")
            .and_then(|value| value.as_str())
            .is_some_and(|reason| reason == "stat_already_allocated:force");
    let green = event_acceptance_gate
        && character_sheet_presence_gate
        && point_award_gate
        && stat_button_enabled_gate
        && stat_confirmation_pending_gate
        && stat_spend_gate
        && character_attribute_mutation_gate
        && stat_button_lock_after_gate;
    let evidence = json!({
        "contract_version": TRILLIONNIUM_WORLD_BEVY_STAT_ALLOCATION_CONTRACT,
        "inventory_equipment_contract": TRILLIONNIUM_WORLD_BEVY_INVENTORY_EQUIPMENT_CONTRACT,
        "green": green,
        "source_of_truth": "Bevy STAT:force button routes through native_live_action_availability and mutates NativeFirstPlayableRuntime plus Rust WorldTrillionniumCharacter attributes",
        "actor_id": actor_id,
        "event_acceptance_gate": event_acceptance_gate,
        "character_sheet_presence_gate": character_sheet_presence_gate,
        "point_award_gate": point_award_gate,
        "stat_button_enabled_gate": stat_button_enabled_gate,
        "stat_confirmation_pending_gate": stat_confirmation_pending_gate,
        "stat_spend_gate": stat_spend_gate,
        "character_attribute_mutation_gate": character_attribute_mutation_gate,
        "stat_button_lock_after_gate": stat_button_lock_after_gate,
        "force_before": before_force,
        "force_pending": pending_force,
        "force_after": after_force,
        "combat_power_hint_before": before_combat_hint,
        "combat_power_hint_pending": pending_combat_hint,
        "combat_power_hint_after": after_combat_hint,
        "button_events": button_events,
        "character_texts": {
            "after_equip": before_character_text,
            "after_stat_pending": pending_character_text,
            "after_stat": after_character_text
        },
        "stat_button_states": {
            "after_equip": before_stat_button_state,
            "after_stat_pending": pending_stat_button_state,
            "after_stat_confirm": after_stat_button_state,
            "pending_confirm": pending_confirm_button_state,
            "pending_cancel": pending_cancel_button_state
        },
        "samples": samples,
        "input_samples": input_samples,
        "final_runtime": final_runtime,
        "android_s5_real_device_claimed": false,
    });
    serde_json::to_string_pretty(&evidence).expect("stat allocation evidence serializes")
}

pub fn native_stat_allocation_persistence_evidence_json(
    actor_id: &str,
    expected_slot_dir: &str,
) -> String {
    let action_slot_dir = native_action_session_slot_dir();
    for slot_id in native_session_slot_ids() {
        let _ = fs::remove_file(native_action_session_slot_path(slot_id));
    }
    let actions = vec![
        NativeControlAction::Talk,
        NativeControlAction::Train,
        NativeControlAction::Move {
            direction: "north".to_string(),
        },
        NativeControlAction::CombatAttack,
        NativeControlAction::CombatDefend,
        NativeControlAction::CombatUseItem,
        NativeControlAction::CombatAttack,
        NativeControlAction::CombatAttack,
        NativeControlAction::OpenBag,
        NativeControlAction::LootDrop,
        NativeControlAction::EquipItem {
            item_id: "bandit_sash".to_string(),
        },
        NativeControlAction::AllocateStat {
            stat_id: "agility".to_string(),
        },
        NativeControlAction::ConfirmStatAllocation,
        NativeControlAction::SaveSelectedSlot,
        NativeControlAction::LoadSelectedSlot,
        NativeControlAction::ContinueAfterLoad,
    ];
    let (samples, input_samples, button_events, final_runtime) =
        run_bevy_button_sequence(actor_id, actions);
    let sample_by_stage = |stage: &str| -> serde_json::Value {
        samples
            .iter()
            .rev()
            .find(|sample| sample.get("stage").and_then(|value| value.as_str()) == Some(stage))
            .cloned()
            .unwrap_or_else(|| json!({}))
    };
    let input_sample_by_stage = |stage: &str| -> serde_json::Value {
        input_samples
            .iter()
            .rev()
            .find(|sample| sample.get("stage").and_then(|value| value.as_str()) == Some(stage))
            .cloned()
            .unwrap_or_else(|| json!({}))
    };
    let attr_u64 = |sample: &serde_json::Value, key: &str| -> Option<u64> {
        sample
            .get("character_attributes")
            .and_then(|value| value.get(key))
            .and_then(|value| value.as_u64())
    };
    let combat_hint = |sample: &serde_json::Value| -> Option<u64> {
        sample
            .pointer("/character_attributes/derived_stats/combat_power_hint")
            .and_then(|value| value.as_u64())
    };
    let character_text = |sample: &serde_json::Value| -> String {
        sample
            .get("character_detail_text")
            .and_then(|value| value.as_str())
            .unwrap_or_default()
            .to_string()
    };
    let button_event_by_action = |action_label: &str| -> serde_json::Value {
        button_events
            .iter()
            .find(|event| {
                event.get("action").and_then(|value| value.as_str()) == Some(action_label)
            })
            .cloned()
            .unwrap_or_else(|| json!({}))
    };
    let button_state_reason = |sample: &serde_json::Value, label: &str| -> Option<String> {
        contextual_button_state_value_from_sample(sample, label)
            .get("reason")
            .and_then(|value| value.as_str())
            .map(str::to_string)
    };
    let button_state_enabled = |sample: &serde_json::Value, label: &str| -> bool {
        contextual_button_state_value_from_sample(sample, label)
            .get("enabled")
            .and_then(|value| value.as_bool())
            == Some(true)
    };

    let before_sample = sample_by_stage("after_EQUIP:bandit_sash");
    let pending_stat_sample = sample_by_stage("after_STAT:agility");
    let after_stat_sample = sample_by_stage("after_STAT:confirm");
    let after_save_sample = sample_by_stage("after_SAVE:SELECTED");
    let after_load_sample = sample_by_stage("after_LOAD:SELECTED");
    let after_continue_sample = sample_by_stage("after_CONTINUE:SESSION");
    let before_input = input_sample_by_stage("after_EQUIP:bandit_sash");
    let pending_stat_input = input_sample_by_stage("after_STAT:agility");
    let after_stat_input = input_sample_by_stage("after_STAT:confirm");

    let before_text = character_text(&before_sample);
    let pending_stat_text = character_text(&pending_stat_sample);
    let after_stat_text = character_text(&after_stat_sample);
    let after_continue_text = character_text(&after_continue_sample);
    let before_force = attr_u64(&before_sample, "force");
    let before_agility = attr_u64(&before_sample, "agility");
    let before_craft = attr_u64(&before_sample, "craft");
    let after_force = attr_u64(&after_stat_sample, "force");
    let after_agility = attr_u64(&after_stat_sample, "agility");
    let after_craft = attr_u64(&after_stat_sample, "craft");
    let after_continue_agility = attr_u64(&after_continue_sample, "agility");
    let combat_power_hint_before = combat_hint(&before_sample);
    let combat_power_hint_pending = combat_hint(&pending_stat_sample);
    let combat_power_hint_after = combat_hint(&after_stat_sample);
    let stat_labels = ["STAT:force", "STAT:agility", "STAT:craft"];
    let multi_stat_option_gate = stat_labels.iter().all(|label| {
        availability_enabled(Some(&before_input), label)
            && button_state_enabled(&before_sample, label)
            && button_state_reason(&before_sample, label)
                .is_some_and(|reason| reason.starts_with("enabled_stat_preview:"))
    });
    let confirmation_pending_gate = pending_stat_text.contains("STAT CONFIRM | pending agility")
        && pending_stat_text.contains("AGILITY pending -> incoming -3 / guard +2 HP")
        && attr_u64(&pending_stat_sample, "agility") == before_agility
        && combat_power_hint_pending == combat_power_hint_before
        && availability_enabled(Some(&pending_stat_input), "STAT:confirm")
        && availability_enabled(Some(&pending_stat_input), "STAT:cancel");
    let selected_stat_spend_gate = before_agility == Some(12)
        && after_agility == Some(13)
        && after_force == before_force
        && after_craft == before_craft
        && after_stat_text.contains("CHARACTER SHEET | LV 2 | UNSPENT 0")
        && after_stat_text.contains("A13")
        && after_stat_text.contains("allocated agility");
    let stat_button_lock_after_gate = stat_labels
        .iter()
        .all(|label| !availability_enabled(Some(&after_stat_input), label))
        && button_state_reason(&after_stat_sample, "STAT:agility")
            .is_some_and(|reason| reason == "stat_already_allocated:agility")
        && button_state_reason(&after_stat_sample, "STAT:force")
            .is_some_and(|reason| reason == "stat_point_required")
        && button_state_reason(&after_stat_sample, "STAT:craft")
            .is_some_and(|reason| reason == "stat_point_required");
    let save_event = button_event_by_action("SAVE:SELECTED");
    let load_event = button_event_by_action("LOAD:SELECTED");
    let continue_event = button_event_by_action("CONTINUE:SESSION");
    let slot_a_path = native_action_session_slot_path("A");
    let slot_a_bytes = fs::metadata(&slot_a_path)
        .map(|metadata| metadata.len())
        .unwrap_or(0);
    let saved_snapshot = fs::read_to_string(&slot_a_path)
        .ok()
        .and_then(|text| serde_json::from_str::<NativePlayableSaveSnapshot>(&text).ok());
    let snapshot_persistence_gate = saved_snapshot.as_ref().is_some_and(|snapshot| {
        snapshot.contract_version == TRILLIONNIUM_WORLD_BEVY_STATE_SNAPSHOT_CONTRACT
            && snapshot.first_playable.growth_stat_points == 0
            && snapshot
                .first_playable
                .allocated_stat_points
                .iter()
                .any(|stat| stat == "agility")
            && snapshot
                .first_playable
                .growth_history
                .iter()
                .any(|event| event == "stat:agility:+1")
            && snapshot.character.attributes.agility == 13
    });
    let save_after_stat_gate = save_event.get("accepted").and_then(|value| value.as_bool())
        == Some(true)
        && slot_a_bytes > 512
        && after_save_sample
            .get("session_slot_text")
            .and_then(|value| value.as_str())
            .is_some_and(|text| text.contains("A:saved"));
    let load_resume_gate = load_event.get("accepted").and_then(|value| value.as_bool())
        == Some(true)
        && after_load_sample
            .pointer("/runtime/session_resume_input_locked")
            .and_then(|value| value.as_bool())
            == Some(true)
        && after_load_sample
            .pointer("/runtime/session_resume_source_slot_id")
            .and_then(|value| value.as_str())
            == Some("A")
        && attr_u64(&after_load_sample, "agility") == Some(13);
    let continue_restores_stat_gate = continue_event
        .get("accepted")
        .and_then(|value| value.as_bool())
        == Some(true)
        && after_continue_sample
            .pointer("/runtime/session_resume_input_locked")
            .and_then(|value| value.as_bool())
            == Some(false)
        && after_continue_agility == Some(13)
        && after_continue_text.contains("A13")
        && after_continue_text.contains("allocated agility")
        && final_runtime.growth_stat_points == 0
        && final_runtime
            .allocated_stat_points
            .iter()
            .any(|stat| stat == "agility");
    let event_acceptance_gate = button_events
        .iter()
        .all(|event| event.get("accepted").and_then(|value| value.as_bool()) == Some(true));
    let green = event_acceptance_gate
        && before_text.contains("CHARACTER SHEET | LV 2 | UNSPENT 1")
        && multi_stat_option_gate
        && confirmation_pending_gate
        && selected_stat_spend_gate
        && stat_button_lock_after_gate
        && save_after_stat_gate
        && snapshot_persistence_gate
        && load_resume_gate
        && continue_restores_stat_gate
        && expected_slot_dir == action_slot_dir;
    let evidence = json!({
        "contract_version": TRILLIONNIUM_WORLD_BEVY_STAT_ALLOCATION_PERSISTENCE_CONTRACT,
        "stat_allocation_contract": TRILLIONNIUM_WORLD_BEVY_STAT_ALLOCATION_CONTRACT,
        "state_snapshot_contract": TRILLIONNIUM_WORLD_BEVY_STATE_SNAPSHOT_CONTRACT,
        "green": green,
        "source_of_truth": "Bevy multi-stat buttons mutate Rust-owned character attributes, then NativePlayableSaveSnapshot persists and restores the allocated stat through LOAD/CONTINUE.",
        "actor_id": actor_id,
        "expected_slot_dir": expected_slot_dir,
        "action_slot_dir": action_slot_dir,
        "slot_a_path": slot_a_path,
        "slot_a_bytes": slot_a_bytes,
        "event_acceptance_gate": event_acceptance_gate,
        "multi_stat_option_gate": multi_stat_option_gate,
        "confirmation_pending_gate": confirmation_pending_gate,
        "selected_stat_spend_gate": selected_stat_spend_gate,
        "stat_button_lock_after_gate": stat_button_lock_after_gate,
        "save_after_stat_gate": save_after_stat_gate,
        "snapshot_persistence_gate": snapshot_persistence_gate,
        "load_resume_gate": load_resume_gate,
        "continue_restores_stat_gate": continue_restores_stat_gate,
        "stat_options": stat_labels,
        "attrs_before": {
            "force": before_force,
            "agility": before_agility,
            "craft": before_craft,
            "combat_power_hint": combat_power_hint_before
        },
        "attrs_after_pending": {
            "agility": attr_u64(&pending_stat_sample, "agility"),
            "combat_power_hint": combat_power_hint_pending
        },
        "attrs_after_stat": {
            "force": after_force,
            "agility": after_agility,
            "craft": after_craft,
            "combat_power_hint": combat_power_hint_after
        },
        "attrs_after_continue": {
            "agility": after_continue_agility
        },
        "button_events": button_events,
        "stat_button_states": {
            "after_equip_force": contextual_button_state_value_from_sample(&before_sample, "STAT:force"),
            "after_equip_agility": contextual_button_state_value_from_sample(&before_sample, "STAT:agility"),
            "after_equip_craft": contextual_button_state_value_from_sample(&before_sample, "STAT:craft"),
            "after_pending_agility": contextual_button_state_value_from_sample(&pending_stat_sample, "STAT:agility"),
            "pending_confirm": contextual_button_state_value_from_sample(&pending_stat_sample, "STAT:confirm"),
            "pending_cancel": contextual_button_state_value_from_sample(&pending_stat_sample, "STAT:cancel"),
            "after_stat_force": contextual_button_state_value_from_sample(&after_stat_sample, "STAT:force"),
            "after_stat_agility": contextual_button_state_value_from_sample(&after_stat_sample, "STAT:agility"),
            "after_stat_craft": contextual_button_state_value_from_sample(&after_stat_sample, "STAT:craft")
        },
        "character_texts": {
            "after_equip": before_text,
            "after_pending": pending_stat_text,
            "after_stat": after_stat_text,
            "after_continue": after_continue_text
        },
        "snapshot_summary": saved_snapshot.as_ref().map(|snapshot| json!({
            "contract_version": snapshot.contract_version,
            "growth_stat_points": snapshot.first_playable.growth_stat_points,
            "allocated_stat_points": snapshot.first_playable.allocated_stat_points,
            "growth_history": snapshot.first_playable.growth_history,
            "agility": snapshot.character.attributes.agility,
            "combat_power_hint": snapshot.character.attributes.derived_stats().combat_power_hint
        })),
        "samples": samples,
        "input_samples": input_samples,
        "final_runtime": final_runtime,
        "android_s5_real_device_claimed": false,
    });
    serde_json::to_string_pretty(&evidence)
        .expect("stat allocation persistence evidence serializes")
}

pub fn native_stat_gameplay_effects_evidence_json(actor_id: &str) -> String {
    let base_to_equip = || {
        vec![
            NativeControlAction::Talk,
            NativeControlAction::Train,
            NativeControlAction::Move {
                direction: "north".to_string(),
            },
            NativeControlAction::CombatAttack,
            NativeControlAction::CombatDefend,
            NativeControlAction::CombatUseItem,
            NativeControlAction::CombatAttack,
            NativeControlAction::CombatAttack,
            NativeControlAction::OpenBag,
            NativeControlAction::LootDrop,
            NativeControlAction::EquipItem {
                item_id: "bandit_sash".to_string(),
            },
        ]
    };
    let run_branch = |stat_id: Option<&str>, followups: Vec<NativeControlAction>| {
        let mut actions = base_to_equip();
        if let Some(stat_id) = stat_id {
            actions.push(NativeControlAction::AllocateStat {
                stat_id: stat_id.to_string(),
            });
            actions.push(NativeControlAction::ConfirmStatAllocation);
        }
        actions.extend(followups);
        run_bevy_button_sequence(actor_id, actions)
    };
    let rematch_actions = || {
        vec![
            NativeControlAction::StartTask {
                task_id: "task-arena-rematch-route".to_string(),
            },
            NativeControlAction::CombatAttack,
        ]
    };
    let complete_task_actions = || vec![NativeControlAction::CompleteTask];

    let (baseline_samples, _, baseline_events, baseline_runtime) =
        run_branch(None, rematch_actions());
    let (force_samples, _, force_events, force_runtime) =
        run_branch(Some("force"), rematch_actions());
    let (agility_samples, _, agility_events, agility_runtime) =
        run_branch(Some("agility"), rematch_actions());
    let (baseline_reward_samples, _, baseline_reward_events, baseline_reward_runtime) =
        run_branch(None, complete_task_actions());
    let (craft_samples, _, craft_events, craft_runtime) =
        run_branch(Some("craft"), complete_task_actions());

    let all_events = [
        baseline_events.as_slice(),
        force_events.as_slice(),
        agility_events.as_slice(),
        baseline_reward_events.as_slice(),
        craft_events.as_slice(),
    ];
    let event_acceptance_gate = all_events.iter().all(|events| {
        events
            .iter()
            .all(|event| event.get("accepted").and_then(|value| value.as_bool()) == Some(true))
    });
    let combat_attack_summary = |runtime: &NativeFirstPlayableRuntime| -> serde_json::Value {
        json!({
            "enemy_hp": runtime.enemy_hp,
            "player_hp": runtime.player_hp,
            "combat_turn": runtime.combat_turn,
            "combat_round_log": runtime.combat_round_log,
            "growth_history": runtime.growth_history,
            "progression_checkpoint_history": runtime.progression_checkpoint_history,
            "stat_effect_floating_text": runtime.stat_effect_floating_text.clone(),
        })
    };
    let reward_summary = |runtime: &NativeFirstPlayableRuntime| -> serde_json::Value {
        json!({
            "coins": runtime.coins,
            "xp": runtime.xp,
            "growth_history": runtime.growth_history,
            "progression_checkpoint_history": runtime.progression_checkpoint_history,
            "stat_effect_floating_text": runtime.stat_effect_floating_text.clone(),
            "reward_settlement_text": runtime.reward_settlement_text.clone(),
            "reward_claimed": runtime.reward_claimed,
        })
    };
    let last_sample_text = |samples: &[serde_json::Value], stage: &str, key: &str| -> String {
        samples
            .iter()
            .rev()
            .find(|sample| sample.get("stage").and_then(|value| value.as_str()) == Some(stage))
            .and_then(|sample| sample.get(key))
            .and_then(|value| value.as_str())
            .unwrap_or_default()
            .to_string()
    };
    let force_feedback_text = last_sample_text(
        &force_samples,
        "after_COMBAT:attack",
        "feedback_banner_text",
    );
    let force_enemy_text = last_sample_text(&force_samples, "after_COMBAT:attack", "enemy_text");
    let force_combat_scene_text =
        last_sample_text(&force_samples, "after_COMBAT:attack", "combat_scene_text");
    let agility_feedback_text = last_sample_text(
        &agility_samples,
        "after_COMBAT:attack",
        "feedback_banner_text",
    );
    let agility_enemy_text =
        last_sample_text(&agility_samples, "after_COMBAT:attack", "enemy_text");
    let agility_combat_scene_text =
        last_sample_text(&agility_samples, "after_COMBAT:attack", "combat_scene_text");
    let craft_reward_toast_text =
        last_sample_text(&craft_samples, "after_COMPLETE", "reward_toast_text");
    let craft_feedback_text =
        last_sample_text(&craft_samples, "after_COMPLETE", "feedback_banner_text");
    let craft_quest_panel_text =
        last_sample_text(&craft_samples, "after_COMPLETE", "quest_panel_text");
    let force_damage_gate = baseline_runtime.enemy_hp - force_runtime.enemy_hp == 4
        && baseline_runtime.enemy_hp == 38
        && force_runtime.enemy_hp == 34
        && force_runtime
            .growth_history
            .iter()
            .any(|entry| entry == "stat_effect:force:attack_damage_bonus")
        && force_runtime
            .progression_checkpoint_history
            .iter()
            .any(|entry| entry == "stat_effect:force:attack_damage_bonus");
    let agility_mitigation_gate = agility_runtime.player_hp - baseline_runtime.player_hp == 3
        && baseline_runtime.player_hp == 94
        && agility_runtime.player_hp == 97
        && agility_runtime.enemy_hp == baseline_runtime.enemy_hp
        && agility_runtime
            .growth_history
            .iter()
            .any(|entry| entry == "stat_effect:agility:incoming_damage_reduced")
        && agility_runtime
            .progression_checkpoint_history
            .iter()
            .any(|entry| entry == "stat_effect:agility:incoming_damage_reduced");
    let craft_reward_gate = baseline_reward_runtime.coins == 10
        && baseline_reward_runtime.xp == 40
        && craft_runtime.coins == 14
        && craft_runtime.xp == 45
        && craft_runtime
            .growth_history
            .iter()
            .any(|entry| entry == "stat_effect:craft:task_reward_bonus")
        && craft_runtime
            .progression_checkpoint_history
            .iter()
            .any(|entry| entry == "stat_effect:craft:reward_bonus");
    let branch_isolation_gate = force_runtime
        .allocated_stat_points
        .iter()
        .any(|entry| entry == "force")
        && agility_runtime
            .allocated_stat_points
            .iter()
            .any(|entry| entry == "agility")
        && craft_runtime
            .allocated_stat_points
            .iter()
            .any(|entry| entry == "craft")
        && force_runtime.growth_stat_points == 0
        && agility_runtime.growth_stat_points == 0
        && craft_runtime.growth_stat_points == 0;
    let visible_force_feedback_gate = force_feedback_text.contains("FORCE +4 DMG")
        && force_feedback_text.contains("FLOAT DMG -18")
        && force_enemy_text.contains("FORCE +4 DMG")
        && force_combat_scene_text.contains("FORCE +4 DMG");
    let visible_agility_feedback_gate = agility_feedback_text.contains("AGILITY -3 INCOMING")
        && agility_feedback_text.contains("FLOAT DMG -14")
        && agility_enemy_text.contains("AGILITY -3 INCOMING")
        && agility_combat_scene_text.contains("AGILITY -3 INCOMING");
    let visible_craft_settlement_gate = craft_reward_toast_text
        .contains("SETTLEMENT +14 coins +45 XP")
        && craft_reward_toast_text.contains("CRAFT +4 coins +5 XP")
        && craft_feedback_text.contains("CRAFT +4 coins +5 XP")
        && craft_quest_panel_text.contains("CRAFT +4 coins +5 XP");
    let green = event_acceptance_gate
        && force_damage_gate
        && agility_mitigation_gate
        && craft_reward_gate
        && branch_isolation_gate;
    let evidence = json!({
        "contract_version": TRILLIONNIUM_WORLD_BEVY_STAT_GAMEPLAY_EFFECTS_CONTRACT,
        "stat_allocation_contract": TRILLIONNIUM_WORLD_BEVY_STAT_ALLOCATION_CONTRACT,
        "stat_allocation_persistence_contract": TRILLIONNIUM_WORLD_BEVY_STAT_ALLOCATION_PERSISTENCE_CONTRACT,
        "green": green,
        "source_of_truth": "Separate Bevy button-driven branches allocate force, agility, or craft, then prove each stat changes a different gameplay result.",
        "actor_id": actor_id,
        "event_acceptance_gate": event_acceptance_gate,
        "force_damage_gate": force_damage_gate,
        "agility_mitigation_gate": agility_mitigation_gate,
        "craft_reward_gate": craft_reward_gate,
        "branch_isolation_gate": branch_isolation_gate,
        "visible_force_feedback_gate": visible_force_feedback_gate,
        "visible_agility_feedback_gate": visible_agility_feedback_gate,
        "visible_craft_settlement_gate": visible_craft_settlement_gate,
        "baseline_rematch": combat_attack_summary(&baseline_runtime),
        "force_rematch": combat_attack_summary(&force_runtime),
        "agility_rematch": combat_attack_summary(&agility_runtime),
        "baseline_reward": reward_summary(&baseline_reward_runtime),
        "craft_reward": reward_summary(&craft_runtime),
        "branch_samples": {
            "baseline_rematch": baseline_samples,
            "force_rematch": force_samples,
            "agility_rematch": agility_samples,
            "baseline_reward": baseline_reward_samples,
            "craft_reward": craft_samples
        },
        "visible_feedback_samples": {
            "force_rematch": {
                "feedback_banner_text": force_feedback_text,
                "enemy_text": force_enemy_text,
                "combat_scene_text": force_combat_scene_text,
            },
            "agility_rematch": {
                "feedback_banner_text": agility_feedback_text,
                "enemy_text": agility_enemy_text,
                "combat_scene_text": agility_combat_scene_text,
            },
            "craft_reward": {
                "reward_toast_text": craft_reward_toast_text,
                "feedback_banner_text": craft_feedback_text,
                "quest_panel_text": craft_quest_panel_text,
            }
        },
        "button_events": {
            "baseline_rematch": baseline_events,
            "force_rematch": force_events,
            "agility_rematch": agility_events,
            "baseline_reward": baseline_reward_events,
            "craft_reward": craft_events
        },
        "android_s5_real_device_claimed": false,
    });
    serde_json::to_string_pretty(&evidence).expect("stat gameplay effects evidence serializes")
}

pub fn native_stat_feedback_ui_evidence_json(actor_id: &str) -> String {
    let gameplay: serde_json::Value =
        serde_json::from_str(&native_stat_gameplay_effects_evidence_json(actor_id))
            .expect("stat gameplay effects evidence parses for UI feedback gate");
    let visible_force_feedback_gate = gameplay
        .get("visible_force_feedback_gate")
        .and_then(|value| value.as_bool())
        == Some(true);
    let visible_agility_feedback_gate = gameplay
        .get("visible_agility_feedback_gate")
        .and_then(|value| value.as_bool())
        == Some(true);
    let visible_craft_settlement_gate = gameplay
        .get("visible_craft_settlement_gate")
        .and_then(|value| value.as_bool())
        == Some(true);
    let gameplay_effects_gate =
        gameplay.get("green").and_then(|value| value.as_bool()) == Some(true);
    let green = gameplay_effects_gate
        && visible_force_feedback_gate
        && visible_agility_feedback_gate
        && visible_craft_settlement_gate;
    let evidence = json!({
        "contract_version": TRILLIONNIUM_WORLD_BEVY_STAT_FEEDBACK_UI_CONTRACT,
        "stat_gameplay_effects_contract": TRILLIONNIUM_WORLD_BEVY_STAT_GAMEPLAY_EFFECTS_CONTRACT,
        "game_feedback_contract": TRILLIONNIUM_WORLD_BEVY_GAME_FEEDBACK_CONTRACT,
        "green": green,
        "source_of_truth": "Bevy runtime samples prove stat gameplay effects are visible in the combat floating text, feedback banner, reward toast, and quest settlement panel.",
        "actor_id": actor_id,
        "gameplay_effects_gate": gameplay_effects_gate,
        "visible_force_feedback_gate": visible_force_feedback_gate,
        "visible_agility_feedback_gate": visible_agility_feedback_gate,
        "visible_craft_settlement_gate": visible_craft_settlement_gate,
        "visible_feedback_samples": gameplay
            .get("visible_feedback_samples")
            .cloned()
            .unwrap_or_else(|| json!({})),
        "stat_effect_summaries": {
            "force_rematch": gameplay.get("force_rematch").cloned().unwrap_or_else(|| json!({})),
            "agility_rematch": gameplay.get("agility_rematch").cloned().unwrap_or_else(|| json!({})),
            "craft_reward": gameplay.get("craft_reward").cloned().unwrap_or_else(|| json!({})),
        },
        "android_s5_real_device_claimed": false,
    });
    serde_json::to_string_pretty(&evidence).expect("stat feedback UI evidence serializes")
}

pub fn native_stat_choice_preview_evidence_json(actor_id: &str) -> String {
    let base_to_equip = || {
        vec![
            NativeControlAction::Talk,
            NativeControlAction::Train,
            NativeControlAction::Move {
                direction: "north".to_string(),
            },
            NativeControlAction::CombatAttack,
            NativeControlAction::CombatDefend,
            NativeControlAction::CombatUseItem,
            NativeControlAction::CombatAttack,
            NativeControlAction::CombatAttack,
            NativeControlAction::OpenBag,
            NativeControlAction::LootDrop,
            NativeControlAction::EquipItem {
                item_id: "bandit_sash".to_string(),
            },
        ]
    };
    let run_branch = |stat_id: Option<&str>| {
        let mut actions = base_to_equip();
        if let Some(stat_id) = stat_id {
            actions.push(NativeControlAction::AllocateStat {
                stat_id: stat_id.to_string(),
            });
            actions.push(NativeControlAction::ConfirmStatAllocation);
        }
        run_bevy_button_sequence(actor_id, actions)
    };
    let (preview_samples, preview_input_samples, preview_events, preview_runtime) =
        run_branch(None);
    let (force_samples, _force_input_samples, force_events, force_runtime) =
        run_branch(Some("force"));
    let (agility_samples, _agility_input_samples, agility_events, agility_runtime) =
        run_branch(Some("agility"));
    let (craft_samples, _craft_input_samples, craft_events, craft_runtime) =
        run_branch(Some("craft"));

    let sample_by_stage = |samples: &[serde_json::Value], stage: &str| -> serde_json::Value {
        samples
            .iter()
            .rev()
            .find(|sample| sample.get("stage").and_then(|value| value.as_str()) == Some(stage))
            .cloned()
            .unwrap_or_else(|| json!({}))
    };
    let character_text_at = |samples: &[serde_json::Value], stage: &str| -> String {
        sample_by_stage(samples, stage)
            .get("character_detail_text")
            .and_then(|value| value.as_str())
            .unwrap_or_default()
            .to_string()
    };
    let preview_sample = sample_by_stage(&preview_samples, "after_EQUIP:bandit_sash");
    let preview_input_sample = sample_by_stage(&preview_input_samples, "after_EQUIP:bandit_sash");
    let preview_text = character_text_at(&preview_samples, "after_EQUIP:bandit_sash");
    let force_active_text = character_text_at(&force_samples, "after_STAT:confirm");
    let agility_active_text = character_text_at(&agility_samples, "after_STAT:confirm");
    let craft_active_text = character_text_at(&craft_samples, "after_STAT:confirm");
    let stat_labels = ["STAT:force", "STAT:agility", "STAT:craft"];
    let stat_button_preview_gate = stat_labels.iter().all(|label| {
        availability_enabled(Some(&preview_input_sample), label)
            && contextual_button_state_value_from_sample(&preview_sample, label)
                .get("enabled")
                .and_then(|value| value.as_bool())
                == Some(true)
    });
    let event_acceptance_gate = [
        preview_events.as_slice(),
        force_events.as_slice(),
        agility_events.as_slice(),
        craft_events.as_slice(),
    ]
    .iter()
    .all(|events| {
        events
            .iter()
            .all(|event| event.get("accepted").and_then(|value| value.as_bool()) == Some(true))
    });
    let preview_visible_gate = preview_runtime.growth_stat_points == 1
        && preview_runtime.allocated_stat_points.is_empty()
        && preview_text.contains("STAT PREVIEW | choose one before spend")
        && preview_text.contains("FORCE -> rematch attack +4 DMG")
        && preview_text.contains("AGILITY -> incoming -3 / guard +2 HP")
        && preview_text.contains("CRAFT -> reward +4 coins +5 XP");
    let force_active_preview_gate = force_runtime
        .allocated_stat_points
        .iter()
        .any(|stat_id| stat_id == "force")
        && force_active_text.contains("STAT BUILD ACTIVE | allocated force")
        && force_active_text.contains("FORCE active -> rematch attack +4 DMG");
    let agility_active_preview_gate = agility_runtime
        .allocated_stat_points
        .iter()
        .any(|stat_id| stat_id == "agility")
        && agility_active_text.contains("STAT BUILD ACTIVE | allocated agility")
        && agility_active_text.contains("AGILITY active -> incoming -3 / guard +2 HP");
    let craft_active_preview_gate = craft_runtime
        .allocated_stat_points
        .iter()
        .any(|stat_id| stat_id == "craft")
        && craft_active_text.contains("STAT BUILD ACTIVE | allocated craft")
        && craft_active_text.contains("CRAFT active -> reward +4 coins +5 XP");
    let green = event_acceptance_gate
        && preview_visible_gate
        && stat_button_preview_gate
        && force_active_preview_gate
        && agility_active_preview_gate
        && craft_active_preview_gate;
    let evidence = json!({
        "contract_version": TRILLIONNIUM_WORLD_BEVY_STAT_CHOICE_PREVIEW_CONTRACT,
        "stat_allocation_contract": TRILLIONNIUM_WORLD_BEVY_STAT_ALLOCATION_CONTRACT,
        "stat_gameplay_effects_contract": TRILLIONNIUM_WORLD_BEVY_STAT_GAMEPLAY_EFFECTS_CONTRACT,
        "green": green,
        "source_of_truth": "Bevy character sheet previews force/agility/craft build effects before the player spends a stat point, then switches to active build text after each allocation.",
        "actor_id": actor_id,
        "event_acceptance_gate": event_acceptance_gate,
        "preview_visible_gate": preview_visible_gate,
        "stat_button_preview_gate": stat_button_preview_gate,
        "force_active_preview_gate": force_active_preview_gate,
        "agility_active_preview_gate": agility_active_preview_gate,
        "craft_active_preview_gate": craft_active_preview_gate,
        "preview_texts": {
            "before_spend": preview_text,
            "force_active": force_active_text,
            "agility_active": agility_active_text,
            "craft_active": craft_active_text,
        },
        "stat_button_states": {
            "force": contextual_button_state_value_from_sample(&preview_sample, "STAT:force"),
            "agility": contextual_button_state_value_from_sample(&preview_sample, "STAT:agility"),
            "craft": contextual_button_state_value_from_sample(&preview_sample, "STAT:craft"),
        },
        "runtime_summaries": {
            "before_spend": {
                "growth_stat_points": preview_runtime.growth_stat_points,
                "allocated_stat_points": preview_runtime.allocated_stat_points,
            },
            "force_active": {
                "growth_stat_points": force_runtime.growth_stat_points,
                "allocated_stat_points": force_runtime.allocated_stat_points,
            },
            "agility_active": {
                "growth_stat_points": agility_runtime.growth_stat_points,
                "allocated_stat_points": agility_runtime.allocated_stat_points,
            },
            "craft_active": {
                "growth_stat_points": craft_runtime.growth_stat_points,
                "allocated_stat_points": craft_runtime.allocated_stat_points,
            },
        },
        "button_events": {
            "before_spend": preview_events,
            "force_active": force_events,
            "agility_active": agility_events,
            "craft_active": craft_events,
        },
        "android_s5_real_device_claimed": false,
    });
    serde_json::to_string_pretty(&evidence).expect("stat choice preview evidence serializes")
}

pub fn native_stat_confirmation_evidence_json(actor_id: &str) -> String {
    let base_to_equip = || {
        vec![
            NativeControlAction::Talk,
            NativeControlAction::Train,
            NativeControlAction::Move {
                direction: "north".to_string(),
            },
            NativeControlAction::CombatAttack,
            NativeControlAction::CombatDefend,
            NativeControlAction::CombatUseItem,
            NativeControlAction::CombatAttack,
            NativeControlAction::CombatAttack,
            NativeControlAction::OpenBag,
            NativeControlAction::LootDrop,
            NativeControlAction::EquipItem {
                item_id: "bandit_sash".to_string(),
            },
        ]
    };
    let run_branch = |extra_actions: Vec<NativeControlAction>| {
        let mut actions = base_to_equip();
        actions.extend(extra_actions);
        run_bevy_button_sequence(actor_id, actions)
    };
    let (pending_samples, pending_input_samples, pending_events, pending_runtime) =
        run_branch(vec![NativeControlAction::AllocateStat {
            stat_id: "force".to_string(),
        }]);
    let (cancel_samples, _cancel_input_samples, cancel_events, cancel_runtime) = run_branch(vec![
        NativeControlAction::AllocateStat {
            stat_id: "agility".to_string(),
        },
        NativeControlAction::CancelStatAllocation,
    ]);
    let (confirm_samples, _confirm_input_samples, confirm_events, confirm_runtime) =
        run_branch(vec![
            NativeControlAction::AllocateStat {
                stat_id: "craft".to_string(),
            },
            NativeControlAction::ConfirmStatAllocation,
        ]);

    let sample_by_stage = |samples: &[serde_json::Value], stage: &str| -> serde_json::Value {
        samples
            .iter()
            .rev()
            .find(|sample| sample.get("stage").and_then(|value| value.as_str()) == Some(stage))
            .cloned()
            .unwrap_or_else(|| json!({}))
    };
    let character_text = |sample: &serde_json::Value| -> String {
        sample
            .get("character_detail_text")
            .and_then(|value| value.as_str())
            .unwrap_or_default()
            .to_string()
    };
    let attr_u64 = |sample: &serde_json::Value, key: &str| -> Option<u64> {
        sample
            .get("character_attributes")
            .and_then(|value| value.get(key))
            .and_then(|value| value.as_u64())
    };
    let equip_sample = sample_by_stage(&pending_samples, "after_EQUIP:bandit_sash");
    let pending_sample = sample_by_stage(&pending_samples, "after_STAT:force");
    let pending_input_sample = sample_by_stage(&pending_input_samples, "after_STAT:force");
    let cancel_pending_sample = sample_by_stage(&cancel_samples, "after_STAT:agility");
    let cancel_sample = sample_by_stage(&cancel_samples, "after_STAT:cancel");
    let confirm_pending_sample = sample_by_stage(&confirm_samples, "after_STAT:craft");
    let confirm_sample = sample_by_stage(&confirm_samples, "after_STAT:confirm");

    let equip_text = character_text(&equip_sample);
    let pending_text = character_text(&pending_sample);
    let cancel_pending_text = character_text(&cancel_pending_sample);
    let cancel_text = character_text(&cancel_sample);
    let confirm_pending_text = character_text(&confirm_pending_sample);
    let confirm_text = character_text(&confirm_sample);
    let event_acceptance_gate = [
        pending_events.as_slice(),
        cancel_events.as_slice(),
        confirm_events.as_slice(),
    ]
    .iter()
    .all(|events| {
        events
            .iter()
            .all(|event| event.get("accepted").and_then(|value| value.as_bool()) == Some(true))
    });
    let preview_is_non_mutating_gate = pending_runtime.growth_stat_points == 1
        && pending_runtime.pending_stat_allocation.as_deref() == Some("force")
        && pending_runtime.allocated_stat_points.is_empty()
        && attr_u64(&equip_sample, "force") == Some(11)
        && attr_u64(&pending_sample, "force") == Some(11)
        && pending_text.contains("STAT CONFIRM | pending force")
        && pending_text.contains("Cost: 1 stat point")
        && pending_text.contains("FORCE pending -> rematch attack +4 DMG");
    let confirm_cancel_button_gate =
        availability_enabled(Some(&pending_input_sample), "STAT:confirm")
            && availability_enabled(Some(&pending_input_sample), "STAT:cancel")
            && contextual_button_state_value_from_sample(&pending_sample, "STAT:confirm")
                .get("visual_state")
                .and_then(|value| value.as_str())
                == Some("stat_confirmation_pending")
            && contextual_button_state_value_from_sample(&pending_sample, "STAT:cancel")
                .get("visual_state")
                .and_then(|value| value.as_str())
                == Some("stat_confirmation_pending");
    let cancel_restores_preview_gate = cancel_pending_text
        .contains("STAT CONFIRM | pending agility")
        && cancel_runtime.growth_stat_points == 1
        && cancel_runtime.pending_stat_allocation.is_none()
        && cancel_runtime.allocated_stat_points.is_empty()
        && attr_u64(&cancel_sample, "agility") == Some(12)
        && cancel_text.contains("STAT PREVIEW | choose one before spend")
        && cancel_text.contains("AGILITY -> incoming -3 / guard +2 HP")
        && cancel_runtime
            .stat_confirmation_history
            .iter()
            .any(|entry| entry == "cancelled:agility");
    let confirm_spends_point_gate = confirm_pending_text.contains("STAT CONFIRM | pending craft")
        && confirm_runtime.growth_stat_points == 0
        && confirm_runtime.pending_stat_allocation.is_none()
        && confirm_runtime
            .allocated_stat_points
            .iter()
            .any(|entry| entry == "craft")
        && attr_u64(&confirm_pending_sample, "craft") == Some(10)
        && attr_u64(&confirm_sample, "craft") == Some(11)
        && confirm_text.contains("STAT BUILD ACTIVE | allocated craft")
        && confirm_text.contains("CRAFT active -> reward +4 coins +5 XP")
        && confirm_runtime
            .stat_confirmation_history
            .iter()
            .any(|entry| entry == "confirmed:craft");
    let green = event_acceptance_gate
        && preview_is_non_mutating_gate
        && confirm_cancel_button_gate
        && cancel_restores_preview_gate
        && confirm_spends_point_gate;
    let evidence = json!({
        "contract_version": TRILLIONNIUM_WORLD_BEVY_STAT_CONFIRMATION_CONTRACT,
        "stat_choice_preview_contract": TRILLIONNIUM_WORLD_BEVY_STAT_CHOICE_PREVIEW_CONTRACT,
        "stat_allocation_contract": TRILLIONNIUM_WORLD_BEVY_STAT_ALLOCATION_CONTRACT,
        "green": green,
        "source_of_truth": "STAT buttons now enter a pending confirmation state first; only STAT:confirm mutates Rust-owned character attributes and spends the point.",
        "actor_id": actor_id,
        "event_acceptance_gate": event_acceptance_gate,
        "preview_is_non_mutating_gate": preview_is_non_mutating_gate,
        "confirm_cancel_button_gate": confirm_cancel_button_gate,
        "cancel_restores_preview_gate": cancel_restores_preview_gate,
        "confirm_spends_point_gate": confirm_spends_point_gate,
        "character_texts": {
            "after_equip": equip_text,
            "pending_force": pending_text,
            "pending_agility_before_cancel": cancel_pending_text,
            "after_cancel": cancel_text,
            "pending_craft_before_confirm": confirm_pending_text,
            "after_confirm": confirm_text,
        },
        "stat_button_states": {
            "pending_force": contextual_button_state_value_from_sample(&pending_sample, "STAT:force"),
            "pending_confirm": contextual_button_state_value_from_sample(&pending_sample, "STAT:confirm"),
            "pending_cancel": contextual_button_state_value_from_sample(&pending_sample, "STAT:cancel"),
            "after_cancel_force": contextual_button_state_value_from_sample(&cancel_sample, "STAT:force"),
            "after_confirm_craft": contextual_button_state_value_from_sample(&confirm_sample, "STAT:craft"),
        },
        "attrs": {
            "force_before": attr_u64(&equip_sample, "force"),
            "force_after_pending": attr_u64(&pending_sample, "force"),
            "agility_after_cancel": attr_u64(&cancel_sample, "agility"),
            "craft_before_confirm": attr_u64(&confirm_pending_sample, "craft"),
            "craft_after_confirm": attr_u64(&confirm_sample, "craft"),
        },
        "runtime_summaries": {
            "pending_force": {
                "growth_stat_points": pending_runtime.growth_stat_points,
                "pending_stat_allocation": pending_runtime.pending_stat_allocation,
                "allocated_stat_points": pending_runtime.allocated_stat_points,
                "stat_confirmation_history": pending_runtime.stat_confirmation_history,
            },
            "after_cancel": {
                "growth_stat_points": cancel_runtime.growth_stat_points,
                "pending_stat_allocation": cancel_runtime.pending_stat_allocation,
                "allocated_stat_points": cancel_runtime.allocated_stat_points,
                "stat_confirmation_history": cancel_runtime.stat_confirmation_history,
            },
            "after_confirm": {
                "growth_stat_points": confirm_runtime.growth_stat_points,
                "pending_stat_allocation": confirm_runtime.pending_stat_allocation,
                "allocated_stat_points": confirm_runtime.allocated_stat_points,
                "stat_confirmation_history": confirm_runtime.stat_confirmation_history,
            }
        },
        "button_events": {
            "pending_force": pending_events,
            "cancel_branch": cancel_events,
            "confirm_branch": confirm_events,
        },
        "android_s5_real_device_claimed": false,
    });
    serde_json::to_string_pretty(&evidence).expect("stat confirmation evidence serializes")
}

pub fn native_equipment_affix_build_evidence_json(actor_id: &str) -> String {
    let base_to_equip = || {
        vec![
            NativeControlAction::Talk,
            NativeControlAction::Train,
            NativeControlAction::Move {
                direction: "north".to_string(),
            },
            NativeControlAction::CombatAttack,
            NativeControlAction::CombatDefend,
            NativeControlAction::CombatUseItem,
            NativeControlAction::CombatAttack,
            NativeControlAction::CombatAttack,
            NativeControlAction::OpenBag,
            NativeControlAction::LootDrop,
            NativeControlAction::EquipItem {
                item_id: "bandit_sash".to_string(),
            },
        ]
    };
    let run_branch = |stat_id: Option<&str>, confirm: bool, followups: Vec<NativeControlAction>| {
        let mut actions = base_to_equip();
        if let Some(stat_id) = stat_id {
            actions.push(NativeControlAction::AllocateStat {
                stat_id: stat_id.to_string(),
            });
            if confirm {
                actions.push(NativeControlAction::ConfirmStatAllocation);
            }
        }
        actions.extend(followups);
        run_bevy_button_sequence(actor_id, actions)
    };
    let rematch_actions = || {
        vec![
            NativeControlAction::StartTask {
                task_id: "task-arena-rematch-route".to_string(),
            },
            NativeControlAction::CombatAttack,
        ]
    };
    let complete_task_actions = || vec![NativeControlAction::CompleteTask];

    let (dormant_samples, _, dormant_events, dormant_runtime) = run_branch(None, false, vec![]);
    let (pending_samples, _, pending_events, pending_runtime) =
        run_branch(Some("force"), false, vec![]);
    let (force_samples, _, force_events, force_runtime) =
        run_branch(Some("force"), true, rematch_actions());
    let (agility_samples, _, agility_events, agility_runtime) =
        run_branch(Some("agility"), true, rematch_actions());
    let (craft_samples, _, craft_events, craft_runtime) =
        run_branch(Some("craft"), true, complete_task_actions());

    let sample_by_stage = |samples: &[serde_json::Value], stage: &str| -> serde_json::Value {
        samples
            .iter()
            .rev()
            .find(|sample| sample.get("stage").and_then(|value| value.as_str()) == Some(stage))
            .cloned()
            .unwrap_or_else(|| json!({}))
    };
    let text_at = |samples: &[serde_json::Value], stage: &str, key: &str| -> String {
        sample_by_stage(samples, stage)
            .get(key)
            .and_then(|value| value.as_str())
            .unwrap_or_default()
            .to_string()
    };
    let dormant_inventory = text_at(
        &dormant_samples,
        "after_EQUIP:bandit_sash",
        "inventory_panel_text",
    );
    let pending_inventory = text_at(&pending_samples, "after_STAT:force", "inventory_panel_text");
    let force_inventory = text_at(&force_samples, "after_STAT:confirm", "inventory_panel_text");
    let agility_inventory = text_at(
        &agility_samples,
        "after_STAT:confirm",
        "inventory_panel_text",
    );
    let craft_inventory = text_at(&craft_samples, "after_STAT:confirm", "inventory_panel_text");
    let force_feedback = text_at(
        &force_samples,
        "after_COMBAT:attack",
        "feedback_banner_text",
    );
    let agility_feedback = text_at(
        &agility_samples,
        "after_COMBAT:attack",
        "feedback_banner_text",
    );
    let craft_reward_toast = text_at(&craft_samples, "after_COMPLETE", "reward_toast_text");

    let event_acceptance_gate = [
        dormant_events.as_slice(),
        pending_events.as_slice(),
        force_events.as_slice(),
        agility_events.as_slice(),
        craft_events.as_slice(),
    ]
    .iter()
    .all(|events| {
        events
            .iter()
            .all(|event| event.get("accepted").and_then(|value| value.as_bool()) == Some(true))
    });
    let dormant_affix_gate = dormant_runtime.growth_stat_points == 1
        && dormant_runtime.allocated_stat_points.is_empty()
        && dormant_inventory.contains("AFFIX: AFFIX dormant")
        && dormant_inventory.contains("choose force/agility/craft to attune bandit_sash");
    let pending_affix_gate = pending_runtime.pending_stat_allocation.as_deref() == Some("force")
        && pending_runtime.allocated_stat_points.is_empty()
        && pending_inventory.contains("AFFIX PREVIEW | bandit_sash:force")
        && pending_inventory.contains("iron-strike preview -> rematch attack +4 DMG");
    let force_affix_gate = force_runtime
        .allocated_stat_points
        .iter()
        .any(|stat| stat == "force")
        && force_inventory.contains("AFFIX ACTIVE | bandit_sash:iron-strike")
        && force_feedback.contains("FORCE +4 DMG")
        && force_runtime.enemy_hp == 34;
    let agility_affix_gate = agility_runtime
        .allocated_stat_points
        .iter()
        .any(|stat| stat == "agility")
        && agility_inventory.contains("AFFIX ACTIVE | bandit_sash:wind-guard")
        && agility_feedback.contains("AGILITY -3 INCOMING")
        && agility_runtime.player_hp == 97;
    let craft_affix_gate = craft_runtime
        .allocated_stat_points
        .iter()
        .any(|stat| stat == "craft")
        && craft_inventory.contains("AFFIX ACTIVE | bandit_sash:market-thread")
        && craft_reward_toast.contains("CRAFT +4 coins +5 XP")
        && craft_runtime.coins == 14
        && craft_runtime.xp == 45;
    let green = event_acceptance_gate
        && dormant_affix_gate
        && pending_affix_gate
        && force_affix_gate
        && agility_affix_gate
        && craft_affix_gate;
    let evidence = json!({
        "contract_version": TRILLIONNIUM_WORLD_BEVY_EQUIPMENT_AFFIX_BUILD_CONTRACT,
        "inventory_equipment_contract": TRILLIONNIUM_WORLD_BEVY_INVENTORY_EQUIPMENT_CONTRACT,
        "stat_confirmation_contract": TRILLIONNIUM_WORLD_BEVY_STAT_CONFIRMATION_CONTRACT,
        "stat_gameplay_effects_contract": TRILLIONNIUM_WORLD_BEVY_STAT_GAMEPLAY_EFFECTS_CONTRACT,
        "green": green,
        "source_of_truth": "bandit_sash affix text is derived from the same pending/confirmed stat runtime that gates combat and reward effects.",
        "actor_id": actor_id,
        "event_acceptance_gate": event_acceptance_gate,
        "dormant_affix_gate": dormant_affix_gate,
        "pending_affix_gate": pending_affix_gate,
        "force_affix_gate": force_affix_gate,
        "agility_affix_gate": agility_affix_gate,
        "craft_affix_gate": craft_affix_gate,
        "inventory_texts": {
            "dormant_after_equip": dormant_inventory,
            "pending_force": pending_inventory,
            "force_active": force_inventory,
            "agility_active": agility_inventory,
            "craft_active": craft_inventory,
        },
        "effect_texts": {
            "force_feedback": force_feedback,
            "agility_feedback": agility_feedback,
            "craft_reward_toast": craft_reward_toast,
        },
        "runtime_summaries": {
            "dormant": {
                "growth_stat_points": dormant_runtime.growth_stat_points,
                "pending_stat_allocation": dormant_runtime.pending_stat_allocation,
                "allocated_stat_points": dormant_runtime.allocated_stat_points,
            },
            "pending_force": {
                "growth_stat_points": pending_runtime.growth_stat_points,
                "pending_stat_allocation": pending_runtime.pending_stat_allocation,
                "allocated_stat_points": pending_runtime.allocated_stat_points,
            },
            "force_active": {
                "enemy_hp": force_runtime.enemy_hp,
                "player_hp": force_runtime.player_hp,
                "allocated_stat_points": force_runtime.allocated_stat_points,
            },
            "agility_active": {
                "enemy_hp": agility_runtime.enemy_hp,
                "player_hp": agility_runtime.player_hp,
                "allocated_stat_points": agility_runtime.allocated_stat_points,
            },
            "craft_active": {
                "coins": craft_runtime.coins,
                "xp": craft_runtime.xp,
                "allocated_stat_points": craft_runtime.allocated_stat_points,
            }
        },
        "android_s5_real_device_claimed": false,
    });
    serde_json::to_string_pretty(&evidence).expect("equipment affix build evidence serializes")
}

pub fn native_build_branch_routes_evidence_json(actor_id: &str) -> String {
    let base_to_equip = || {
        vec![
            NativeControlAction::Talk,
            NativeControlAction::Train,
            NativeControlAction::Move {
                direction: "north".to_string(),
            },
            NativeControlAction::CombatAttack,
            NativeControlAction::CombatDefend,
            NativeControlAction::CombatUseItem,
            NativeControlAction::CombatAttack,
            NativeControlAction::CombatAttack,
            NativeControlAction::OpenBag,
            NativeControlAction::LootDrop,
            NativeControlAction::EquipItem {
                item_id: "bandit_sash".to_string(),
            },
        ]
    };
    let run_branch = |stat_id: Option<&str>, task_id: Option<&str>| {
        let mut actions = base_to_equip();
        if let Some(stat_id) = stat_id {
            actions.push(NativeControlAction::AllocateStat {
                stat_id: stat_id.to_string(),
            });
            actions.push(NativeControlAction::ConfirmStatAllocation);
        }
        if let Some(task_id) = task_id {
            actions.push(NativeControlAction::StartTask {
                task_id: task_id.to_string(),
            });
        }
        run_bevy_button_sequence(actor_id, actions)
    };
    let text_at = |samples: &[serde_json::Value], stage: &str, key: &str| -> String {
        samples
            .iter()
            .rev()
            .find(|sample| sample.get("stage").and_then(|value| value.as_str()) == Some(stage))
            .and_then(|sample| sample.get(key))
            .and_then(|value| value.as_str())
            .unwrap_or_default()
            .to_string()
    };
    let availability_for =
        |runtime: &NativeFirstPlayableRuntime, task_id: &str| -> serde_json::Value {
            let action = NativeControlAction::StartTask {
                task_id: task_id.to_string(),
            };
            let (enabled, reason) = native_live_action_availability(runtime, &action);
            json!({
                "action": native_control_action_label(&action),
                "enabled": enabled,
                "reason": reason,
            })
        };

    let (dormant_samples, _, dormant_events, dormant_runtime) = run_branch(None, None);
    let (force_samples, _, force_events, force_runtime) =
        run_branch(Some("force"), Some("task-force-combat-commission"));
    let (agility_samples, _, agility_events, agility_runtime) =
        run_branch(Some("agility"), Some("task-agility-scout-route"));
    let (craft_samples, _, craft_events, craft_runtime) =
        run_branch(Some("craft"), Some("task-craft-delivery-order"));

    let dormant_quest = text_at(
        &dormant_samples,
        "after_EQUIP:bandit_sash",
        "quest_panel_text",
    );
    let force_confirm_quest = text_at(&force_samples, "after_STAT:confirm", "quest_panel_text");
    let force_task_quest = text_at(
        &force_samples,
        "after_TASK:task-force-combat-commission",
        "quest_panel_text",
    );
    let agility_confirm_quest = text_at(&agility_samples, "after_STAT:confirm", "quest_panel_text");
    let agility_task_quest = text_at(
        &agility_samples,
        "after_TASK:task-agility-scout-route",
        "quest_panel_text",
    );
    let craft_confirm_quest = text_at(&craft_samples, "after_STAT:confirm", "quest_panel_text");
    let craft_task_quest = text_at(
        &craft_samples,
        "after_TASK:task-craft-delivery-order",
        "quest_panel_text",
    );

    let dormant_force_availability =
        availability_for(&dormant_runtime, "task-force-combat-commission");
    let force_wrong_craft_availability =
        availability_for(&force_runtime, "task-craft-delivery-order");
    let agility_wrong_force_availability =
        availability_for(&agility_runtime, "task-force-combat-commission");
    let craft_wrong_agility_availability =
        availability_for(&craft_runtime, "task-agility-scout-route");

    let branch_events_accepted = [
        force_events.as_slice(),
        agility_events.as_slice(),
        craft_events.as_slice(),
    ]
    .iter()
    .all(|events| {
        events
            .iter()
            .all(|event| event.get("accepted").and_then(|value| value.as_bool()) == Some(true))
    });
    let dormant_events_accepted = dormant_events
        .iter()
        .all(|event| event.get("accepted").and_then(|value| value.as_bool()) == Some(true));
    let dormant_locked_gate = dormant_events_accepted
        && dormant_runtime
            .unlocked_task_ids
            .iter()
            .all(|task_id| !build_branch_task_ids().contains(&task_id.as_str()))
        && dormant_force_availability
            .get("enabled")
            .and_then(|value| value.as_bool())
            == Some(false)
        && dormant_force_availability
            .get("reason")
            .and_then(|value| value.as_str())
            == Some("build_branch_requires_force:task-force-combat-commission")
        && dormant_quest.contains("BUILD ROUTES | build dormant_choose_force_agility_craft")
        && dormant_quest.contains("force:task-force-combat-commission:locked_requires_force");
    let exclusive_unlock_gate = force_runtime
        .unlocked_task_ids
        .iter()
        .any(|task_id| task_id == "task-force-combat-commission")
        && !force_runtime
            .unlocked_task_ids
            .iter()
            .any(|task_id| task_id == "task-agility-scout-route")
        && !force_runtime
            .unlocked_task_ids
            .iter()
            .any(|task_id| task_id == "task-craft-delivery-order")
        && agility_runtime
            .unlocked_task_ids
            .iter()
            .any(|task_id| task_id == "task-agility-scout-route")
        && craft_runtime
            .unlocked_task_ids
            .iter()
            .any(|task_id| task_id == "task-craft-delivery-order");
    let force_branch_gate = force_runtime
        .active_task_ids
        .iter()
        .any(|task_id| task_id == "task-force-combat-commission")
        && force_runtime.route_director_task_id == "task-force-combat-commission"
        && force_runtime.route_director_target_room_id == "league-coliseum"
        && force_runtime.objective_status
            == "build_branch_active:force:task-force-combat-commission"
        && force_runtime.combat_scene_state == "force_commission_duelist_ready"
        && force_task_quest.contains("force:task-force-combat-commission:active")
        && force_confirm_quest.contains("force:task-force-combat-commission:unlocked");
    let agility_branch_gate = agility_runtime
        .active_task_ids
        .iter()
        .any(|task_id| task_id == "task-agility-scout-route")
        && agility_runtime.route_director_task_id == "task-agility-scout-route"
        && agility_runtime.route_director_target_room_id == "delivery-dock"
        && agility_runtime.objective_status
            == "build_branch_active:agility:task-agility-scout-route"
        && agility_task_quest.contains("agility:task-agility-scout-route:active")
        && agility_confirm_quest.contains("agility:task-agility-scout-route:unlocked");
    let craft_branch_gate = craft_runtime
        .active_task_ids
        .iter()
        .any(|task_id| task_id == "task-craft-delivery-order")
        && craft_runtime.route_director_task_id == "task-craft-delivery-order"
        && craft_runtime.route_director_target_room_id == "forge-workbench"
        && craft_runtime.objective_status == "build_branch_active:craft:task-craft-delivery-order"
        && craft_task_quest.contains("craft:task-craft-delivery-order:active")
        && craft_confirm_quest.contains("craft:task-craft-delivery-order:unlocked");
    let wrong_branch_guard_gate = force_wrong_craft_availability
        .get("enabled")
        .and_then(|value| value.as_bool())
        == Some(false)
        && force_wrong_craft_availability
            .get("reason")
            .and_then(|value| value.as_str())
            == Some("build_branch_requires_craft:task-craft-delivery-order")
        && agility_wrong_force_availability
            .get("reason")
            .and_then(|value| value.as_str())
            == Some("build_branch_requires_force:task-force-combat-commission")
        && craft_wrong_agility_availability
            .get("reason")
            .and_then(|value| value.as_str())
            == Some("build_branch_requires_agility:task-agility-scout-route");
    let ui_task_state_gate = [&force_task_quest, &agility_task_quest, &craft_task_quest]
        .iter()
        .all(|text| {
            text.contains("BUILD ROUTES")
                && text.contains("task-force-combat-commission")
                && text.contains("task-agility-scout-route")
                && text.contains("task-craft-delivery-order")
        });
    let green = branch_events_accepted
        && dormant_locked_gate
        && exclusive_unlock_gate
        && force_branch_gate
        && agility_branch_gate
        && craft_branch_gate
        && wrong_branch_guard_gate
        && ui_task_state_gate;
    let evidence = json!({
        "contract_version": TRILLIONNIUM_WORLD_BEVY_BUILD_BRANCH_ROUTES_CONTRACT,
        "equipment_affix_build_contract": TRILLIONNIUM_WORLD_BEVY_EQUIPMENT_AFFIX_BUILD_CONTRACT,
        "stat_confirmation_contract": TRILLIONNIUM_WORLD_BEVY_STAT_CONFIRMATION_CONTRACT,
        "scene_pack_contract": TRILLIONNIUM_WORLD_BEVY_SCENE_PACK_CONTRACT,
        "green": green,
        "source_of_truth": "Confirmed bandit_sash build attunement unlocks exactly one build-specific route; StartTask availability rejects wrong-build branches before mutation.",
        "actor_id": actor_id,
        "branch_events_accepted": branch_events_accepted,
        "dormant_locked_gate": dormant_locked_gate,
        "exclusive_unlock_gate": exclusive_unlock_gate,
        "force_branch_gate": force_branch_gate,
        "agility_branch_gate": agility_branch_gate,
        "craft_branch_gate": craft_branch_gate,
        "wrong_branch_guard_gate": wrong_branch_guard_gate,
        "ui_task_state_gate": ui_task_state_gate,
        "availability_guards": {
            "dormant_force": dormant_force_availability,
            "force_wrong_craft": force_wrong_craft_availability,
            "agility_wrong_force": agility_wrong_force_availability,
            "craft_wrong_agility": craft_wrong_agility_availability,
        },
        "quest_texts": {
            "dormant_after_equip": dormant_quest,
            "force_after_confirm": force_confirm_quest,
            "force_after_task": force_task_quest,
            "agility_after_confirm": agility_confirm_quest,
            "agility_after_task": agility_task_quest,
            "craft_after_confirm": craft_confirm_quest,
            "craft_after_task": craft_task_quest,
        },
        "runtime_summaries": {
            "dormant": {
                "allocated_stat_points": dormant_runtime.allocated_stat_points,
                "unlocked_task_ids": dormant_runtime.unlocked_task_ids,
                "active_task_ids": dormant_runtime.active_task_ids,
            },
            "force": {
                "allocated_stat_points": force_runtime.allocated_stat_points,
                "unlocked_task_ids": force_runtime.unlocked_task_ids,
                "active_task_ids": force_runtime.active_task_ids,
                "route_director_task_id": force_runtime.route_director_task_id,
                "route_director_target_room_id": force_runtime.route_director_target_room_id,
                "objective_status": force_runtime.objective_status,
                "combat_scene_state": force_runtime.combat_scene_state,
            },
            "agility": {
                "allocated_stat_points": agility_runtime.allocated_stat_points,
                "unlocked_task_ids": agility_runtime.unlocked_task_ids,
                "active_task_ids": agility_runtime.active_task_ids,
                "route_director_task_id": agility_runtime.route_director_task_id,
                "route_director_target_room_id": agility_runtime.route_director_target_room_id,
                "objective_status": agility_runtime.objective_status,
            },
            "craft": {
                "allocated_stat_points": craft_runtime.allocated_stat_points,
                "unlocked_task_ids": craft_runtime.unlocked_task_ids,
                "active_task_ids": craft_runtime.active_task_ids,
                "route_director_task_id": craft_runtime.route_director_task_id,
                "route_director_target_room_id": craft_runtime.route_director_target_room_id,
                "objective_status": craft_runtime.objective_status,
            },
        },
        "button_events": {
            "force": force_events,
            "agility": agility_events,
            "craft": craft_events,
        },
        "android_s5_real_device_claimed": false,
    });
    serde_json::to_string_pretty(&evidence).expect("build branch routes evidence serializes")
}

pub fn native_build_branch_outcomes_evidence_json(actor_id: &str) -> String {
    let base_to_equip = || {
        vec![
            NativeControlAction::Talk,
            NativeControlAction::Train,
            NativeControlAction::Move {
                direction: "north".to_string(),
            },
            NativeControlAction::CombatAttack,
            NativeControlAction::CombatDefend,
            NativeControlAction::CombatUseItem,
            NativeControlAction::CombatAttack,
            NativeControlAction::CombatAttack,
            NativeControlAction::OpenBag,
            NativeControlAction::LootDrop,
            NativeControlAction::EquipItem {
                item_id: "bandit_sash".to_string(),
            },
        ]
    };
    let branch_start_actions = |stat_id: &str, task_id: &str| {
        let mut actions = base_to_equip();
        actions.push(NativeControlAction::AllocateStat {
            stat_id: stat_id.to_string(),
        });
        actions.push(NativeControlAction::ConfirmStatAllocation);
        actions.push(NativeControlAction::StartTask {
            task_id: task_id.to_string(),
        });
        actions
    };
    let branch_complete_actions = |stat_id: &str, task_id: &str| {
        let mut actions = branch_start_actions(stat_id, task_id);
        if stat_id == "force" {
            actions.extend([
                NativeControlAction::CombatAttack,
                NativeControlAction::CombatAttack,
                NativeControlAction::CombatAttack,
                NativeControlAction::CombatAttack,
            ]);
        } else {
            let plan = scene_pack_route_plan_for_task("league-coliseum", task_id);
            actions.extend(scene_pack_route_actions(&plan));
        }
        actions.push(NativeControlAction::CompleteTask);
        actions
    };
    let text_at = |samples: &[serde_json::Value], stage: &str, key: &str| -> String {
        samples
            .iter()
            .rev()
            .find(|sample| sample.get("stage").and_then(|value| value.as_str()) == Some(stage))
            .and_then(|sample| sample.get(key))
            .and_then(|value| value.as_str())
            .unwrap_or_default()
            .to_string()
    };
    let availability_for_action =
        |runtime: &NativeFirstPlayableRuntime, action: NativeControlAction| -> serde_json::Value {
            let (enabled, reason) = native_live_action_availability(runtime, &action);
            json!({
                "action": native_control_action_label(&action),
                "enabled": enabled,
                "reason": reason,
            })
        };

    let force_task_id = "task-force-combat-commission";
    let agility_task_id = "task-agility-scout-route";
    let craft_task_id = "task-craft-delivery-order";

    let (_, _, _, force_started_runtime) =
        run_bevy_button_sequence(actor_id, branch_start_actions("force", force_task_id));
    let mut force_victory_actions = branch_start_actions("force", force_task_id);
    force_victory_actions.extend([
        NativeControlAction::CombatAttack,
        NativeControlAction::CombatAttack,
        NativeControlAction::CombatAttack,
        NativeControlAction::CombatAttack,
    ]);
    let (_, _, _, force_victory_runtime) =
        run_bevy_button_sequence(actor_id, force_victory_actions);
    let (_, _, _, agility_started_runtime) =
        run_bevy_button_sequence(actor_id, branch_start_actions("agility", agility_task_id));
    let (_, _, _, craft_started_runtime) =
        run_bevy_button_sequence(actor_id, branch_start_actions("craft", craft_task_id));

    let (force_samples, _, force_events, force_runtime) =
        run_bevy_button_sequence(actor_id, branch_complete_actions("force", force_task_id));
    let (agility_samples, _, agility_events, agility_runtime) = run_bevy_button_sequence(
        actor_id,
        branch_complete_actions("agility", agility_task_id),
    );
    let (craft_samples, _, craft_events, craft_runtime) =
        run_bevy_button_sequence(actor_id, branch_complete_actions("craft", craft_task_id));

    let force_before_victory_availability =
        availability_for_action(&force_started_runtime, NativeControlAction::CompleteTask);
    let force_after_victory_availability =
        availability_for_action(&force_victory_runtime, NativeControlAction::CompleteTask);
    let agility_before_target_availability =
        availability_for_action(&agility_started_runtime, NativeControlAction::CompleteTask);
    let craft_before_target_availability =
        availability_for_action(&craft_started_runtime, NativeControlAction::CompleteTask);
    let force_wrong_craft_after_completion = availability_for_action(
        &force_runtime,
        NativeControlAction::StartTask {
            task_id: craft_task_id.to_string(),
        },
    );

    let force_quest_after_complete = text_at(&force_samples, "after_COMPLETE", "quest_panel_text");
    let agility_quest_after_complete =
        text_at(&agility_samples, "after_COMPLETE", "quest_panel_text");
    let craft_quest_after_complete = text_at(&craft_samples, "after_COMPLETE", "quest_panel_text");

    let all_branch_events_accepted = [
        force_events.as_slice(),
        agility_events.as_slice(),
        craft_events.as_slice(),
    ]
    .iter()
    .all(|events| {
        events
            .iter()
            .all(|event| event.get("accepted").and_then(|value| value.as_bool()) == Some(true))
    });
    let force_completion_guard_gate = force_before_victory_availability
        .get("enabled")
        .and_then(|value| value.as_bool())
        == Some(false)
        && force_before_victory_availability
            .get("reason")
            .and_then(|value| value.as_str())
            == Some("build_branch_force_victory_required:task-force-combat-commission")
        && force_after_victory_availability
            .get("enabled")
            .and_then(|value| value.as_bool())
            == Some(true)
        && force_after_victory_availability
            .get("reason")
            .and_then(|value| value.as_str())
            == Some("enabled_build_branch_outcome:task-force-combat-commission");
    let target_room_completion_guard_gate = agility_before_target_availability
        .get("enabled")
        .and_then(|value| value.as_bool())
        == Some(false)
        && agility_before_target_availability
            .get("reason")
            .and_then(|value| value.as_str())
            == Some("build_branch_target_room_required:delivery-dock:task-agility-scout-route")
        && craft_before_target_availability
            .get("enabled")
            .and_then(|value| value.as_bool())
            == Some(false)
        && craft_before_target_availability
            .get("reason")
            .and_then(|value| value.as_str())
            == Some("build_branch_target_room_required:forge-workbench:task-craft-delivery-order");
    let force_outcome_gate = force_runtime
        .completed_task_ids
        .iter()
        .any(|task_id| task_id == force_task_id)
        && !force_runtime
            .active_task_ids
            .iter()
            .any(|task_id| task_id == force_task_id)
        && force_runtime
            .inventory_items
            .iter()
            .any(|item| item == "force-commission-token")
        && force_runtime.objective_status
            == "build_branch_completed:force:task-force-combat-commission"
        && force_runtime
            .reward_settlement_text
            .contains("FORCE OUTCOME | duel cleared")
        && force_runtime
            .reward_settlement_text
            .contains("+18 coins +60 XP");
    let agility_outcome_gate = agility_runtime
        .completed_task_ids
        .iter()
        .any(|task_id| task_id == agility_task_id)
        && agility_runtime.current_room_id == "delivery-dock"
        && !agility_runtime
            .active_task_ids
            .iter()
            .any(|task_id| task_id == agility_task_id)
        && agility_runtime
            .inventory_items
            .iter()
            .any(|item| item == "agility-scout-token")
        && agility_runtime.objective_status
            == "build_branch_completed:agility:task-agility-scout-route"
        && agility_runtime
            .reward_settlement_text
            .contains("AGILITY OUTCOME | scout route mapped")
        && agility_runtime
            .reward_settlement_text
            .contains("+16 coins +55 XP");
    let craft_outcome_gate = craft_runtime
        .completed_task_ids
        .iter()
        .any(|task_id| task_id == craft_task_id)
        && craft_runtime.current_room_id == "forge-workbench"
        && !craft_runtime
            .active_task_ids
            .iter()
            .any(|task_id| task_id == craft_task_id)
        && craft_runtime
            .inventory_items
            .iter()
            .any(|item| item == "craft-order-token")
        && craft_runtime.objective_status
            == "build_branch_completed:craft:task-craft-delivery-order"
        && craft_runtime
            .reward_settlement_text
            .contains("CRAFT OUTCOME | order delivered")
        && craft_runtime
            .reward_settlement_text
            .contains("+20 coins +65 XP");
    let wrong_branch_reward_guard_gate = force_wrong_craft_after_completion
        .get("enabled")
        .and_then(|value| value.as_bool())
        == Some(false)
        && force_wrong_craft_after_completion
            .get("reason")
            .and_then(|value| value.as_str())
            == Some("build_branch_requires_craft:task-craft-delivery-order")
        && !force_runtime
            .inventory_items
            .iter()
            .any(|item| item == "craft-order-token")
        && !force_runtime
            .reward_settlement_text
            .contains("CRAFT OUTCOME");
    let ui_settlement_gate = force_quest_after_complete
        .contains("force:task-force-combat-commission:completed")
        && force_quest_after_complete.contains("FORCE OUTCOME | duel cleared")
        && agility_quest_after_complete.contains("agility:task-agility-scout-route:completed")
        && agility_quest_after_complete.contains("AGILITY OUTCOME | scout route mapped")
        && craft_quest_after_complete.contains("craft:task-craft-delivery-order:completed")
        && craft_quest_after_complete.contains("CRAFT OUTCOME | order delivered");
    let green = all_branch_events_accepted
        && force_completion_guard_gate
        && target_room_completion_guard_gate
        && force_outcome_gate
        && agility_outcome_gate
        && craft_outcome_gate
        && wrong_branch_reward_guard_gate
        && ui_settlement_gate;

    let evidence = json!({
        "contract_version": TRILLIONNIUM_WORLD_BEVY_BUILD_BRANCH_OUTCOMES_CONTRACT,
        "build_branch_routes_contract": TRILLIONNIUM_WORLD_BEVY_BUILD_BRANCH_ROUTES_CONTRACT,
        "equipment_affix_build_contract": TRILLIONNIUM_WORLD_BEVY_EQUIPMENT_AFFIX_BUILD_CONTRACT,
        "green": green,
        "source_of_truth": "Active build-branch tasks settle through CompleteTask only after their branch-specific objective is proven; rewards are exclusive to the confirmed sash build.",
        "actor_id": actor_id,
        "all_branch_events_accepted": all_branch_events_accepted,
        "force_completion_guard_gate": force_completion_guard_gate,
        "target_room_completion_guard_gate": target_room_completion_guard_gate,
        "force_outcome_gate": force_outcome_gate,
        "agility_outcome_gate": agility_outcome_gate,
        "craft_outcome_gate": craft_outcome_gate,
        "wrong_branch_reward_guard_gate": wrong_branch_reward_guard_gate,
        "ui_settlement_gate": ui_settlement_gate,
        "availability_guards": {
            "force_before_victory_complete": force_before_victory_availability,
            "force_after_victory_complete": force_after_victory_availability,
            "agility_before_target_complete": agility_before_target_availability,
            "craft_before_target_complete": craft_before_target_availability,
            "force_wrong_craft_after_completion": force_wrong_craft_after_completion,
        },
        "quest_texts": {
            "force_after_complete": force_quest_after_complete,
            "agility_after_complete": agility_quest_after_complete,
            "craft_after_complete": craft_quest_after_complete,
        },
        "runtime_summaries": {
            "force": {
                "completed_task_ids": force_runtime.completed_task_ids,
                "active_task_ids": force_runtime.active_task_ids,
                "inventory_items": force_runtime.inventory_items,
                "coins": force_runtime.coins,
                "xp": force_runtime.xp,
                "objective_status": force_runtime.objective_status,
                "reward_settlement_text": force_runtime.reward_settlement_text,
                "combat_scene_state": force_runtime.combat_scene_state,
            },
            "agility": {
                "current_room_id": agility_runtime.current_room_id,
                "completed_task_ids": agility_runtime.completed_task_ids,
                "active_task_ids": agility_runtime.active_task_ids,
                "inventory_items": agility_runtime.inventory_items,
                "coins": agility_runtime.coins,
                "xp": agility_runtime.xp,
                "objective_status": agility_runtime.objective_status,
                "reward_settlement_text": agility_runtime.reward_settlement_text,
            },
            "craft": {
                "current_room_id": craft_runtime.current_room_id,
                "completed_task_ids": craft_runtime.completed_task_ids,
                "active_task_ids": craft_runtime.active_task_ids,
                "inventory_items": craft_runtime.inventory_items,
                "coins": craft_runtime.coins,
                "xp": craft_runtime.xp,
                "objective_status": craft_runtime.objective_status,
                "reward_settlement_text": craft_runtime.reward_settlement_text,
            },
        },
        "button_events": {
            "force": force_events,
            "agility": agility_events,
            "craft": craft_events,
        },
        "android_s5_real_device_claimed": false,
    });
    serde_json::to_string_pretty(&evidence).expect("build branch outcomes evidence serializes")
}

