fn native_runtime_probe_value_with_texture_manifest(
    actor_id: &str,
    world: &WorldState,
    character: &WorldTrillionniumCharacter,
    gameplay_log: &NativeGameplayLog,
    runtime: &NativeFirstPlayableRuntime,
    runtime_texture_probe: Option<&NativeRuntimeTextureManifestProbe>,
    runtime_texture_asset_store: Option<&NativeRuntimeTextureAssetStoreRegistration>,
) -> serde_json::Value {
    let current_node_id = player_node_id(world, actor_id).unwrap_or_else(|| "unknown".to_string());
    let runtime_json = serde_json::to_value(runtime).expect("runtime probe serializes runtime");
    let runtime_texture_probe = runtime_texture_probe
        .cloned()
        .unwrap_or_else(runtime_texture_manifest_probe_from_env);
    let runtime_texture_probe_gate = runtime_texture_probe.green
        && runtime_texture_probe.manifest_hash_gate
        && runtime_texture_probe.handle_gate;
    let runtime_texture_asset_store = runtime_texture_asset_store.cloned().unwrap_or_default();
    let runtime_texture_asset_store_gate = runtime_texture_asset_store.green
        && runtime_texture_asset_store.asset_store_registered_gate
        && !runtime_texture_asset_store.gpu_upload_claimed
        && !runtime_texture_asset_store.android_s5_real_device_claimed;
    json!({
        "contract_version": TRILLIONNIUM_WORLD_BEVY_RUNTIME_PROBE_CONTRACT,
        "actor_id": actor_id,
        "current_node_id": current_node_id,
        "first_minute_next_button": first_minute_onboarding_next_button(runtime),
        "player_action_coach": player_action_coach_text(runtime),
        "player_action_coach_action": player_action_coach_action_label(runtime),
        "input_feedback_toast": input_feedback_toast_text(runtime),
        "input_telemetry_summary": native_input_telemetry_summary(runtime),
        "last_input_feedback": runtime.input_feedback_history.last(),
        "runtime": runtime_json,
        "gameplay_log": {
            "turn": gameplay_log.turn,
            "last_action": gameplay_log.last_action,
            "last_result": gameplay_log.last_result,
            "last_rejection": gameplay_log.last_rejection,
        },
        "character": {
            "display_name": character.display_name,
            "title": character.title,
        },
        "runtime_texture_manifest_probe_contract": TRILLIONNIUM_WORLD_BEVY_RUNTIME_TEXTURE_MANIFEST_PROBE_CONTRACT,
        "runtime_texture_manifest_probe": runtime_texture_probe,
        "runtime_texture_manifest_probe_gate": runtime_texture_probe_gate,
        "runtime_texture_asset_store_registration_contract": TRILLIONNIUM_WORLD_BEVY_ASSET_STORE_REGISTRATION_CONTRACT,
        "runtime_texture_asset_store_registration": runtime_texture_asset_store,
        "runtime_texture_asset_store_registration_gate": runtime_texture_asset_store_gate,
        "android_s5_real_device_claimed": false,
    })
}

#[allow(clippy::too_many_arguments)]
pub fn write_native_runtime_probe(
    bootstrap: Res<NativeWorldBootstrap>,
    world: Res<AuthoritativeWorldResource>,
    tactics_character: Res<NativeTacticsCharacter>,
    gameplay_log: Res<NativeGameplayLog>,
    first_playable: Res<NativeFirstPlayableRuntime>,
    runtime_texture_probe: Option<Res<NativeRuntimeTextureManifestProbe>>,
    runtime_texture_asset_store: Option<Res<NativeRuntimeTextureAssetStoreRegistration>>,
    runtime_texture_sprite_binding_lookup: Option<Res<NativeRuntimeTextureSpriteBindingLookup>>,
    runtime_texture_sprite_asset_bindings: Query<&BevyWorldRuntimeTextureSpriteAssetBinding>,
) {
    let Ok(path) = env::var("TRNM_WORLD_BEVY_RUNTIME_PROBE_PATH") else {
        return;
    };
    let mut probe = native_runtime_probe_value_with_texture_manifest(
        &bootstrap.actor_id,
        &world.state,
        &tactics_character.character,
        &gameplay_log,
        &first_playable,
        runtime_texture_probe.as_deref(),
        runtime_texture_asset_store.as_deref(),
    );
    let sprite_bindings = runtime_texture_sprite_asset_bindings
        .iter()
        .cloned()
        .collect::<Vec<_>>();
    let sprite_binding_values = sprite_bindings
        .iter()
        .map(|binding| serde_json::to_value(binding).expect("sprite asset binding serializes"))
        .collect::<Vec<_>>();
    let sprite_binding_scene_layers = authored_binding_set(&sprite_binding_values, "scene_layer");
    let sprite_binding_material_slots =
        authored_binding_set(&sprite_binding_values, "material_slot");
    let sprite_binding_gate = runtime_texture_sprite_binding_lookup
        .as_deref()
        .map(|lookup| lookup.green && lookup.binding_count >= 32)
        .unwrap_or(false)
        && sprite_bindings.len() >= 24
        && ["map", "hud", "actor", "feedback"]
            .iter()
            .all(|layer| sprite_binding_scene_layers.contains(*layer))
        && sprite_bindings.iter().all(|binding| {
            binding.sprite_component_texture_handle_gate
                && binding.sprite_component_texture_atlas_gate
                && !binding.gpu_upload_claimed
                && !binding.android_s5_real_device_claimed
                && !binding.live_osm_ingestion_claimed
        });
    if let Some(probe_object) = probe.as_object_mut() {
        probe_object.insert(
            "runtime_texture_sprite_asset_binding_contract".to_string(),
            json!(TRILLIONNIUM_WORLD_BEVY_SPRITE_ASSET_BINDING_CONTRACT),
        );
        probe_object.insert(
            "runtime_texture_sprite_asset_binding_gate".to_string(),
            json!(sprite_binding_gate),
        );
        probe_object.insert(
            "runtime_texture_sprite_asset_binding".to_string(),
            json!({
                "contract_version": TRILLIONNIUM_WORLD_BEVY_SPRITE_ASSET_BINDING_CONTRACT,
                "bound_sprite_surface_count": sprite_bindings.len(),
                "runtime_manifest_binding_count": runtime_texture_sprite_binding_lookup
                    .as_deref()
                    .map(|lookup| lookup.binding_count)
                    .unwrap_or_default(),
                "scene_layers": sprite_binding_scene_layers.iter().cloned().collect::<Vec<_>>(),
                "material_slots": sprite_binding_material_slots.iter().cloned().collect::<Vec<_>>(),
                "sample": sprite_binding_values.iter().take(8).cloned().collect::<Vec<_>>(),
                "sprite_component_binding_gate": sprite_binding_gate,
                "asset_boundary": "runtime_probe_reports_sprite_component_asset_binding_not_gpu_upload_claim",
                "gpu_upload_claimed": false,
                "android_s5_real_device_claimed": false,
                "live_osm_ingestion_claimed": false,
            }),
        );
    }
    if let Ok(probe_json) = serde_json::to_string_pretty(&probe) {
        let probe_path = Path::new(&path);
        if let Some(parent) = probe_path.parent() {
            let _ = fs::create_dir_all(parent);
        }
        let tmp_path = probe_path.with_extension("json.tmp");
        if fs::write(&tmp_path, probe_json.as_bytes()).is_ok() {
            let _ = fs::rename(&tmp_path, probe_path);
        }
    }
}

fn first_minute_replay_input_feedback_signature_from_runtime_value(
    runtime: &serde_json::Value,
) -> Vec<serde_json::Value> {
    runtime
        .get("input_feedback_history")
        .and_then(|value| value.as_array())
        .map(|events| {
            events
                .iter()
                .map(|event| {
                    json!({
                        "input_source": sample_pointer_value(event, "/input_source"),
                        "action_label": sample_pointer_value(event, "/action_label"),
                        "accepted": sample_pointer_value(event, "/accepted"),
                        "reason": sample_pointer_value(event, "/reason"),
                        "room_id": sample_pointer_value(event, "/room_id"),
                    })
                })
                .collect::<Vec<_>>()
        })
        .unwrap_or_default()
}

