fn playable_snapshot_from_app(app: &App, actor_id: &str) -> NativePlayableSaveSnapshot {
    let world = app.world().resource::<AuthoritativeWorldResource>();
    let character = app.world().resource::<NativeTacticsCharacter>();
    let gameplay_log = app.world().resource::<NativeGameplayLog>();
    let first_playable = app.world().resource::<NativeFirstPlayableRuntime>();
    native_playable_save_snapshot(
        &world.state,
        &character.character,
        gameplay_log,
        first_playable,
        actor_id,
    )
}

fn restore_keyboard_runtime_app(snapshot: NativePlayableSaveSnapshot, actor_id: &str) -> App {
    let (world, character, gameplay_log, mut first_playable) =
        native_restore_playable_save_snapshot(snapshot);
    push_progression_checkpoint(&mut first_playable, "session_snapshot_restored");
    let mut app = build_keyboard_runtime_app(world.clone(), actor_id);
    app.world_mut()
        .insert_resource(AuthoritativeWorldResource { state: world });
    app.world_mut()
        .insert_resource(NativeTacticsCharacter { character });
    app.world_mut().insert_resource(gameplay_log);
    app.world_mut().insert_resource(first_playable);
    app.update();
    app
}

fn press_keyboard_script_step(app: &mut App, step: NativeKeyboardScriptInput) -> serde_json::Value {
    let key = step.key;
    let key_label = step.key_label;
    let action = step.action;
    let action_label = native_control_action_label(&action);
    let runtime_before = app.world().resource::<NativeFirstPlayableRuntime>().clone();
    let core_before = keyboard_runtime_guard_snapshot(&runtime_before);
    let availability_before = native_live_action_availability(&runtime_before, &action);
    {
        let mut input = app.world_mut().resource_mut::<ButtonInput<KeyCode>>();
        input.clear();
        input.press(key);
    }
    app.update();
    {
        let mut input = app.world_mut().resource_mut::<ButtonInput<KeyCode>>();
        input.release(key);
        input.clear();
    }
    app.update();
    let runtime_after = app.world().resource::<NativeFirstPlayableRuntime>().clone();
    let core_after = keyboard_runtime_guard_snapshot(&runtime_after);
    json!({
        "key": key_label,
        "action": action_label,
        "input_path": "ButtonInput<KeyCode> -> handle_native_keyboard_input -> apply_live_native_action",
        "accepted": availability_before.0,
        "availability_before": availability_before.1,
        "core_state_unchanged_when_disabled": !availability_before.0 && core_before == core_after,
        "current_room_before": runtime_before.current_room_id,
        "current_room_after": runtime_after.current_room_id,
        "feedback_after": runtime_after.last_feedback,
        "core_state_before": core_before,
        "core_state_after": core_after,
    })
}

fn run_bevy_keyboard_sequence(
    actor_id: &str,
    steps: Vec<NativeKeyboardScriptInput>,
) -> (
    Vec<serde_json::Value>,
    Vec<serde_json::Value>,
    Vec<serde_json::Value>,
    NativeFirstPlayableRuntime,
) {
    let mut app = build_keyboard_runtime_app(native_bevy_playable_fixture(), actor_id);
    let mut samples = vec![sample_live_app_state(&mut app, "initial")];
    let mut input_samples = vec![sample_live_input_state(
        app.world().resource::<NativeFirstPlayableRuntime>(),
        "initial",
    )];
    let mut keyboard_events = Vec::new();
    for step in steps {
        let key_label = step.key_label;
        let action_label = native_control_action_label(&step.action);
        let stage = format!("after_{key_label}_{action_label}");
        let event = press_keyboard_script_step(&mut app, step);
        keyboard_events.push(event);
        samples.push(sample_live_app_state(&mut app, &stage));
        input_samples.push(sample_live_input_state(
            app.world().resource::<NativeFirstPlayableRuntime>(),
            &stage,
        ));
    }
    let final_runtime = app.world().resource::<NativeFirstPlayableRuntime>().clone();
    (samples, input_samples, keyboard_events, final_runtime)
}

