pub fn native_input_telemetry_summary(
    runtime: &NativeFirstPlayableRuntime,
) -> NativeInputTelemetrySummary {
    let mut accepted_action_labels = Vec::new();
    let mut blocked_action_labels = Vec::new();
    let mut blocked_reasons = Vec::new();
    for event in &runtime.input_feedback_history {
        if event.accepted {
            push_unique_string(&mut accepted_action_labels, &event.action_label);
        } else {
            push_unique_string(&mut blocked_action_labels, &event.action_label);
            push_unique_string(&mut blocked_reasons, &event.reason);
        }
    }
    let last = runtime.input_feedback_history.last();
    NativeInputTelemetrySummary {
        contract_version: TRILLIONNIUM_WORLD_BEVY_INPUT_TELEMETRY_SUMMARY_CONTRACT.to_string(),
        source_of_truth: "NativeFirstPlayableRuntime.input_feedback_history".to_string(),
        total_events: runtime.input_feedback_history.len(),
        accepted_events: runtime
            .input_feedback_history
            .iter()
            .filter(|event| event.accepted)
            .count(),
        blocked_events: runtime
            .input_feedback_history
            .iter()
            .filter(|event| !event.accepted)
            .count(),
        keyboard_events: runtime
            .input_feedback_history
            .iter()
            .filter(|event| event.input_source == "keyboard")
            .count(),
        bevy_button_events: runtime
            .input_feedback_history
            .iter()
            .filter(|event| event.input_source == "bevy_button")
            .count(),
        direct_events: runtime
            .input_feedback_history
            .iter()
            .filter(|event| event.input_source == "direct")
            .count(),
        last_input_source: last.map(|event| event.input_source.clone()),
        last_action_label: last.map(|event| event.action_label.clone()),
        last_accepted: last.map(|event| event.accepted),
        last_reason: last.map(|event| event.reason.clone()),
        last_room_id: last.map(|event| event.room_id.clone()),
        accepted_action_labels,
        blocked_action_labels,
        blocked_reasons,
        final_objective_status: runtime.objective_status.clone(),
        final_room_id: runtime.current_room_id.clone(),
        equipment_ready: runtime.equipment_ready,
    }
}

fn replay_input_feedback_history(
    actor_id: &str,
    feedback_history: &[NativeInputFeedbackEvent],
) -> (NativeFirstPlayableRuntime, Vec<serde_json::Value>) {
    let mut world = native_bevy_playable_fixture();
    let mut character = WorldTrillionniumCharacter::default_for(actor_id);
    let mut gameplay_log = NativeGameplayLog {
        turn: 0,
        last_action: "boot".to_string(),
        last_result: "native_bevy_client_ready".to_string(),
        last_rejection: None,
    };
    let mut runtime = NativeFirstPlayableRuntime::default();
    let mut replay_events = Vec::new();
    for expected in feedback_history {
        if let Some(action) = native_control_action_from_label(&expected.action_label) {
            let _response = apply_live_native_action_with_source(
                &mut world,
                &mut character,
                &mut gameplay_log,
                &mut runtime,
                actor_id,
                &expected.input_source,
                action,
            );
            let replayed = runtime.input_feedback_history.last().cloned();
            replay_events.push(json!({
                "input_source": expected.input_source,
                "action_label": expected.action_label,
                "parsed": true,
                "expected_accepted": expected.accepted,
                "replay_accepted": replayed.as_ref().map(|event| event.accepted),
                "expected_reason": expected.reason,
                "replay_reason": replayed.as_ref().map(|event| event.reason.clone()),
                "expected_room_id": expected.room_id,
                "replay_room_id": replayed.as_ref().map(|event| event.room_id.clone()),
                "event_match": replayed.as_ref().is_some_and(|event| {
                    event.input_source == expected.input_source
                        && event.action_label == expected.action_label
                        && event.accepted == expected.accepted
                        && event.reason == expected.reason
                        && event.room_id == expected.room_id
                }),
            }));
        } else {
            replay_events.push(json!({
                "input_source": expected.input_source,
                "action_label": expected.action_label,
                "parsed": false,
                "event_match": false,
            }));
        }
    }
    (runtime, replay_events)
}

fn replay_events_all_parsed(events: &[serde_json::Value]) -> bool {
    events
        .iter()
        .all(|event| event.get("parsed").and_then(|value| value.as_bool()) == Some(true))
}

fn replay_events_all_match(events: &[serde_json::Value]) -> bool {
    events
        .iter()
        .all(|event| event.get("event_match").and_then(|value| value.as_bool()) == Some(true))
}

fn feedback_source_action_pairs(feedback_history: &[NativeInputFeedbackEvent]) -> Vec<String> {
    feedback_history
        .iter()
        .map(|event| format!("{}:{}", event.input_source, event.action_label))
        .collect()
}

fn input_replay_signature(runtime: &NativeFirstPlayableRuntime) -> serde_json::Value {
    let feedback = runtime
        .input_feedback_history
        .iter()
        .map(|event| {
            json!({
                "input_source": event.input_source,
                "action_label": event.action_label,
                "accepted": event.accepted,
                "reason": event.reason,
                "room_id": event.room_id,
            })
        })
        .collect::<Vec<_>>();
    json!({
        "objective_status": runtime.objective_status,
        "current_room_id": runtime.current_room_id,
        "completed_steps": runtime.completed_steps,
        "active_task_ids": runtime.active_task_ids,
        "completed_task_ids": runtime.completed_task_ids,
        "blocked_action_history": runtime.blocked_action_history,
        "combat_result_state": runtime.combat_result_state,
        "reward_claimed": runtime.reward_claimed,
        "equipment_ready": runtime.equipment_ready,
        "xp": runtime.xp,
        "coins": runtime.coins,
        "input_feedback_history": feedback,
    })
}

fn native_control_action_from_label(label: &str) -> Option<NativeControlAction> {
    if let Some(direction) = label.strip_prefix("MOVE:") {
        Some(NativeControlAction::Move {
            direction: direction.to_string(),
        })
    } else if let Some(group_id) = label.strip_prefix("RTS:SELECT:") {
        Some(NativeControlAction::RtsSelectControlGroup {
            group_id: group_id.to_string(),
        })
    } else if let Some(queue_id) = label.strip_prefix("RTS:QUEUE:") {
        Some(NativeControlAction::RtsQueueProduction {
            queue_id: queue_id.to_string(),
        })
    } else if let Some(rest) = label.strip_prefix("RTS:MOVE:") {
        Some(NativeControlAction::RtsMoveCommand {
            command_id: if rest.trim().is_empty() {
                "7,4:diamond".to_string()
            } else {
                rest.to_string()
            },
        })
    } else if let Some(target_id) = label.strip_prefix("RTS:ATTACK:") {
        Some(NativeControlAction::RtsAttackCommand {
            target_id: target_id.to_string(),
        })
    } else if let Some(ability_id) = label.strip_prefix("RTS:ABILITY:") {
        Some(NativeControlAction::RtsAbilityCommand {
            ability_id: ability_id.to_string(),
        })
    } else if let Some(room_id) = label.strip_prefix("ROOM:") {
        Some(NativeControlAction::EnterRoom {
            room_id: room_id.to_string(),
        })
    } else if let Some(npc_id) = label.strip_prefix("NPC:") {
        Some(NativeControlAction::InteractNpc {
            npc_id: npc_id.to_string(),
        })
    } else if let Some(task_id) = label.strip_prefix("TASK:") {
        Some(NativeControlAction::StartTask {
            task_id: task_id.to_string(),
        })
    } else if let Some(slot_id) = label.strip_prefix("SLOT:") {
        Some(NativeControlAction::SelectSlot {
            slot_id: normalize_session_slot_id(slot_id),
        })
    } else if let Some(slot_id) = label.strip_prefix("SAVE:") {
        if slot_id == "SLOT" {
            Some(NativeControlAction::SaveSlot)
        } else if slot_id == "SELECTED" {
            Some(NativeControlAction::SaveSelectedSlot)
        } else {
            Some(NativeControlAction::SaveSlotNamed {
                slot_id: normalize_session_slot_id(slot_id),
            })
        }
    } else if let Some(slot_id) = label.strip_prefix("LOAD:") {
        if slot_id == "SLOT" {
            Some(NativeControlAction::LoadSlot)
        } else if slot_id == "SELECTED" {
            Some(NativeControlAction::LoadSelectedSlot)
        } else {
            Some(NativeControlAction::LoadSlotNamed {
                slot_id: normalize_session_slot_id(slot_id),
            })
        }
    } else if let Some(item_id) = label.strip_prefix("EQUIP:") {
        Some(NativeControlAction::EquipItem {
            item_id: item_id.to_string(),
        })
    } else if let Some(title_id) = label.strip_prefix("TITLE:EQUIP:") {
        Some(NativeControlAction::EquipBuildTitle {
            title_id: title_id.to_string(),
        })
    } else if let Some(stat_id) = label.strip_prefix("STAT:") {
        match stat_id.to_ascii_lowercase().as_str() {
            "confirm" => Some(NativeControlAction::ConfirmStatAllocation),
            "cancel" => Some(NativeControlAction::CancelStatAllocation),
            normalized => Some(NativeControlAction::AllocateStat {
                stat_id: normalized.to_string(),
            }),
        }
    } else {
        match label {
            "TALK" => Some(NativeControlAction::Talk),
            "TRAIN" => Some(NativeControlAction::Train),
            "FIGHT" => Some(NativeControlAction::Fight),
            "COMPLETE" => Some(NativeControlAction::CompleteTask),
            "EQUIP" => Some(NativeControlAction::Equip),
            "COMBAT:attack" => Some(NativeControlAction::CombatAttack),
            "COMBAT:defend" => Some(NativeControlAction::CombatDefend),
            "COMBAT:potion" => Some(NativeControlAction::CombatUseItem),
            "COMBAT:escape" => Some(NativeControlAction::CombatEscape),
            "BAG:open" => Some(NativeControlAction::OpenBag),
            "LOOT:drop" => Some(NativeControlAction::LootDrop),
            "CONFIRM:OVERWRITE" => Some(NativeControlAction::ConfirmOverwriteSlot),
            "CANCEL:OVERWRITE" => Some(NativeControlAction::CancelOverwriteSlot),
            "CONTINUE:SESSION" => Some(NativeControlAction::ContinueAfterLoad),
            "PAUSE:MENU" => Some(NativeControlAction::PauseMenu),
            "RESUME:MENU" => Some(NativeControlAction::ResumeFromPause),
            "SETTINGS:OPEN" => Some(NativeControlAction::OpenSettingsMenu),
            "SETTINGS:BACK" => Some(NativeControlAction::CloseSettingsMenu),
            "SETTINGS:LOW_MOTION" => Some(NativeControlAction::ToggleLowMotion),
            "SETTINGS:VOLUME_DOWN" => Some(NativeControlAction::VolumeDown),
            "SETTINGS:VOLUME_UP" => Some(NativeControlAction::VolumeUp),
            "SETTINGS:INPUT_MODE" => Some(NativeControlAction::CycleInputMode),
            "TITLE:OPEN" => Some(NativeControlAction::OpenTitleMenu),
            "TITLE:NEW" => Some(NativeControlAction::NewGameFromTitle),
            "TITLE:LOAD" => Some(NativeControlAction::LoadFromTitle),
            "TITLE:CONTINUE" => Some(NativeControlAction::ContinueFromTitle),
            "TITLE:ROUTE" => Some(NativeControlAction::AcceptTitleRouteRecommendation),
            "CAMPAIGN:START" => Some(NativeControlAction::StartCampaignFromTitle),
            "CAMPAIGN:CONTINUE" => Some(NativeControlAction::ContinueCampaignFromTitle),
            "CAMPAIGN:REPLAY" => Some(NativeControlAction::ReplayCampaignFromTitle),
            "ACCOUNT:REGISTER" => Some(NativeControlAction::RegisterAccountFromTitle),
            "ACCOUNT:LOGIN" => Some(NativeControlAction::LoginAccountFromTitle),
            "ACCOUNT:CONTINUE" => Some(NativeControlAction::ContinueAccountFromTitle),
            "CREATE:NAME" => Some(NativeControlAction::CycleCharacterName),
            "CREATE:ARCHETYPE" => Some(NativeControlAction::CycleCharacterArchetype),
            "CREATE:CONFIRM" => Some(NativeControlAction::ConfirmCharacterCreate),
            "CREATE:BACK" => Some(NativeControlAction::BackToTitleFromCreate),
            _ => None,
        }
    }
}

fn press_live_button_action(app: &mut App, action: NativeControlAction) -> serde_json::Value {
    let runtime_before = app.world().resource::<NativeFirstPlayableRuntime>().clone();
    let availability_before = native_live_action_availability(&runtime_before, &action);
    let entity = live_button_entity(app.world_mut(), &action).unwrap_or_else(|| {
        panic!(
            "live button exists for {}",
            native_control_action_label(&action)
        )
    });
    app.world_mut()
        .entity_mut(entity)
        .insert(Interaction::Pressed);
    app.update();
    app.world_mut().entity_mut(entity).insert(Interaction::None);
    app.update();
    let runtime_after = app.world().resource::<NativeFirstPlayableRuntime>().clone();
    json!({
        "action": native_control_action_label(&action),
        "button_entity": format!("{entity:?}"),
        "accepted": availability_before.0,
        "availability_before": availability_before.1,
        "runtime_step_after": runtime_after.tutorial_step,
        "scene_after": runtime_after.map_scene,
        "feedback_after": runtime_after.last_feedback,
    })
}

fn live_button_entity(world: &mut World, action: &NativeControlAction) -> Option<Entity> {
    let mut query = world.query::<(Entity, &NativeControlAction, &Button)>();
    query
        .iter(world)
        .find(|(_, button_action, _)| *button_action == action)
        .map(|(entity, _, _)| entity)
}

