fn spawn_status_bar(
    commands: &mut Commands,
    kind: BevyWorldStatusBarKind,
    label: &str,
    position: Vec3,
    fill_color: Color,
) {
    let max_width = 156.0;
    commands.spawn((
        Text2d(label.to_string()),
        TextFont::from_font_size(10.0),
        TextColor(Color::srgb(0.84, 0.92, 0.86)),
        Transform::from_translation(position + Vec3::new(0.0, 10.0, 1.0)),
    ));
    commands.spawn((
        Sprite::from_color(
            Color::srgb(0.02, 0.04, 0.05),
            Vec2::new(max_width + 6.0, 10.0),
        ),
        Transform::from_translation(position + Vec3::new(max_width * 0.5, 0.0, -0.2)),
    ));
    commands.spawn((
        Sprite::from_color(fill_color, Vec2::new(max_width, 6.0)),
        Transform::from_translation(position + Vec3::new(max_width * 0.5, 0.0, 0.0)),
        BevyWorldStatusBar {
            kind,
            max_width,
            left_x: position.x,
        },
    ));
}

