fn spawn_static_chibi_actor(
    commands: &mut Commands,
    position: Vec3,
    label: &str,
    role: &str,
    body_color: Color,
    hair_color: Color,
) {
    let base = position + Vec3::new(0.0, 0.0, 4.2);
    let (marker_surface, marker_role, marker_focus, marker_color) = if role == "enemy" {
        (
            "enemy_threat_ring",
            "enemy_threat_marker",
            "enemy_danger",
            Color::srgba(0.98, 0.24, 0.18, 0.60),
        )
    } else {
        (
            "npc_interaction_ring",
            "npc_interaction_marker",
            "npc_talk_target",
            Color::srgba(0.74, 0.62, 1.0, 0.58),
        )
    };
    commands.spawn((
        Sprite::from_color(marker_color, Vec2::new(44.0, 14.0)),
        Transform::from_translation(base + Vec3::new(0.0, -17.0, -0.42)),
        BevyWorldTileRpgSurface {
            surface_id: marker_surface.to_string(),
            role: marker_role.to_string(),
        },
        scene_readability_surface(marker_surface, marker_role, marker_focus),
    ));
    for (surface_id, part_role, offset, size, color) in [
        (
            "sprite_shadow",
            "npc_shadow",
            Vec3::new(0.0, -14.0, -0.5),
            Vec2::new(36.0, 9.0),
            Color::srgba(0.02, 0.03, 0.03, 0.64),
        ),
        (
            "npc_chibi_sprite",
            role,
            Vec3::new(0.0, -5.0, 0.0),
            Vec2::new(24.0, 27.0),
            body_color,
        ),
        (
            "npc_chibi_head",
            "npc_head",
            Vec3::new(0.0, 13.0, 0.2),
            Vec2::new(22.0, 20.0),
            Color::srgb(0.90, 0.70, 0.50),
        ),
        (
            "npc_chibi_hair",
            "npc_hair",
            Vec3::new(0.0, 23.0, 0.3),
            Vec2::new(24.0, 8.0),
            hair_color,
        ),
        (
            if role == "enemy" {
                "enemy_facing_frame"
            } else {
                "npc_facing_frame"
            },
            "facing_marker",
            Vec3::new(0.0, 5.0, 0.4),
            Vec2::new(6.0, 11.0),
            Color::srgb(0.98, 0.90, 0.48),
        ),
    ] {
        commands.spawn((
            Sprite::from_color(color, size),
            Transform::from_translation(base + offset),
            BevyWorldTileRpgSurface {
                surface_id: surface_id.to_string(),
                role: part_role.to_string(),
            },
            BevyWorldSceneToken {
                token_id: format!("{label}:{part_role}"),
                role: role.to_string(),
            },
        ));
    }
    commands.spawn((
        Text2d(label.to_string()),
        TextFont::from_font_size(10.0),
        TextColor(Color::srgb(0.98, 0.96, 0.88)),
        Transform::from_translation(base + Vec3::new(0.0, 34.0, 0.6)),
        BevyWorldTileRpgSurface {
            surface_id: format!("{label}:map_actor_label"),
            role: "actor_runtime_label".to_string(),
        },
    ));
}

