fn node_scene_label(node_id: &str) -> &str {
    match node_id {
        "mirror-city-square" => "START",
        "league-coliseum" => "ARENA",
        "starter-studio" => "CRAFT",
        "zbj-market-gate" => "MARKET",
        "client-board" => "TASKS",
        "delivery-dock" => "DOCK",
        "ledger-office" => "LEDGER",
        "raid-hall" => "RAID",
        _ => "ROOM",
    }
}

fn text_adventure_room_title(node_id: &str) -> &'static str {
    match node_id {
        "mirror-city-square" => "Mirror City Square",
        "league-coliseum" => "League Coliseum",
        "starter-studio" => "Starter Studio",
        "zbj-market-gate" => "Market Gate",
        "client-board" => "Client Board",
        "delivery-dock" => "Delivery Dock",
        "ledger-office" => "Ledger Office",
        "raid-hall" => "Raid Hall",
        _ => "Unknown Room",
    }
}

fn text_adventure_room_description(node_id: &str) -> &'static str {
    match node_id {
        "mirror-city-square" => {
            "A compact city square lit by contract lanterns. A mentor watches the exits and waits to teach the first route skill."
        }
        "league-coliseum" => {
            "The starter arena is open. A practice opponent blocks the route reward until you resolve the first combat."
        }
        "starter-studio" => "A quiet workshop with tools, drafts, and route supplies.",
        "zbj-market-gate" => "Market notices are pinned beside the gate. Public contracts flow through here.",
        "client-board" => "A task board lists work orders, delivery claims, and route objectives.",
        "delivery-dock" => "Crates and courier tags mark the delivery dock.",
        "ledger-office" => "Ledger clerks reconcile rewards, refunds, and settlement holds.",
        "raid-hall" => "Raid teams gather here before harder route encounters.",
        _ => "This room has not received authored text yet.",
    }
}

fn text_adventure_item_label(item_id: &str) -> &'static str {
    if item_id == "route-guard-staff" {
        "Route Staff"
    } else if item_id == "none" {
        "none"
    } else {
        "Starter Gear"
    }
}

fn spawn_scene_role_token(
    commands: &mut Commands,
    layout: &BevyWorldLayout,
    node_id: &str,
    label: &str,
    role: &str,
    color: Color,
    offset: Vec3,
) {
    let Some(position) = layout.node_positions.get(node_id) else {
        return;
    };
    spawn_static_chibi_actor(
        commands,
        *position + offset,
        label,
        role,
        color,
        if role == "mentor" {
            Color::srgb(0.86, 0.82, 0.72)
        } else {
            Color::srgb(0.16, 0.08, 0.07)
        },
    );
    commands.spawn((BevyWorldSceneToken {
        token_id: format!("{node_id}:{role}"),
        role: role.to_string(),
    },));
}

