#[allow(clippy::too_many_arguments)]
fn tile_rpg_state_panel<C: Component>(
    panel_id: &str,
    title: &str,
    placeholder: &str,
    marker: C,
    left: f32,
    top: Option<f32>,
    bottom: Option<f32>,
    width: f32,
    height: f32,
) -> impl Bundle {
    let (map_role, alpha) = tile_rpg_map_occlusion_style(panel_id);
    (
        Node {
            position_type: PositionType::Absolute,
            top: top.map(px).unwrap_or(Val::Auto),
            bottom: bottom.map(px).unwrap_or(Val::Auto),
            left: px(left),
            width: px(width),
            height: px(height),
            border: UiRect::all(px(1)),
            padding: UiRect::all(px(8)),
            flex_direction: FlexDirection::Column,
            row_gap: px(4),
            ..default()
        },
        BackgroundColor(Color::srgba(0.025, 0.044, 0.041, alpha)),
        BorderColor::all(Color::srgb(0.54, 0.62, 0.46)),
        BevyWorldTileRpgPanel {
            panel_id: panel_id.to_string(),
        },
        BevyWorldMapOcclusionSurface {
            panel_id: panel_id.to_string(),
            map_role: map_role.to_string(),
            width,
            height,
            alpha,
        },
        ui_polish_surface(
            panel_id,
            "map_edge_hints",
            "micro_status_chip",
            "edge_anchor",
            "tertiary",
            7.5,
        ),
        children![
            (
                Text::new(title.to_string()),
                TextFont::from_font_size(7.5),
                TextColor(Color::srgb(0.94, 0.78, 0.36)),
            ),
            (
                Text::new(placeholder.to_string()),
                marker,
                TextFont::from_font_size(7.0),
                TextColor(Color::srgb(0.88, 0.94, 0.86)),
            ),
        ],
    )
}

fn tile_rpg_map_occlusion_style(panel_id: &str) -> (&'static str, f32) {
    match panel_id {
        "npc_dialogue_choice_panel" => ("edge_dialogue_hint", 0.26),
        "scene_transition_panel" => ("edge_scene_hint", 0.22),
        "walk_animation_panel" => ("edge_step_hint", 0.24),
        "combat_scene_panel" => ("edge_combat_hint", 0.24),
        _ => ("edge_status_hint", 0.26),
    }
}

