pub fn update_native_rts_scrollable_map_camera(
    time: Res<Time>,
    input: Res<ButtonInput<KeyCode>>,
    mouse_buttons: Res<ButtonInput<MouseButton>>,
    mouse_motion: Res<AccumulatedMouseMotion>,
    mouse_scroll: Res<AccumulatedMouseScroll>,
    windows: Query<&Window, With<PrimaryWindow>>,
    mut cameras: Query<&mut BevyRtsScrollableMapCamera>,
) {
    let Ok(window) = windows.single() else {
        return;
    };
    let Ok(mut camera) = cameras.single_mut() else {
        return;
    };
    let config = rts_scrollable_map_camera_config();
    let delta_seconds = time.delta_secs().clamp(1.0 / 120.0, 1.0 / 12.0);
    let shift_pressed = input.pressed(KeyCode::ShiftLeft) || input.pressed(KeyCode::ShiftRight);
    let mut pan_delta = Vec2::ZERO;
    let mut source_parts = Vec::new();

    if shift_pressed {
        if input.pressed(KeyCode::ArrowRight) || input.pressed(KeyCode::KeyD) {
            pan_delta.x += config.keyboard_speed * delta_seconds;
        }
        if input.pressed(KeyCode::ArrowLeft) || input.pressed(KeyCode::KeyA) {
            pan_delta.x -= config.keyboard_speed * delta_seconds;
        }
        if input.pressed(KeyCode::ArrowUp) || input.pressed(KeyCode::KeyW) {
            pan_delta.y += config.keyboard_speed * delta_seconds;
        }
        if input.pressed(KeyCode::ArrowDown) || input.pressed(KeyCode::KeyS) {
            pan_delta.y -= config.keyboard_speed * delta_seconds;
        }
        if pan_delta != Vec2::ZERO {
            source_parts.push("shift_keyboard_pan");
        }
    }

    let mut minimap_jump = None;
    if let Some(cursor) = window.cursor_position() {
        let width = window.width();
        let height = window.height();
        if cursor.x <= config.edge_band_pixels {
            pan_delta.x -= config.edge_speed * delta_seconds;
            source_parts.push("edge_scroll");
        } else if cursor.x >= width - config.edge_band_pixels {
            pan_delta.x += config.edge_speed * delta_seconds;
            source_parts.push("edge_scroll");
        }
        if cursor.y <= config.edge_band_pixels {
            pan_delta.y -= config.edge_speed * delta_seconds;
            source_parts.push("edge_scroll");
        } else if cursor.y >= height - config.edge_band_pixels {
            pan_delta.y += config.edge_speed * delta_seconds;
            source_parts.push("edge_scroll");
        }

        let minimap_left = 18.0;
        let minimap_bottom = 18.0;
        let minimap_width = 156.0;
        let minimap_height = 104.0;
        let in_minimap = cursor.x >= minimap_left
            && cursor.x <= minimap_left + minimap_width
            && cursor.y >= minimap_bottom
            && cursor.y <= minimap_bottom + minimap_height;
        if in_minimap && mouse_buttons.just_pressed(MouseButton::Left) {
            let norm_x = ((cursor.x - minimap_left) / minimap_width).clamp(0.0, 1.0);
            let norm_y = ((cursor.y - minimap_bottom) / minimap_height).clamp(0.0, 1.0);
            let target = Vec2::new(
                config.min_x + (config.max_x - config.min_x) * norm_x,
                config.min_y + (config.max_y - config.min_y) * norm_y,
            );
            minimap_jump = Some(("minimap_cursor_jump", target));
            source_parts.push("minimap_jump");
        }
    }

    if mouse_buttons.pressed(MouseButton::Middle) && mouse_motion.delta != Vec2::ZERO {
        pan_delta.x -= mouse_motion.delta.x * config.drag_world_units_per_pixel * camera.state.zoom;
        pan_delta.y += mouse_motion.delta.y * config.drag_world_units_per_pixel * camera.state.zoom;
        source_parts.push("middle_mouse_drag");
    }

    let zoom_delta = -mouse_scroll.delta.y * config.wheel_zoom_step;
    if zoom_delta.abs() > f32::EPSILON {
        source_parts.push("wheel_zoom");
    }

    if pan_delta == Vec2::ZERO && zoom_delta.abs() <= f32::EPSILON && minimap_jump.is_none() {
        return;
    }

    let source = if source_parts.is_empty() {
        "camera_idle".to_string()
    } else {
        source_parts.join("+")
    };
    let step = apply_rts_scrollable_map_camera_input(
        &source,
        camera.state,
        config,
        pan_delta,
        zoom_delta,
        minimap_jump,
    );
    camera.state = step.after;
}

pub fn apply_native_rts_scrollable_map_view(
    mut commands: Commands,
    camera_query: Query<&BevyRtsScrollableMapCamera>,
    mut surfaces: Query<(
        Entity,
        &BevyWorldTileRpgSurface,
        &mut Transform,
        Option<&BevyWorldScrollableMapAnchor>,
    )>,
) {
    let Ok(camera) = camera_query.single() else {
        return;
    };
    let viewport_center = rts_scrollable_map_viewport_center();
    let zoom_scale = (1.0 / camera.state.zoom).clamp(0.54, 1.52);
    let camera_center = Vec2::new(camera.state.center_x, camera.state.center_y);
    for (entity, surface, mut transform, anchor) in &mut surfaces {
        if !is_scrollable_map_surface_role(&surface.role) {
            continue;
        }
        let anchor = match anchor {
            Some(anchor) => *anchor,
            None => {
                let anchor = BevyWorldScrollableMapAnchor {
                    base_translation: transform.translation,
                    base_scale: transform.scale,
                };
                commands.entity(entity).insert(anchor);
                anchor
            }
        };
        let centered = Vec2::new(
            anchor.base_translation.x - viewport_center.x - camera_center.x,
            anchor.base_translation.y - viewport_center.y - camera_center.y,
        ) * zoom_scale;
        transform.translation.x = viewport_center.x + centered.x;
        transform.translation.y = viewport_center.y + centered.y;
        transform.translation.z = anchor.base_translation.z;
        transform.scale = Vec3::new(
            anchor.base_scale.x * zoom_scale,
            anchor.base_scale.y * zoom_scale,
            anchor.base_scale.z,
        );
    }
}

#[allow(clippy::too_many_arguments)]
pub fn handle_native_keyboard_input(
    input: Res<ButtonInput<KeyCode>>,
    bootstrap: Res<NativeWorldBootstrap>,
    mut world: ResMut<AuthoritativeWorldResource>,
    mut projection: ResMut<BevyWorldProjection>,
    mut tactics_character: ResMut<NativeTacticsCharacter>,
    mut gameplay_log: ResMut<NativeGameplayLog>,
    mut first_playable: ResMut<NativeFirstPlayableRuntime>,
    mut commands: Commands,
) {
    let control_action = if let Some(direction) = keyboard_direction(&input) {
        Some(NativeControlAction::Move {
            direction: direction.to_string(),
        })
    } else if input.just_pressed(KeyCode::KeyR) {
        Some(NativeControlAction::Talk)
    } else if input.just_pressed(KeyCode::KeyT) {
        Some(NativeControlAction::Train)
    } else if input.just_pressed(KeyCode::KeyF) || input.just_pressed(KeyCode::Space) {
        Some(NativeControlAction::Fight)
    } else if input.just_pressed(KeyCode::KeyC) {
        Some(NativeControlAction::CompleteTask)
    } else if input.just_pressed(KeyCode::KeyI) {
        Some(NativeControlAction::Equip)
    } else if input.just_pressed(KeyCode::KeyB) {
        Some(NativeControlAction::OpenBag)
    } else if input.just_pressed(KeyCode::KeyL) {
        Some(NativeControlAction::LootDrop)
    } else if input.just_pressed(KeyCode::KeyO) {
        Some(NativeControlAction::EquipItem {
            item_id: "bandit_sash".to_string(),
        })
    } else if input.just_pressed(KeyCode::KeyJ) {
        Some(NativeControlAction::CombatAttack)
    } else if input.just_pressed(KeyCode::KeyK) {
        Some(NativeControlAction::CombatDefend)
    } else if input.just_pressed(KeyCode::KeyU) {
        Some(NativeControlAction::CombatUseItem)
    } else if input.just_pressed(KeyCode::KeyG) {
        Some(NativeControlAction::AllocateStat {
            stat_id: "force".to_string(),
        })
    } else if input.just_pressed(KeyCode::KeyH) {
        Some(NativeControlAction::AllocateStat {
            stat_id: "agility".to_string(),
        })
    } else if input.just_pressed(KeyCode::KeyV) {
        Some(NativeControlAction::AllocateStat {
            stat_id: "craft".to_string(),
        })
    } else if input.just_pressed(KeyCode::KeyM) {
        Some(NativeControlAction::ConfirmStatAllocation)
    } else if input.just_pressed(KeyCode::KeyN) && first_playable.session_character_create_visible {
        Some(NativeControlAction::CycleCharacterName)
    } else if input.just_pressed(KeyCode::KeyY) && first_playable.session_character_create_visible {
        Some(NativeControlAction::CycleCharacterArchetype)
    } else if input.just_pressed(KeyCode::KeyP) || input.just_pressed(KeyCode::Escape) {
        if first_playable.pending_stat_allocation.is_some() {
            Some(NativeControlAction::CancelStatAllocation)
        } else if first_playable.session_character_create_visible {
            Some(NativeControlAction::BackToTitleFromCreate)
        } else {
            Some(NativeControlAction::PauseMenu)
        }
    } else if input.just_pressed(KeyCode::Enter) || input.just_pressed(KeyCode::NumpadEnter) {
        if first_playable.pending_stat_allocation.is_some() {
            Some(NativeControlAction::ConfirmStatAllocation)
        } else if first_playable.session_character_create_visible {
            Some(NativeControlAction::ConfirmCharacterCreate)
        } else if first_playable.session_resume_input_locked
            || first_playable.session_continue_cta_visible
        {
            Some(NativeControlAction::ContinueAfterLoad)
        } else if first_playable.session_pause_menu_visible
            || first_playable.session_pause_input_locked
        {
            Some(NativeControlAction::ResumeFromPause)
        } else if let Some(focus_action) =
            build_branch_title_route_action_focus_control_action(&first_playable)
        {
            Some(focus_action)
        } else if let Some(next_action) =
            native_control_action_from_label(first_minute_onboarding_next_button(&first_playable))
        {
            Some(next_action)
        } else {
            Some(NativeControlAction::ContinueAfterLoad)
        }
    } else {
        None
    };

    if let Some(action) = control_action {
        let response = apply_live_native_action_with_source(
            &mut world.state,
            &mut tactics_character.character,
            &mut gameplay_log,
            &mut first_playable,
            &bootstrap.actor_id,
            "keyboard",
            action,
        );
        *projection = projection_resource(&world.state, &bootstrap.actor_id);
        if let Some(response) = response {
            commands.insert_resource(LastNativeCommandResponse {
                response_json: serde_json::to_string(&response)
                    .expect("native control response serializes"),
            });
        }
    }
}

#[allow(clippy::too_many_arguments, clippy::type_complexity)]
pub fn handle_native_control_buttons(
    mut input_focus: ResMut<InputFocus>,
    mut interactions: Query<
        (
            Entity,
            &Interaction,
            &NativeControlAction,
            &mut BackgroundColor,
            &mut BorderColor,
            &mut Button,
        ),
        (Changed<Interaction>, With<Button>),
    >,
    bootstrap: Res<NativeWorldBootstrap>,
    mut world: ResMut<AuthoritativeWorldResource>,
    mut projection: ResMut<BevyWorldProjection>,
    mut tactics_character: ResMut<NativeTacticsCharacter>,
    mut gameplay_log: ResMut<NativeGameplayLog>,
    mut first_playable: ResMut<NativeFirstPlayableRuntime>,
    mut commands: Commands,
) {
    for (entity, interaction, action, mut color, mut border, mut button) in &mut interactions {
        match *interaction {
            Interaction::Pressed => {
                input_focus.set(entity, FocusCause::Pressed);
                *color = BackgroundColor(Color::srgb(0.34, 0.52, 0.32));
                *border = BorderColor::all(Color::srgb(0.96, 0.86, 0.45));
                button.set_changed();
                let response = apply_live_native_action_with_source(
                    &mut world.state,
                    &mut tactics_character.character,
                    &mut gameplay_log,
                    &mut first_playable,
                    &bootstrap.actor_id,
                    "bevy_button",
                    action.clone(),
                );
                *projection = projection_resource(&world.state, &bootstrap.actor_id);
                if let Some(response) = response {
                    commands.insert_resource(LastNativeCommandResponse {
                        response_json: serde_json::to_string(&response)
                            .expect("native control response serializes"),
                    });
                }
            }
            Interaction::Hovered => {
                input_focus.set(entity, FocusCause::Pressed);
                *color = BackgroundColor(Color::srgb(0.16, 0.26, 0.27));
                *border = BorderColor::all(Color::srgb(0.70, 0.78, 0.72));
                button.set_changed();
            }
            Interaction::None => {
                input_focus.clear();
                *color = BackgroundColor(Color::srgb(0.10, 0.18, 0.19));
                *border = BorderColor::all(Color::srgb(0.45, 0.55, 0.52));
            }
        }
    }
}

pub fn apply_live_native_action(
    world: &mut WorldState,
    character: &mut WorldTrillionniumCharacter,
    gameplay_log: &mut NativeGameplayLog,
    first_playable: &mut NativeFirstPlayableRuntime,
    actor_id: &str,
    action: NativeControlAction,
) -> Option<WorldApiCommandResponse> {
    apply_live_native_action_with_source(
        world,
        character,
        gameplay_log,
        first_playable,
        actor_id,
        "direct",
        action,
    )
}

pub fn apply_live_native_action_with_source(
    world: &mut WorldState,
    character: &mut WorldTrillionniumCharacter,
    gameplay_log: &mut NativeGameplayLog,
    first_playable: &mut NativeFirstPlayableRuntime,
    actor_id: &str,
    input_source: &str,
    action: NativeControlAction,
) -> Option<WorldApiCommandResponse> {
    let availability = native_live_action_availability(first_playable, &action);
    let label = native_control_action_label(&action);
    if !availability.0 {
        gameplay_log.turn += 1;
        gameplay_log.last_action = format!("blocked:{label}");
        gameplay_log.last_result = availability.1.clone();
        gameplay_log.last_rejection = Some(availability.1.clone());
        push_history(
            &mut first_playable.blocked_action_history,
            &format!("{label}:{}", availability.1),
        );
        let feedback_text = if label.starts_with("RTS:") {
            classic_rts_blocked_feedback_toast(input_source, &label, &availability.1)
        } else {
            format!("Input blocked: {label} ({})", availability.1)
        };
        push_feedback_event(first_playable, &feedback_text);
        if label.starts_with("RTS:")
            && classic_rts_should_emit_rejection_feedback_chip(input_source)
        {
            push_history(
                &mut first_playable.rts_command_queue,
                &classic_rts_rejection_feedback_chip(&label, &availability.1),
            );
        }
        refresh_contextual_action_runtime(first_playable);
        record_input_feedback(first_playable, input_source, &label, false, &availability.1);
        return None;
    }
    let action_for_stamp = action.clone();
    let response = apply_native_first_playable_action(
        world,
        character,
        gameplay_log,
        first_playable,
        actor_id,
        action,
    );
    #[cfg(not(target_os = "android"))]
    apply_classic_rts_command_stamp_for_action(first_playable, input_source, &action_for_stamp);
    record_input_feedback(first_playable, input_source, &label, true, &availability.1);
    response
}

fn active_build_title_route_accept_availability(
    runtime: &NativeFirstPlayableRuntime,
) -> (bool, String) {
    let Some((_, stat_id, _effect_id)) = active_build_title_parts(runtime) else {
        return (false, "title_route_recommendation_missing".to_string());
    };
    let Some(task_id) = build_branch_title_recommended_task_id_for_runtime_stat(runtime, stat_id)
    else {
        return (false, format!("title_route_complete:{stat_id}"));
    };
    let plan = scene_pack_route_plan_for_task(&runtime.current_room_id, task_id);
    if let Some(blocked_reason) = plan.blocked_reason.as_deref() {
        return (
            false,
            format!("title_route_step_blocked:{task_id}:{blocked_reason}"),
        );
    }
    if runtime.current_room_id != plan.target_room_id
        && build_mastery_room_override(runtime, &plan.target_room_id)
    {
        return if runtime
            .available_room_exits
            .iter()
            .any(|exit| exit == &plan.target_room_id)
        {
            (
                true,
                format!(
                    "enabled_title_route_step:{stat_id}:{task_id}:{}",
                    plan.target_room_id
                ),
            )
        } else {
            (
                false,
                format!(
                    "title_route_step_blocked:{task_id}:room_not_adjacent:{}",
                    plan.target_room_id
                ),
            )
        };
    }
    if runtime.current_room_id == plan.target_room_id {
        let start_action = NativeControlAction::StartTask {
            task_id: task_id.to_string(),
        };
        let (enabled, reason) = native_live_action_availability(runtime, &start_action);
        return if enabled {
            (
                true,
                format!("enabled_title_route_start:{stat_id}:{task_id}"),
            )
        } else {
            (false, format!("title_route_start_blocked:{reason}"))
        };
    }
    let Some(next_room_id) = plan.steps.first().map(|step| step.to_room_id.clone()) else {
        return (false, format!("title_route_waiting:{task_id}"));
    };
    if scene_pack_room(&next_room_id).is_none() {
        return (
            false,
            format!("title_route_step_blocked:{task_id}:unknown_room:{next_room_id}"),
        );
    }
    if runtime
        .available_room_exits
        .iter()
        .any(|exit| exit == &next_room_id)
    {
        (
            true,
            format!("enabled_title_route_step:{stat_id}:{task_id}:{next_room_id}"),
        )
    } else {
        (
            false,
            format!("title_route_step_blocked:{task_id}:room_not_adjacent:{next_room_id}"),
        )
    }
}

pub fn native_live_action_availability(
    runtime: &NativeFirstPlayableRuntime,
    action: &NativeControlAction,
) -> (bool, String) {
    if matches!(action, NativeControlAction::ContinueAfterLoad) {
        return if runtime.session_resume_input_locked || runtime.session_continue_cta_visible {
            (true, "enabled_session_resume_continue".to_string())
        } else {
            (false, "session_resume_not_active".to_string())
        };
    }
    if matches!(
        action,
        NativeControlAction::RegisterAccountFromTitle
            | NativeControlAction::LoginAccountFromTitle
            | NativeControlAction::ContinueAccountFromTitle
    ) {
        let reason = match action {
            NativeControlAction::RegisterAccountFromTitle => "enabled_title_account_register",
            NativeControlAction::LoginAccountFromTitle => "enabled_title_account_login",
            NativeControlAction::ContinueAccountFromTitle => "enabled_title_account_continue",
            _ => unreachable!("matched account title flow action"),
        };
        return (true, reason.to_string());
    }
    if runtime.session_resume_input_locked {
        return (false, "session_resume_continue_required".to_string());
    }
    if matches!(
        action,
        NativeControlAction::CycleCharacterName
            | NativeControlAction::CycleCharacterArchetype
            | NativeControlAction::ConfirmCharacterCreate
            | NativeControlAction::BackToTitleFromCreate
    ) {
        return if runtime.session_character_create_visible
            || runtime.session_character_create_input_locked
        {
            let reason = match action {
                NativeControlAction::CycleCharacterName => "enabled_character_name_cycle",
                NativeControlAction::CycleCharacterArchetype => "enabled_character_archetype_cycle",
                NativeControlAction::ConfirmCharacterCreate => "enabled_character_create_confirm",
                NativeControlAction::BackToTitleFromCreate => "enabled_character_create_back",
                _ => unreachable!("matched character create action"),
            };
            (true, reason.to_string())
        } else {
            (false, "character_create_not_active".to_string())
        };
    }
    if runtime.session_character_create_input_locked && !character_create_allows_action(action) {
        return (false, "character_create_confirm_required".to_string());
    }
    if matches!(action, NativeControlAction::OpenTitleMenu) {
        return if runtime.session_title_menu_visible || runtime.session_title_input_locked {
            (false, "title_menu_already_open".to_string())
        } else {
            (true, "enabled_open_title_menu".to_string())
        };
    }
    if matches!(action, NativeControlAction::NewGameFromTitle) {
        return if runtime.session_title_menu_visible || runtime.session_title_input_locked {
            (true, "enabled_title_new_game".to_string())
        } else {
            (false, "title_menu_not_active".to_string())
        };
    }
    if matches!(
        action,
        NativeControlAction::StartCampaignFromTitle | NativeControlAction::ReplayCampaignFromTitle
    ) {
        let reason = if matches!(action, NativeControlAction::ReplayCampaignFromTitle) {
            "enabled_title_campaign_replay"
        } else {
            "enabled_title_campaign_start"
        };
        return if runtime.session_title_menu_visible || runtime.session_title_input_locked {
            (true, reason.to_string())
        } else {
            (false, "title_menu_not_active".to_string())
        };
    }
    if matches!(action, NativeControlAction::ContinueCampaignFromTitle) {
        let slot_path = native_campaign_entry_slot_path();
        return if !(runtime.session_title_menu_visible || runtime.session_title_input_locked) {
            (false, "title_menu_not_active".to_string())
        } else if Path::new(&slot_path).exists() {
            (true, "enabled_title_campaign_continue".to_string())
        } else {
            (false, "title_campaign_continue_slot_missing".to_string())
        };
    }
    if matches!(action, NativeControlAction::LoadFromTitle) {
        let slot_id = normalize_session_slot_id(&runtime.session_selected_slot_id);
        let slot_path = native_action_session_slot_path(&slot_id);
        return if !(runtime.session_title_menu_visible || runtime.session_title_input_locked) {
            (false, "title_menu_not_active".to_string())
        } else if Path::new(&slot_path).exists() {
            (true, format!("enabled_title_load_slot:{slot_id}"))
        } else {
            (false, format!("title_load_slot_missing:{slot_id}"))
        };
    }
    if matches!(action, NativeControlAction::ContinueFromTitle) {
        let slot_id = normalize_session_slot_id(&runtime.session_selected_slot_id);
        let slot_path = native_action_session_slot_path(&slot_id);
        return if !(runtime.session_title_menu_visible || runtime.session_title_input_locked) {
            (false, "title_menu_not_active".to_string())
        } else if Path::new(&slot_path).exists() {
            (true, format!("enabled_title_continue_slot:{slot_id}"))
        } else {
            (false, format!("title_continue_slot_missing:{slot_id}"))
        };
    }
    if runtime.session_title_input_locked && !title_menu_allows_action(action) {
        return (false, "title_menu_choice_required".to_string());
    }
    if matches!(action, NativeControlAction::PauseMenu) {
        return if runtime.session_pause_menu_visible || runtime.session_pause_input_locked {
            (false, "pause_menu_already_open".to_string())
        } else {
            (true, "enabled_open_pause_menu".to_string())
        };
    }
    if matches!(action, NativeControlAction::ResumeFromPause) {
        return if runtime.session_pause_menu_visible || runtime.session_pause_input_locked {
            (true, "enabled_pause_resume".to_string())
        } else {
            (false, "pause_menu_not_active".to_string())
        };
    }
    if matches!(action, NativeControlAction::OpenSettingsMenu) {
        return if !(runtime.session_pause_menu_visible || runtime.session_pause_input_locked) {
            (false, "pause_menu_required_before_settings".to_string())
        } else if runtime.session_settings_menu_visible {
            (false, "settings_menu_already_open".to_string())
        } else {
            (true, "enabled_open_settings_menu".to_string())
        };
    }
    if matches!(action, NativeControlAction::CloseSettingsMenu) {
        return if runtime.session_settings_menu_visible {
            (true, "enabled_close_settings_menu".to_string())
        } else {
            (false, "settings_menu_not_active".to_string())
        };
    }
    if matches!(
        action,
        NativeControlAction::ToggleLowMotion
            | NativeControlAction::VolumeDown
            | NativeControlAction::VolumeUp
            | NativeControlAction::CycleInputMode
    ) {
        return if runtime.session_settings_menu_visible {
            (true, "enabled_settings_adjustment".to_string())
        } else if runtime.session_pause_menu_visible || runtime.session_pause_input_locked {
            (false, "settings_menu_required".to_string())
        } else {
            (false, "pause_menu_required_before_settings".to_string())
        };
    }
    if runtime.session_pause_input_locked && !pause_menu_allows_action(action) {
        return (false, "pause_menu_resume_required".to_string());
    }
    if runtime.movement_input_locked {
        return (false, "movement_input_locked".to_string());
    }
    match action {
        NativeControlAction::RtsSelectControlGroup { group_id } => {
            return if group_id.trim().is_empty() {
                (false, "rts_group_id_required".to_string())
            } else {
                (true, format!("enabled_rts_select_group:{group_id}"))
            };
        }
        NativeControlAction::RtsQueueProduction { queue_id } => {
            return if queue_id.trim().is_empty() {
                (false, "rts_queue_id_required".to_string())
            } else if let Some(reason) = classic_rts_queue_unaffordable_reason(runtime, queue_id) {
                (false, reason)
            } else {
                (true, format!("enabled_rts_queue:{queue_id}"))
            };
        }
        NativeControlAction::RtsMoveCommand { command_id } => {
            let (tile_id, formation) = classic_rts_move_command_parts(command_id);
            return if runtime.rts_control_group_id.is_none()
                && runtime.rts_selected_unit_ids.is_empty()
            {
                (false, "rts_group_selection_required".to_string())
            } else if classic_parse_rts_tile(tile_id).is_none() {
                (false, format!("rts_invalid_tile:{tile_id}"))
            } else if formation.trim().is_empty() {
                (false, "rts_formation_required".to_string())
            } else {
                (true, format!("enabled_rts_move:{tile_id}:{formation}"))
            };
        }
        NativeControlAction::RtsAttackCommand { target_id } => {
            return if runtime.rts_control_group_id.is_none()
                && runtime.rts_selected_unit_ids.is_empty()
            {
                (false, "rts_group_selection_required".to_string())
            } else if target_id.trim().is_empty() {
                (false, "rts_attack_target_required".to_string())
            } else {
                (true, format!("enabled_rts_attack:{target_id}"))
            };
        }
        NativeControlAction::RtsAbilityCommand { ability_id } => {
            return if runtime.rts_attack_target_id.is_none() {
                (false, "rts_attack_required_before_ability".to_string())
            } else if ability_id.trim().is_empty() {
                (false, "rts_ability_required".to_string())
            } else {
                (true, format!("enabled_rts_ability:{ability_id}"))
            };
        }
        _ => {}
    }
    match action {
        NativeControlAction::Talk => {
            if runtime
                .completed_steps
                .iter()
                .any(|step| step == "talk_to_mentor")
            {
                (false, "mentor_dialogue_already_opened".to_string())
            } else {
                (true, "enabled_at_mentor_tile".to_string())
            }
        }
        NativeControlAction::Train => {
            if runtime
                .completed_steps
                .iter()
                .any(|step| step == "train_basic_unarmed")
            {
                (false, "training_already_complete".to_string())
            } else if runtime.dialogue_overlay_visible
                || runtime
                    .completed_steps
                    .iter()
                    .any(|step| step == "talk_to_mentor")
            {
                (true, "enabled_after_dialogue_choice".to_string())
            } else {
                (false, "talk_required_before_training".to_string())
            }
        }
        NativeControlAction::Move { direction } => {
            if direction == "wait" {
                (true, "wait_allowed".to_string())
            } else if runtime
                .completed_steps
                .iter()
                .any(|step| step == "arrive_at_first_objective")
            {
                (true, format!("enabled_local_map_step_{direction}"))
            } else if runtime
                .completed_steps
                .iter()
                .any(|step| step == "train_basic_unarmed")
            {
                (true, format!("enabled_route_step_{direction}"))
            } else {
                (true, format!("enabled_local_map_step_{direction}"))
            }
        }
        NativeControlAction::Fight => {
            if runtime
                .completed_steps
                .iter()
                .any(|step| step == "resolve_first_combat")
            {
                (false, "combat_already_resolved".to_string())
            } else if runtime
                .completed_steps
                .iter()
                .any(|step| step == "arrive_at_first_objective")
            {
                (true, "enabled_enemy_adjacent".to_string())
            } else {
                (false, "arena_required_before_fight".to_string())
            }
        }
        NativeControlAction::CompleteTask => {
            if let Some(task_id) = active_build_branch_mastery_challenge_task_id(runtime) {
                build_branch_mastery_challenge_completion_availability(runtime, task_id)
            } else if let Some(task_id) = active_build_branch_followup_task_id(runtime) {
                build_branch_followup_completion_availability(runtime, task_id)
            } else if let Some(task_id) = active_build_branch_task_id(runtime) {
                build_branch_completion_availability(runtime, task_id)
            } else if runtime
                .completed_steps
                .iter()
                .any(|step| step == "resolve_first_combat")
            {
                (true, "enabled_after_combat".to_string())
            } else {
                (false, "combat_required_before_task_completion".to_string())
            }
        }
        NativeControlAction::Equip => {
            if runtime.equipment_ready {
                (false, "equipment_already_ready".to_string())
            } else if runtime.reward_claimed {
                (true, "enabled_after_reward_claim".to_string())
            } else {
                (false, "reward_required_before_equip".to_string())
            }
        }
        NativeControlAction::EnterRoom { room_id } => {
            if runtime.current_room_id == *room_id {
                (false, "already_in_room".to_string())
            } else if runtime
                .available_room_exits
                .iter()
                .any(|exit| exit == room_id)
            {
                (true, format!("enabled_exit_to_{room_id}"))
            } else {
                (false, format!("room_not_adjacent:{room_id}"))
            }
        }
        NativeControlAction::InteractNpc { npc_id } => {
            if runtime
                .active_room_npc_ids
                .iter()
                .any(|available| available == npc_id)
            {
                (true, format!("enabled_npc_{npc_id}"))
            } else {
                (false, format!("npc_not_in_current_room:{npc_id}"))
            }
        }
        NativeControlAction::StartTask { task_id } => {
            if let Some(required_stat) = build_branch_task_required_stat(task_id) {
                if !runtime_has_equipped_bandit_sash(runtime) {
                    (false, format!("build_branch_requires_sash:{task_id}"))
                } else if !runtime_has_active_sash_stat(runtime, required_stat) {
                    (
                        false,
                        format!("build_branch_requires_{required_stat}:{task_id}"),
                    )
                } else if runtime
                    .completed_task_ids
                    .iter()
                    .any(|completed| completed == task_id)
                {
                    (false, format!("task_already_completed:{task_id}"))
                } else if runtime
                    .active_task_ids
                    .iter()
                    .any(|active| active == task_id)
                {
                    (false, format!("task_already_active:{task_id}"))
                } else if !runtime
                    .unlocked_task_ids
                    .iter()
                    .any(|unlocked| unlocked == task_id)
                {
                    (false, format!("task_locked_by_progression:{task_id}"))
                } else if runtime
                    .available_task_ids
                    .iter()
                    .any(|available| available == task_id)
                {
                    (
                        true,
                        format!("enabled_build_branch_{required_stat}:{task_id}"),
                    )
                } else {
                    (false, format!("task_not_in_current_room:{task_id}"))
                }
            } else if let Some(required_stat) =
                build_branch_mastery_challenge_required_stat(task_id)
            {
                if !runtime_has_build_mastery(runtime, required_stat) {
                    (
                        false,
                        format!("mastery_challenge_requires_{required_stat}:{task_id}"),
                    )
                } else if runtime
                    .completed_task_ids
                    .iter()
                    .any(|completed| completed == task_id)
                {
                    (false, format!("task_already_completed:{task_id}"))
                } else if runtime
                    .active_task_ids
                    .iter()
                    .any(|active| active == task_id)
                {
                    (false, format!("task_already_active:{task_id}"))
                } else if !runtime
                    .unlocked_task_ids
                    .iter()
                    .any(|unlocked| unlocked == task_id)
                {
                    (false, format!("task_locked_by_progression:{task_id}"))
                } else if runtime
                    .available_task_ids
                    .iter()
                    .any(|available| available == task_id)
                {
                    (
                        true,
                        format!("enabled_build_mastery_challenge_{required_stat}:{task_id}"),
                    )
                } else {
                    (false, format!("task_not_in_current_room:{task_id}"))
                }
            } else if runtime
                .completed_task_ids
                .iter()
                .any(|completed| completed == task_id)
            {
                (false, format!("task_already_completed:{task_id}"))
            } else if runtime
                .active_task_ids
                .iter()
                .any(|active| active == task_id)
            {
                (false, format!("task_already_active:{task_id}"))
            } else if runtime
                .available_task_ids
                .iter()
                .any(|available| available == task_id)
                && (!task_requires_progression_unlock(task_id)
                    || runtime
                        .unlocked_task_ids
                        .iter()
                        .any(|unlocked| unlocked == task_id))
            {
                (true, format!("enabled_task_{task_id}"))
            } else if task_requires_progression_unlock(task_id)
                && !runtime
                    .unlocked_task_ids
                    .iter()
                    .any(|unlocked| unlocked == task_id)
            {
                (false, format!("task_locked_by_progression:{task_id}"))
            } else {
                (false, format!("task_not_in_current_room:{task_id}"))
            }
        }
        NativeControlAction::CombatAttack
        | NativeControlAction::CombatDefend
        | NativeControlAction::CombatEscape => {
            if runtime.current_room_id == "league-coliseum"
                && runtime.combat_result_state != "victory"
                && runtime.combat_result_state != "escaped"
            {
                (true, "enabled_turn_combat".to_string())
            } else if runtime.current_room_id != "league-coliseum" {
                (false, "arena_required_before_turn_combat".to_string())
            } else {
                (
                    false,
                    format!("combat_already_{}", runtime.combat_result_state),
                )
            }
        }
        NativeControlAction::CombatUseItem => {
            if runtime.current_room_id != "league-coliseum" {
                (false, "arena_required_before_turn_combat".to_string())
            } else if runtime
                .inventory_items
                .iter()
                .any(|item| item == "small_healing_pill")
                && runtime.combat_result_state != "victory"
                && runtime.combat_result_state != "escaped"
            {
                (true, "enabled_combat_potion".to_string())
            } else {
                (false, "combat_potion_unavailable".to_string())
            }
        }
        NativeControlAction::OpenBag => (true, "bag_available".to_string()),
        NativeControlAction::LootDrop => {
            if runtime.combat_result_state == "victory"
                && runtime
                    .dropped_items
                    .iter()
                    .any(|item| item == "bandit_sash")
            {
                (true, "enabled_after_victory_drop".to_string())
            } else if runtime.combat_result_state != "victory" {
                (false, "victory_required_before_loot".to_string())
            } else {
                (false, "no_unclaimed_drop".to_string())
            }
        }
        NativeControlAction::EquipItem { item_id } => {
            if runtime.inventory_items.iter().any(|item| item == item_id) {
                (true, format!("enabled_inventory_item:{item_id}"))
            } else if runtime.equipped_items.iter().any(|item| item == item_id) {
                (false, format!("item_already_equipped:{item_id}"))
            } else {
                (false, format!("item_not_in_bag:{item_id}"))
            }
        }
        NativeControlAction::EquipBuildTitle { title_id } => {
            let Some(stat_id) = build_branch_mastery_title_stat_for_id(title_id) else {
                return (false, format!("unknown_build_title:{title_id}"));
            };
            if !runtime_has_build_title_id(runtime, title_id) {
                (false, format!("build_title_locked:{title_id}"))
            } else if runtime.active_build_title_id.as_deref() == Some(title_id.as_str()) {
                (false, format!("build_title_already_active:{title_id}"))
            } else {
                (
                    true,
                    format!("enabled_build_title_equip:{stat_id}:{title_id}"),
                )
            }
        }
        NativeControlAction::AcceptTitleRouteRecommendation => {
            active_build_title_route_accept_availability(runtime)
        }
        NativeControlAction::AllocateStat { stat_id } => {
            if !valid_growth_stat_id(stat_id) {
                (false, format!("invalid_stat:{stat_id}"))
            } else if runtime
                .allocated_stat_points
                .iter()
                .any(|allocated| allocated == stat_id)
            {
                (false, format!("stat_already_allocated:{stat_id}"))
            } else if runtime.growth_level < 2 {
                (false, "growth_level_required".to_string())
            } else if runtime.growth_stat_points == 0 {
                (false, "stat_point_required".to_string())
            } else if runtime.pending_stat_allocation.as_deref() == Some(stat_id.as_str()) {
                (false, format!("stat_confirmation_pending:{stat_id}"))
            } else if runtime.pending_stat_allocation.is_some() {
                (true, format!("enabled_stat_preview_switch:{stat_id}"))
            } else {
                (true, format!("enabled_stat_preview:{stat_id}"))
            }
        }
        NativeControlAction::ConfirmStatAllocation => {
            if let Some(stat_id) = runtime.pending_stat_allocation.as_deref() {
                if runtime.growth_stat_points == 0 {
                    (false, "stat_point_required".to_string())
                } else if !valid_growth_stat_id(stat_id) {
                    (false, format!("invalid_stat:{stat_id}"))
                } else if runtime
                    .allocated_stat_points
                    .iter()
                    .any(|allocated| allocated == stat_id)
                {
                    (false, format!("stat_already_allocated:{stat_id}"))
                } else {
                    (true, format!("enabled_stat_confirm:{stat_id}"))
                }
            } else {
                (false, "stat_confirmation_missing".to_string())
            }
        }
        NativeControlAction::CancelStatAllocation => {
            if let Some(stat_id) = runtime.pending_stat_allocation.as_deref() {
                (true, format!("enabled_stat_cancel:{stat_id}"))
            } else {
                (false, "stat_confirmation_missing".to_string())
            }
        }
        NativeControlAction::SaveSlot => {
            if runtime.input_feedback_history.is_empty() {
                (
                    false,
                    "session_checkpoint_requires_input_history".to_string(),
                )
            } else {
                (true, "enabled_session_checkpoint".to_string())
            }
        }
        NativeControlAction::LoadSlot => {
            let slot_path = native_action_session_save_slot_path();
            if Path::new(&slot_path).exists() {
                (true, "enabled_session_slot_found".to_string())
            } else {
                (false, "session_slot_missing".to_string())
            }
        }
        NativeControlAction::SaveSlotNamed { slot_id } => {
            let slot_id = normalize_session_slot_id(slot_id);
            if runtime.input_feedback_history.is_empty() {
                (
                    false,
                    format!("session_checkpoint_requires_input_history:{slot_id}"),
                )
            } else {
                (true, format!("enabled_session_checkpoint:{slot_id}"))
            }
        }
        NativeControlAction::LoadSlotNamed { slot_id } => {
            let slot_id = normalize_session_slot_id(slot_id);
            let slot_path = native_action_session_slot_path(&slot_id);
            if Path::new(&slot_path).exists() {
                (true, format!("enabled_session_slot_found:{slot_id}"))
            } else {
                (false, format!("session_slot_missing:{slot_id}"))
            }
        }
        NativeControlAction::SelectSlot { slot_id } => {
            let slot_id = normalize_session_slot_id(slot_id);
            (true, format!("enabled_select_slot:{slot_id}"))
        }
        NativeControlAction::SaveSelectedSlot => {
            let slot_id = normalize_session_slot_id(&runtime.session_selected_slot_id);
            if runtime.input_feedback_history.is_empty() {
                (
                    false,
                    format!("session_checkpoint_requires_input_history:{slot_id}"),
                )
            } else if runtime.session_overwrite_pending_slot_id.as_deref() == Some(slot_id.as_str())
            {
                (false, format!("overwrite_confirmation_pending:{slot_id}"))
            } else if Path::new(&native_action_session_slot_path(&slot_id)).exists() {
                (true, format!("enabled_overwrite_prompt:{slot_id}"))
            } else {
                (true, format!("enabled_save_selected_slot:{slot_id}"))
            }
        }
        NativeControlAction::LoadSelectedSlot => {
            let slot_id = normalize_session_slot_id(&runtime.session_selected_slot_id);
            let slot_path = native_action_session_slot_path(&slot_id);
            if Path::new(&slot_path).exists() {
                (true, format!("enabled_session_slot_found:{slot_id}"))
            } else {
                (false, format!("session_slot_missing:{slot_id}"))
            }
        }
        NativeControlAction::ConfirmOverwriteSlot => {
            if let Some(slot_id) = runtime.session_overwrite_pending_slot_id.as_deref() {
                (
                    true,
                    format!(
                        "enabled_confirm_overwrite:{}",
                        normalize_session_slot_id(slot_id)
                    ),
                )
            } else {
                (false, "overwrite_confirmation_missing".to_string())
            }
        }
        NativeControlAction::CancelOverwriteSlot => {
            if let Some(slot_id) = runtime.session_overwrite_pending_slot_id.as_deref() {
                (
                    true,
                    format!(
                        "enabled_cancel_overwrite:{}",
                        normalize_session_slot_id(slot_id)
                    ),
                )
            } else {
                (false, "overwrite_confirmation_missing".to_string())
            }
        }
        NativeControlAction::ContinueAfterLoad => {
            unreachable!("handled before general availability")
        }
        NativeControlAction::PauseMenu | NativeControlAction::ResumeFromPause => {
            unreachable!("handled before general availability")
        }
        NativeControlAction::OpenSettingsMenu
        | NativeControlAction::CloseSettingsMenu
        | NativeControlAction::ToggleLowMotion
        | NativeControlAction::VolumeDown
        | NativeControlAction::VolumeUp
        | NativeControlAction::CycleInputMode
        | NativeControlAction::OpenTitleMenu
        | NativeControlAction::NewGameFromTitle
        | NativeControlAction::LoadFromTitle
        | NativeControlAction::ContinueFromTitle
        | NativeControlAction::StartCampaignFromTitle
        | NativeControlAction::ContinueCampaignFromTitle
        | NativeControlAction::ReplayCampaignFromTitle
        | NativeControlAction::RegisterAccountFromTitle
        | NativeControlAction::LoginAccountFromTitle
        | NativeControlAction::ContinueAccountFromTitle
        | NativeControlAction::CycleCharacterName
        | NativeControlAction::CycleCharacterArchetype
        | NativeControlAction::ConfirmCharacterCreate
        | NativeControlAction::BackToTitleFromCreate
        | NativeControlAction::RtsSelectControlGroup { .. }
        | NativeControlAction::RtsQueueProduction { .. }
        | NativeControlAction::RtsMoveCommand { .. }
        | NativeControlAction::RtsAttackCommand { .. }
        | NativeControlAction::RtsAbilityCommand { .. } => {
            unreachable!("handled before general availability")
        }
    }
}

fn native_control_action_label(action: &NativeControlAction) -> String {
    match action {
        NativeControlAction::Move { direction } => format!("MOVE:{direction}"),
        NativeControlAction::Talk => "TALK".to_string(),
        NativeControlAction::Train => "TRAIN".to_string(),
        NativeControlAction::Fight => "FIGHT".to_string(),
        NativeControlAction::CompleteTask => "COMPLETE".to_string(),
        NativeControlAction::Equip => "EQUIP".to_string(),
        NativeControlAction::EnterRoom { room_id } => format!("ROOM:{room_id}"),
        NativeControlAction::InteractNpc { npc_id } => format!("NPC:{npc_id}"),
        NativeControlAction::StartTask { task_id } => format!("TASK:{task_id}"),
        NativeControlAction::CombatAttack => "COMBAT:attack".to_string(),
        NativeControlAction::CombatDefend => "COMBAT:defend".to_string(),
        NativeControlAction::CombatUseItem => "COMBAT:potion".to_string(),
        NativeControlAction::CombatEscape => "COMBAT:escape".to_string(),
        NativeControlAction::OpenBag => "BAG:open".to_string(),
        NativeControlAction::LootDrop => "LOOT:drop".to_string(),
        NativeControlAction::EquipItem { item_id } => format!("EQUIP:{item_id}"),
        NativeControlAction::EquipBuildTitle { title_id } => format!("TITLE:EQUIP:{title_id}"),
        NativeControlAction::AcceptTitleRouteRecommendation => "TITLE:ROUTE".to_string(),
        NativeControlAction::AllocateStat { stat_id } => format!("STAT:{stat_id}"),
        NativeControlAction::ConfirmStatAllocation => "STAT:confirm".to_string(),
        NativeControlAction::CancelStatAllocation => "STAT:cancel".to_string(),
        NativeControlAction::SaveSlot => "SAVE:SLOT".to_string(),
        NativeControlAction::LoadSlot => "LOAD:SLOT".to_string(),
        NativeControlAction::SaveSlotNamed { slot_id } => {
            format!("SAVE:{}", normalize_session_slot_id(slot_id))
        }
        NativeControlAction::LoadSlotNamed { slot_id } => {
            format!("LOAD:{}", normalize_session_slot_id(slot_id))
        }
        NativeControlAction::SelectSlot { slot_id } => {
            format!("SLOT:{}", normalize_session_slot_id(slot_id))
        }
        NativeControlAction::SaveSelectedSlot => "SAVE:SELECTED".to_string(),
        NativeControlAction::LoadSelectedSlot => "LOAD:SELECTED".to_string(),
        NativeControlAction::ConfirmOverwriteSlot => "CONFIRM:OVERWRITE".to_string(),
        NativeControlAction::CancelOverwriteSlot => "CANCEL:OVERWRITE".to_string(),
        NativeControlAction::ContinueAfterLoad => "CONTINUE:SESSION".to_string(),
        NativeControlAction::PauseMenu => "PAUSE:MENU".to_string(),
        NativeControlAction::ResumeFromPause => "RESUME:MENU".to_string(),
        NativeControlAction::OpenSettingsMenu => "SETTINGS:OPEN".to_string(),
        NativeControlAction::CloseSettingsMenu => "SETTINGS:BACK".to_string(),
        NativeControlAction::ToggleLowMotion => "SETTINGS:LOW_MOTION".to_string(),
        NativeControlAction::VolumeDown => "SETTINGS:VOLUME_DOWN".to_string(),
        NativeControlAction::VolumeUp => "SETTINGS:VOLUME_UP".to_string(),
        NativeControlAction::CycleInputMode => "SETTINGS:INPUT_MODE".to_string(),
        NativeControlAction::OpenTitleMenu => "TITLE:OPEN".to_string(),
        NativeControlAction::NewGameFromTitle => "TITLE:NEW".to_string(),
        NativeControlAction::LoadFromTitle => "TITLE:LOAD".to_string(),
        NativeControlAction::ContinueFromTitle => "TITLE:CONTINUE".to_string(),
        NativeControlAction::StartCampaignFromTitle => "CAMPAIGN:START".to_string(),
        NativeControlAction::ContinueCampaignFromTitle => "CAMPAIGN:CONTINUE".to_string(),
        NativeControlAction::ReplayCampaignFromTitle => "CAMPAIGN:REPLAY".to_string(),
        NativeControlAction::RegisterAccountFromTitle => "ACCOUNT:REGISTER".to_string(),
        NativeControlAction::LoginAccountFromTitle => "ACCOUNT:LOGIN".to_string(),
        NativeControlAction::ContinueAccountFromTitle => "ACCOUNT:CONTINUE".to_string(),
        NativeControlAction::CycleCharacterName => "CREATE:NAME".to_string(),
        NativeControlAction::CycleCharacterArchetype => "CREATE:ARCHETYPE".to_string(),
        NativeControlAction::ConfirmCharacterCreate => "CREATE:CONFIRM".to_string(),
        NativeControlAction::BackToTitleFromCreate => "CREATE:BACK".to_string(),
        NativeControlAction::RtsSelectControlGroup { group_id } => {
            format!("RTS:SELECT:{group_id}")
        }
        NativeControlAction::RtsQueueProduction { queue_id } => format!("RTS:QUEUE:{queue_id}"),
        NativeControlAction::RtsMoveCommand { command_id } => {
            format!("RTS:MOVE:{command_id}")
        }
        NativeControlAction::RtsAttackCommand { target_id } => format!("RTS:ATTACK:{target_id}"),
        NativeControlAction::RtsAbilityCommand { ability_id } => {
            format!("RTS:ABILITY:{ability_id}")
        }
    }
}

pub fn apply_native_control_action(
    world: &mut WorldState,
    character: &mut WorldTrillionniumCharacter,
    gameplay_log: &mut NativeGameplayLog,
    actor_id: &str,
    action: NativeControlAction,
) -> Option<WorldApiCommandResponse> {
    match action {
        NativeControlAction::Move { direction } => {
            let label = format!("move:{direction}");
            let response = apply_native_intent(
                world,
                WorldCommand::Move {
                    actor_id: actor_id.to_string(),
                    direction,
                },
            );
            update_log_from_world_response(gameplay_log, label, &response);
            Some(response)
        }
        NativeControlAction::Talk => {
            let npc_id = local_npc_for_actor(world, actor_id)
                .map(|npc| npc.id.clone())
                .unwrap_or_else(|| "npc-street-compass-sifu".to_string());
            let response = apply_native_intent(
                world,
                WorldCommand::TalkNpc {
                    actor_id: actor_id.to_string(),
                    npc_id,
                },
            );
            update_log_from_world_response(gameplay_log, "talk:npc".to_string(), &response);
            Some(response)
        }
        NativeControlAction::Train => {
            let npc_id = local_npc_for_actor(world, actor_id)
                .map(|npc| npc.id.clone())
                .unwrap_or_else(|| "npc-street-compass-sifu".to_string());
            let response = apply_native_intent(
                world,
                WorldCommand::TrainSkill {
                    actor_id: actor_id.to_string(),
                    npc_id: npc_id.clone(),
                    skill_id: "basic_unarmed".to_string(),
                },
            );
            update_log_from_world_response(
                gameplay_log,
                "train:basic_unarmed".to_string(),
                &response,
            );
            if response.decision.accepted {
                let outcome = apply_tactics_command(
                    character,
                    WorldTacticsCommandRequest {
                        command: "train_skill".to_string(),
                        skill_id: Some("basic_unarmed".to_string()),
                        npc_id: Some(npc_id),
                        ..default()
                    },
                    native_now_epoch(),
                );
                update_log_from_tactics_outcome(gameplay_log, "train:basic_unarmed", outcome);
            }
            Some(response)
        }
        NativeControlAction::Fight => {
            let outcome = apply_tactics_command(
                character,
                WorldTacticsCommandRequest {
                    command: "attack".to_string(),
                    skill_id: Some("basic_unarmed".to_string()),
                    target_tile: Some("F5".to_string()),
                    ..default()
                },
                native_now_epoch(),
            );
            update_log_from_tactics_outcome(gameplay_log, "fight:F5", outcome);
            None
        }
        NativeControlAction::CompleteTask => {
            let task_id = local_task_for_actor(world, actor_id)
                .map(|task| task.id.clone())
                .or_else(|| world.tasks.first().map(|task| task.id.clone()))
                .unwrap_or_else(|| "task-fixture-first-route".to_string());
            let response = apply_native_intent(
                world,
                WorldCommand::CompleteTask {
                    actor_id: actor_id.to_string(),
                    task_id,
                },
            );
            update_log_from_world_response(gameplay_log, "complete:task".to_string(), &response);
            Some(response)
        }
        NativeControlAction::Equip => {
            let outcome = apply_tactics_command(
                character,
                WorldTacticsCommandRequest {
                    command: "equip_item".to_string(),
                    item_id: Some("route-guard-staff".to_string()),
                    target_slot: Some("weapon".to_string()),
                    ..default()
                },
                native_now_epoch(),
            );
            update_log_from_tactics_outcome(gameplay_log, "equip:route-guard-staff", outcome);
            None
        }
        NativeControlAction::EnterRoom { room_id } => {
            if let Some(direction) = direction_to_room(world, actor_id, &room_id) {
                let label = format!("room:{room_id}");
                let response = apply_native_intent(
                    world,
                    WorldCommand::Move {
                        actor_id: actor_id.to_string(),
                        direction,
                    },
                );
                update_log_from_world_response(gameplay_log, label, &response);
                Some(response)
            } else {
                record_runtime_only_log(
                    gameplay_log,
                    format!("room:{room_id}"),
                    "room_transition_not_adjacent".to_string(),
                    Some("rust_world_edge_required".to_string()),
                );
                None
            }
        }
        NativeControlAction::InteractNpc { npc_id } => {
            let response = apply_native_intent(
                world,
                WorldCommand::TalkNpc {
                    actor_id: actor_id.to_string(),
                    npc_id: npc_id.clone(),
                },
            );
            update_log_from_world_response(gameplay_log, format!("talk:{npc_id}"), &response);
            let outcome = apply_tactics_command(
                character,
                WorldTacticsCommandRequest {
                    command: "talk_npc".to_string(),
                    npc_id: Some(npc_id),
                    ..default()
                },
                native_now_epoch(),
            );
            update_log_from_tactics_outcome(gameplay_log, "talk_npc:room", outcome);
            Some(response)
        }
        NativeControlAction::StartTask { task_id } => {
            let outcome = apply_tactics_command(
                character,
                WorldTacticsCommandRequest {
                    command: "offer_task".to_string(),
                    npc_id: local_npc_for_actor(world, actor_id).map(|npc| npc.id.clone()),
                    item_id: Some(task_id.clone()),
                    ..default()
                },
                native_now_epoch(),
            );
            update_log_from_tactics_outcome(
                gameplay_log,
                &format!("start_task:{task_id}"),
                outcome,
            );
            None
        }
        NativeControlAction::CombatAttack => {
            let outcome = apply_tactics_command(
                character,
                WorldTacticsCommandRequest {
                    command: "attack".to_string(),
                    skill_id: Some("basic_unarmed".to_string()),
                    target_tile: Some("F5".to_string()),
                    ..default()
                },
                native_now_epoch(),
            );
            update_log_from_tactics_outcome(gameplay_log, "combat:attack", outcome);
            None
        }
        NativeControlAction::CombatDefend => {
            record_runtime_only_log(
                gameplay_log,
                "combat:defend".to_string(),
                "guard_stance_reduces_next_hit".to_string(),
                None,
            );
            None
        }
        NativeControlAction::CombatUseItem => {
            record_runtime_only_log(
                gameplay_log,
                "combat:potion".to_string(),
                "small_healing_pill_used".to_string(),
                None,
            );
            None
        }
        NativeControlAction::CombatEscape => {
            record_runtime_only_log(
                gameplay_log,
                "combat:escape".to_string(),
                "escape_path_sampled".to_string(),
                None,
            );
            None
        }
        NativeControlAction::OpenBag => {
            record_runtime_only_log(
                gameplay_log,
                "bag:open".to_string(),
                "bag_opened".to_string(),
                None,
            );
            None
        }
        NativeControlAction::LootDrop => {
            record_runtime_only_log(
                gameplay_log,
                "loot:drop".to_string(),
                "victory_drop_collected".to_string(),
                None,
            );
            None
        }
        NativeControlAction::EquipItem { item_id } => {
            record_runtime_only_log(
                gameplay_log,
                format!("equip_item:{item_id}"),
                "inventory_item_equipped".to_string(),
                None,
            );
            None
        }
        NativeControlAction::EquipBuildTitle { title_id } => {
            record_runtime_only_log(
                gameplay_log,
                format!("equip_title:{title_id}"),
                "build_title_equipped".to_string(),
                None,
            );
            None
        }
        NativeControlAction::AcceptTitleRouteRecommendation => {
            record_runtime_only_log(
                gameplay_log,
                "title:route".to_string(),
                "active_title_route_accepted".to_string(),
                None,
            );
            None
        }
        NativeControlAction::AllocateStat { stat_id } => {
            record_runtime_only_log(
                gameplay_log,
                format!("stat:{stat_id}"),
                "stat_preview_selected".to_string(),
                None,
            );
            None
        }
        NativeControlAction::ConfirmStatAllocation => {
            record_runtime_only_log(
                gameplay_log,
                "stat:confirm".to_string(),
                "stat_point_allocated".to_string(),
                None,
            );
            None
        }
        NativeControlAction::CancelStatAllocation => {
            record_runtime_only_log(
                gameplay_log,
                "stat:cancel".to_string(),
                "stat_preview_cancelled".to_string(),
                None,
            );
            None
        }
        NativeControlAction::RtsSelectControlGroup { group_id } => {
            record_runtime_only_log(
                gameplay_log,
                format!("rts:select:{group_id}"),
                "rts_control_group_selected".to_string(),
                None,
            );
            None
        }
        NativeControlAction::RtsQueueProduction { queue_id } => {
            record_runtime_only_log(
                gameplay_log,
                format!("rts:queue:{queue_id}"),
                "rts_production_queued".to_string(),
                None,
            );
            None
        }
        NativeControlAction::RtsMoveCommand { command_id } => {
            let (tile_id, formation) = classic_rts_move_command_parts(&command_id);
            record_runtime_only_log(
                gameplay_log,
                format!("rts:move:{tile_id}:{formation}"),
                "rts_move_command_accepted".to_string(),
                None,
            );
            None
        }
        NativeControlAction::RtsAttackCommand { target_id } => {
            record_runtime_only_log(
                gameplay_log,
                format!("rts:attack:{target_id}"),
                "rts_attack_command_accepted".to_string(),
                None,
            );
            None
        }
        NativeControlAction::RtsAbilityCommand { ability_id } => {
            record_runtime_only_log(
                gameplay_log,
                format!("rts:ability:{ability_id}"),
                "rts_ability_command_accepted".to_string(),
                None,
            );
            None
        }
        NativeControlAction::SaveSlot
        | NativeControlAction::LoadSlot
        | NativeControlAction::SaveSlotNamed { .. }
        | NativeControlAction::LoadSlotNamed { .. }
        | NativeControlAction::SelectSlot { .. }
        | NativeControlAction::SaveSelectedSlot
        | NativeControlAction::LoadSelectedSlot
        | NativeControlAction::ConfirmOverwriteSlot
        | NativeControlAction::CancelOverwriteSlot
        | NativeControlAction::ContinueAfterLoad
        | NativeControlAction::PauseMenu
        | NativeControlAction::ResumeFromPause
        | NativeControlAction::OpenSettingsMenu
        | NativeControlAction::CloseSettingsMenu
        | NativeControlAction::ToggleLowMotion
        | NativeControlAction::VolumeDown
        | NativeControlAction::VolumeUp
        | NativeControlAction::CycleInputMode
        | NativeControlAction::OpenTitleMenu
        | NativeControlAction::NewGameFromTitle
        | NativeControlAction::LoadFromTitle
        | NativeControlAction::ContinueFromTitle
        | NativeControlAction::StartCampaignFromTitle
        | NativeControlAction::ContinueCampaignFromTitle
        | NativeControlAction::ReplayCampaignFromTitle
        | NativeControlAction::RegisterAccountFromTitle
        | NativeControlAction::LoginAccountFromTitle
        | NativeControlAction::ContinueAccountFromTitle
        | NativeControlAction::CycleCharacterName
        | NativeControlAction::CycleCharacterArchetype
        | NativeControlAction::ConfirmCharacterCreate
        | NativeControlAction::BackToTitleFromCreate => None,
    }
}

fn direction_to_room(world: &WorldState, actor_id: &str, room_id: &str) -> Option<String> {
    let current_node_id = player_node_id(world, actor_id)?;
    world
        .edges
        .iter()
        .find(|edge| edge.from == current_node_id && edge.to == room_id)
        .map(|edge| edge.direction.clone())
}

fn record_runtime_only_log(
    gameplay_log: &mut NativeGameplayLog,
    action: String,
    result: String,
    rejection: Option<String>,
) {
    gameplay_log.turn += 1;
    gameplay_log.last_action = action;
    gameplay_log.last_result = result;
    gameplay_log.last_rejection = rejection;
}

fn apply_active_build_title_route_accept(
    world: &mut WorldState,
    character: &mut WorldTrillionniumCharacter,
    gameplay_log: &mut NativeGameplayLog,
    first_playable: &mut NativeFirstPlayableRuntime,
    actor_id: &str,
) -> Option<WorldApiCommandResponse> {
    let Some((_, stat_id, effect_id, task_id)) =
        active_build_title_route_recommendation_parts(first_playable)
    else {
        record_runtime_only_log(
            gameplay_log,
            "title:route".to_string(),
            "title_route_recommendation_missing".to_string(),
            Some("active_title_required".to_string()),
        );
        push_feedback_event(first_playable, "Title route blocked: active title required");
        refresh_contextual_action_runtime(first_playable);
        return None;
    };
    let stat_id = stat_id.to_string();
    let effect_id = effect_id.to_string();
    let task_id = task_id.to_string();
    apply_build_title_route_recommendation(first_playable, &stat_id, &effect_id);
    if first_playable.current_room_id == first_playable.route_director_target_room_id {
        let start_action = NativeControlAction::StartTask {
            task_id: task_id.clone(),
        };
        let response = apply_native_control_action(
            world,
            character,
            gameplay_log,
            actor_id,
            start_action.clone(),
        );
        update_first_playable_runtime(
            first_playable,
            &start_action,
            response.as_ref(),
            character,
            world,
            actor_id,
        );
        push_history(
            &mut first_playable.route_director_history,
            &format!("active_title_route_accept:{stat_id}:{task_id}:start_task"),
        );
        push_feedback_event(
            first_playable,
            &format!(
                "Title route accepted: {} started",
                build_branch_followup_task_label(&task_id)
            ),
        );
        refresh_contextual_action_runtime(first_playable);
        return response;
    }
    let Some(next_room_id) = first_playable.route_director_next_room_id.clone() else {
        record_runtime_only_log(
            gameplay_log,
            "title:route".to_string(),
            "title_route_waiting".to_string(),
            Some(task_id.clone()),
        );
        push_history(
            &mut first_playable.blocked_action_history,
            &format!("TITLE:ROUTE:title_route_waiting:{task_id}"),
        );
        push_feedback_event(
            first_playable,
            &format!("Title route waiting: no next step for {task_id}"),
        );
        refresh_contextual_action_runtime(first_playable);
        return None;
    };
    let enter_action = NativeControlAction::EnterRoom {
        room_id: next_room_id.clone(),
    };
    if build_mastery_room_override(first_playable, &next_room_id)
        && !world
            .edges
            .iter()
            .any(|edge| edge.from == first_playable.current_room_id && edge.to == next_room_id)
    {
        world.edges.push(WorldEdge {
            from: first_playable.current_room_id.clone(),
            to: next_room_id.clone(),
            direction: format!("mastery_shortcut_to_{next_room_id}"),
        });
    }
    let response = apply_native_control_action(
        world,
        character,
        gameplay_log,
        actor_id,
        enter_action.clone(),
    );
    update_first_playable_runtime(
        first_playable,
        &enter_action,
        response.as_ref(),
        character,
        world,
        actor_id,
    );
    push_history(
        &mut first_playable.route_director_history,
        &format!("active_title_route_accept:{stat_id}:{task_id}:move:{next_room_id}"),
    );
    push_feedback_event(
        first_playable,
        &format!(
            "Title route accepted: {} moved to {}",
            build_branch_followup_task_label(&task_id),
            node_scene_label(&next_room_id)
        ),
    );
    refresh_contextual_action_runtime(first_playable);
    response
}

pub fn apply_native_first_playable_action(
    world: &mut WorldState,
    character: &mut WorldTrillionniumCharacter,
    gameplay_log: &mut NativeGameplayLog,
    first_playable: &mut NativeFirstPlayableRuntime,
    actor_id: &str,
    action: NativeControlAction,
) -> Option<WorldApiCommandResponse> {
    match action {
        NativeControlAction::OpenTitleMenu => {
            open_title_menu(first_playable);
            gameplay_log.turn += 1;
            gameplay_log.last_action = "title:open".to_string();
            gameplay_log.last_result = "title_menu_opened".to_string();
            gameplay_log.last_rejection = None;
            refresh_contextual_action_runtime(first_playable);
            return None;
        }
        NativeControlAction::NewGameFromTitle => {
            open_character_create(first_playable);
            gameplay_log.turn += 1;
            gameplay_log.last_action = "title:new_game".to_string();
            gameplay_log.last_result = "character_create_opened".to_string();
            gameplay_log.last_rejection = None;
            push_history(&mut first_playable.session_title_history, "title_new_game");
            refresh_contextual_action_runtime(first_playable);
            return None;
        }
        NativeControlAction::CycleCharacterName => {
            cycle_character_name(first_playable);
            gameplay_log.turn += 1;
            gameplay_log.last_action = "character:create:name".to_string();
            gameplay_log.last_result = format!(
                "character_name:{}",
                first_playable.session_character_create_name
            );
            gameplay_log.last_rejection = None;
            refresh_contextual_action_runtime(first_playable);
            return None;
        }
        NativeControlAction::CycleCharacterArchetype => {
            cycle_character_archetype(first_playable);
            gameplay_log.turn += 1;
            gameplay_log.last_action = "character:create:archetype".to_string();
            gameplay_log.last_result = format!(
                "character_archetype:{}",
                first_playable.session_character_create_archetype
            );
            gameplay_log.last_rejection = None;
            refresh_contextual_action_runtime(first_playable);
            return None;
        }
        NativeControlAction::BackToTitleFromCreate => {
            close_character_create(first_playable, "back_to_title");
            open_title_menu(first_playable);
            gameplay_log.turn += 1;
            gameplay_log.last_action = "character:create:back".to_string();
            gameplay_log.last_result = "title_menu_opened".to_string();
            gameplay_log.last_rejection = None;
            refresh_contextual_action_runtime(first_playable);
            return None;
        }
        NativeControlAction::RegisterAccountFromTitle
        | NativeControlAction::LoginAccountFromTitle
        | NativeControlAction::ContinueAccountFromTitle => {
            let decision = apply_title_account_flow(first_playable, actor_id, &action);
            if decision.accepted {
                character.display_name = decision.profile.display_name.clone();
                character.ensure_defaults(native_now_epoch());
                push_history(
                    &mut first_playable.session_account_history,
                    "account_profile_bound_to_character_identity",
                );
            }
            gameplay_log.turn += 1;
            gameplay_log.last_action = format!("account:{}", decision.action);
            gameplay_log.last_result = decision.reason.clone();
            gameplay_log.last_rejection = (!decision.accepted).then(|| decision.reason.clone());
            push_progression_checkpoint(
                first_playable,
                &format!("account_title_flow:{}", decision.action),
            );
            if decision.accepted {
                push_progression_checkpoint(first_playable, "account_profile_bound_to_character");
            }
            refresh_contextual_action_runtime(first_playable);
            return None;
        }
        NativeControlAction::ConfirmCharacterCreate => {
            let chosen_name = first_playable.session_character_create_name.clone();
            let chosen_archetype = first_playable.session_character_create_archetype.clone();
            let next_turn = gameplay_log.turn + 1;
            *world = native_bevy_playable_fixture();
            *character = character_for_creation(actor_id, &chosen_name, &chosen_archetype);
            *gameplay_log = NativeGameplayLog {
                turn: next_turn,
                last_action: "character:create:confirm".to_string(),
                last_result: format!("new_character:{chosen_name}:{chosen_archetype}"),
                last_rejection: None,
            };
            *first_playable = NativeFirstPlayableRuntime::default();
            first_playable.session_character_create_name = chosen_name.clone();
            first_playable.session_character_create_archetype = chosen_archetype.clone();
            close_character_create(first_playable, "new_game_started");
            first_playable.session_title_boot_state = "new_game_started".to_string();
            push_history(
                &mut first_playable.session_character_create_history,
                &format!("confirmed:{chosen_name}:{chosen_archetype}"),
            );
            push_progression_checkpoint(first_playable, "character_created_from_title");
            push_feedback_event(
                first_playable,
                &format!("New character created: {chosen_name} / {chosen_archetype}"),
            );
            refresh_contextual_action_runtime(first_playable);
            return None;
        }
        NativeControlAction::AcceptTitleRouteRecommendation => {
            return apply_active_build_title_route_accept(
                world,
                character,
                gameplay_log,
                first_playable,
                actor_id,
            );
        }
        NativeControlAction::StartCampaignFromTitle
        | NativeControlAction::ReplayCampaignFromTitle => {
            let replay = matches!(action, NativeControlAction::ReplayCampaignFromTitle);
            let slot_path = native_campaign_entry_slot_path();
            let next_turn = gameplay_log.turn + 1;
            *world = native_bevy_playable_fixture();
            *character = WorldTrillionniumCharacter::default_for(actor_id);
            character.ensure_defaults(native_now_epoch());
            *gameplay_log = NativeGameplayLog {
                turn: next_turn,
                last_action: if replay {
                    "campaign:replay:title".to_string()
                } else {
                    "campaign:start:title".to_string()
                },
                last_result: "classic_rts_campaign_entry_started".to_string(),
                last_rejection: None,
            };
            *first_playable = NativeFirstPlayableRuntime::default();
            push_history(
                &mut first_playable.session_title_history,
                if replay {
                    "campaign_replay_from_title"
                } else {
                    "campaign_start_from_title"
                },
            );
            let accepted_input_count = apply_classic_rts_campaign_handoff_sequence(
                world,
                character,
                gameplay_log,
                first_playable,
                actor_id,
                "classic_rts_campaign_entry_title_input",
            );
            push_progression_checkpoint(
                first_playable,
                &format!("campaign_entry_inputs_accepted:{accepted_input_count}"),
            );
            let snapshot = native_playable_save_snapshot(
                world,
                character,
                gameplay_log,
                first_playable,
                actor_id,
            );
            let slot_result = write_native_playable_snapshot_slot(&slot_path, &snapshot);
            gameplay_log.turn += 1;
            gameplay_log.last_action = if replay {
                "campaign:replay:title".to_string()
            } else {
                "campaign:start:title".to_string()
            };
            gameplay_log.last_rejection = None;
            match slot_result {
                Ok(bytes) => {
                    gameplay_log.last_result =
                        format!("classic_rts_campaign_entry_saved:{accepted_input_count}:{bytes}");
                    first_playable.session_title_last_slot_id = Some("CAMPAIGN".to_string());
                    push_history(
                        &mut first_playable.session_title_history,
                        &format!("campaign_entry_saved:{bytes}"),
                    );
                    push_progression_checkpoint(first_playable, "campaign_entry_snapshot_saved");
                    push_feedback_event(
                        first_playable,
                        &format!(
                            "Campaign entry complete: {accepted_input_count} inputs, saved {bytes} bytes"
                        ),
                    );
                }
                Err(error) => {
                    gameplay_log.last_result = "classic_rts_campaign_entry_save_failed".to_string();
                    gameplay_log.last_rejection = Some(error.to_string());
                    push_feedback_event(
                        first_playable,
                        &format!("Campaign entry save failed: {error}"),
                    );
                }
            }
            refresh_contextual_action_runtime(first_playable);
            return None;
        }
        NativeControlAction::ContinueCampaignFromTitle => {
            let slot_path = native_campaign_entry_slot_path();
            let slot_result = read_native_playable_snapshot_slot(&slot_path);
            match slot_result {
                Ok(snapshot) => {
                    let (
                        restored_world,
                        restored_character,
                        mut restored_log,
                        mut restored_first_playable,
                    ) = native_restore_playable_save_snapshot(snapshot);
                    restored_first_playable.session_selected_slot_id =
                        first_playable.session_selected_slot_id.clone();
                    restored_first_playable.session_title_last_slot_id =
                        Some("CAMPAIGN".to_string());
                    push_progression_checkpoint(
                        &mut restored_first_playable,
                        "campaign_entry_snapshot_restored",
                    );
                    push_history(
                        &mut restored_first_playable.session_title_history,
                        "campaign_continue_from_title",
                    );
                    restored_log.turn += 1;
                    restored_log.last_action = "campaign:continue:title".to_string();
                    restored_log.last_result = "classic_rts_campaign_entry_continued".to_string();
                    restored_log.last_rejection = None;
                    push_feedback_event(
                        &mut restored_first_playable,
                        "Campaign continue restored the open-world handoff",
                    );
                    mark_session_resume_overlay(&mut restored_first_playable, "CAMPAIGN");
                    refresh_contextual_action_runtime(&mut restored_first_playable);
                    *world = restored_world;
                    *character = restored_character;
                    *gameplay_log = restored_log;
                    *first_playable = restored_first_playable;
                }
                Err(error) => {
                    gameplay_log.turn += 1;
                    gameplay_log.last_action = "campaign:continue:title".to_string();
                    gameplay_log.last_result =
                        "classic_rts_campaign_entry_continue_failed".to_string();
                    gameplay_log.last_rejection = Some(error.to_string());
                    push_feedback_event(
                        first_playable,
                        &format!("Campaign continue failed: {error}"),
                    );
                    refresh_contextual_action_runtime(first_playable);
                }
            }
            return None;
        }
        NativeControlAction::LoadFromTitle | NativeControlAction::ContinueFromTitle => {
            let selected_slot_id =
                normalize_session_slot_id(&first_playable.session_selected_slot_id);
            let slot_path = native_action_session_slot_path(&selected_slot_id);
            let title_action_is_continue = matches!(action, NativeControlAction::ContinueFromTitle);
            let slot_result = read_native_playable_snapshot_slot(&slot_path);
            match slot_result {
                Ok(snapshot) => {
                    let (
                        restored_world,
                        restored_character,
                        mut restored_log,
                        mut restored_first_playable,
                    ) = native_restore_playable_save_snapshot(snapshot);
                    restored_first_playable.session_selected_slot_id = selected_slot_id.clone();
                    restored_first_playable.session_overwrite_pending_slot_id = None;
                    restored_first_playable.session_title_last_slot_id =
                        Some(selected_slot_id.clone());
                    push_progression_checkpoint(
                        &mut restored_first_playable,
                        "session_snapshot_restored",
                    );
                    push_progression_checkpoint(
                        &mut restored_first_playable,
                        &format!("title_slot_{selected_slot_id}_restored"),
                    );
                    restored_log.turn += 1;
                    restored_log.last_action = if title_action_is_continue {
                        format!("title:continue:{selected_slot_id}")
                    } else {
                        format!("title:load:{selected_slot_id}")
                    };
                    restored_log.last_result = if title_action_is_continue {
                        format!("title_slot_{selected_slot_id}_continued")
                    } else {
                        format!("title_slot_{selected_slot_id}_loaded")
                    };
                    restored_log.last_rejection = None;
                    let title_history_entry = if title_action_is_continue {
                        format!("title_continue_slot:{selected_slot_id}")
                    } else {
                        format!("title_load_slot:{selected_slot_id}")
                    };
                    push_history(
                        &mut restored_first_playable.session_title_history,
                        &title_history_entry,
                    );
                    let title_feedback = if title_action_is_continue {
                        format!("Title continue loaded slot {selected_slot_id}")
                    } else {
                        format!("Title load restored slot {selected_slot_id}")
                    };
                    push_feedback_event(&mut restored_first_playable, &title_feedback);
                    mark_session_resume_overlay(&mut restored_first_playable, &selected_slot_id);
                    refresh_contextual_action_runtime(&mut restored_first_playable);
                    *world = restored_world;
                    *character = restored_character;
                    *gameplay_log = restored_log;
                    *first_playable = restored_first_playable;
                }
                Err(error) => {
                    gameplay_log.turn += 1;
                    gameplay_log.last_action = if title_action_is_continue {
                        format!("title:continue:{selected_slot_id}")
                    } else {
                        format!("title:load:{selected_slot_id}")
                    };
                    gameplay_log.last_result = if title_action_is_continue {
                        format!("title_slot_{selected_slot_id}_continue_failed")
                    } else {
                        format!("title_slot_{selected_slot_id}_load_failed")
                    };
                    gameplay_log.last_rejection = Some(error.to_string());
                    push_feedback_event(
                        first_playable,
                        &format!("Title slot {selected_slot_id} load failed: {error}"),
                    );
                    refresh_contextual_action_runtime(first_playable);
                }
            }
            return None;
        }
        NativeControlAction::PauseMenu => {
            open_pause_menu(first_playable);
            gameplay_log.turn += 1;
            gameplay_log.last_action = "pause:menu".to_string();
            gameplay_log.last_result = "pause_menu_opened".to_string();
            gameplay_log.last_rejection = None;
            refresh_contextual_action_runtime(first_playable);
            return None;
        }
        NativeControlAction::ResumeFromPause => {
            close_pause_menu(first_playable);
            gameplay_log.turn += 1;
            gameplay_log.last_action = "resume:pause_menu".to_string();
            gameplay_log.last_result = "pause_menu_closed".to_string();
            gameplay_log.last_rejection = None;
            refresh_contextual_action_runtime(first_playable);
            return None;
        }
        NativeControlAction::OpenSettingsMenu => {
            open_settings_menu(first_playable);
            gameplay_log.turn += 1;
            gameplay_log.last_action = "settings:open".to_string();
            gameplay_log.last_result = "settings_menu_opened".to_string();
            gameplay_log.last_rejection = None;
            refresh_contextual_action_runtime(first_playable);
            return None;
        }
        NativeControlAction::CloseSettingsMenu => {
            close_settings_menu(first_playable);
            gameplay_log.turn += 1;
            gameplay_log.last_action = "settings:back".to_string();
            gameplay_log.last_result = "settings_menu_closed".to_string();
            gameplay_log.last_rejection = None;
            refresh_contextual_action_runtime(first_playable);
            return None;
        }
        NativeControlAction::ToggleLowMotion => {
            toggle_low_motion(first_playable);
            gameplay_log.turn += 1;
            gameplay_log.last_action = "settings:low_motion".to_string();
            gameplay_log.last_result = format!(
                "low_motion:{}",
                if first_playable.session_settings_low_motion_enabled {
                    "on"
                } else {
                    "off"
                }
            );
            gameplay_log.last_rejection = None;
            refresh_contextual_action_runtime(first_playable);
            return None;
        }
        NativeControlAction::VolumeDown => {
            adjust_volume(first_playable, -1);
            gameplay_log.turn += 1;
            gameplay_log.last_action = "settings:volume_down".to_string();
            gameplay_log.last_result =
                format!("volume:{}", first_playable.session_settings_volume_level);
            gameplay_log.last_rejection = None;
            refresh_contextual_action_runtime(first_playable);
            return None;
        }
        NativeControlAction::VolumeUp => {
            adjust_volume(first_playable, 1);
            gameplay_log.turn += 1;
            gameplay_log.last_action = "settings:volume_up".to_string();
            gameplay_log.last_result =
                format!("volume:{}", first_playable.session_settings_volume_level);
            gameplay_log.last_rejection = None;
            refresh_contextual_action_runtime(first_playable);
            return None;
        }
        NativeControlAction::CycleInputMode => {
            cycle_input_mode(first_playable);
            gameplay_log.turn += 1;
            gameplay_log.last_action = "settings:input_mode".to_string();
            gameplay_log.last_result =
                format!("input_mode:{}", first_playable.session_settings_input_mode);
            gameplay_log.last_rejection = None;
            refresh_contextual_action_runtime(first_playable);
            return None;
        }
        NativeControlAction::ContinueAfterLoad => {
            let slot_id = first_playable
                .session_resume_source_slot_id
                .clone()
                .unwrap_or_else(|| "unknown".to_string());
            clear_session_resume_overlay(first_playable);
            gameplay_log.turn += 1;
            gameplay_log.last_action = format!("continue:session:{slot_id}");
            gameplay_log.last_result = "session_resume_continued".to_string();
            gameplay_log.last_rejection = None;
            refresh_contextual_action_runtime(first_playable);
            return None;
        }
        NativeControlAction::SaveSlot => {
            let slot_path = native_action_session_save_slot_path();
            let snapshot = native_playable_save_snapshot(
                world,
                character,
                gameplay_log,
                first_playable,
                actor_id,
            );
            let slot_result = write_native_playable_snapshot_slot(&slot_path, &snapshot);
            gameplay_log.turn += 1;
            gameplay_log.last_action = "save:slot".to_string();
            gameplay_log.last_rejection = None;
            match slot_result {
                Ok(bytes) => {
                    gameplay_log.last_result = format!("session_slot_saved:{bytes}");
                    push_progression_checkpoint(first_playable, "session_slot_saved");
                    push_feedback_event(first_playable, &format!("Session saved: {bytes} bytes"));
                }
                Err(error) => {
                    gameplay_log.last_result = "session_slot_save_failed".to_string();
                    gameplay_log.last_rejection = Some(error.to_string());
                    push_feedback_event(first_playable, &format!("Session save failed: {error}"));
                }
            }
            refresh_contextual_action_runtime(first_playable);
            return None;
        }
        NativeControlAction::LoadSlot => {
            let slot_path = native_action_session_save_slot_path();
            let slot_result = read_native_playable_snapshot_slot(&slot_path);
            match slot_result {
                Ok(snapshot) => {
                    let (
                        restored_world,
                        restored_character,
                        mut restored_log,
                        mut restored_first_playable,
                    ) = native_restore_playable_save_snapshot(snapshot);
                    push_progression_checkpoint(
                        &mut restored_first_playable,
                        "session_snapshot_restored",
                    );
                    restored_log.turn += 1;
                    restored_log.last_action = "load:slot".to_string();
                    restored_log.last_result = "session_slot_loaded".to_string();
                    restored_log.last_rejection = None;
                    push_feedback_event(
                        &mut restored_first_playable,
                        "Session loaded: slot restored",
                    );
                    mark_session_resume_overlay(&mut restored_first_playable, "SLOT");
                    refresh_contextual_action_runtime(&mut restored_first_playable);
                    *world = restored_world;
                    *character = restored_character;
                    *gameplay_log = restored_log;
                    *first_playable = restored_first_playable;
                }
                Err(error) => {
                    gameplay_log.turn += 1;
                    gameplay_log.last_action = "load:slot".to_string();
                    gameplay_log.last_result = "session_slot_load_failed".to_string();
                    gameplay_log.last_rejection = Some(error.to_string());
                    push_feedback_event(first_playable, &format!("Session load failed: {error}"));
                    refresh_contextual_action_runtime(first_playable);
                }
            }
            return None;
        }
        NativeControlAction::SaveSlotNamed { slot_id } => {
            let slot_id = normalize_session_slot_id(&slot_id);
            let slot_path = native_action_session_slot_path(&slot_id);
            let snapshot = native_playable_save_snapshot(
                world,
                character,
                gameplay_log,
                first_playable,
                actor_id,
            );
            let slot_result = write_native_playable_snapshot_slot(&slot_path, &snapshot);
            gameplay_log.turn += 1;
            gameplay_log.last_action = format!("save:slot:{slot_id}");
            gameplay_log.last_rejection = None;
            match slot_result {
                Ok(bytes) => {
                    gameplay_log.last_result = format!("session_slot_{slot_id}_saved:{bytes}");
                    push_progression_checkpoint(
                        first_playable,
                        &format!("session_slot_{slot_id}_saved"),
                    );
                    push_feedback_event(
                        first_playable,
                        &format!("Session slot {slot_id} saved: {bytes} bytes"),
                    );
                }
                Err(error) => {
                    gameplay_log.last_result = format!("session_slot_{slot_id}_save_failed");
                    gameplay_log.last_rejection = Some(error.to_string());
                    push_feedback_event(
                        first_playable,
                        &format!("Session slot {slot_id} save failed: {error}"),
                    );
                }
            }
            refresh_contextual_action_runtime(first_playable);
            return None;
        }
        NativeControlAction::LoadSlotNamed { slot_id } => {
            let slot_id = normalize_session_slot_id(&slot_id);
            let slot_path = native_action_session_slot_path(&slot_id);
            let slot_result = read_native_playable_snapshot_slot(&slot_path);
            match slot_result {
                Ok(snapshot) => {
                    let (
                        restored_world,
                        restored_character,
                        mut restored_log,
                        mut restored_first_playable,
                    ) = native_restore_playable_save_snapshot(snapshot);
                    push_progression_checkpoint(
                        &mut restored_first_playable,
                        "session_snapshot_restored",
                    );
                    push_progression_checkpoint(
                        &mut restored_first_playable,
                        &format!("session_slot_{slot_id}_restored"),
                    );
                    restored_log.turn += 1;
                    restored_log.last_action = format!("load:slot:{slot_id}");
                    restored_log.last_result = format!("session_slot_{slot_id}_loaded");
                    restored_log.last_rejection = None;
                    push_feedback_event(
                        &mut restored_first_playable,
                        &format!("Session slot {slot_id} loaded: restored"),
                    );
                    mark_session_resume_overlay(&mut restored_first_playable, &slot_id);
                    refresh_contextual_action_runtime(&mut restored_first_playable);
                    *world = restored_world;
                    *character = restored_character;
                    *gameplay_log = restored_log;
                    *first_playable = restored_first_playable;
                }
                Err(error) => {
                    gameplay_log.turn += 1;
                    gameplay_log.last_action = format!("load:slot:{slot_id}");
                    gameplay_log.last_result = format!("session_slot_{slot_id}_load_failed");
                    gameplay_log.last_rejection = Some(error.to_string());
                    push_feedback_event(
                        first_playable,
                        &format!("Session slot {slot_id} load failed: {error}"),
                    );
                    refresh_contextual_action_runtime(first_playable);
                }
            }
            return None;
        }
        NativeControlAction::SelectSlot { slot_id } => {
            let slot_id = normalize_session_slot_id(&slot_id);
            first_playable.session_selected_slot_id = slot_id.clone();
            first_playable.session_overwrite_pending_slot_id = None;
            gameplay_log.turn += 1;
            gameplay_log.last_action = format!("select:slot:{slot_id}");
            gameplay_log.last_result = format!("session_slot_{slot_id}_selected");
            gameplay_log.last_rejection = None;
            push_feedback_event(first_playable, &format!("Session slot {slot_id} selected"));
            refresh_contextual_action_runtime(first_playable);
            return None;
        }
        NativeControlAction::SaveSelectedSlot => {
            let slot_id = normalize_session_slot_id(&first_playable.session_selected_slot_id);
            let slot_path = native_action_session_slot_path(&slot_id);
            gameplay_log.turn += 1;
            gameplay_log.last_action = format!("save:selected:{slot_id}");
            gameplay_log.last_rejection = None;
            if Path::new(&slot_path).exists() {
                first_playable.session_overwrite_pending_slot_id = Some(slot_id.clone());
                gameplay_log.last_result = format!("session_slot_{slot_id}_overwrite_pending");
                push_feedback_event(
                    first_playable,
                    &format!("Confirm overwrite slot {slot_id} before saving"),
                );
                refresh_contextual_action_runtime(first_playable);
                return None;
            }
            first_playable.session_overwrite_pending_slot_id = None;
            let snapshot = native_playable_save_snapshot(
                world,
                character,
                gameplay_log,
                first_playable,
                actor_id,
            );
            match write_native_playable_snapshot_slot(&slot_path, &snapshot) {
                Ok(bytes) => {
                    gameplay_log.last_result =
                        format!("session_slot_{slot_id}_selected_saved:{bytes}");
                    push_progression_checkpoint(
                        first_playable,
                        &format!("session_slot_{slot_id}_selected_saved"),
                    );
                    push_feedback_event(
                        first_playable,
                        &format!("Selected slot {slot_id} saved: {bytes} bytes"),
                    );
                }
                Err(error) => {
                    gameplay_log.last_result =
                        format!("session_slot_{slot_id}_selected_save_failed");
                    gameplay_log.last_rejection = Some(error.to_string());
                    push_feedback_event(
                        first_playable,
                        &format!("Selected slot {slot_id} save failed: {error}"),
                    );
                }
            }
            refresh_contextual_action_runtime(first_playable);
            return None;
        }
        NativeControlAction::ConfirmOverwriteSlot => {
            let slot_id = first_playable
                .session_overwrite_pending_slot_id
                .as_deref()
                .map(normalize_session_slot_id)
                .unwrap_or_else(|| {
                    normalize_session_slot_id(&first_playable.session_selected_slot_id)
                });
            let slot_path = native_action_session_slot_path(&slot_id);
            first_playable.session_selected_slot_id = slot_id.clone();
            first_playable.session_overwrite_pending_slot_id = None;
            gameplay_log.turn += 1;
            gameplay_log.last_action = format!("confirm-overwrite:slot:{slot_id}");
            gameplay_log.last_rejection = None;
            let snapshot = native_playable_save_snapshot(
                world,
                character,
                gameplay_log,
                first_playable,
                actor_id,
            );
            match write_native_playable_snapshot_slot(&slot_path, &snapshot) {
                Ok(bytes) => {
                    gameplay_log.last_result =
                        format!("session_slot_{slot_id}_overwritten:{bytes}");
                    push_progression_checkpoint(
                        first_playable,
                        &format!("session_slot_{slot_id}_overwritten"),
                    );
                    push_feedback_event(
                        first_playable,
                        &format!("Slot {slot_id} overwrite confirmed: {bytes} bytes"),
                    );
                }
                Err(error) => {
                    gameplay_log.last_result = format!("session_slot_{slot_id}_overwrite_failed");
                    gameplay_log.last_rejection = Some(error.to_string());
                    push_feedback_event(
                        first_playable,
                        &format!("Slot {slot_id} overwrite failed: {error}"),
                    );
                }
            }
            refresh_contextual_action_runtime(first_playable);
            return None;
        }
        NativeControlAction::CancelOverwriteSlot => {
            let slot_id = first_playable
                .session_overwrite_pending_slot_id
                .as_deref()
                .map(normalize_session_slot_id)
                .unwrap_or_else(|| {
                    normalize_session_slot_id(&first_playable.session_selected_slot_id)
                });
            first_playable.session_overwrite_pending_slot_id = None;
            gameplay_log.turn += 1;
            gameplay_log.last_action = format!("cancel-overwrite:slot:{slot_id}");
            gameplay_log.last_result = format!("session_slot_{slot_id}_overwrite_cancelled");
            gameplay_log.last_rejection = None;
            push_feedback_event(
                first_playable,
                &format!("Slot {slot_id} overwrite cancelled"),
            );
            refresh_contextual_action_runtime(first_playable);
            return None;
        }
        NativeControlAction::LoadSelectedSlot => {
            let slot_id = normalize_session_slot_id(&first_playable.session_selected_slot_id);
            let slot_path = native_action_session_slot_path(&slot_id);
            let slot_result = read_native_playable_snapshot_slot(&slot_path);
            match slot_result {
                Ok(snapshot) => {
                    let (
                        restored_world,
                        restored_character,
                        mut restored_log,
                        mut restored_first_playable,
                    ) = native_restore_playable_save_snapshot(snapshot);
                    restored_first_playable.session_selected_slot_id = slot_id.clone();
                    restored_first_playable.session_overwrite_pending_slot_id = None;
                    push_progression_checkpoint(
                        &mut restored_first_playable,
                        "session_snapshot_restored",
                    );
                    push_progression_checkpoint(
                        &mut restored_first_playable,
                        &format!("session_selected_slot_{slot_id}_restored"),
                    );
                    restored_log.turn += 1;
                    restored_log.last_action = format!("load:selected:{slot_id}");
                    restored_log.last_result = format!("session_selected_slot_{slot_id}_loaded");
                    restored_log.last_rejection = None;
                    push_feedback_event(
                        &mut restored_first_playable,
                        &format!("Selected slot {slot_id} loaded: restored"),
                    );
                    mark_session_resume_overlay(&mut restored_first_playable, &slot_id);
                    refresh_contextual_action_runtime(&mut restored_first_playable);
                    *world = restored_world;
                    *character = restored_character;
                    *gameplay_log = restored_log;
                    *first_playable = restored_first_playable;
                }
                Err(error) => {
                    gameplay_log.turn += 1;
                    gameplay_log.last_action = format!("load:selected:{slot_id}");
                    gameplay_log.last_result =
                        format!("session_selected_slot_{slot_id}_load_failed");
                    gameplay_log.last_rejection = Some(error.to_string());
                    push_feedback_event(
                        first_playable,
                        &format!("Selected slot {slot_id} load failed: {error}"),
                    );
                    refresh_contextual_action_runtime(first_playable);
                }
            }
            return None;
        }
        NativeControlAction::Move { direction }
            if !first_playable
                .completed_steps
                .iter()
                .any(|step| step == "train_basic_unarmed")
                || first_playable
                    .completed_steps
                    .iter()
                    .any(|step| step == "arrive_at_first_objective") =>
        {
            let arrived_at_objective = first_playable
                .completed_steps
                .iter()
                .any(|step| step == "arrive_at_first_objective");
            record_runtime_only_log(
                gameplay_log,
                format!("local_move:{direction}"),
                if arrived_at_objective {
                    "local_map_step_after_arrival".to_string()
                } else {
                    "local_map_step_before_training".to_string()
                },
                None,
            );
            update_first_playable_runtime(
                first_playable,
                &NativeControlAction::Move { direction },
                None,
                character,
                world,
                actor_id,
            );
            return None;
        }
        _ => {}
    }
    let action_for_runtime = action.clone();
    let response = apply_native_control_action(world, character, gameplay_log, actor_id, action);
    update_first_playable_runtime(
        first_playable,
        &action_for_runtime,
        response.as_ref(),
        character,
        world,
        actor_id,
    );
    response
}

fn classic_rts_default_group_units() -> Vec<String> {
    string_vec([
        "player",
        "square_guard_patrol",
        "square_worker_carry",
        "square_creep_wander",
    ])
}

fn classic_rts_group_two_units() -> Vec<String> {
    string_vec(["square_guard_patrol", "square_creep_wander"])
}

fn classic_rts_unit_selection_class(unit_id: &str) -> &'static str {
    if unit_id.contains("guard") || unit_id == "player" {
        "guard"
    } else if unit_id.contains("worker") {
        "worker"
    } else if unit_id.contains("creep") {
        "creep"
    } else {
        "unit"
    }
}

fn classic_rts_same_class_units(unit_id: &str) -> Vec<String> {
    match classic_rts_unit_selection_class(unit_id) {
        "guard" => string_vec(["player", "square_guard_front", "square_guard_patrol"]),
        "worker" => string_vec(["square_worker_carry", "square_worker_harvest"]),
        "creep" => string_vec(["square_creep_wander"]),
        _ => vec![unit_id.to_string()],
    }
}

fn classic_rts_selectable_unit_entries() -> [(&'static str, (i32, i32), &'static str, u8); 6] {
    [
        ("player", (5, 4), "player", 0),
        ("square_guard_front", (5, 4), "player", 1),
        ("square_guard_patrol", (7, 5), "player", 2),
        ("square_worker_carry", (4, 5), "player", 3),
        ("square_worker_harvest", (8, 5), "player", 4),
        ("square_creep_wander", (9, 4), "hostile", 20),
    ]
}

fn classic_rts_unit_allegiance(unit_id: &str) -> &'static str {
    classic_rts_selectable_unit_entries()
        .into_iter()
        .find_map(|(entry_unit_id, _, allegiance, _)| {
            (entry_unit_id == unit_id).then_some(allegiance)
        })
        .unwrap_or("unknown")
}

fn classic_rts_unit_is_player_owned(unit_id: &str) -> bool {
    classic_rts_unit_allegiance(unit_id) == "player"
}

fn classic_rts_unit_selection_priority(unit_id: &str) -> u8 {
    classic_rts_selectable_unit_entries()
        .into_iter()
        .find_map(|(entry_unit_id, _, _, priority)| (entry_unit_id == unit_id).then_some(priority))
        .unwrap_or(u8::MAX)
}

fn classic_rts_selectable_unit_tile(unit_id: &str) -> Option<(i32, i32)> {
    classic_rts_selectable_unit_entries()
        .into_iter()
        .find_map(|(entry_unit_id, tile, _, _)| (entry_unit_id == unit_id).then_some(tile))
}

fn classic_rts_selectable_unit_at_tile(tile: (i32, i32)) -> Option<&'static str> {
    classic_rts_selectable_unit_entries()
        .into_iter()
        .filter(|(_, unit_tile, _, _)| *unit_tile == tile)
        .min_by_key(|(unit_id, _, allegiance, priority)| {
            let allegiance_priority = if *allegiance == "player" { 0 } else { 1 };
            (allegiance_priority, *priority, *unit_id)
        })
        .map(|(unit_id, _, _, _)| unit_id)
}

fn classic_rts_selection_clear_parts(group_id: &str) -> Option<(String, Option<String>, String)> {
    let payload = group_id.strip_prefix("clear:")?;
    if let Some(tile_id) = payload.strip_prefix("empty@") {
        return Some(("empty".to_string(), None, tile_id.to_string()));
    }
    if let Some(hostile_payload) = payload.strip_prefix("hostile:") {
        let (unit_id, tile_id) = hostile_payload.split_once('@')?;
        return Some((
            "hostile".to_string(),
            Some(unit_id.to_string()),
            tile_id.to_string(),
        ));
    }
    None
}

fn classic_rts_selection_tiles_for_units(unit_ids: &[String]) -> Vec<String> {
    let mut tiles = Vec::new();
    for unit_id in unit_ids {
        if let Some(tile) = classic_rts_selectable_unit_tile(unit_id) {
            push_unique_string(&mut tiles, &classic_rts_tile_id(tile));
        }
    }
    tiles
}

fn classic_rts_selection_box_tiles() -> Vec<String> {
    string_vec(["5,5", "6,5", "5,4", "6,4"])
}

fn classic_rts_control_group_hotkey_slot(group_id: &str, prefix: &str) -> Option<String> {
    group_id
        .strip_prefix(prefix)
        .map(str::trim)
        .filter(|slot| !slot.is_empty())
        .map(ToOwned::to_owned)
}

fn classic_rts_default_units_for_control_group_slot(slot: &str) -> Vec<String> {
    match slot {
        "2" => classic_rts_group_two_units(),
        "3" => string_vec(["square_worker_carry", "square_worker_harvest"]),
        _ => classic_rts_default_group_units(),
    }
}

fn classic_rts_units_from_control_group_assignment(
    assignments: &[String],
    slot: &str,
) -> Vec<String> {
    let prefix = format!("{slot}:");
    for assignment in assignments.iter().rev() {
        let Some(payload) = assignment.strip_prefix(&prefix) else {
            continue;
        };
        let unit_payload = payload.rsplit(':').next().unwrap_or(payload);
        let units = unit_payload
            .split('|')
            .map(str::trim)
            .filter(|unit| !unit.is_empty())
            .filter(|unit| classic_rts_selectable_unit_tile(unit).is_some())
            .map(ToOwned::to_owned)
            .collect::<Vec<_>>();
        if !units.is_empty() {
            return units;
        }
    }
    Vec::new()
}

fn classic_rts_control_group_slot_label(slot: &str) -> &str {
    if slot == "10" {
        "0"
    } else {
        slot
    }
}

fn classic_rts_control_group_slot_member_count(
    runtime: &NativeFirstPlayableRuntime,
    slot: &str,
) -> usize {
    classic_rts_units_from_control_group_assignment(&runtime.rts_control_group_assignments, slot)
        .len()
}

fn classic_rts_control_group_slot_is_active(
    runtime: &NativeFirstPlayableRuntime,
    slot: &str,
) -> bool {
    runtime
        .rts_active_control_group_ids
        .iter()
        .any(|group| group == slot)
        || runtime.rts_control_group_id.as_deref() == Some(slot)
}

fn classic_rts_control_group_slot_summaries(runtime: &NativeFirstPlayableRuntime) -> Vec<Value> {
    (1..=10)
        .map(|slot_index| {
            let slot = slot_index.to_string();
            let member_count = classic_rts_control_group_slot_member_count(runtime, &slot);
            json!({
                "slot": slot,
                "key_label": classic_rts_control_group_slot_label(&slot),
                "member_count": member_count,
                "occupied": member_count > 0,
                "active": classic_rts_control_group_slot_is_active(runtime, &slot),
            })
        })
        .collect()
}

fn replace_classic_rts_control_group_assignment(
    assignments: &mut Vec<String>,
    slot: &str,
    unit_ids: &[String],
) {
    let prefix = format!("{slot}:");
    assignments.retain(|assignment| !assignment.starts_with(&prefix));
    push_unique_string(assignments, &format!("{slot}:{}", unit_ids.join("|")));
}

fn replace_classic_rts_control_group_assignment_tagged(
    assignments: &mut Vec<String>,
    slot: &str,
    tag: &str,
    unit_ids: &[String],
) {
    let prefix = format!("{slot}:");
    assignments.retain(|assignment| !assignment.starts_with(&prefix));
    push_unique_string(assignments, &format!("{slot}:{tag}:{}", unit_ids.join("|")));
}

fn classic_rts_merged_unit_ids(base_units: &[String], extra_units: &[String]) -> Vec<String> {
    let mut merged = base_units.to_vec();
    for unit_id in extra_units {
        push_unique_string(&mut merged, unit_id);
    }
    merged
}

fn classic_rts_drag_selection_parts(group_id: &str) -> Option<((i32, i32), (i32, i32))> {
    let payload = group_id.strip_prefix("drag:")?;
    let (start, end) = payload.split_once("->")?;
    Some((classic_parse_rts_tile(start)?, classic_parse_rts_tile(end)?))
}

fn classic_rts_selection_box_tiles_between(start: (i32, i32), end: (i32, i32)) -> Vec<String> {
    let start = classic_rts_large_map_clamp_tile(start);
    let end = classic_rts_large_map_clamp_tile(end);
    let min_x = start.0.min(end.0);
    let max_x = start.0.max(end.0);
    let min_y = start.1.min(end.1);
    let max_y = start.1.max(end.1);
    let mut tiles = Vec::new();
    for y in min_y..=max_y {
        for x in min_x..=max_x {
            tiles.push(classic_rts_tile_id((x, y)));
        }
    }
    tiles
}

fn classic_rts_drag_selected_units(start: (i32, i32), end: (i32, i32)) -> Vec<String> {
    classic_rts_drag_units_between(start, end, true)
}

fn classic_rts_drag_rejected_unit_ids(start: (i32, i32), end: (i32, i32)) -> Vec<String> {
    classic_rts_drag_units_between(start, end, false)
        .into_iter()
        .filter(|unit_id| !classic_rts_unit_is_player_owned(unit_id))
        .collect()
}

fn classic_rts_drag_units_between(
    start: (i32, i32),
    end: (i32, i32),
    owned_only: bool,
) -> Vec<String> {
    let start = classic_rts_large_map_clamp_tile(start);
    let end = classic_rts_large_map_clamp_tile(end);
    let min_x = start.0.min(end.0);
    let max_x = start.0.max(end.0);
    let min_y = start.1.min(end.1);
    let max_y = start.1.max(end.1);
    let mut selected = Vec::new();
    for (unit_id, tile, _, _) in classic_rts_selectable_unit_entries() {
        if tile.0 >= min_x && tile.0 <= max_x && tile.1 >= min_y && tile.1 <= max_y {
            if !owned_only || classic_rts_unit_is_player_owned(unit_id) {
                push_unique_string(&mut selected, unit_id);
            }
        }
    }
    selected
}

fn classic_rts_move_command_parts(command_id: &str) -> (&str, &str) {
    let command_payload = command_id.strip_prefix("minimap:").unwrap_or(command_id);
    let mut parts = command_payload.splitn(2, ':');
    let tile_id = parts
        .next()
        .filter(|value| !value.trim().is_empty())
        .unwrap_or("7,4");
    let formation = parts
        .next()
        .filter(|value| !value.trim().is_empty())
        .unwrap_or("diamond");
    (tile_id, formation)
}

