fn turn_combat_attack_damage(runtime: &NativeFirstPlayableRuntime) -> i32 {
    let base_damage = if runtime.combat_turn >= 4 { 18 } else { 14 };
    if runtime_has_active_sash_stat(runtime, "force") {
        base_damage + 4
    } else {
        base_damage
    }
}

fn turn_combat_incoming_damage(runtime: &NativeFirstPlayableRuntime) -> i32 {
    let base = if runtime_has_active_sash_stat(runtime, "agility") {
        3
    } else {
        6
    };
    let mastery_adjusted = if runtime_has_build_mastery(runtime, "force") {
        base - 2
    } else {
        base
    };
    let title_adjusted = if runtime_has_active_build_title(runtime, "force") {
        mastery_adjusted - 1
    } else {
        mastery_adjusted
    };
    title_adjusted.max(1)
}

fn turn_combat_defend_heal(runtime: &NativeFirstPlayableRuntime) -> i32 {
    if runtime_has_active_sash_stat(runtime, "agility") {
        6
    } else {
        4
    }
}

fn task_completion_coin_reward(runtime: &NativeFirstPlayableRuntime) -> u64 {
    let base = if runtime_has_active_sash_stat(runtime, "craft") {
        14
    } else {
        10
    };
    let mastery_base = if runtime_has_build_mastery(runtime, "craft") {
        base + 3
    } else {
        base
    };
    if runtime_has_active_build_title(runtime, "craft") {
        mastery_base + 2
    } else {
        mastery_base
    }
}

fn task_completion_xp_reward(runtime: &NativeFirstPlayableRuntime) -> u64 {
    if runtime_has_active_sash_stat(runtime, "craft") {
        45
    } else {
        40
    }
}

fn combat_stat_effect_floating_text(
    runtime: &NativeFirstPlayableRuntime,
    damage: i32,
    incoming_damage: i32,
    enemy_alive: bool,
) -> String {
    let force_suffix = if runtime_has_active_sash_stat(runtime, "force") {
        " | FORCE +4 DMG"
    } else {
        ""
    };
    let agility_suffix = if enemy_alive && runtime_has_active_sash_stat(runtime, "agility") {
        " | AGILITY -3 INCOMING"
    } else {
        ""
    };
    let force_mastery_suffix = if enemy_alive && runtime_has_build_mastery(runtime, "force") {
        " | FORCE MASTERY -2 INCOMING"
    } else {
        ""
    };
    let force_title_suffix = if enemy_alive && runtime_has_active_build_title(runtime, "force") {
        " | FORCE TITLE -1 INCOMING"
    } else {
        ""
    };
    format!(
        "FLOAT DMG -{damage} | INCOMING -{incoming_damage}{force_suffix}{agility_suffix}{force_mastery_suffix}{force_title_suffix}"
    )
}

fn defend_stat_effect_floating_text(runtime: &NativeFirstPlayableRuntime, heal: i32) -> String {
    let agility_suffix = if runtime_has_active_sash_stat(runtime, "agility") {
        " | AGILITY +2 RECOVERY"
    } else {
        ""
    };
    format!("FLOAT GUARD +{heal} HP{agility_suffix}")
}

fn reward_settlement_text(runtime: &NativeFirstPlayableRuntime, coins: u64, xp: u64) -> String {
    let title_suffix = if runtime_has_active_build_title(runtime, "craft") {
        " | CRAFT TITLE +2 coins"
    } else {
        ""
    };
    if runtime_has_active_sash_stat(runtime, "craft") && runtime_has_build_mastery(runtime, "craft")
    {
        format!(
            "SETTLEMENT +{coins} coins +{xp} XP | CRAFT +4 coins +5 XP | CRAFT MASTERY +3 coins{title_suffix}"
        )
    } else if runtime_has_active_sash_stat(runtime, "craft") {
        format!("SETTLEMENT +{coins} coins +{xp} XP | CRAFT +4 coins +5 XP{title_suffix}")
    } else if runtime_has_build_mastery(runtime, "craft") {
        format!("SETTLEMENT +{coins} coins +{xp} XP | CRAFT MASTERY +3 coins{title_suffix}")
    } else {
        format!("SETTLEMENT +{coins} coins +{xp} XP{title_suffix}")
    }
}

