fn bandit_sash_affix_text(runtime: &NativeFirstPlayableRuntime) -> String {
    if !runtime_has_equipped_bandit_sash(runtime) {
        return "AFFIX locked | equip bandit_sash to attune a build".to_string();
    }
    if let Some(stat_id) = runtime.pending_stat_allocation.as_deref() {
        let preview = match stat_id {
            "force" => "iron-strike preview -> rematch attack +4 DMG",
            "agility" => "wind-guard preview -> incoming -3 / guard +2 HP",
            "craft" => "market-thread preview -> reward +4 coins +5 XP",
            other => {
                return format!("AFFIX PREVIEW | bandit_sash:{other} | custom route bonus pending")
            }
        };
        return format!("AFFIX PREVIEW | bandit_sash:{stat_id} | {preview}");
    }
    if runtime_has_active_sash_stat(runtime, "force") {
        return "AFFIX ACTIVE | bandit_sash:iron-strike | rematch attack +4 DMG".to_string();
    }
    if runtime_has_active_sash_stat(runtime, "agility") {
        return "AFFIX ACTIVE | bandit_sash:wind-guard | incoming -3 / guard +2 HP".to_string();
    }
    if runtime_has_active_sash_stat(runtime, "craft") {
        return "AFFIX ACTIVE | bandit_sash:market-thread | reward +4 coins +5 XP".to_string();
    }
    "AFFIX dormant | choose force/agility/craft to attune bandit_sash".to_string()
}

fn apply_character_stat_allocation(
    character: &mut WorldTrillionniumCharacter,
    stat_id: &str,
) -> bool {
    match stat_id {
        "physique" => {
            character.attributes.physique = character.attributes.physique.saturating_add(1)
        }
        "force" => character.attributes.force = character.attributes.force.saturating_add(1),
        "agility" => character.attributes.agility = character.attributes.agility.saturating_add(1),
        "insight" => character.attributes.insight = character.attributes.insight.saturating_add(1),
        "resolve" => character.attributes.resolve = character.attributes.resolve.saturating_add(1),
        "craft" => character.attributes.craft = character.attributes.craft.saturating_add(1),
        "commerce" => {
            character.attributes.commerce = character.attributes.commerce.saturating_add(1)
        }
        _ => return false,
    }
    character
        .combat_numerics_state
        .ensure_defaults(&character.attributes);
    character.updated_at_epoch = native_now_epoch();
    true
}

fn update_log_from_world_response(
    gameplay_log: &mut NativeGameplayLog,
    action_label: String,
    response: &WorldApiCommandResponse,
) {
    gameplay_log.turn += 1;
    gameplay_log.last_action = action_label;
    gameplay_log.last_result = response.decision.reason.clone();
    gameplay_log.last_rejection = response
        .decision
        .transition
        .as_ref()
        .and_then(|transition| {
            transition
                .blocked_reason
                .clone()
                .or_else(|| (!transition.accepted).then(|| transition.result.clone()))
        });
}

fn update_log_from_tactics_outcome(
    gameplay_log: &mut NativeGameplayLog,
    action_label: &str,
    outcome: WorldTacticsCommandOutcome,
) {
    gameplay_log.turn += 1;
    gameplay_log.last_action = action_label.to_string();
    gameplay_log.last_result = outcome.result;
    gameplay_log.last_rejection = outcome.rejection_reason;
}

fn keyboard_direction(input: &ButtonInput<KeyCode>) -> Option<&'static str> {
    if input.pressed(KeyCode::ShiftLeft) || input.pressed(KeyCode::ShiftRight) {
        return None;
    }
    if input.just_pressed(KeyCode::ArrowRight) || input.just_pressed(KeyCode::KeyD) {
        Some("east")
    } else if input.just_pressed(KeyCode::ArrowLeft) || input.just_pressed(KeyCode::KeyA) {
        Some("west")
    } else if input.just_pressed(KeyCode::ArrowUp) || input.just_pressed(KeyCode::KeyW) {
        Some("north")
    } else if input.just_pressed(KeyCode::ArrowDown) || input.just_pressed(KeyCode::KeyS) {
        Some("south")
    } else if input.just_pressed(KeyCode::KeyQ) {
        Some("north-west")
    } else if input.just_pressed(KeyCode::KeyE) {
        Some("north-east")
    } else if input.just_pressed(KeyCode::KeyZ) {
        Some("south-west")
    } else if input.just_pressed(KeyCode::KeyX) {
        Some("south-east")
    } else {
        None
    }
}

pub fn sync_player_sprite_to_world(
    world: Res<AuthoritativeWorldResource>,
    bootstrap: Res<NativeWorldBootstrap>,
    first_playable: Res<NativeFirstPlayableRuntime>,
    layout: Res<BevyWorldLayout>,
    mut players: Query<(&mut Transform, &mut BevyWorldActorPosition), With<BevyPlayerSprite>>,
    mut sprite_parts: Query<
        (&mut Transform, &mut BevyWorldActorSpritePart),
        Without<BevyPlayerSprite>,
    >,
) {
    let Some(node_id) = player_node_id(&world.state, &bootstrap.actor_id) else {
        return;
    };
    let Some(position) = layout.node_positions.get(&node_id) else {
        return;
    };
    let frame = first_playable.walk_cycle_frame as f32;
    let body_bob = if first_playable.walk_cycle_frame.is_multiple_of(2) {
        0.0
    } else {
        2.0
    };
    for (mut transform, mut actor_position) in &mut players {
        transform.translation = *position + Vec3::new(0.0, -5.0 + body_bob, 4.0);
        actor_position.node_id = node_id.clone();
    }
    for (mut transform, mut part) in &mut sprite_parts {
        if part.actor_id.as_str() != bootstrap.actor_id.as_str() {
            continue;
        }
        let mut animated_offset = part.offset;
        if part.part_id == "player_left_foot" {
            animated_offset.x -= 1.5 + frame;
        } else if part.part_id == "player_right_foot" {
            animated_offset.x += 1.5 + frame;
        } else if part.part_id == "player_head" || part.part_id == "player_hair" {
            animated_offset.y += body_bob;
        }
        transform.translation = *position + Vec3::new(0.0, 0.0, 4.0) + animated_offset;
        part.node_id = node_id.clone();
    }
}

pub fn update_native_visible_actor_runtime(
    first_playable: Res<NativeFirstPlayableRuntime>,
    layout: Res<BevyWorldLayout>,
    mut actors: Query<(&mut Transform, &mut BevyWorldVisibleActorRuntime)>,
) {
    for (mut transform, mut actor) in &mut actors {
        let home_node = visible_actor_home_node(&actor.actor_id);
        actor.node_id = home_node.clone();
        actor.visible_state = visible_actor_visible_state(&first_playable, &actor);
        actor.behavior_state = visible_actor_behavior_state(&first_playable, &actor);
        actor.animation_state = visible_actor_animation_state(&first_playable, &actor);
        actor.patrol_frame = visible_actor_patrol_frame(&first_playable, &actor);
        actor.hp = visible_actor_hp(&first_playable, &actor);
        actor.facing = visible_actor_facing(&first_playable, &actor);
        let base = layout
            .node_positions
            .get(&home_node)
            .copied()
            .unwrap_or(Vec3::ZERO);
        let bob = if actor.visible_state == "visible"
            && actor.actor_kind != "drop"
            && actor.patrol_frame % 2 == 1
        {
            2.0
        } else {
            0.0
        };
        transform.translation = if actor.visible_state == "visible" {
            base + visible_actor_runtime_offset(&actor.actor_id) + Vec3::new(0.0, bob, 5.3)
        } else {
            Vec3::new(5000.0, 5000.0, -10.0)
        };
    }
}

fn visible_actor_home_node(actor_id: &str) -> String {
    scene_pack_actor(actor_id)
        .map(|actor| actor.room_id)
        .unwrap_or_else(|| "mirror-city-square".to_string())
}

fn visible_actor_runtime_offset(actor_id: &str) -> Vec3 {
    visible_actor_runtime_seeds()
        .into_iter()
        .find(|seed| seed.actor_id == actor_id)
        .map(|seed| seed.offset)
        .unwrap_or(Vec3::ZERO)
}

fn visible_actor_visible_state(
    runtime: &NativeFirstPlayableRuntime,
    actor: &BevyWorldVisibleActorRuntime,
) -> String {
    let visible = match actor.actor_kind.as_str() {
        "npc" => runtime
            .active_room_npc_ids
            .iter()
            .any(|npc_id| npc_id == &actor.actor_id),
        "enemy" => runtime.current_room_id == actor.node_id,
        "drop" => {
            runtime.current_room_id == actor.node_id
                && runtime
                    .dropped_items
                    .iter()
                    .any(|item| item == "bandit_sash")
        }
        _ => false,
    };
    if visible { "visible" } else { "hidden" }.to_string()
}

fn visible_actor_behavior_state(
    runtime: &NativeFirstPlayableRuntime,
    actor: &BevyWorldVisibleActorRuntime,
) -> String {
    if actor.visible_state != "visible" {
        return "hidden_not_current_room".to_string();
    }
    match actor.actor_kind.as_str() {
        "npc" => {
            if runtime
                .multi_room_history
                .iter()
                .any(|event| event == &format!("interact_npc:{}", actor.actor_id))
            {
                format!("dialogue_or_task_ready:{}", actor.actor_id)
            } else {
                format!("patrol_waiting:{}", actor.actor_id)
            }
        }
        "enemy" => {
            if runtime.enemy_hp == 0 {
                "defeated_drop_ready".to_string()
            } else if runtime.combat_turn > 0 {
                "turn_combat_engaged".to_string()
            } else {
                "arena_guard_patrol".to_string()
            }
        }
        "drop" => "loot_drop_waiting_for_pickup".to_string(),
        _ => "runtime_visible".to_string(),
    }
}

fn visible_actor_animation_state(
    runtime: &NativeFirstPlayableRuntime,
    actor: &BevyWorldVisibleActorRuntime,
) -> String {
    if actor.visible_state != "visible" {
        return "hidden".to_string();
    }
    match actor.actor_kind.as_str() {
        "npc" => format!("npc_step_frame_{}", runtime.npc_patrol_frame),
        "enemy" if runtime.enemy_hp == 0 => "enemy_down_victory".to_string(),
        "enemy" if runtime.combat_turn > 0 => {
            format!("enemy_hit_frame_{}", runtime.enemy_patrol_frame)
        }
        "enemy" => format!("enemy_patrol_frame_{}", runtime.enemy_patrol_frame),
        "drop" => "drop_sparkle_visible".to_string(),
        _ => "idle".to_string(),
    }
}

fn visible_actor_patrol_frame(
    runtime: &NativeFirstPlayableRuntime,
    actor: &BevyWorldVisibleActorRuntime,
) -> u8 {
    match actor.actor_kind.as_str() {
        "enemy" => runtime.enemy_patrol_frame,
        "drop" => runtime.combat_turn,
        _ => runtime.npc_patrol_frame,
    }
}

fn visible_actor_hp(
    runtime: &NativeFirstPlayableRuntime,
    actor: &BevyWorldVisibleActorRuntime,
) -> i32 {
    match actor.actor_kind.as_str() {
        "enemy" => runtime.enemy_hp,
        "npc" => 100,
        _ => 0,
    }
}

fn visible_actor_facing(
    runtime: &NativeFirstPlayableRuntime,
    actor: &BevyWorldVisibleActorRuntime,
) -> String {
    match actor.actor_kind.as_str() {
        "enemy" => "west".to_string(),
        "drop" => "none".to_string(),
        _ => runtime.facing_direction.clone(),
    }
}

#[allow(clippy::too_many_arguments, clippy::type_complexity)]
pub fn update_native_world_hud(
    world: Res<AuthoritativeWorldResource>,
    bootstrap: Res<NativeWorldBootstrap>,
    gameplay_log: Res<NativeGameplayLog>,
    tactics_character: Res<NativeTacticsCharacter>,
    first_playable: Res<NativeFirstPlayableRuntime>,
    mut hud_texts: Query<
        &mut Text,
        (
            With<BevyWorldHudText>,
            Without<BevyWorldActionLogText>,
            Without<BevyWorldRoomPanelText>,
        ),
    >,
    mut action_texts: Query<
        &mut Text,
        (
            With<BevyWorldActionLogText>,
            Without<BevyWorldHudText>,
            Without<BevyWorldRoomPanelText>,
        ),
    >,
    mut room_texts: Query<
        &mut Text,
        (
            With<BevyWorldRoomPanelText>,
            Without<BevyWorldHudText>,
            Without<BevyWorldActionLogText>,
        ),
    >,
) {
    let node_id =
        player_node_id(&world.state, &bootstrap.actor_id).unwrap_or_else(|| "unknown".to_string());
    let exits = exits_for_node(&world.state, &node_id);
    let objective = playable_objective_for_actor(&world.state, &bootstrap.actor_id);
    let local_npcs = local_npc_names_for_actor(&world.state, &bootstrap.actor_id);
    let known_skill_count = tactics_character.character.skill_ids.len();
    let has_unarmed = tactics_character
        .character
        .skill_ids
        .iter()
        .any(|skill| skill == "basic_unarmed");
    let next_prompt = first_playable_next_prompt(&first_playable);
    for mut text in &mut hud_texts {
        text.0 = String::new();
    }
    for mut text in &mut action_texts {
        text.0 = format!(
            "DEV LOG | Turn {} | Last {} -> {}{} | Shortcuts: Move WASD/Arrows, Enter primary, R/T/F/C/I quick actions",
            gameplay_log.turn,
            gameplay_log.last_action,
            gameplay_log.last_result,
            gameplay_log
                .last_rejection
                .as_ref()
                .map(|reason| format!(" ({reason})"))
                .unwrap_or_default()
        );
    }
    for mut text in &mut room_texts {
        text.0 = format!(
            "PLAYER ROUTE | {}\nNEXT STEP | {}\nPROGRESS | {}\nLOCATION | {} ({})\nWORLD | Exits {} | NPCs {} | Skill {}{}\nREWARD | {} | Gear {}",
            objective_mission_summary(objective.as_ref()),
            next_prompt,
            first_playable_checklist(&first_playable),
            node_scene_label(&node_id),
            node_id,
            if exits.is_empty() {
                "none".to_string()
            } else {
                exits.join(", ")
            },
            if local_npcs.is_empty() {
                "none".to_string()
            } else {
                "mentor".to_string()
            },
            known_skill_count,
            if has_unarmed { " + unarmed" } else { "" },
            if first_playable.reward_claimed {
                "claimed"
            } else {
                "pending"
            },
            if first_playable.equipment_ready {
                "ready"
            } else {
                "pending"
            }
        );
    }
}

fn objective_mission_summary(objective: Option<&NativePlayableObjective>) -> String {
    objective
        .map(|objective| {
            format!(
                "Reach {} and clear starter route",
                node_scene_label(&objective.target_node_id)
            )
        })
        .unwrap_or_else(|| "Find a local objective".to_string())
}

fn player_facing_status_hud_text(
    runtime: &NativeFirstPlayableRuntime,
    weapon_label: &str,
) -> String {
    format!(
        "PLAYER HUD | HP {}/176 | Enemy {} | XP {} | Coins {} | Room {} | Goal {} | Next {} | Gear {} | {}",
        runtime.player_hp,
        runtime.enemy_hp,
        runtime.xp,
        runtime.coins,
        node_scene_label(&runtime.current_room_id),
        first_minute_onboarding_state_hint(runtime),
        first_minute_onboarding_next_button(runtime),
        weapon_label,
        active_build_title_status_text(runtime)
    )
}

fn debug_layer_event_log_text(
    recent_events: &str,
    input_summary_line: &str,
    recent_input_feedback: &str,
    gameplay_log: &NativeGameplayLog,
) -> String {
    format!(
        "DEBUG LAYER | input/runtime diagnostics\n{}\n\nINPUT\n{}\n{}\n\nTurn {}: {} -> {}{}",
        recent_events,
        input_summary_line,
        if recent_input_feedback.is_empty() {
            "waiting"
        } else {
            recent_input_feedback
        },
        gameplay_log.turn,
        gameplay_log.last_action,
        gameplay_log.last_result,
        gameplay_log
            .last_rejection
            .as_ref()
            .map(|reason| format!(" ({reason})"))
            .unwrap_or_default()
    )
}

fn player_action_coach_control_action(
    runtime: &NativeFirstPlayableRuntime,
) -> Option<NativeControlAction> {
    if runtime.pending_stat_allocation.is_some() {
        Some(NativeControlAction::ConfirmStatAllocation)
    } else if runtime.session_character_create_visible
        || runtime.session_character_create_input_locked
    {
        Some(NativeControlAction::ConfirmCharacterCreate)
    } else if runtime.session_resume_input_locked || runtime.session_continue_cta_visible {
        Some(NativeControlAction::ContinueAfterLoad)
    } else if runtime.session_pause_menu_visible || runtime.session_pause_input_locked {
        Some(NativeControlAction::ResumeFromPause)
    } else if let Some(focus_action) = build_branch_title_route_action_focus_control_action(runtime)
    {
        Some(focus_action)
    } else {
        native_control_action_from_label(first_minute_onboarding_next_button(runtime))
    }
}

fn player_action_coach_action_label(runtime: &NativeFirstPlayableRuntime) -> String {
    player_action_coach_control_action(runtime)
        .map(|action| native_control_action_label(&action))
        .unwrap_or_else(|| "none".to_string())
}

fn player_action_coach_shortcut_label(action_label: &str) -> String {
    match action_label {
        "TALK" => "R / Enter".to_string(),
        "TRAIN" => "T / Enter".to_string(),
        "MOVE:north" => "W / Enter".to_string(),
        "FIGHT" => "F or Space / Enter".to_string(),
        "COMPLETE" => "C / Enter".to_string(),
        "EQUIP" => "I / Enter".to_string(),
        "SAVE:SELECTED" | "TITLE:OPEN" | "TITLE:CONTINUE" | "CONTINUE:SESSION" => {
            "Enter".to_string()
        }
        "CAMPAIGN:START" | "CAMPAIGN:CONTINUE" | "CAMPAIGN:REPLAY" => "Enter".to_string(),
        "CREATE:CONFIRM" => "Enter".to_string(),
        "STAT:confirm" => "M / Enter".to_string(),
        label if label.starts_with("ROOM:") => "tap room button / Enter".to_string(),
        label if label.starts_with("TASK:") => "tap task button / Enter".to_string(),
        label if label.starts_with("TITLE:EQUIP:") || label == "TITLE:ROUTE" => "Enter".to_string(),
        "none" => "none".to_string(),
        _ => "tap highlighted button".to_string(),
    }
}

fn player_action_coach_text(runtime: &NativeFirstPlayableRuntime) -> String {
    let action_label = player_action_coach_action_label(runtime);
    let shortcut = player_action_coach_shortcut_label(&action_label);
    let prompt = first_playable_next_prompt(runtime);
    format!(
        "ACTION COACH | Enter/NumpadEnter -> {action_label} | Shortcut {shortcut} | Goal {prompt} | Room {}",
        node_scene_label(&runtime.current_room_id)
    )
}

fn first_playable_next_prompt(runtime: &NativeFirstPlayableRuntime) -> &'static str {
    if runtime.session_title_menu_visible || runtime.session_title_input_locked {
        return if first_minute_slot_a_ready(runtime) {
            "Press TITLE:CONTINUE to resume the saved first-minute route"
        } else {
            "Press TITLE:NEW to create a character"
        };
    }
    if runtime.session_character_create_visible || runtime.session_character_create_input_locked {
        return "Press CREATE:NAME / CREATE:ARCHETYPE, then CREATE:CONFIRM";
    }
    if runtime.session_resume_input_locked || runtime.session_continue_cta_visible {
        return "Press CONTINUE:SESSION to restore map controls";
    }
    if first_minute_onboarding_next_button(runtime) == "SAVE:SELECTED" {
        return "Press SAVE:SELECTED to checkpoint the first fight";
    }
    if first_minute_onboarding_next_button(runtime) == "TITLE:OPEN" {
        return "Press TITLE:OPEN, then continue from slot A";
    }
    if runtime.pending_stat_allocation.is_some() {
        return "Confirm STAT:confirm to spend 1 point, or STAT:cancel to keep the point";
    }
    if runtime.growth_stat_points > 0 {
        return "Preview STAT:force / STAT:agility / STAT:craft, then confirm before spending";
    }
    if !runtime
        .completed_steps
        .iter()
        .any(|step| step == "talk_to_mentor")
    {
        "Press R or TALK to meet the mentor"
    } else if !runtime
        .completed_steps
        .iter()
        .any(|step| step == "train_basic_unarmed")
    {
        "Press T or TRAIN to learn basic_unarmed"
    } else if !runtime
        .completed_steps
        .iter()
        .any(|step| step == "arrive_at_first_objective")
    {
        "Move NORTH to enter the arena"
    } else if !runtime
        .completed_steps
        .iter()
        .any(|step| step == "resolve_first_combat")
    {
        "Press F or FIGHT to resolve the first combat"
    } else if !runtime
        .completed_steps
        .iter()
        .any(|step| step == "complete_first_task")
    {
        "Press C or COMPLETE to settle the route task"
    } else if !runtime
        .completed_steps
        .iter()
        .any(|step| step == "equip_route_guard_staff")
    {
        "Press I or EQUIP to ready the route staff"
    } else if runtime.visited_rooms.len() < 5 {
        "Explore STUDIO / FORGE / YARD / MARKET / BOARD"
    } else if runtime.combat_result_state != "victory" {
        "Use ATTACK / DEFEND / POTION for turn combat"
    } else {
        "Continue accepting room tasks"
    }
}

fn runtime_has_completed_step(runtime: &NativeFirstPlayableRuntime, step: &str) -> bool {
    runtime.completed_steps.iter().any(|done| done == step)
}

fn runtime_has_checkpoint(runtime: &NativeFirstPlayableRuntime, checkpoint: &str) -> bool {
    runtime
        .progression_checkpoint_history
        .iter()
        .any(|done| done == checkpoint)
}

fn runtime_has_accepted_action(runtime: &NativeFirstPlayableRuntime, action_label: &str) -> bool {
    runtime
        .input_feedback_history
        .iter()
        .any(|event| event.accepted && event.action_label == action_label)
}

fn first_minute_slot_a_ready(runtime: &NativeFirstPlayableRuntime) -> bool {
    runtime_has_accepted_action(runtime, "SAVE:SELECTED")
        || runtime_has_accepted_action(runtime, "SAVE:A")
        || runtime_has_checkpoint(runtime, "title_slot_A_restored")
        || runtime.session_title_last_slot_id.as_deref() == Some("A")
        || Path::new(&native_action_session_slot_path("A")).exists()
}

fn first_minute_character_created(runtime: &NativeFirstPlayableRuntime) -> bool {
    runtime_has_checkpoint(runtime, "character_created_from_title")
        || runtime_has_accepted_action(runtime, "CREATE:CONFIRM")
        || runtime.session_title_boot_state == "new_game_started"
        || runtime.session_title_boot_state == "game_active"
            && !runtime.session_title_menu_visible
            && !runtime.session_character_create_visible
}

fn first_minute_continue_restored(runtime: &NativeFirstPlayableRuntime) -> bool {
    runtime_has_checkpoint(runtime, "title_slot_A_restored")
        && !runtime.session_resume_input_locked
        && !runtime.session_continue_cta_visible
        && runtime.session_title_boot_state == "game_active"
}

fn first_minute_onboarding_next_button(runtime: &NativeFirstPlayableRuntime) -> &'static str {
    if runtime.session_title_menu_visible || runtime.session_title_input_locked {
        return if first_minute_slot_a_ready(runtime) {
            "TITLE:CONTINUE"
        } else {
            "TITLE:NEW"
        };
    }
    if runtime.session_character_create_visible || runtime.session_character_create_input_locked {
        return "CREATE:CONFIRM";
    }
    if runtime.session_resume_input_locked || runtime.session_continue_cta_visible {
        return "CONTINUE:SESSION";
    }
    if !first_minute_character_created(runtime) {
        "TITLE:NEW"
    } else if !runtime_has_completed_step(runtime, "talk_to_mentor") {
        "TALK"
    } else if !runtime_has_completed_step(runtime, "train_basic_unarmed") {
        "TRAIN"
    } else if !runtime_has_completed_step(runtime, "arrive_at_first_objective") {
        "MOVE:north"
    } else if !runtime_has_completed_step(runtime, "resolve_first_combat") {
        "FIGHT"
    } else if !first_minute_slot_a_ready(runtime) {
        "SAVE:SELECTED"
    } else if !runtime_has_checkpoint(runtime, "title_slot_A_restored") {
        "TITLE:OPEN"
    } else if !first_minute_continue_restored(runtime) {
        "CONTINUE:SESSION"
    } else {
        "FIRST MINUTE COMPLETE"
    }
}

fn first_minute_onboarding_state_hint(runtime: &NativeFirstPlayableRuntime) -> &'static str {
    match first_minute_onboarding_next_button(runtime) {
        "TITLE:NEW" => "start a new profile",
        "CREATE:CONFIRM" => "choose name/style",
        "TALK" => "meet mentor",
        "TRAIN" => "learn basic_unarmed",
        "MOVE:north" => "walk to arena",
        "FIGHT" => "resolve first combat",
        "SAVE:SELECTED" => "save slot A",
        "TITLE:OPEN" => "return to title",
        "TITLE:CONTINUE" => "continue slot A",
        "CONTINUE:SESSION" => "restore controls",
        _ => "ready for next route",
    }
}

fn first_minute_task_mark(done: bool, label: &str) -> String {
    format!("{}{}", if done { "[x]" } else { "[ ]" }, label)
}

fn first_minute_onboarding_task_log(runtime: &NativeFirstPlayableRuntime) -> String {
    [
        first_minute_task_mark(first_minute_character_created(runtime), "CREATE"),
        first_minute_task_mark(
            runtime_has_completed_step(runtime, "talk_to_mentor"),
            "TALK",
        ),
        first_minute_task_mark(
            runtime_has_completed_step(runtime, "train_basic_unarmed"),
            "TRAIN",
        ),
        first_minute_task_mark(
            runtime_has_completed_step(runtime, "arrive_at_first_objective"),
            "ARENA",
        ),
        first_minute_task_mark(
            runtime_has_completed_step(runtime, "resolve_first_combat"),
            "FIGHT",
        ),
        first_minute_task_mark(first_minute_slot_a_ready(runtime), "SAVE"),
        first_minute_task_mark(first_minute_continue_restored(runtime), "CONTINUE"),
    ]
    .join(" ")
}

fn first_minute_onboarding_hud_text(runtime: &NativeFirstPlayableRuntime) -> String {
    let next_button = first_minute_onboarding_next_button(runtime);
    let task_log = first_minute_onboarding_task_log(runtime);
    let state_hint = first_minute_onboarding_state_hint(runtime);
    format!(
        "PLAYER ROUTE | FIRST MINUTE HUD | NEXT BUTTON: {next_button} | NEXT STEP: {state_hint}\nQUEST JOURNAL | TASK LOG / PROGRESS: {task_log}\nSTATE: {state_hint}"
    )
}

fn journal_list_or_none(values: &[String]) -> String {
    if values.is_empty() {
        "none".to_string()
    } else {
        values.join(", ")
    }
}

fn quest_journal_milestones(runtime: &NativeFirstPlayableRuntime) -> String {
    [
        ("CREATE", first_minute_character_created(runtime)),
        (
            "TALK",
            runtime_has_completed_step(runtime, "talk_to_mentor"),
        ),
        (
            "TRAIN",
            runtime_has_completed_step(runtime, "train_basic_unarmed"),
        ),
        (
            "ARENA",
            runtime_has_completed_step(runtime, "arrive_at_first_objective"),
        ),
        (
            "FIGHT",
            runtime_has_completed_step(runtime, "resolve_first_combat"),
        ),
        (
            "COMPLETE",
            runtime_has_completed_step(runtime, "complete_first_task"),
        ),
        (
            "EQUIP",
            runtime_has_completed_step(runtime, "equip_route_guard_staff"),
        ),
    ]
    .into_iter()
    .map(|(label, done)| format!("{}{}", if done { "[x]" } else { "[ ]" }, label))
    .collect::<Vec<_>>()
    .join(" ")
}

fn quest_journal_locked_task_ids(runtime: &NativeFirstPlayableRuntime) -> Vec<String> {
    native_bevy_scene_pack_fixture()
        .tasks
        .into_iter()
        .filter(|task| {
            !runtime
                .unlocked_task_ids
                .iter()
                .any(|unlocked| unlocked == &task.task_id)
                && !runtime
                    .completed_task_ids
                    .iter()
                    .any(|completed| completed == &task.task_id)
        })
        .map(|task| task.task_id)
        .collect()
}

fn build_branch_route_status(runtime: &NativeFirstPlayableRuntime, task_id: &str) -> String {
    let required_stat = build_branch_task_required_stat(task_id).unwrap_or("custom");
    if runtime
        .completed_task_ids
        .iter()
        .any(|completed| completed == task_id)
    {
        "completed".to_string()
    } else if runtime
        .active_task_ids
        .iter()
        .any(|active| active == task_id)
    {
        "active".to_string()
    } else if runtime
        .unlocked_task_ids
        .iter()
        .any(|unlocked| unlocked == task_id)
    {
        "unlocked".to_string()
    } else if runtime.pending_stat_allocation.as_deref() == Some(required_stat) {
        "preview_pending_confirm".to_string()
    } else if runtime_has_active_sash_stat(runtime, required_stat) {
        "attuned_needs_unlock".to_string()
    } else if runtime_has_equipped_bandit_sash(runtime) {
        format!("locked_requires_{required_stat}")
    } else {
        "locked_requires_bandit_sash".to_string()
    }
}

fn build_branch_routes_text(runtime: &NativeFirstPlayableRuntime) -> String {
    let build_state = if let Some(stat_id) = runtime.pending_stat_allocation.as_deref() {
        format!("pending:{stat_id}")
    } else if let Some(stat_id) = runtime.allocated_stat_points.first() {
        format!("active:{stat_id}")
    } else if runtime_has_equipped_bandit_sash(runtime) {
        "dormant_choose_force_agility_craft".to_string()
    } else {
        "locked_equip_bandit_sash".to_string()
    };
    let branch_lines = build_branch_task_ids()
        .into_iter()
        .map(|task_id| {
            let required_stat = build_branch_task_required_stat(task_id).unwrap_or("custom");
            let target_room = scene_pack_task(task_id)
                .and_then(|task| task.room_ids.last().cloned())
                .unwrap_or_else(|| "unknown".to_string());
            format!(
                "{required_stat}:{task_id}:{} -> {} at {target_room}",
                build_branch_route_status(runtime, task_id),
                build_branch_task_label(task_id)
            )
        })
        .collect::<Vec<_>>()
        .join(" | ");
    format!("BUILD ROUTES | build {build_state} | {branch_lines}")
}

fn quest_journal_text(
    runtime: &NativeFirstPlayableRuntime,
    objective: Option<&NativePlayableObjective>,
) -> String {
    let tracked_route = objective
        .map(|objective| objective.title.clone())
        .unwrap_or_else(|| runtime.route_director_task_id.clone());
    let locked_tasks = quest_journal_locked_task_ids(runtime);
    let next_button = first_minute_onboarding_next_button(runtime);
    format!(
        "QUEST JOURNAL | TRACKED: {tracked_route} | NEXT: {next_button}\nMILESTONES: {}\nTASKS active: {} | available: {} | completed: {} | locked: {}\nROUTE: {}\n{}\n{}\n{}\n{}\n{}\n{}\n{}\n{}\nREWARDS: coins {} xp {} | claim {} | equipment {}\n{}",
        quest_journal_milestones(runtime),
        journal_list_or_none(&runtime.active_task_ids),
        journal_list_or_none(&runtime.available_task_ids),
        journal_list_or_none(&runtime.completed_task_ids),
        journal_list_or_none(&locked_tasks),
        route_director_summary(runtime),
        build_branch_routes_text(runtime),
        build_branch_world_reaction_text(runtime),
        build_branch_followup_unlock_text(runtime),
        build_branch_followup_reaction_text(runtime),
        build_branch_mastery_text(runtime),
        build_branch_mastery_challenge_text(runtime),
        build_branch_mastery_title_text(runtime),
        build_branch_title_route_recommendation_text(runtime),
        runtime.coins,
        runtime.xp,
        if runtime.reward_claimed { "claimed" } else { "pending" },
        if runtime.equipment_ready { "ready" } else { "pending" },
        runtime.reward_settlement_text
    )
}

fn inventory_equipment_text(runtime: &NativeFirstPlayableRuntime, weapon_label: &str) -> String {
    let bag_state = if runtime.bag_open { "OPEN" } else { "CLOSED" };
    let bag_items = journal_list_or_none(&runtime.inventory_items);
    let equipped = journal_list_or_none(&runtime.equipped_items);
    let drops = journal_list_or_none(&runtime.dropped_items);
    let bandit_sash_state = if runtime
        .equipped_items
        .iter()
        .any(|item| item == "bandit_sash")
    {
        "equipped"
    } else if runtime
        .inventory_items
        .iter()
        .any(|item| item == "bandit_sash")
    {
        "in_bag"
    } else if runtime
        .dropped_items
        .iter()
        .any(|item| item == "bandit_sash")
    {
        "dropped"
    } else {
        "locked"
    };
    let affix_text = bandit_sash_affix_text(runtime);
    format!(
        "BAG HUD | STATUS {bag_state} | ITEMS {} | EQUIPPED {} | DROPS {}\nBAG ITEMS: {bag_items}\nEQUIPPED: weapon {weapon_label} | accessory bandit_sash:{bandit_sash_state}\nEQUIPPED ITEMS: {equipped}\nDROPS: {drops}\nITEM DETAIL: small_healing_pill +18 HP | bandit_sash unlocks rematch | route-guard-staff starter weapon\nAFFIX: {affix_text}\nVISUALS: {}\nPROGRESSION: loot {} | equipment {} | level {} +{} stat",
        runtime.inventory_items.len(),
        runtime.equipped_items.len(),
        runtime.dropped_items.len(),
        if runtime
            .visible_behavior_history
            .iter()
            .any(|event| event == "bag_overlay_visible")
        {
            "bag_overlay_visible"
        } else {
            "bag_overlay_hidden"
        },
        if runtime.loot_history.iter().any(|event| event == "loot:bandit_sash") {
            "collected"
        } else if runtime.dropped_items.iter().any(|item| item == "bandit_sash") {
            "visible"
        } else {
            "pending"
        },
        if runtime.equipment_ready { "ready" } else { "pending" },
        runtime.growth_level,
        runtime.growth_stat_points
    )
}

fn character_growth_text(
    runtime: &NativeFirstPlayableRuntime,
    character: &WorldTrillionniumCharacter,
    skill_line: &str,
    weapon_label: &str,
) -> String {
    let attributes = &character.attributes;
    let derived = attributes.derived_stats();
    let allocated = journal_list_or_none(&runtime.allocated_stat_points);
    let growth_history = journal_list_or_none(&runtime.growth_history);
    let accessory = if runtime
        .equipped_items
        .iter()
        .any(|item| item == "bandit_sash")
    {
        "bandit_sash"
    } else {
        "none"
    };
    format!(
        "CHARACTER SHEET | LV {} | UNSPENT {}\nATTR P{} F{} A{} I{} R{} C{} M{} REP{}\nDERIVED HP {} IE {} MOVE {} COMBAT {}\nSkills: {}\nGear: weapon {} / accessory {}\n{}\n{}\nGROWTH: allocated {} | history {}\n{}",
        runtime.growth_level,
        runtime.growth_stat_points,
        attributes.physique,
        attributes.force,
        attributes.agility,
        attributes.insight,
        attributes.resolve,
        attributes.craft,
        attributes.commerce,
        attributes.reputation,
        derived.max_hp,
        derived.inner_energy,
        derived.move_range,
        derived.combat_power_hint,
        skill_line,
        weapon_label,
        accessory,
        active_build_title_sheet_text(runtime),
        build_branch_title_loadout_text(runtime),
        allocated,
        growth_history,
        stat_choice_preview_text(runtime),
    )
}

fn stat_choice_preview_text(runtime: &NativeFirstPlayableRuntime) -> String {
    if let Some(stat_id) = runtime.pending_stat_allocation.as_deref() {
        let effect_line = match stat_id {
            "force" => "FORCE pending -> rematch attack +4 DMG",
            "agility" => "AGILITY pending -> incoming -3 / guard +2 HP",
            "craft" => "CRAFT pending -> reward +4 coins +5 XP",
            other => {
                return format!(
                    "STAT CONFIRM | pending {other}\nCost: 1 stat point | Confirm STAT:confirm or cancel STAT:cancel\n{other} pending -> custom route bonus pending"
                );
            }
        };
        return format!(
            "STAT CONFIRM | pending {stat_id}\nCost: 1 stat point | Confirm STAT:confirm or cancel STAT:cancel\n{effect_line}"
        );
    }
    if !runtime.allocated_stat_points.is_empty() {
        let active = runtime.allocated_stat_points.join(", ");
        let effect_lines = runtime
            .allocated_stat_points
            .iter()
            .map(|stat_id| match stat_id.as_str() {
                "force" => "FORCE active -> rematch attack +4 DMG".to_string(),
                "agility" => "AGILITY active -> incoming -3 / guard +2 HP".to_string(),
                "craft" => "CRAFT active -> reward +4 coins +5 XP".to_string(),
                other => format!("{other} active -> custom route bonus pending"),
            })
            .collect::<Vec<_>>()
            .join("\n");
        return format!("STAT BUILD ACTIVE | allocated {active}\n{effect_lines}");
    }
    if runtime.growth_stat_points > 0 {
        return [
            "STAT PREVIEW | choose one before spend",
            "FORCE -> rematch attack +4 DMG",
            "AGILITY -> incoming -3 / guard +2 HP",
            "CRAFT -> reward +4 coins +5 XP",
        ]
        .join("\n");
    }
    "STAT PREVIEW locked | equip bandit_sash to unlock force/agility/craft".to_string()
}

fn input_feedback_toast_text(runtime: &NativeFirstPlayableRuntime) -> String {
    let next_button = first_minute_onboarding_next_button(runtime);
    if let Some(event) = runtime.input_feedback_history.last() {
        let state = if event.accepted { "OK" } else { "BLOCKED" };
        format!(
            "TOAST {state} | {} | {} | NEXT {next_button}",
            event.action_label, event.reason
        )
    } else {
        format!("TOAST READY | NEXT {next_button}")
    }
}

fn route_director_summary(runtime: &NativeFirstPlayableRuntime) -> String {
    let path = if runtime.route_director_path.is_empty() {
        "no route".to_string()
    } else {
        runtime.route_director_path.join(" -> ")
    };
    let next = runtime
        .route_director_next_room_id
        .clone()
        .unwrap_or_else(|| "arrived".to_string());
    format!(
        "{} to {} | next {} | {}",
        runtime.route_director_task_id, runtime.route_director_target_room_id, next, path
    )
}

