#[allow(clippy::type_complexity)]
pub fn update_native_game_feedback_visuals(
    first_playable: Res<NativeFirstPlayableRuntime>,
    mut bars: Query<(&mut Sprite, &mut Transform, &BevyWorldStatusBar)>,
    mut feedback_texts: Query<
        &mut Text2d,
        (
            With<BevyWorldFeedbackBannerText>,
            Without<BevyWorldRewardToastText>,
        ),
    >,
    mut reward_texts: Query<
        &mut Text2d,
        (
            With<BevyWorldRewardToastText>,
            Without<BevyWorldFeedbackBannerText>,
        ),
    >,
) {
    for (mut sprite, mut transform, bar) in &mut bars {
        let ratio = match bar.kind {
            BevyWorldStatusBarKind::PlayerHp => {
                (first_playable.player_hp as f32 / 176.0).clamp(0.0, 1.0)
            }
            BevyWorldStatusBarKind::EnemyHp => {
                (first_playable.enemy_hp as f32 / 40.0).clamp(0.0, 1.0)
            }
            BevyWorldStatusBarKind::Xp => (first_playable.xp as f32 / 40.0).clamp(0.0, 1.0),
        };
        let width = (bar.max_width * ratio).max(2.0);
        sprite.custom_size = Some(Vec2::new(width, 6.0));
        transform.translation.x = bar.left_x + width * 0.5;
    }
    for mut text in &mut feedback_texts {
        text.0 = format!(
            "{} | FEEDBACK: {} | STAT FX: {}",
            input_feedback_toast_text(&first_playable),
            first_playable.last_feedback,
            first_playable.stat_effect_floating_text
        );
    }
    for mut text in &mut reward_texts {
        text.0 = if first_playable.equipment_ready {
            format!(
                "REWARD: Route Guard Staff equipped\n{}",
                first_playable.reward_settlement_text
            )
        } else if first_playable.reward_claimed {
            format!("REWARD: {}", first_playable.reward_settlement_text)
        } else {
            "REWARD: pending".to_string()
        };
    }
}

#[allow(clippy::type_complexity)]
pub fn update_native_tile_rpg_interaction_ui(
    first_playable: Res<NativeFirstPlayableRuntime>,
    mut texts: ParamSet<(
        Query<&mut Text, With<BevyWorldSceneStateText>>,
        Query<&mut Text, With<BevyWorldDialogueChoiceText>>,
        Query<&mut Text, With<BevyWorldSceneTransitionText>>,
        Query<&mut Text, With<BevyWorldCombatSceneText>>,
        Query<&mut Text, With<BevyWorldWalkAnimationText>>,
    )>,
) {
    for mut text in &mut texts.p0() {
        text.0 = format!(
            "DEBUG LAYER | Scene {} | Transition {} | Dialogue {} | Combat {} | Step {} | Frame {}",
            first_playable.map_scene,
            first_playable.scene_transition,
            first_playable.npc_dialogue_state,
            first_playable.combat_scene_state,
            first_playable.last_tile_step,
            first_playable.walk_cycle_frame
        );
    }
    for mut text in &mut texts.p1() {
        text.0 = tile_rpg_dialogue_choice_text(&first_playable);
    }
    for mut text in &mut texts.p2() {
        text.0 = tile_rpg_scene_transition_text(&first_playable);
    }
    for mut text in &mut texts.p3() {
        text.0 = tile_rpg_combat_scene_text(&first_playable);
    }
    for mut text in &mut texts.p4() {
        text.0 = tile_rpg_walk_animation_text(&first_playable);
    }
}

fn tile_rpg_dialogue_choice_text(runtime: &NativeFirstPlayableRuntime) -> String {
    match runtime.npc_dialogue_state.as_str() {
        "mentor_dialogue_open" => {
            "Mentor: first train, then enter the arena.\n1 Train basic_unarmed\n2 Ask route"
                .to_string()
        }
        "mentor_training_complete" => {
            "Mentor: skill learned. Take the north road.\nChoice locked: go to arena".to_string()
        }
        _ => "Mentor waits near the square.\nPress TALK to open choices.".to_string(),
    }
}

fn tile_rpg_scene_transition_text(runtime: &NativeFirstPlayableRuntime) -> String {
    match runtime.map_scene.as_str() {
        "starter_studio_indoor" => {
            "Starter studio\nDoor: forge / yard / square\nState: indoor room loaded".to_string()
        }
        "forge_workbench_indoor" => {
            "Forge workbench\nDoor: studio / yard\nState: crafting tilemap loaded".to_string()
        }
        "client_board_room" => {
            "Client board\nDoor: market / delivery dock\nState: task board loaded".to_string()
        }
        "delivery_dock_outdoor" => {
            "Delivery dock\nDoor: client board / arena bridge\nState: route dock loaded".to_string()
        }
        "mentor_training_room_indoor" => {
            "Indoor training room\nDoor: exit north to arena route\nState: room loaded".to_string()
        }
        "arena_outdoor" => {
            "Arena outdoor\nGate: town -> arena\nState: route map restored".to_string()
        }
        _ => "Town square outdoor\nDoor: mentor room / north road\nState: map ready".to_string(),
    }
}

fn tile_rpg_combat_scene_text(runtime: &NativeFirstPlayableRuntime) -> String {
    if runtime.combat_result_state == "victory" {
        return format!(
            "Turn combat victory\nRounds: {}\nEnemy HP {} / Player HP {}\nLast: {}",
            runtime.combat_turn,
            runtime.enemy_hp,
            runtime.player_hp,
            runtime
                .combat_round_log
                .last()
                .cloned()
                .unwrap_or_else(|| "none".to_string())
        );
    }
    if runtime.combat_result_state == "in_progress" {
        return format!(
            "Turn combat active\nRound {} | actions {}\nEnemy HP {} / Player HP {}\nLast: {}\n{}",
            runtime.combat_turn,
            runtime.combat_actions_available.join(", "),
            runtime.enemy_hp,
            runtime.player_hp,
            runtime
                .combat_round_log
                .last()
                .cloned()
                .unwrap_or_else(|| "none".to_string()),
            runtime.stat_effect_floating_text
        );
    }
    if runtime.combat_scene_state == "combat_returned_to_map" {
        format!(
            "Combat returned to map\nF5 strike resolved\nEnemy HP {} / Player HP {}",
            runtime.enemy_hp, runtime.player_hp
        )
    } else if runtime
        .completed_steps
        .iter()
        .any(|step| step == "arrive_at_first_objective")
    {
        format!(
            "Combat encounter ready\nEnemy HP {} / Player HP {}\nPress FIGHT",
            runtime.enemy_hp, runtime.player_hp
        )
    } else {
        "No encounter yet\nReach arena to load combat scene.".to_string()
    }
}

fn tile_rpg_walk_animation_text(runtime: &NativeFirstPlayableRuntime) -> String {
    format!(
        "Last step: {}\nFrom {} -> {}\nProgress {}% | lock observed {}\nFacing {} | pose {}",
        runtime.last_tile_step,
        runtime.movement_from_tile,
        runtime.movement_to_tile,
        runtime.tile_step_progress_percent,
        runtime.movement_lock_observed,
        runtime.facing_direction,
        runtime.player_sprite_pose
    )
}

#[allow(clippy::type_complexity)]
pub fn update_native_tile_rpg_scene_visuals(
    first_playable: Res<NativeFirstPlayableRuntime>,
    mut scene_layers: Query<&mut Sprite, With<BevyWorldSceneLayerSprite>>,
    mut dialogue_overlays: Query<
        &mut Sprite,
        (
            With<BevyWorldDialogueOverlaySprite>,
            Without<BevyWorldCombatOverlaySprite>,
            Without<BevyWorldSceneLayerSprite>,
        ),
    >,
    mut combat_overlays: Query<
        &mut Sprite,
        (
            With<BevyWorldCombatOverlaySprite>,
            Without<BevyWorldDialogueOverlaySprite>,
            Without<BevyWorldSceneLayerSprite>,
        ),
    >,
    mut npc_texts: Query<
        &mut Text2d,
        (
            With<BevyWorldNpcBehaviorText>,
            Without<BevyWorldEnemyBehaviorText>,
        ),
    >,
    mut enemy_texts: Query<
        &mut Text2d,
        (
            With<BevyWorldEnemyBehaviorText>,
            Without<BevyWorldNpcBehaviorText>,
        ),
    >,
) {
    let scene_color = match first_playable.tilemap_variant.as_str() {
        "indoor_training_room" => Color::srgba(0.58, 0.34, 0.18, 0.32),
        "arena_outdoor" => Color::srgba(0.38, 0.10, 0.08, 0.24),
        _ => Color::srgba(0.16, 0.30, 0.16, 0.10),
    };
    for mut sprite in &mut scene_layers {
        sprite.color = scene_color;
    }
    for mut sprite in &mut dialogue_overlays {
        sprite.color = if first_playable.dialogue_overlay_visible {
            Color::srgba(0.07, 0.10, 0.12, 0.76)
        } else {
            Color::srgba(0.07, 0.10, 0.12, 0.0)
        };
    }
    for mut sprite in &mut combat_overlays {
        sprite.color = if first_playable.combat_overlay_visible {
            Color::srgba(0.28, 0.04, 0.035, 0.70)
        } else {
            Color::srgba(0.28, 0.04, 0.035, 0.0)
        };
    }
    for mut text in &mut npc_texts {
        text.0 = format!(
            "Mentor: {}\n{}",
            first_playable.npc_behavior_state, first_playable.npc_bubble_text
        );
    }
    for mut text in &mut enemy_texts {
        text.0 = format!(
            "Enemy: {}\n{}\n{}",
            first_playable.enemy_behavior_state,
            first_playable.enemy_damage_feedback,
            first_playable.stat_effect_floating_text
        );
    }
}

#[allow(clippy::type_complexity)]
pub fn update_native_input_hint_ui(
    first_playable: Res<NativeFirstPlayableRuntime>,
    mut hint_texts: Query<&mut Text, With<BevyWorldInputHintText>>,
    mut visible_coach_texts: Query<
        &mut Text,
        (
            With<BevyWorldVisibleActionCoachText>,
            Without<BevyWorldInputHintText>,
        ),
    >,
    mut primary_cta_texts: Query<
        &mut Text,
        (
            With<BevyWorldPrimaryCtaText>,
            Without<BevyWorldInputHintText>,
            Without<BevyWorldVisibleActionCoachText>,
        ),
    >,
) {
    let deck = native_contextual_action_deck(&first_playable);
    let contextual_labels = deck
        .actions
        .iter()
        .filter(|entry| entry.enabled)
        .map(|entry| entry.label.clone())
        .collect::<Vec<_>>()
        .join(", ");
    let enabled = native_live_probe_actions()
        .iter()
        .map(|action| {
            let (is_enabled, reason) = native_live_action_availability(&first_playable, action);
            format!(
                "{}:{}({})",
                native_control_action_label(action),
                if is_enabled { "ON" } else { "OFF" },
                reason
            )
        })
        .collect::<Vec<_>>()
        .join(" | ");
    let locked = native_live_probe_actions()
        .iter()
        .filter_map(|action| {
            let (is_enabled, reason) = native_live_action_availability(&first_playable, action);
            (!is_enabled).then(|| format!("{}:{reason}", native_control_action_label(action)))
        })
        .take(5)
        .collect::<Vec<_>>()
        .join(", ");
    let ready_count = deck.actions.iter().filter(|entry| entry.enabled).count();
    let locked_count = native_live_probe_actions()
        .iter()
        .filter(|action| {
            let (is_enabled, _reason) = native_live_action_availability(&first_playable, action);
            !is_enabled
        })
        .count();
    let primary_label = deck
        .primary_action_label
        .clone()
        .unwrap_or_else(|| "none".to_string());
    let focused_action = player_action_coach_action_label(&first_playable);
    let focused_shortcut = player_action_coach_shortcut_label(&focused_action);
    let action_coach = player_action_coach_text(&first_playable);
    let title_route_confirm = build_branch_title_route_action_confirm_hud_text(&first_playable);
    let next_button = first_minute_onboarding_next_button(&first_playable);
    let compact_ready = if contextual_labels.is_empty() {
        "none".to_string()
    } else {
        contextual_labels
            .split(", ")
            .take(3)
            .collect::<Vec<_>>()
            .join(", ")
    };
    let compact_coach = format!(
        "ACTION COACH | Enter -> {}\nNEXT | {next_button}   PRIMARY | {primary_label}\nREADY | {compact_ready}",
        focused_action
    );
    let primary_cta = format!(
        "PRIMARY | Enter -> {focused_action}\nSHORTCUT | {focused_shortcut} | NEXT {next_button}"
    );
    for mut text in &mut hint_texts {
        text.0 = format!(
            "{action_coach}\nINPUT HUD | NEXT {next_button} | PRIMARY {primary_label}\nPLAYER ACTIONS | READY: {}\nDEV INPUT | TITLE ROUTE CONFIRM: {title_route_confirm} | LOCKED: {}\nGATES: {ready_count} ready / {locked_count} locked | {enabled}",
            if contextual_labels.is_empty() {
                "none".to_string()
            } else {
                contextual_labels.clone()
            },
            if locked.is_empty() {
                "none".to_string()
            } else {
                locked.clone()
            }
        );
    }
    for mut text in &mut visible_coach_texts {
        text.0 = compact_coach.clone();
    }
    for mut text in &mut primary_cta_texts {
        text.0 = primary_cta.clone();
    }
}

fn session_recovery_status_text(runtime: &NativeFirstPlayableRuntime) -> String {
    let summary = native_input_telemetry_summary(runtime);
    let status = if runtime
        .progression_checkpoint_history
        .iter()
        .any(|checkpoint| checkpoint == "session_snapshot_restored")
    {
        "RECOVERED"
    } else if summary.total_events > 0 {
        "CHECKPOINT"
    } else {
        "NEW"
    };
    let last_source = summary.last_input_source.as_deref().unwrap_or("none");
    let last_action = summary.last_action_label.as_deref().unwrap_or("none");
    let guard = runtime
        .input_feedback_history
        .iter()
        .rev()
        .find(|event| !event.accepted)
        .map(|event| format!("{}:{}", event.action_label, event.reason))
        .or_else(|| runtime.blocked_action_history.last().cloned())
        .unwrap_or_else(|| "none".to_string());
    format!(
        "SESSION {} | checkpoint events {} accepted {} blocked {} | last {} {} | guard {}",
        status,
        summary.total_events,
        summary.accepted_events,
        summary.blocked_events,
        last_source,
        last_action,
        guard
    )
}

