fn contextual_action_row_should_show(
    row_id: &str,
    row_children: &Children,
    button_states: &HashMap<Entity, (String, String, bool, bool)>,
) -> bool {
    let row_signals = row_children
        .iter()
        .filter_map(|child| button_states.get(&child))
        .collect::<Vec<_>>();
    let row_can_host_global_focus = !matches!(row_id, "title_menu" | "account_title_actions");
    if row_can_host_global_focus
        && row_signals.iter().any(|(_, visual_state, _, _)| {
            matches!(
                visual_state.as_str(),
                "onboarding_next_button" | "title_route_dashboard_focus"
            )
        })
    {
        return true;
    }
    match row_id {
        "core_route_actions" => row_signals.iter().any(|(_, visual_state, _, enabled)| {
            *enabled
                && matches!(
                    visual_state.as_str(),
                    "enabled_contextual" | "primary_enabled"
                )
        }),
        "selected_slot_actions" => {
            row_signals
                .iter()
                .any(|(action_label, visual_state, _, enabled)| {
                    matches!(
                        visual_state.as_str(),
                        "selected_slot"
                            | "overwrite_pending"
                            | "resume_continue_required"
                            | "title_choice_required"
                    ) || (*enabled
                        && matches!(
                            action_label.as_str(),
                            "SAVE:SELECTED" | "LOAD:SELECTED" | "CONTINUE:SESSION"
                        ))
                })
        }
        "title_menu" => row_signals
            .iter()
            .any(|(action_label, visual_state, _, _)| {
                matches!(
                    visual_state.as_str(),
                    "title_menu_active" | "title_choice_required"
                ) || (action_label == "TITLE:OPEN" && visual_state == "onboarding_next_button")
            }),
        "account_title_actions" => row_signals
            .iter()
            .any(|(action_label, _, _, enabled)| *enabled && action_label.starts_with("ACCOUNT:")),
        "campaign_title_actions" => row_signals
            .iter()
            .any(|(action_label, visual_state, _, _)| {
                action_label.starts_with("CAMPAIGN:")
                    && matches!(
                        visual_state.as_str(),
                        "title_menu_active" | "title_choice_required"
                    )
            }),
        "character_create" => row_signals.iter().any(|(_, visual_state, _, _)| {
            visual_state.as_str() == "character_create_choice_required"
        }),
        "support_menu_actions" => row_signals.iter().any(|(_, visual_state, _, _)| {
            matches!(
                visual_state.as_str(),
                "pause_menu_active"
                    | "pause_resume_required"
                    | "settings_menu_active"
                    | "settings_back_required"
            )
        }),
        "combat_bag_stat_actions" => {
            row_signals
                .iter()
                .any(|(action_label, visual_state, _, enabled)| {
                    matches!(
                        visual_state.as_str(),
                        "stat_confirmation_pending" | "primary_enabled"
                    ) || (*enabled
                        && (action_label.starts_with("COMBAT:")
                            || action_label.starts_with("BAG:")
                            || action_label.starts_with("LOOT:")
                            || action_label.starts_with("EQUIP:")
                            || action_label.starts_with("STAT:")))
                })
        }
        "room_travel_actions"
        | "npc_and_intro_task_actions"
        | "branch_followup_actions"
        | "mastery_task_actions"
        | "build_title_actions" => row_signals
            .iter()
            .any(|(_, visual_state, _, _)| visual_state.as_str() == "primary_enabled"),
        "save_load_actions" | "settings_actions" => false,
        _ => false,
    }
}

#[allow(clippy::type_complexity)]
pub fn update_native_contextual_button_visuals(
    first_playable: Res<NativeFirstPlayableRuntime>,
    mut buttons: Query<
        (
            Entity,
            &NativeControlAction,
            &mut Node,
            &mut BevyWorldContextualActionButtonState,
            &mut BackgroundColor,
            &mut BorderColor,
        ),
        With<Button>,
    >,
    mut action_rows: Query<
        (&mut Node, &Children, &mut BevyWorldContextualActionRow),
        Without<Button>,
    >,
    mut labels: Query<(
        &mut Text,
        &mut TextColor,
        &BevyWorldContextualActionButtonText,
    )>,
) {
    let deck = native_contextual_action_deck(&first_playable);
    let entries = deck
        .actions
        .iter()
        .map(|entry| (entry.label.as_str(), entry))
        .collect::<HashMap<_, _>>();
    let onboarding_next_label = first_minute_onboarding_next_button(&first_playable);
    let title_route_focus = build_branch_title_route_action_focus(&first_playable);
    let mut label_states: HashMap<String, (String, String, bool, bool)> = HashMap::new();
    let mut visible_button_entities = HashSet::new();
    let mut button_row_signals: HashMap<Entity, (String, String, bool, bool)> = HashMap::new();
    for (entity, action, mut node, mut state, mut background, mut border) in &mut buttons {
        let action_label = native_control_action_label(action);
        let entry = entries.get(action_label.as_str()).copied();
        let availability = native_live_action_availability(&first_playable, action);
        let entry_enabled = entry.is_some_and(|entry| entry.enabled);
        let entry_primary = entry.is_some_and(|entry| entry.primary);
        let onboarding_next_highlight = onboarding_next_label != "FIRST MINUTE COMPLETE"
            && action_label == onboarding_next_label
            && availability.0;
        let title_route_dashboard_focus = title_route_focus.as_ref().is_some_and(|focus| {
            focus.action_label == action_label && focus.action_label != "DONE"
        });
        let title_route_dashboard_focus_enabled = title_route_focus
            .as_ref()
            .is_some_and(|focus| title_route_dashboard_focus && focus.enabled);
        let account_title_surface_active =
            first_playable.session_title_menu_visible || first_playable.session_title_input_locked;
        let account_title_action = matches!(
            action,
            NativeControlAction::RegisterAccountFromTitle
                | NativeControlAction::LoginAccountFromTitle
                | NativeControlAction::ContinueAccountFromTitle
        );
        let campaign_title_action = matches!(
            action,
            NativeControlAction::StartCampaignFromTitle
                | NativeControlAction::ContinueCampaignFromTitle
                | NativeControlAction::ReplayCampaignFromTitle
        );
        let enabled =
            entry_enabled || onboarding_next_highlight || title_route_dashboard_focus_enabled;
        let primary =
            entry_primary || onboarding_next_highlight || title_route_dashboard_focus_enabled;
        let selected_slot = matches!(
            action,
            NativeControlAction::SelectSlot { slot_id }
                if normalize_session_slot_id(slot_id)
                    == normalize_session_slot_id(&first_playable.session_selected_slot_id)
        );
        let pending_overwrite = matches!(
            action,
            NativeControlAction::ConfirmOverwriteSlot | NativeControlAction::CancelOverwriteSlot
        ) && first_playable.session_overwrite_pending_slot_id.is_some();
        let pending_stat_confirmation = matches!(
            action,
            NativeControlAction::ConfirmStatAllocation | NativeControlAction::CancelStatAllocation
        ) && first_playable.pending_stat_allocation.is_some();
        let resume_continue_required = matches!(action, NativeControlAction::ContinueAfterLoad)
            && (first_playable.session_resume_input_locked
                || first_playable.session_continue_cta_visible);
        let pause_resume_required = matches!(action, NativeControlAction::ResumeFromPause)
            && (first_playable.session_pause_menu_visible
                || first_playable.session_pause_input_locked);
        let pause_menu_active = matches!(action, NativeControlAction::PauseMenu)
            && (first_playable.session_pause_menu_visible
                || first_playable.session_pause_input_locked);
        let settings_menu_active = matches!(action, NativeControlAction::OpenSettingsMenu)
            && first_playable.session_settings_menu_visible;
        let settings_back_required = matches!(action, NativeControlAction::CloseSettingsMenu)
            && first_playable.session_settings_menu_visible;
        let title_menu_active = matches!(action, NativeControlAction::OpenTitleMenu)
            && (first_playable.session_title_menu_visible
                || first_playable.session_title_input_locked);
        let title_choice_required = matches!(
            action,
            NativeControlAction::NewGameFromTitle
                | NativeControlAction::LoadFromTitle
                | NativeControlAction::ContinueFromTitle
                | NativeControlAction::StartCampaignFromTitle
                | NativeControlAction::ContinueCampaignFromTitle
                | NativeControlAction::ReplayCampaignFromTitle
        ) && (first_playable.session_title_menu_visible
            || first_playable.session_title_input_locked);
        let character_create_choice = matches!(
            action,
            NativeControlAction::CycleCharacterName
                | NativeControlAction::CycleCharacterArchetype
                | NativeControlAction::ConfirmCharacterCreate
                | NativeControlAction::BackToTitleFromCreate
        ) && (first_playable.session_character_create_visible
            || first_playable.session_character_create_input_locked);
        let reason = if onboarding_next_highlight {
            availability.1.clone()
        } else if title_route_dashboard_focus {
            title_route_focus
                .as_ref()
                .map(|focus| focus.reason.clone())
                .unwrap_or_else(|| availability.1.clone())
        } else {
            entry
                .map(|entry| entry.reason.clone())
                .unwrap_or_else(|| "not_in_contextual_deck".to_string())
        };
        let source = if onboarding_next_highlight {
            "first_minute_next_button".to_string()
        } else if title_route_dashboard_focus {
            "title_route_action_dashboard".to_string()
        } else {
            entry
                .map(|entry| entry.source.clone())
                .unwrap_or_else(|| "static_button_outside_current_context".to_string())
        };
        let visual_state =
            if (account_title_action || campaign_title_action) && !account_title_surface_active {
                "hidden_or_not_current_context"
            } else if onboarding_next_highlight {
                "onboarding_next_button"
            } else if title_route_dashboard_focus_enabled {
                "title_route_dashboard_focus"
            } else if title_route_dashboard_focus {
                "title_route_dashboard_blocked"
            } else if selected_slot {
                "selected_slot"
            } else if pending_overwrite {
                "overwrite_pending"
            } else if pending_stat_confirmation {
                "stat_confirmation_pending"
            } else if resume_continue_required {
                "resume_continue_required"
            } else if pause_resume_required {
                "pause_resume_required"
            } else if pause_menu_active {
                "pause_menu_active"
            } else if settings_back_required {
                "settings_back_required"
            } else if settings_menu_active {
                "settings_menu_active"
            } else if title_choice_required {
                "title_choice_required"
            } else if title_menu_active {
                "title_menu_active"
            } else if character_create_choice {
                "character_create_choice_required"
            } else if primary {
                "primary_enabled"
            } else if enabled {
                "enabled_contextual"
            } else if entry.is_some() {
                "disabled_contextual"
            } else {
                "hidden_or_not_current_context"
            };
        state.action_label = action_label.clone();
        state.visual_state = visual_state.to_string();
        state.enabled = enabled;
        state.primary = primary || onboarding_next_highlight;
        let movement_pad_button = matches!(action, NativeControlAction::Move { .. });
        let player_deck_visible = movement_pad_button
            || (account_title_action && account_title_surface_active)
            || (campaign_title_action && account_title_surface_active)
            || !matches!(
                visual_state,
                "hidden_or_not_current_context" | "disabled_contextual"
            ) && !account_title_action
                && !campaign_title_action;
        state.player_deck_visible = player_deck_visible;
        if player_deck_visible {
            visible_button_entities.insert(entity);
        }
        state.reason = reason;
        state.source = source;
        button_row_signals.insert(
            entity,
            (
                state.action_label.clone(),
                state.visual_state.clone(),
                state.primary,
                state.enabled,
            ),
        );
        node.display = if player_deck_visible {
            Display::Flex
        } else {
            Display::None
        };
        *background = if onboarding_next_highlight {
            BackgroundColor(Color::srgb(0.62, 0.48, 0.10))
        } else if title_route_dashboard_focus_enabled {
            BackgroundColor(Color::srgb(0.20, 0.38, 0.25))
        } else if title_route_dashboard_focus {
            BackgroundColor(Color::srgb(0.24, 0.17, 0.12))
        } else if selected_slot {
            BackgroundColor(Color::srgb(0.22, 0.40, 0.46))
        } else if pending_overwrite {
            BackgroundColor(Color::srgb(0.46, 0.28, 0.10))
        } else if pending_stat_confirmation {
            BackgroundColor(Color::srgb(0.28, 0.30, 0.10))
        } else if resume_continue_required {
            BackgroundColor(Color::srgb(0.48, 0.32, 0.12))
        } else if pause_resume_required {
            BackgroundColor(Color::srgb(0.18, 0.36, 0.48))
        } else if pause_menu_active {
            BackgroundColor(Color::srgb(0.14, 0.20, 0.24))
        } else if settings_back_required {
            BackgroundColor(Color::srgb(0.22, 0.34, 0.20))
        } else if settings_menu_active {
            BackgroundColor(Color::srgb(0.16, 0.28, 0.18))
        } else if title_choice_required {
            BackgroundColor(Color::srgb(0.32, 0.22, 0.14))
        } else if title_menu_active {
            BackgroundColor(Color::srgb(0.18, 0.12, 0.08))
        } else if character_create_choice {
            BackgroundColor(Color::srgb(0.34, 0.20, 0.22))
        } else if primary {
            BackgroundColor(Color::srgb(0.48, 0.42, 0.16))
        } else if enabled {
            BackgroundColor(Color::srgb(0.13, 0.28, 0.24))
        } else if entry.is_some() {
            BackgroundColor(Color::srgba(0.10, 0.10, 0.09, 0.38))
        } else {
            BackgroundColor(Color::srgba(0.02, 0.03, 0.03, 0.03))
        };
        *border = if onboarding_next_highlight {
            BorderColor::all(Color::srgb(1.0, 0.92, 0.36))
        } else if title_route_dashboard_focus_enabled {
            BorderColor::all(Color::srgb(0.88, 0.95, 0.42))
        } else if title_route_dashboard_focus {
            BorderColor::all(Color::srgb(0.95, 0.50, 0.24))
        } else if selected_slot {
            BorderColor::all(Color::srgb(0.55, 0.86, 0.96))
        } else if pending_overwrite {
            BorderColor::all(Color::srgb(1.0, 0.64, 0.28))
        } else if pending_stat_confirmation {
            BorderColor::all(Color::srgb(0.96, 0.92, 0.36))
        } else if resume_continue_required {
            BorderColor::all(Color::srgb(1.0, 0.72, 0.30))
        } else if pause_resume_required {
            BorderColor::all(Color::srgb(0.50, 0.82, 1.0))
        } else if pause_menu_active {
            BorderColor::all(Color::srgb(0.36, 0.48, 0.56))
        } else if settings_back_required {
            BorderColor::all(Color::srgb(0.66, 0.92, 0.56))
        } else if settings_menu_active {
            BorderColor::all(Color::srgb(0.44, 0.68, 0.44))
        } else if title_choice_required {
            BorderColor::all(Color::srgb(0.96, 0.72, 0.38))
        } else if title_menu_active {
            BorderColor::all(Color::srgb(0.78, 0.48, 0.30))
        } else if character_create_choice {
            BorderColor::all(Color::srgb(0.96, 0.64, 0.58))
        } else if primary {
            BorderColor::all(Color::srgb(0.96, 0.84, 0.32))
        } else if enabled {
            BorderColor::all(Color::srgb(0.52, 0.74, 0.60))
        } else if visual_state == "hidden_or_not_current_context" {
            BorderColor::all(Color::srgba(0.12, 0.16, 0.15, 0.04))
        } else if visual_state == "disabled_contextual" {
            BorderColor::all(Color::srgba(0.30, 0.34, 0.31, 0.36))
        } else {
            BorderColor::all(Color::srgb(0.28, 0.34, 0.32))
        };
        label_states.insert(
            action_label,
            (
                state.base_label.clone(),
                visual_state.to_string(),
                enabled,
                primary || selected_slot || onboarding_next_highlight,
            ),
        );
    }
    for (mut row_node, row_children, mut row_state) in &mut action_rows {
        let row_active = row_children
            .iter()
            .any(|child| visible_button_entities.contains(&child))
            && contextual_action_row_should_show(
                &row_state.row_id,
                row_children,
                &button_row_signals,
            );
        row_state.active = row_active;
        row_node.display = if row_active {
            Display::Flex
        } else {
            Display::None
        };
    }
    for (mut text, mut text_color, label) in &mut labels {
        if let Some((base_label, visual_state, enabled, primary)) =
            label_states.get(&label.action_label)
        {
            text.0 = if visual_state == "onboarding_next_button"
                || visual_state == "title_route_dashboard_focus"
            {
                format!(">> {base_label}")
            } else if visual_state == "selected_slot" {
                format!("* {base_label}")
            } else if visual_state == "overwrite_pending"
                || visual_state == "stat_confirmation_pending"
                || visual_state == "resume_continue_required"
                || visual_state == "pause_resume_required"
                || visual_state == "settings_back_required"
                || visual_state == "title_route_dashboard_blocked"
            {
                format!("! {base_label}")
            } else if *primary {
                format!("> {base_label}")
            } else if *enabled {
                base_label.clone()
            } else {
                format!("x {base_label}")
            };
            text_color.0 = if visual_state == "hidden_or_not_current_context" {
                Color::srgba(0.96, 0.98, 0.88, 0.05)
            } else if *primary {
                Color::srgb(1.0, 0.94, 0.54)
            } else if *enabled {
                Color::srgb(0.94, 0.98, 0.88)
            } else {
                Color::srgba(0.72, 0.78, 0.72, 0.50)
            };
        }
    }
}

#[allow(clippy::too_many_arguments, clippy::type_complexity)]
pub fn update_native_text_adventure_ui(
    world: Res<AuthoritativeWorldResource>,
    bootstrap: Res<NativeWorldBootstrap>,
    gameplay_log: Res<NativeGameplayLog>,
    tactics_character: Res<NativeTacticsCharacter>,
    first_playable: Res<NativeFirstPlayableRuntime>,
    mut texts: ParamSet<(
        Query<&mut Text, With<BevyWorldCharacterStatusText>>,
        Query<&mut Text, With<BevyWorldRoomNarrativeText>>,
        Query<&mut Text, With<BevyWorldEventLogPanelText>>,
        Query<&mut Text, With<BevyWorldVisibleEventSummaryText>>,
        Query<&mut Text, With<BevyWorldQuestPanelText>>,
        Query<&mut Text, With<BevyWorldCharacterDetailText>>,
        Query<&mut Text, With<BevyWorldInventoryPanelText>>,
    )>,
) {
    let actor_id = bootstrap.actor_id.as_str();
    let node_id = player_node_id(&world.state, actor_id).unwrap_or_else(|| "unknown".to_string());
    let room_name = text_adventure_room_title(&node_id);
    let room_description = text_adventure_room_description(&node_id);
    let exits = exits_for_node(&world.state, &node_id);
    let exit_line = if exits.is_empty() {
        "none".to_string()
    } else {
        exits.join(" / ")
    };
    let local_npcs = local_npc_names_for_actor(&world.state, actor_id);
    let npc_line = if local_npcs.is_empty() {
        "none".to_string()
    } else {
        local_npcs.join(" / ")
    };
    let objective = playable_objective_for_actor(&world.state, actor_id);
    let next_prompt = first_playable_next_prompt(&first_playable);
    let route_director_line = route_director_summary(&first_playable);
    let skill_line = if tactics_character.character.skill_ids.is_empty() {
        "none".to_string()
    } else {
        tactics_character.character.skill_ids.join(", ")
    };
    let weapon = tactics_character
        .character
        .equipment_slots
        .get("weapon")
        .cloned()
        .unwrap_or_else(|| "none".to_string());
    let weapon_label = text_adventure_item_label(&weapon);
    let recent_events = first_playable
        .feedback_events
        .iter()
        .rev()
        .take(5)
        .map(|event| format!("> {event}"))
        .collect::<Vec<_>>()
        .join("\n");
    let recent_input_feedback = first_playable
        .input_feedback_history
        .iter()
        .rev()
        .take(4)
        .map(|event| {
            format!(
                "{} {} {} ({})",
                event.input_source,
                event.action_label,
                if event.accepted {
                    "accepted"
                } else {
                    "blocked"
                },
                event.reason
            )
        })
        .collect::<Vec<_>>()
        .join("\n");
    let input_summary = native_input_telemetry_summary(&first_playable);
    let input_summary_line = format!(
        "INPUT SUMMARY total {} accepted {} blocked {} keyboard {} buttons {} last {} {} {}",
        input_summary.total_events,
        input_summary.accepted_events,
        input_summary.blocked_events,
        input_summary.keyboard_events,
        input_summary.bevy_button_events,
        input_summary.last_input_source.as_deref().unwrap_or("none"),
        input_summary.last_action_label.as_deref().unwrap_or("none"),
        input_summary.last_reason.as_deref().unwrap_or("none")
    );
    let onboarding_hud = first_minute_onboarding_hud_text(&first_playable);
    let quest_journal = quest_journal_text(&first_playable, objective.as_ref());
    let quest_summary = objective
        .as_ref()
        .map(|objective| {
            format!(
                "{}\n{}\nRoute: {}\nReward: {} coins\nDirector: {}",
                onboarding_hud,
                quest_journal,
                objective.title,
                objective.reward_units,
                route_director_line
            )
        })
        .unwrap_or_else(|| {
            format!(
                "{}\n{}\nNo active route.\nDirector: {}",
                onboarding_hud, quest_journal, route_director_line
            )
        });

    let status_text = player_facing_status_hud_text(&first_playable, weapon_label);
    let narrative_text = format!(
        "{} [{}]\n{}\n\nExits: {}\nNPCs: {}\n\nNEXT: {}",
        room_name, node_id, room_description, exit_line, npc_line, next_prompt
    );
    let event_text = debug_layer_event_log_text(
        &recent_events,
        &input_summary_line,
        &recent_input_feedback,
        &gameplay_log,
    );
    let visible_event_text = visible_event_summary_text(&first_playable);
    let character_text = character_growth_text(
        &first_playable,
        &tactics_character.character,
        &skill_line,
        weapon_label,
    );
    let inventory_text = inventory_equipment_text(&first_playable, weapon_label);

    for mut text in &mut texts.p0() {
        text.0 = status_text.clone();
    }
    for mut text in &mut texts.p1() {
        text.0 = narrative_text.clone();
    }
    for mut text in &mut texts.p2() {
        text.0 = event_text.clone();
    }
    for mut text in &mut texts.p3() {
        text.0 = visible_event_text.clone();
    }
    for mut text in &mut texts.p4() {
        text.0 = quest_summary.clone();
    }
    for mut text in &mut texts.p5() {
        text.0 = character_text.clone();
    }
    for mut text in &mut texts.p6() {
        text.0 = inventory_text.clone();
    }
}

fn visible_event_summary_text(runtime: &NativeFirstPlayableRuntime) -> String {
    let last_event = runtime
        .feedback_events
        .last()
        .cloned()
        .unwrap_or_else(|| "route ready".to_string());
    let last_input = runtime
        .input_feedback_history
        .last()
        .map(|event| {
            format!(
                "{} {} {}",
                event.action_label,
                if event.accepted { "ok" } else { "blocked" },
                event.reason
            )
        })
        .unwrap_or_else(|| "waiting for input".to_string());
    format!(
        "LAST | {last_event}\nINPUT | {last_input}\nNEXT | {}",
        first_minute_onboarding_next_button(runtime)
    )
}

fn first_minute_completed_step_count(runtime: &NativeFirstPlayableRuntime) -> usize {
    [
        first_minute_character_created(runtime),
        runtime_has_completed_step(runtime, "talk_to_mentor"),
        runtime_has_completed_step(runtime, "train_basic_unarmed"),
        runtime_has_completed_step(runtime, "arrive_at_first_objective"),
        runtime_has_completed_step(runtime, "resolve_first_combat"),
        runtime_has_completed_step(runtime, "complete_first_task"),
        runtime_has_completed_step(runtime, "equip_route_guard_staff"),
    ]
    .into_iter()
    .filter(|done| *done)
    .count()
}

fn visible_quest_summary_text(
    runtime: &NativeFirstPlayableRuntime,
    objective: Option<&NativePlayableObjective>,
) -> String {
    let tracked = objective
        .map(|objective| objective.title.clone())
        .unwrap_or_else(|| runtime.route_director_task_id.clone());
    let reward = objective
        .map(|objective| objective.reward_units)
        .unwrap_or(runtime.coins);
    let next_button = first_minute_onboarding_next_button(runtime);
    let state_hint = first_minute_onboarding_state_hint(runtime);
    format!(
        "CURRENT OBJECTIVE | {tracked}\nNEXT | {next_button} - {state_hint}\nPROGRESS | {}/7 | REWARD {}c | gear {}",
        first_minute_completed_step_count(runtime),
        reward,
        if runtime.equipment_ready { "ready" } else { "pending" }
    )
}

fn visible_stats_summary_text(
    runtime: &NativeFirstPlayableRuntime,
    character: &WorldTrillionniumCharacter,
    skill_line: &str,
    weapon_label: &str,
) -> String {
    let attributes = &character.attributes;
    let build = runtime
        .pending_stat_allocation
        .as_deref()
        .map(|stat| format!("pending {stat}"))
        .or_else(|| {
            runtime
                .allocated_stat_points
                .first()
                .map(|stat| format!("active {stat}"))
        })
        .unwrap_or_else(|| format!("unspent {}", runtime.growth_stat_points));
    let title = runtime.active_build_title_id.as_deref().unwrap_or("none");
    let skill = if skill_line == "none" {
        "no skill"
    } else {
        skill_line
    };
    format!(
        "STATS | HP {}/176 | XP {} | COINS {}\nBUILD | P{} F{} A{} C{} | {build}\nGEAR | {} | skill {skill} | title {title}",
        runtime.player_hp,
        runtime.xp,
        runtime.coins,
        attributes.physique,
        attributes.force,
        attributes.agility,
        attributes.craft,
        weapon_label
    )
}

fn visible_bag_summary_text(runtime: &NativeFirstPlayableRuntime) -> String {
    let bag_state = if runtime.bag_open { "open" } else { "closed" };
    let sash = if runtime
        .equipped_items
        .iter()
        .any(|item| item == "bandit_sash")
    {
        "equipped"
    } else if runtime
        .inventory_items
        .iter()
        .any(|item| item == "bandit_sash")
    {
        "in_bag"
    } else if runtime
        .dropped_items
        .iter()
        .any(|item| item == "bandit_sash")
    {
        "dropped"
    } else {
        "locked"
    };
    let affix = if let Some(stat) = runtime.pending_stat_allocation.as_deref() {
        format!("preview {stat}")
    } else if let Some(stat) = runtime.allocated_stat_points.first() {
        format!("active {stat}")
    } else if sash == "equipped" {
        "choose build".to_string()
    } else {
        "locked".to_string()
    };
    format!(
        "BAG | {bag_state} | items {} equipped {} drops {}\nAFFIX | {affix} | KEY bandit_sash {sash}\nLOOT | {}",
        runtime.inventory_items.len(),
        runtime.equipped_items.len(),
        runtime.dropped_items.len(),
        if runtime.loot_history.is_empty() {
            "pending".to_string()
        } else {
            runtime.loot_history.join(", ")
        }
    )
}

#[allow(clippy::type_complexity)]
pub fn update_native_right_rail_summary_ui(
    world: Res<AuthoritativeWorldResource>,
    bootstrap: Res<NativeWorldBootstrap>,
    tactics_character: Res<NativeTacticsCharacter>,
    first_playable: Res<NativeFirstPlayableRuntime>,
    mut texts: ParamSet<(
        Query<&mut Text, With<BevyWorldVisibleQuestSummaryText>>,
        Query<&mut Text, With<BevyWorldVisibleStatsSummaryText>>,
        Query<&mut Text, With<BevyWorldVisibleBagSummaryText>>,
    )>,
) {
    let objective = playable_objective_for_actor(&world.state, bootstrap.actor_id.as_str());
    let skill_line = if tactics_character.character.skill_ids.is_empty() {
        "none".to_string()
    } else {
        tactics_character.character.skill_ids.join(", ")
    };
    let weapon = tactics_character
        .character
        .equipment_slots
        .get("weapon")
        .cloned()
        .unwrap_or_else(|| "none".to_string());
    let weapon_label = text_adventure_item_label(&weapon);
    let quest_summary = visible_quest_summary_text(&first_playable, objective.as_ref());
    let stats_summary = visible_stats_summary_text(
        &first_playable,
        &tactics_character.character,
        &skill_line,
        weapon_label,
    );
    let bag_summary = visible_bag_summary_text(&first_playable);
    for mut text in &mut texts.p0() {
        text.0 = quest_summary.clone();
    }
    for mut text in &mut texts.p1() {
        text.0 = stats_summary.clone();
    }
    for mut text in &mut texts.p2() {
        text.0 = bag_summary.clone();
    }
}

fn native_command_label(command: &WorldCommand) -> String {
    match command {
        WorldCommand::Move { direction, .. } => format!("move:{direction}"),
        WorldCommand::TalkNpc { npc_id, .. } => format!("talk:{npc_id}"),
        WorldCommand::TrainSkill { skill_id, .. } => format!("train:{skill_id}"),
        WorldCommand::CompleteTask { task_id, .. } => format!("complete:{task_id}"),
    }
}

fn player_node_id(world: &WorldState, actor_id: &str) -> Option<String> {
    world
        .positions
        .iter()
        .find(|position| position.actor_id == actor_id)
        .map(|position| position.node_id.clone())
}

fn exits_for_node(world: &WorldState, node_id: &str) -> Vec<String> {
    world
        .edges
        .iter()
        .filter(|edge| edge.from == node_id)
        .map(|edge| edge.direction.clone())
        .collect()
}

fn playable_exits_for_actor(world: &WorldState, actor_id: &str) -> Vec<NativePlayableExit> {
    let Some(node_id) = player_node_id(world, actor_id) else {
        return Vec::new();
    };
    world
        .edges
        .iter()
        .filter(|edge| edge.from == node_id)
        .map(|edge| NativePlayableExit {
            direction: edge.direction.clone(),
            to_node_id: edge.to.clone(),
            to_room_name: world
                .node(&edge.to)
                .map(|node| node.name.clone())
                .unwrap_or_else(|| edge.to.clone()),
        })
        .collect()
}

fn playable_objective_for_actor(
    world: &WorldState,
    actor_id: &str,
) -> Option<NativePlayableObjective> {
    let task = world.tasks.first()?;
    let target_room_name = world
        .node(&task.node_id)
        .map(|node| node.name.clone())
        .unwrap_or_else(|| task.node_id.clone());
    Some(NativePlayableObjective {
        task_id: task.id.clone(),
        title: task.title.clone(),
        target_node_id: task.node_id.clone(),
        target_room_name,
        reward_units: task.reward_units,
        ledger_settlement_required: task.ledger_settlement_required,
        route_hint: objective_route_hint(world, actor_id, &task.node_id),
    })
}

fn objective_route_hint(world: &WorldState, actor_id: &str, target_node_id: &str) -> String {
    let Some(current_node_id) = player_node_id(world, actor_id) else {
        return "player_position_missing".to_string();
    };
    if current_node_id == target_node_id {
        return "arrived".to_string();
    }
    if let Some(edge) = world
        .edges
        .iter()
        .find(|edge| edge.from == current_node_id && edge.to == target_node_id)
    {
        return format!("{} -> {}", edge.direction, target_node_id);
    }
    world
        .edges
        .iter()
        .find(|edge| edge.from == current_node_id)
        .map(|edge| format!("{} -> {} then continue route", edge.direction, edge.to))
        .unwrap_or_else(|| "no_open_exit".to_string())
}

fn current_room_json(world: &WorldState, actor_id: &str) -> serde_json::Value {
    let node_id = player_node_id(world, actor_id).unwrap_or_else(|| "unknown".to_string());
    if let Some(node) = world.node(&node_id) {
        json!({
            "node_id": node.id.clone(),
            "name": node.name.clone(),
            "location_id": node.location_id.clone(),
            "kind": node.node_kind.clone(),
            "description": node.description.clone(),
        })
    } else {
        json!({ "node_id": node_id, "name": "unknown" })
    }
}

fn local_npc_for_actor<'a>(world: &'a WorldState, actor_id: &str) -> Option<&'a WorldNpc> {
    let node_id = player_node_id(world, actor_id)?;
    world.npcs.iter().find(|npc| npc.node_id == node_id)
}

fn local_npc_names_for_actor(world: &WorldState, actor_id: &str) -> Vec<String> {
    let Some(node_id) = player_node_id(world, actor_id) else {
        return Vec::new();
    };
    world
        .npcs
        .iter()
        .filter(|npc| npc.node_id == node_id)
        .map(|npc| format!("{} ({})", npc.name, npc.id))
        .collect()
}

fn local_task_for_actor<'a>(world: &'a WorldState, actor_id: &str) -> Option<&'a WorldTask> {
    let node_id = player_node_id(world, actor_id)?;
    world.tasks.iter().find(|task| task.node_id == node_id)
}

fn world_node_screen_positions(world: &WorldState) -> HashMap<String, Vec3> {
    let min_x = world
        .nodes
        .iter()
        .map(|node| node.lng_e7)
        .min()
        .unwrap_or(0) as f32;
    let max_x = world
        .nodes
        .iter()
        .map(|node| node.lng_e7)
        .max()
        .unwrap_or(1) as f32;
    let min_y = world
        .nodes
        .iter()
        .map(|node| node.lat_e7)
        .min()
        .unwrap_or(0) as f32;
    let max_y = world
        .nodes
        .iter()
        .map(|node| node.lat_e7)
        .max()
        .unwrap_or(1) as f32;
    let span_x = (max_x - min_x).abs().max(1.0);
    let span_y = (max_y - min_y).abs().max(1.0);
    world
        .nodes
        .iter()
        .enumerate()
        .map(|(index, node)| {
            let normalized_x = (node.lng_e7 as f32 - min_x) / span_x;
            let normalized_y = (node.lat_e7 as f32 - min_y) / span_y;
            let jitter = ((index % 3) as f32 - 1.0) * 8.0;
            (
                node.id.clone(),
                Vec3::new(
                    -320.0 + normalized_x * 640.0 + jitter,
                    180.0 - normalized_y * 360.0 - jitter,
                    0.0,
                ),
            )
        })
        .collect()
}

fn native_now_epoch() -> i64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|duration| duration.as_secs() as i64)
        .unwrap_or_default()
}

