    #[test]
    fn build_branch_title_route_all_branch_keyboard_replay_evidence_replays_recorded_sequences() {
        let _slot_guard = SESSION_SLOT_TEST_LOCK
            .lock()
            .expect("session slot tests serialize filesystem fixtures");
        for slot_id in native_session_slot_ids() {
            let _ = std::fs::remove_file(native_action_session_slot_path(slot_id));
        }
        let value: serde_json::Value = serde_json::from_str(
            &native_build_branch_title_route_all_branch_keyboard_replay_evidence_json(
                "local-player",
            ),
        )
        .expect("build branch title route all-branch keyboard replay evidence parses");
        assert_eq!(
            value
                .get("contract_version")
                .and_then(|value| value.as_str()),
            Some(
                TRILLIONNIUM_WORLD_BEVY_BUILD_BRANCH_TITLE_ROUTE_ALL_BRANCH_KEYBOARD_REPLAY_CONTRACT
            ),
        );
        assert_eq!(
            value.get("green").and_then(|value| value.as_bool()),
            Some(true),
        );
        assert_eq!(
            value
                .get("all_branch_keyboard_loop_contract_green")
                .and_then(|value| value.as_bool()),
            Some(true),
        );
        assert_eq!(
            value.get("branch_count").and_then(|value| value.as_u64()),
            Some(3),
        );
        for stat_id in ["force", "agility", "craft"] {
            assert_eq!(
                value
                    .pointer(&format!("/replay_results/{stat_id}/green"))
                    .and_then(|value| value.as_bool()),
                Some(true),
                "{stat_id} replay should be green",
            );
            for gate in [
                "recorded_branch_green",
                "recorded_sequence_parse_gate",
                "recorded_sequence_path_gate",
                "replay_sequence_signature_match",
                "final_runtime_match",
            ] {
                assert_eq!(
                    value
                        .pointer(&format!("/replay_results/{stat_id}/{gate}"))
                        .and_then(|value| value.as_bool()),
                    Some(true),
                    "{stat_id} {gate} should pass",
                );
            }
            let recorded_count = value
                .pointer(&format!(
                    "/replay_results/{stat_id}/recorded_sequence_count"
                ))
                .and_then(|value| value.as_u64())
                .unwrap_or_default();
            let replay_count = value
                .pointer(&format!("/replay_results/{stat_id}/replay_event_count"))
                .and_then(|value| value.as_u64())
                .unwrap_or_default();
            assert!(
                recorded_count > 0,
                "{stat_id} recorded sequence should exist"
            );
            assert_eq!(recorded_count, replay_count, "{stat_id} event count");
        }
        assert!(value
            .pointer("/replay_results/force/recorded_sequence")
            .and_then(|value| value.as_array())
            .is_some_and(|steps| steps.iter().any(|step| {
                step.get("key").and_then(|value| value.as_str()) == Some("KeyJ")
                    && step.get("action").and_then(|value| value.as_str()) == Some("COMBAT:attack")
            })));
        assert_eq!(
            value
                .pointer("/replay_results/force/replay_final_runtime/combat_result_state")
                .and_then(|value| value.as_str()),
            Some("victory"),
        );
        assert_eq!(
            value
                .pointer("/replay_results/craft/replay_final_runtime/objective_status")
                .and_then(|value| value.as_str()),
            Some("build_mastery_challenge_completed:craft:task-craft-mastery-client-order"),
        );
        for slot_id in native_session_slot_ids() {
            let _ = std::fs::remove_file(native_action_session_slot_path(slot_id));
        }
    }

    #[test]
    fn enter_key_advances_current_first_minute_next_action() {
        let _slot_guard = SESSION_SLOT_TEST_LOCK
            .lock()
            .expect("session slot tests serialize filesystem fixtures");
        for slot_id in native_session_slot_ids() {
            let _ = std::fs::remove_file(native_action_session_slot_path(slot_id));
        }
        let mut app = build_keyboard_runtime_app(native_bevy_playable_fixture(), "local-player");
        seed_rendering_app_title_menu(&mut app);
        let steps = [
            (NativeControlAction::NewGameFromTitle, "CREATE:CONFIRM"),
            (NativeControlAction::ConfirmCharacterCreate, "TALK"),
            (NativeControlAction::Talk, "TRAIN"),
            (NativeControlAction::Train, "MOVE:north"),
            (
                NativeControlAction::Move {
                    direction: "north".to_string(),
                },
                "FIGHT",
            ),
            (NativeControlAction::Fight, "SAVE:SELECTED"),
            (NativeControlAction::SaveSelectedSlot, "TITLE:OPEN"),
            (NativeControlAction::OpenTitleMenu, "TITLE:CONTINUE"),
            (NativeControlAction::ContinueFromTitle, "CONTINUE:SESSION"),
            (
                NativeControlAction::ContinueAfterLoad,
                "FIRST MINUTE COMPLETE",
            ),
        ];
        for (expected_action, expected_next_after) in steps {
            let event = press_keyboard_script_step(
                &mut app,
                NativeKeyboardScriptInput {
                    key: KeyCode::Enter,
                    key_label: "Enter",
                    action: expected_action,
                },
            );
            assert_eq!(
                event.get("accepted").and_then(|value| value.as_bool()),
                Some(true)
            );
            assert_eq!(
                first_minute_onboarding_next_button(
                    app.world().resource::<NativeFirstPlayableRuntime>()
                ),
                expected_next_after
            );
        }
        let final_runtime = app.world().resource::<NativeFirstPlayableRuntime>();
        assert_eq!(final_runtime.objective_status, "combat_resolved");
        assert!(!final_runtime.session_resume_input_locked);
        for slot_id in native_session_slot_ids() {
            let _ = std::fs::remove_file(native_action_session_slot_path(slot_id));
        }
    }

    #[test]
    fn rendering_scene_spawns_touch_buttons_and_room_panel() {
        let world = native_bevy_playable_fixture();
        let mut app = App::new();
        app.add_plugins(MinimalPlugins)
            .add_plugins(TrillionniumWorldBevyPlugin::new(world, "local-player"))
            .add_systems(Startup, spawn_native_render_scene);
        app.update();
        let world = app.world_mut();
        let mut controls = world.query::<&NativeControlAction>();
        assert!(controls.iter(world).count() >= 7);
        let mut scene_tokens = world.query::<&BevyWorldSceneToken>();
        let roles = scene_tokens
            .iter(world)
            .map(|token| token.role.as_str())
            .collect::<Vec<_>>();
        assert!(roles.contains(&"mentor"));
        assert!(roles.contains(&"enemy"));
        let mut status_bars = world.query::<&BevyWorldStatusBar>();
        assert_eq!(status_bars.iter(world).count(), 3);
        let mut feedback_texts = world.query::<&BevyWorldFeedbackBannerText>();
        assert_eq!(feedback_texts.iter(world).count(), 1);
        let mut reward_texts = world.query::<&BevyWorldRewardToastText>();
        assert_eq!(reward_texts.iter(world).count(), 1);
        let mut tile_rpg_panels = world.query::<&BevyWorldTileRpgPanel>();
        let panel_ids = tile_rpg_panels
            .iter(world)
            .map(|panel| panel.panel_id.as_str())
            .collect::<Vec<_>>();
        for required_panel in [
            "tile_rpg_shell",
            "top_character_status",
            "room_narrative_panel",
            "event_log_panel",
            "npc_dialogue_choice_panel",
            "scene_transition_panel",
            "combat_scene_panel",
            "walk_animation_panel",
            "virtual_joystick",
            "right_action_buttons",
            "monochrome_stat_panel",
            "paper_skill_menu_overlay",
            "quest_objective_panel",
        ] {
            assert!(panel_ids.contains(&required_panel));
        }
        let mut tile_rpg_surfaces = world.query::<&BevyWorldTileRpgSurface>();
        let surface_ids = tile_rpg_surfaces
            .iter(world)
            .map(|surface| surface.surface_id.as_str())
            .collect::<Vec<_>>();
        for required_surface in [
            "top_down_tilemap_viewport",
            "outdoor_town_tiles",
            "indoor_room_tiles",
            "stone_road_tiles",
            "water_tiles",
            "town_wall_tiles",
            "building_roof_tiles",
            "building_wall_tiles",
            "door_tiles",
            "roof_shadow_tiles",
            "water_edge_tiles",
            "furniture_props",
            "tree_props",
            "tree_canopy_tiles",
            "visible_dialogue_choice_panel",
            "visible_combat_scene_panel",
            "player_chibi_sprite",
            "player_chibi_head",
            "player_chibi_hair",
            "player_chibi_feet",
            "player_facing_frame",
            "npc_chibi_sprite",
            "npc_chibi_head",
            "npc_chibi_hair",
            "npc_facing_frame",
            "enemy_facing_frame",
            "npc_patrol_path_tiles",
            "enemy_patrol_path_tiles",
            "item_drop_sprite",
            "damage_number_sprite",
            "equipment_icon_sprite",
            "bag_slot_sprite",
            "sprite_shadow",
        ] {
            assert!(surface_ids.contains(&required_surface));
        }
        let mut actor_parts = world.query::<&BevyWorldActorSpritePart>();
        assert!(actor_parts.iter(world).count() >= 4);
        let mut scene_state_texts = world.query::<&BevyWorldSceneStateText>();
        assert_eq!(scene_state_texts.iter(world).count(), 1);
        let mut scene_layers = world.query::<&BevyWorldSceneLayerSprite>();
        assert_eq!(scene_layers.iter(world).count(), 1);
        let mut dialogue_overlays = world.query::<&BevyWorldDialogueOverlaySprite>();
        assert_eq!(dialogue_overlays.iter(world).count(), 1);
        let mut combat_overlays = world.query::<&BevyWorldCombatOverlaySprite>();
        assert_eq!(combat_overlays.iter(world).count(), 1);
        let mut npc_behavior_texts = world.query::<&BevyWorldNpcBehaviorText>();
        assert_eq!(npc_behavior_texts.iter(world).count(), 1);
        let mut enemy_behavior_texts = world.query::<&BevyWorldEnemyBehaviorText>();
        assert_eq!(enemy_behavior_texts.iter(world).count(), 1);
        let mut dialogue_texts = world.query::<&BevyWorldDialogueChoiceText>();
        assert_eq!(dialogue_texts.iter(world).count(), 1);
        let mut transition_texts = world.query::<&BevyWorldSceneTransitionText>();
        assert_eq!(transition_texts.iter(world).count(), 1);
        let mut combat_texts = world.query::<&BevyWorldCombatSceneText>();
        assert_eq!(combat_texts.iter(world).count(), 1);
        let mut walk_texts = world.query::<&BevyWorldWalkAnimationText>();
        assert_eq!(walk_texts.iter(world).count(), 1);
        let mut session_recovery_texts = world.query::<&BevyWorldSessionRecoveryText>();
        assert_eq!(session_recovery_texts.iter(world).count(), 1);
        let final_runtime = NativeFirstPlayableRuntime {
            map_scene: "arena_outdoor".to_string(),
            scene_transition: "combat_overlay_return_to_map".to_string(),
            npc_dialogue_state: "mentor_training_complete".to_string(),
            combat_scene_state: "combat_returned_to_map".to_string(),
            last_tile_step: "step_north".to_string(),
            walk_cycle_frame: 2,
            player_hp: 164,
            enemy_hp: 10,
            completed_steps: vec!["arrive_at_first_objective".to_string()],
            ..default()
        };
        assert!(tile_rpg_dialogue_choice_text(&final_runtime).contains("Choice locked"));
        assert!(tile_rpg_scene_transition_text(&final_runtime).contains("Arena outdoor"));
        assert!(tile_rpg_combat_scene_text(&final_runtime).contains("Combat returned"));
        assert!(tile_rpg_walk_animation_text(&final_runtime).contains("step_north"));
        let mut narratives = world.query::<&BevyWorldRoomNarrativeText>();
        assert_eq!(narratives.iter(world).count(), 1);
        let mut character_details = world.query::<&BevyWorldCharacterDetailText>();
        assert_eq!(character_details.iter(world).count(), 1);
    }
